def now_text():
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")

SENSITIVE_AUDIT_KEYS = ("key", "token", "secret", "password", "authorization", "api")

def _safe_audit_value(value):
    if isinstance(value, dict):
        safe = {}
        for key, item in value.items():
            if any(marker in str(key).lower() for marker in SENSITIVE_AUDIT_KEYS):
                safe[key] = "***"
            else:
                safe[key] = _safe_audit_value(item)
        return safe
    if isinstance(value, list):
        return [_safe_audit_value(item) for item in value]
    return value

def _audit_json(value):
    if value is None:
        return ""
    try:
        return json.dumps(_safe_audit_value(value), ensure_ascii=False, default=str)
    except Exception:
        return str(value)

def record_audit(conn, actor_id, actor_type, action, object_type="", object_id="", before=None, after=None, note=""):
    try:
        c = conn.cursor()
        c.execute(
            """INSERT INTO audit_logs
            (actor_id, actor_type, action, object_type, object_id, before_json, after_json, note, created_at)
            VALUES (?,?,?,?,?,?,?,?,?)""",
            (
                str(actor_id or ""),
                str(actor_type or ""),
                str(action or ""),
                str(object_type or ""),
                str(object_id or ""),
                _audit_json(before),
                _audit_json(after),
                str(note or "")[:1200],
                now_text(),
            )
        )
    except Exception as e:
        logger.warning(f"Audit log write failed: {e}")

def record_audit_event(actor_id, actor_type, action, object_type="", object_id="", before=None, after=None, note=""):
    conn = None
    try:
        conn = db_connect()
        record_audit(conn, actor_id, actor_type, action, object_type, object_id, before, after, note)
        conn.commit()
    except Exception as e:
        logger.warning(f"Audit event write failed: {e}")
    finally:
        if conn:
            conn.close()

def get_system_setting(key, default=""):
    conn = None
    try:
        conn = db_connect()
        c = conn.cursor()
        c.execute("SELECT value FROM system_settings WHERE key=?", (str(key),))
        row = c.fetchone()
        return row[0] if row else default
    except sqlite3.OperationalError as e:
        if "no such table: system_settings" not in str(e).lower():
            logger.warning(f"System setting read failed: {e}")
        return default
    except Exception as e:
        logger.warning(f"System setting read failed: {e}")
        return default
    finally:
        if conn:
            conn.close()

def get_system_settings(keys: list[str]) -> dict:
    return {key: get_system_setting(key, "") for key in keys}

def set_system_setting(key, value, note="", updated_by=""):
    conn = None
    try:
        conn = db_connect()
        c = conn.cursor()
        c.execute(
            """INSERT OR REPLACE INTO system_settings
            (key, value, note, updated_at, updated_by)
            VALUES (?,?,?,?,?)""",
            (str(key), str(value or ""), str(note or "")[:1200], now_text(), str(updated_by or "")),
        )
        conn.commit()
    except Exception as e:
        logger.warning(f"System setting write failed: {e}")
        raise
    finally:
        if conn:
            conn.close()

def record_api_debug(provider: str, action: str, status: str, http_status: int = 0, detail: str = ""):
    conn = None
    try:
        conn = db_connect()
        conn.execute("""CREATE TABLE IF NOT EXISTS api_debug_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            provider TEXT,
            action TEXT,
            status TEXT,
            http_status INTEGER DEFAULT 0,
            detail TEXT,
            created_at TEXT
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS security_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_type TEXT,
            severity TEXT,
            user_id TEXT,
            username TEXT,
            detail TEXT,
            created_at TEXT
        )""")
        conn.execute(
            "INSERT INTO api_debug_events (provider, action, status, http_status, detail, created_at) VALUES (?,?,?,?,?,?)",
            (
                str(provider or "")[:60],
                str(action or "")[:80],
                str(status or "")[:80],
                int(http_status or 0),
                sanitize_log_text(str(detail or ""))[:1000],
                now_text(),
            ),
        )
        status_upper = str(status or "").upper()
        if status_upper not in {"PASS", "OK", "SUCCESS"}:
            since = (vn_now() - timedelta(minutes=10)).strftime("%Y-%m-%d %H:%M:%S")
            row = conn.execute(
                """SELECT COUNT(*) FROM api_debug_events
                WHERE provider=? AND UPPER(status) NOT IN ('PASS','OK','SUCCESS') AND created_at>=?""",
                (str(provider or "")[:60], since),
            ).fetchone()
            fail_count = int(row[0] or 0) if row else 0
            if fail_count in {10, 20, 50}:
                conn.execute(
                    """INSERT INTO security_events (event_type, severity, user_id, username, detail, created_at)
                    VALUES (?,?,?,?,?,?)""",
                    (
                        "provider_error_spike",
                        "medium",
                        "",
                        "",
                        f"provider={sanitize_log_text(str(provider or ''))[:60]}; fail_count_10m={fail_count}; last_action={sanitize_log_text(str(action or ''))[:80]}",
                        now_text(),
                    ),
                )
        conn.commit()
    except Exception as e:
        logger.warning(f"API debug event write failed: {e}")
    finally:
        if conn:
            conn.close()

def latest_api_debug_event(provider: str, actions: list[str]) -> dict:
    action_list = [str(item or "")[:80] for item in actions if str(item or "").strip()]
    if not action_list:
        return {}
    conn = None
    try:
        conn = db_connect()
        placeholders = ",".join("?" for _ in action_list)
        row = conn.execute(
            f"""SELECT provider, action, status, http_status, detail, created_at
            FROM api_debug_events
            WHERE provider=? AND action IN ({placeholders})
            ORDER BY id DESC LIMIT 1""",
            [str(provider or "")[:60], *action_list],
        ).fetchone()
        if not row:
            return {}
        return {
            "provider": row[0] or "",
            "action": row[1] or "",
            "status": row[2] or "",
            "http_status": int(row[3] or 0),
            "detail": row[4] or "",
            "created_at": row[5] or "",
        }
    except sqlite3.OperationalError as e:
        if "no such table" not in str(e).lower():
            logger.warning(f"API debug read failed: {e}")
        return {}
    except Exception as e:
        logger.warning(f"API debug read failed: {e}")
        return {}
    finally:
        if conn:
            conn.close()

