_MISSING_UI_TEXT_KEYS: set[str] = set()

def ui_text(lang: str | None, key: str, **kwargs) -> str:
    selected = normalize_user_language(lang) or "en"
    if selected not in UI_TEXT or selected in OTHER_USER_LANGUAGES:
        selected = "en"
    value = (UI_TEXT.get(selected) or {}).get(key)
    if value is None:
        value = UI_TEXT["en"].get(key)
    if value is None:
        value = UI_TEXT["vi"].get(key, key)
        marker = f"{selected}:{key}"
        if marker not in _MISSING_UI_TEXT_KEYS:
            _MISSING_UI_TEXT_KEYS.add(marker)
            logger.warning("Missing UI translation key %s for lang %s", key, selected)
    try:
        return str(value).format(**kwargs)
    except Exception:
        logger.warning("UI translation format failed for key %s", key)
        return str(value)

def user_ui_lang(user_id) -> str:
    return normalize_user_language(get_user_language(user_id)) or "vi"

def trial_bonus_hash_value(value: str) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    salt = TRIAL_BONUS_HASH_SALT or TELEGRAM_WEBHOOK_SECRET or OPERATOR_API_TOKEN or "toan-aas-trial-bonus-local-salt"
    return hmac.new(str(salt).encode("utf-8"), raw.encode("utf-8"), hashlib.sha256).hexdigest()

def record_trial_bonus_claim_conn(
    conn,
    telegram_user_id,
    amount: int,
    status: str,
    source: str = "telegram_start",
    reason: str = "",
    ip_hash: str = "",
    ip_prefix_hash: str = "",
    user_agent_hash: str = "",
    metadata: dict | None = None,
):
    try:
        conn.execute(
            """INSERT INTO trial_bonus_claims
               (telegram_user_id, ip_hash, ip_prefix_hash, user_agent_hash, claim_source, bonus_amount,
                status, reason, created_at, updated_at, metadata_json)
               VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
            (
                str(telegram_user_id or ""),
                str(ip_hash or ""),
                str(ip_prefix_hash or ""),
                str(user_agent_hash or ""),
                str(source or "unknown"),
                int(amount or 0),
                str(status or ""),
                str(reason or "")[:300],
                now_text(),
                now_text(),
                json.dumps(metadata or {}, ensure_ascii=False),
            ),
        )
    except Exception as e:
        logger.warning(f"trial bonus audit write failed: {type(e).__name__}")

def get_user(user_id, username="Unknown"):
    uid = str(user_id)
    clean_username = str(username or "Unknown")
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT credits, total_spent, is_vip FROM users WHERE user_id=?", (uid,))
    row = c.fetchone()
    if row:
        conn.close()
        return row[0], row[1], row[2]

    c.execute("SELECT granted_xu FROM trial_grants WHERE user_id=?", (uid,))
    trial_row = c.fetchone()
    if trial_row:
        initial_credits = 0
        note = "User recreated after missing users row; trial already granted before, no new trial credits."
        c.execute(
            "INSERT INTO users (user_id, username, credits, is_vip, join_date, total_spent) VALUES (?,?,?,?,?,?)",
            (uid, clean_username, initial_credits, 0, now_text(), 0)
        )
        record_credit_event(conn, uid, 0, "trial_already_granted_recreated", "", note)
        record_trial_bonus_claim_conn(
            conn,
            uid,
            0,
            "blocked_duplicate_user",
            "telegram_start",
            "trial_grants already has this Telegram user; no new free trial",
            metadata={"paid_topups_unaffected": True},
        )
        conn.commit()
        conn.close()
        return initial_credits, 0, 0

    initial_credits = TRIAL_BONUS_AMOUNT if TRIAL_BONUS_ENABLED else 0
    now = now_text()
    c.execute(
        "INSERT INTO users (user_id, username, credits, is_vip, join_date, total_spent) VALUES (?,?,?,?,?,?)",
        (uid, clean_username, initial_credits, 0, now, 0)
    )
    if TRIAL_BONUS_ENABLED and initial_credits > 0:
        c.execute(
            """INSERT OR IGNORE INTO trial_grants (user_id, granted_xu, granted_at, username, note)
            VALUES (?,?,?,?,?)""",
            (uid, initial_credits, now, clean_username, "First trial grant"),
        )
        record_trial_bonus_claim_conn(
            conn,
            uid,
            initial_credits,
            "granted",
            "telegram_start",
            "one_time_free_trial_by_telegram_user_id; no IP available from Telegram bot",
            metadata={
                "ip_available": False,
                "ip_check_applies_only_when_ip_available": bool(TRIAL_BONUS_IP_CHECK_ENABLED),
                "paid_topups_unaffected": True,
            },
        )
        record_credit_event(conn, uid, initial_credits, "trial_grant", "", f"Tặng {initial_credits} Xu trải nghiệm lần đầu")
    conn.commit()
    conn.close()
    return initial_credits, 0, 0

def get_trial_grant_status(user_id) -> dict:
    uid = str(user_id)
    conn = db_connect()
    try:
        c = conn.cursor()
        c.execute("SELECT granted_xu, granted_at, username, note FROM trial_grants WHERE user_id=?", (uid,))
        row = c.fetchone()
        return {
            "user_id": uid,
            "granted": row is not None,
            "granted_xu": int(row[0] or 0) if row else 0,
            "granted_at": row[1] if row else "",
            "username": row[2] if row else "",
            "note": row[3] if row else "",
        }
    finally:
        conn.close()

def add_credit(user_id, amount, event_type="manual_add", ref_id="", note=""):
    get_user(user_id)
    conn = db_connect()
    c = conn.cursor()
    c.execute("UPDATE users SET credits = credits + ? WHERE user_id=?", (amount, str(user_id)))
    record_credit_event(conn, user_id, amount, event_type, ref_id, note)
    if event_type in {"admin_add", "manual_deposit"}:
        record_audit(
            conn,
            ADMIN_ID,
            "admin",
            "credit.added",
            "user",
            str(user_id),
            before=None,
            after={"delta": int(amount), "event_type": event_type, "ref_id": ref_id},
            note=note,
        )
    conn.commit()
    conn.close()

def refund_charged_credit(user_id, amount, event_type="refund", ref_id="", note="", was_charged=True) -> bool:
    if not was_charged or is_admin_user(user_id) or int(amount or 0) <= 0:
        return False
    get_user(user_id)
    amount = int(amount)
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """UPDATE users
        SET credits = credits + ?,
            total_spent = CASE WHEN total_spent >= ? THEN total_spent - ? ELSE 0 END
        WHERE user_id=?""",
        (amount, amount, amount, str(user_id))
    )
    record_credit_event(conn, user_id, amount, event_type, ref_id, note)
    conn.commit()
    conn.close()
    return True

def spend_fixed_credit_info(user_id, amount, event_type, note="", apply_member_discount_flag=True) -> dict:
    base_amount = int(amount or 0)
    if is_admin_user(user_id):
        return {
            "ok": True,
            "base_cost": base_amount,
            "final_cost": 0,
            "discount_rate": 0,
            "discount_xu": 0,
            "tier": "admin",
            "badge": admin_display_badge(user_id) or "Admin",
            "note": "admin_free",
        }
    get_user(user_id)
    charge = (
        apply_member_service_discount(user_id, base_amount, event_type)
        if apply_member_discount_flag
        else {
            "base_cost": base_amount,
            "final_cost": base_amount,
            "discount_rate": 0,
            "discount_xu": 0,
            "tier": get_member_profile(user_id).get("tier") or "newbie",
            "badge": get_role_badge(user_id),
        }
    )
    final_amount = int(charge.get("final_cost") or 0)
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT credits FROM users WHERE user_id=?", (str(user_id),))
    row = c.fetchone()
    if not row or int(row[0] or 0) < final_amount:
        conn.close()
        charge["ok"] = False
        return charge
    c.execute(
        "UPDATE users SET credits = credits - ?, total_spent = total_spent + ? WHERE user_id=?",
        (final_amount, final_amount, str(user_id)),
    )
    discount_note = ""
    if int(charge.get("discount_xu") or 0) > 0:
        discount_note = (
            f" | member_discount tier={charge.get('tier')} "
            f"base={charge.get('base_cost')} rate={charge.get('discount_rate')} "
            f"discount={charge.get('discount_xu')} final={final_amount}"
        )
    record_credit_event(conn, user_id, -final_amount, event_type, "", f"{note}{discount_note}")
    conn.commit()
    conn.close()
    charge["ok"] = True
    return charge

def spend_fixed_credit(user_id, amount, event_type, note="") -> bool:
    return bool(spend_fixed_credit_info(user_id, amount, event_type, note).get("ok"))

def is_payos_order_processed(order_code: str) -> bool:
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT 1 FROM payos_processed WHERE order_code=?", (str(order_code),))
    exists = c.fetchone() is not None
    conn.close()
    return exists

def mark_payos_order_processed(order_code: str):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        "INSERT OR IGNORE INTO payos_processed (order_code, processed_at) VALUES (?,?)",
        (str(order_code), now_text())
    )
    conn.commit()
    conn.close()

PAYMENT_TYPES = {
    "topup_xu",
    "storage_addon",
    "combo_purchase",
    "monthly_package",
    "manual_topup",
}

def normalize_payment_type(value: str = "", order_type: str = "", metadata: dict | None = None) -> str:
    candidate = str(value or "").strip().lower()
    if candidate in PAYMENT_TYPES:
        return candidate
    order = str(order_type or "topup").strip().lower()
    meta = metadata if isinstance(metadata, dict) else {}
    if order in {"topup", "topup_xu", ""}:
        return "topup_xu"
    if order == "storage_addon":
        return "storage_addon"
    if order == "plan_purchase":
        return "monthly_package"
    if order == "package_purchase":
        return "monthly_package" if str(meta.get("package_type") or "").lower() == "monthly" else "combo_purchase"
    if order == "manual_topup":
        return "manual_topup"
    return candidate or order

def payment_package_id(order_type: str = "", plan_id: str = "", metadata: dict | None = None) -> str:
    meta = metadata if isinstance(metadata, dict) else {}
    return str(
        meta.get("package_id")
        or meta.get("package_code")
        or meta.get("item_id")
        or plan_id
        or order_type
        or ""
    ).strip()

def record_payos_processed_conn(
    conn,
    order_code: str,
    payment_type: str,
    apply_status: str = "success",
    payment_link_id: str = "",
    apply_error: str = "",
) -> None:
    conn.execute(
        """INSERT OR IGNORE INTO payos_processed
        (order_code, payment_link_id, payment_type, apply_status, apply_error, processed_at)
        VALUES (?,?,?,?,?,?)""",
        (
            str(order_code),
            str(payment_link_id or ""),
            normalize_payment_type(payment_type),
            str(apply_status or "success"),
            str(apply_error or "")[:300],
            now_text(),
        ),
    )

def create_order(
    order_code,
    user_id,
    amount,
    xu,
    base_xu=0,
    launch_bonus_xu=0,
    package_amount_vnd=None,
    order_type="topup",
    plan_id="",
    plan_name="",
    duration_days=0,
    plan_xu=0,
    metadata_json="",
):
    try:
        metadata = json.loads(metadata_json or "{}") if metadata_json else {}
        if not isinstance(metadata, dict):
            metadata = {}
    except Exception:
        metadata = {}
    payment_type = normalize_payment_type(metadata.get("payment_type"), order_type, metadata)
    package_id = payment_package_id(order_type, plan_id, metadata)
    conn = db_connect()
    c = conn.cursor()
    created_at = datetime.now()
    expires_at = created_at + timedelta(minutes=ORDER_TTL_MINUTES)
    package_vnd = int(amount if package_amount_vnd is None else package_amount_vnd)
    c.execute(
        """INSERT INTO payos_orders
        (order_code, user_id, amount, xu, package_amount_vnd, base_xu, launch_bonus_xu,
         order_type, plan_id, plan_name, duration_days, plan_xu, metadata_json,
         payment_type, package_id, status, created_at, expires_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (str(order_code), str(user_id), amount, xu, package_vnd, int(base_xu or 0), int(launch_bonus_xu or 0),
         str(order_type or "topup"), str(plan_id or ""), str(plan_name or ""), int(duration_days or 0), int(plan_xu or 0), str(metadata_json or ""),
         payment_type, package_id, PAYOS_STATUS_PENDING,
         created_at.strftime("%Y-%m-%d %H:%M:%S"), expires_at.strftime("%Y-%m-%d %H:%M:%S"))
    )
    conn.commit()
    conn.close()

def get_order(order_code):
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT user_id, amount, xu, status, expires_at FROM payos_orders WHERE order_code=?", (str(order_code),))
    row = c.fetchone()
    conn.close()
    return row

def update_order_status(order_code, status):
    conn = db_connect()
    c = conn.cursor()
    c.execute("UPDATE payos_orders SET status=? WHERE order_code=?", (status, str(order_code)))
    conn.commit()
    conn.close()

def update_order_checkout_info(order_code, checkout_url, payment_link_id=""):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        "UPDATE payos_orders SET checkout_url=?, payment_link_id=? WHERE order_code=?",
        (checkout_url, str(payment_link_id), str(order_code))
    )
    conn.commit()
    conn.close()

def get_order_payment_link_id(order_code):
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT payment_link_id FROM payos_orders WHERE order_code=?", (str(order_code),))
    row = c.fetchone()
    conn.close()
    return row[0] if row and row[0] else ""

def package_base_xu(amount_vnd: int) -> int:
    try:
        amount = int(amount_vnd or 0)
    except Exception:
        amount = 0
    return max(0, amount // 100)

def package_launch_bonus_xu(amount_vnd: int) -> int:
    try:
        amount = int(amount_vnd or 0)
    except Exception:
        amount = 0
    return int(LAUNCH_BONUS_BY_AMOUNT.get(amount, 0))

def has_used_launch_bonus(user_id, amount_vnd: int, conn=None) -> bool:
    bonus = package_launch_bonus_xu(amount_vnd)
    if bonus <= 0:
        return True
    own_conn = conn is None
    if own_conn:
        conn = db_connect()
    try:
        cur = conn.cursor()
        cur.execute(
            "SELECT 1 FROM launch_bonus_redemptions WHERE user_id=? AND package_amount_vnd=? LIMIT 1",
            (str(user_id), int(amount_vnd or 0)),
        )
        if cur.fetchone():
            return True
        cur.execute(
            "SELECT 1 FROM payos_orders WHERE user_id=? AND amount=? AND status=? LIMIT 1",
            (str(user_id), int(amount_vnd or 0), PAYOS_STATUS_PAID),
        )
        return bool(cur.fetchone())
    finally:
        if own_conn:
            conn.close()

def calculate_package_credit_for_user(user_id, amount_vnd: int, conn=None) -> dict:
    base_xu = package_base_xu(amount_vnd)
    launch_bonus_available = package_launch_bonus_xu(amount_vnd)
    launch_bonus_eligible = launch_bonus_available > 0 and not has_used_launch_bonus(user_id, amount_vnd, conn=conn)
    launch_bonus = launch_bonus_available if launch_bonus_eligible else 0
    return {
        "base_xu": base_xu,
        "launch_bonus_xu": launch_bonus,
        "launch_bonus_eligible": launch_bonus_eligible,
        "launch_bonus_available": launch_bonus_available,
        "total_xu": base_xu + launch_bonus,
    }

def record_launch_bonus_redemption(conn, user_id, amount_vnd: int, base_xu: int, launch_bonus_xu: int, order_code: str) -> int:
    bonus = int(launch_bonus_xu or 0)
    if bonus <= 0:
        return 0
    note = f"Launch Bonus lan dau mua goi {int(amount_vnd or 0)} VND"
    try:
        conn.execute(
            """INSERT INTO launch_bonus_redemptions
            (user_id, package_amount_vnd, base_xu, order_code, bonus_xu, launch_bonus_xu, status, created_at, note)
            VALUES (?,?,?,?,?,?,?,?,?)""",
            (str(user_id), int(amount_vnd or 0), int(base_xu or 0), str(order_code), int(bonus), int(bonus), "redeemed", now_text(), note),
        )
        return int(bonus)
    except sqlite3.IntegrityError:
        return 0

def redeem_launch_bonus_for_order(conn, user_id, order_code: str, amount_vnd: int) -> int:
    bonus = package_launch_bonus_xu(amount_vnd)
    if bonus <= 0:
        return 0
    if has_used_launch_bonus(user_id, amount_vnd, conn=conn):
        return 0
    return record_launch_bonus_redemption(
        conn,
        user_id,
        amount_vnd,
        package_base_xu(amount_vnd),
        bonus,
        order_code,
    )

def generate_order_code() -> int:
    # payOS hoạt động ổn định hơn với orderCode trong phạm vi số nguyên 32-bit.
    base = int(time.time())
    for _ in range(20):
        code = base + random.randint(0, 999)
        if not get_order(code):
            return code
    return base

def make_payos_return_url(context: ContextTypes.DEFAULT_TYPE) -> str:
    if PAYOS_RETURN_URL:
        return PAYOS_RETURN_URL
    if PUBLIC_BASE_URL:
        return PUBLIC_BASE_URL.rstrip("/") + "/landing"
    bot_name = context.bot.username or BOT_USERNAME
    return f"https://t.me/{bot_name}" if bot_name else "https://t.me"

def make_payos_cancel_url(context: ContextTypes.DEFAULT_TYPE) -> str:
    return PAYOS_CANCEL_URL or make_payos_return_url(context)

def make_payos_description(pkg_key: str) -> str:
    # payOS giới hạn 9 ký tự mô tả với một số kênh ngân hàng chưa liên kết.
    return f"AAS{pkg_key.upper()}"[:9]

def make_payos_plan_description(plan_id: str) -> str:
    # Giữ cùng giới hạn mô tả ngắn của payOS; thông tin đầy đủ lưu trong order metadata.
    return f"AAS{str(plan_id or 'PLAN').upper()}"[:9]

def normalize_plan_id(raw: str | None) -> str:
    plan_id = str(raw or "").strip().lower()
    return plan_id if plan_id in PLAN_CATALOG else ""

def plan_label(plan_id: str) -> str:
    plan = PLAN_CATALOG.get(normalize_plan_id(plan_id) or "")
    return str(plan.get("name") or plan_id or "").strip()

def plan_required_tier_label(plan_id: str) -> str:
    plan = PLAN_CATALOG.get(normalize_plan_id(plan_id) or "")
    required = str(plan.get("required_member_tier") or "").strip()
    if required == "silver":
        return "🥈 Silver trở lên"
    if required == "gold":
        return "🥇 Gold trở lên"
    if required == "gold_or_admin_approve":
        return "🥇 Gold trở lên hoặc admin duyệt"
    return "Thành viên đủ điều kiện"

def user_can_buy_plan(user_id, plan_id: str) -> tuple[bool, str]:
    plan_id = normalize_plan_id(plan_id)
    plan = PLAN_CATALOG.get(plan_id)
    if not plan:
        return False, "Gói tháng không tồn tại."
    if is_admin_user(user_id):
        return True, "admin_bypass"
    profile = get_member_profile(user_id)
    tier = normalize_member_tier(profile.get("tier") or "newbie") or "newbie"
    required = str(plan.get("required_member_tier") or "").strip()
    required_tier = "gold" if required == "gold_or_admin_approve" else required
    if required_tier and member_tier_rank(tier) < member_tier_rank(required_tier):
        return False, f"Gói này yêu cầu từ {plan_required_tier_label(plan_id)}. Hạng hiện tại của bạn: {get_member_badge(tier)}."
    return True, "eligible"

def current_plan_purchase_month(dt: datetime | None = None) -> str:
    dt = dt or vn_now()
    return dt.strftime("%Y-%m")

def monthly_plan_purchase_row(user_id, plan_id: str, purchase_month: str = "", conn=None) -> dict | None:
    plan_id = normalize_plan_id(plan_id)
    if not plan_id:
        return None
    own_conn = conn is None
    if own_conn:
        conn = db_connect()
    try:
        row = conn.execute(
            """SELECT user_id, plan_code, purchase_month, purchase_count, order_code, status, source, created_at, updated_at
               FROM plan_purchases
               WHERE user_id=? AND plan_code=? AND purchase_month=?
               LIMIT 1""",
            (str(user_id), plan_id, purchase_month or current_plan_purchase_month()),
        ).fetchone()
        if not row:
            return None
        return {
            "user_id": row[0],
            "plan_code": row[1],
            "purchase_month": row[2],
            "purchase_count": int(row[3] or 0),
            "order_code": row[4] or "",
            "status": row[5] or "",
            "source": row[6] or "",
            "created_at": row[7] or "",
            "updated_at": row[8] or "",
        }
    finally:
        if own_conn:
            conn.close()

def monthly_plan_purchase_block_message(plan_id: str, purchase_month: str = "") -> str:
    label = plan_label(plan_id) or str(plan_id or "").title()
    month = purchase_month or current_plan_purchase_month()
    return (
        f"Bạn đã mua gói {label} trong tháng {month}. "
        f"Mỗi gói chỉ mua 1 lần/tháng. Bạn có thể dùng gói khác nếu đủ điều kiện hoặc chờ tháng sau."
    )

def can_purchase_monthly_plan(user_id, plan_id: str, purchase_month: str = "", conn=None) -> tuple[bool, str]:
    row = monthly_plan_purchase_row(user_id, plan_id, purchase_month=purchase_month, conn=conn)
    if row and str(row.get("status") or "").lower() in {"paid", "active"}:
        return False, monthly_plan_purchase_block_message(plan_id, row.get("purchase_month") or purchase_month)
    return True, "eligible"

def record_monthly_plan_purchase_conn(conn, user_id, plan_id: str, order_code: str = "", status: str = "active", source: str = "payos") -> None:
    plan_id = normalize_plan_id(plan_id)
    if not plan_id:
        return
    month = current_plan_purchase_month()
    now = now_text()
    conn.execute(
        """INSERT INTO plan_purchases
        (user_id, plan_code, purchase_month, purchase_count, order_code, status, source, created_at, updated_at)
        VALUES (?,?,?,?,?,?,?,?,?)
        ON CONFLICT(user_id, plan_code, purchase_month) DO UPDATE SET
            purchase_count=CASE
                WHEN plan_purchases.status IN ('paid','active') THEN plan_purchases.purchase_count
                ELSE plan_purchases.purchase_count + 1
            END,
            order_code=excluded.order_code,
            status=excluded.status,
            source=excluded.source,
            updated_at=excluded.updated_at""",
        (str(user_id), plan_id, month, 1, str(order_code or ""), str(status or "active"), str(source or ""), now, now),
    )

def get_user_plan(user_id, conn=None) -> dict:
    own_conn = conn is None
    if own_conn:
        conn = db_connect()
    try:
        row = conn.execute(
            """SELECT current_plan, plan_name, plan_started_at, plan_expires_at,
                      plan_xu_monthly, plan_xu_remaining, plan_status, order_code
               FROM user_plans WHERE user_id=?""",
            (str(user_id),),
        ).fetchone()
        if not row:
            return {"active": False, "plan_status": "inactive"}
        status = str(row[6] or "inactive")
        expires_at = str(row[3] or "")
        active = status == "active" and (not expires_at or expires_at >= now_text())
        return {
            "active": bool(active),
            "current_plan": row[0] or "",
            "plan_name": row[1] or "",
            "plan_started_at": row[2] or "",
            "plan_expires_at": expires_at,
            "plan_xu_monthly": int(row[4] or 0),
            "plan_xu_remaining": int(row[5] or 0),
            "plan_status": status,
            "order_code": row[7] or "",
        }
    finally:
        if own_conn:
            conn.close()

def activate_user_plan_conn(conn, user_id, plan_id: str, days: int | None = None, order_code: str = "", source: str = "payos") -> dict:
    plan_id = normalize_plan_id(plan_id)
    if not plan_id:
        raise ValueError("invalid_plan")
    plan = PLAN_CATALOG[plan_id]
    duration_days = int(days or plan["duration_days"])
    started_dt = datetime.now()
    expires_dt = started_dt + timedelta(days=duration_days)
    started_at = started_dt.strftime("%Y-%m-%d %H:%M:%S")
    expires_at = expires_dt.strftime("%Y-%m-%d %H:%M:%S")
    plan_xu = int(plan["plan_xu"])
    conn.execute(
        """INSERT INTO user_plans
        (user_id, current_plan, plan_name, plan_started_at, plan_expires_at,
         plan_xu_monthly, plan_xu_remaining, plan_status, order_code, updated_at)
        VALUES (?,?,?,?,?,?,?,?,?,?)
        ON CONFLICT(user_id) DO UPDATE SET
            current_plan=excluded.current_plan,
            plan_name=excluded.plan_name,
            plan_started_at=excluded.plan_started_at,
            plan_expires_at=excluded.plan_expires_at,
            plan_xu_monthly=excluded.plan_xu_monthly,
            plan_xu_remaining=excluded.plan_xu_remaining,
            plan_status=excluded.plan_status,
            order_code=excluded.order_code,
            updated_at=excluded.updated_at""",
        (str(user_id), plan_id, plan["name"], started_at, expires_at, plan_xu, plan_xu, "active", str(order_code or ""), now_text()),
    )
    record_monthly_plan_purchase_conn(conn, user_id, plan_id, order_code=order_code, status="active", source=source)
    record_usage_event_conn(
        conn,
        user_id,
        event_type="plan_activated",
        tool_name="subscription",
        command="/buy_plan" if source == "payos" else "/admin_grant_plan",
        status="active",
        xu_delta=0,
        amount_vnd=int(plan.get("price_vnd") or 0) if source == "payos" else 0,
        provider=source,
        detail=f"plan={plan_id}; days={duration_days}; plan_xu={plan_xu}; order={order_code}",
    )
    record_audit(
        conn,
        source,
        "system" if source == "payos" else "admin",
        "plan.activated",
        "user_plan",
        str(user_id),
        before=None,
        after={"plan": plan_id, "expires_at": expires_at, "plan_xu": plan_xu, "order_code": str(order_code or "")},
        note="Monthly plan activated; not counted as member top-up",
    )
    return {
        "user_id": str(user_id),
        "plan_id": plan_id,
        "plan_name": plan["name"],
        "duration_days": duration_days,
        "plan_xu": plan_xu,
        "started_at": started_at,
        "expires_at": expires_at,
        "order_code": str(order_code or ""),
    }

def revoke_user_plan_conn(conn, user_id, admin_id="") -> dict:
    before = get_user_plan(user_id, conn=conn)
    conn.execute(
        """INSERT INTO user_plans
        (user_id, current_plan, plan_name, plan_status, plan_xu_monthly, plan_xu_remaining, updated_at)
        VALUES (?,?,?,?,?,?,?)
        ON CONFLICT(user_id) DO UPDATE SET
            plan_status='revoked',
            plan_xu_remaining=0,
            updated_at=excluded.updated_at""",
        (str(user_id), "", "", "revoked", 0, 0, now_text()),
    )
    record_audit(
        conn,
        admin_id or "admin",
        "admin",
        "plan.revoked",
        "user_plan",
        str(user_id),
        before=before,
        after={"plan_status": "revoked"},
        note="Admin revoked monthly plan",
    )
    return before

def resolve_payment_package_arg(raw_arg: str | None, default_key: str = "50k") -> tuple[str, dict] | None:
    token = str(raw_arg or default_key or "").strip().lower()
    if not token:
        token = default_key
    if token in PAYMENT_PACKAGES:
        return token, PAYMENT_PACKAGES[token]
    normalized = token.replace(".", "").replace(",", "")
    try:
        if normalized.endswith("k"):
            amount = int(normalized[:-1]) * 1000
        else:
            amount = int(normalized)
    except (TypeError, ValueError):
        return None
    for key, pkg in PAYMENT_PACKAGES.items():
        if int(pkg.get("amount") or 0) == amount:
            return key, pkg
    return None

