PAYOS_FAILURE_EVENTS: list[dict] = []
PAYOS_LAST_ALERT_AT = 0.0
PAYOS_ALERT_MUTED_UNTIL = 0.0

def payos_alert_keyboard() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("💵 Mở nạp thủ công", callback_data="payosalert|manual"), InlineKeyboardButton("🧪 Test PayOS", callback_data="payosalert|test")],
        [InlineKeyboardButton("🔕 Tắt cảnh báo 1 giờ", callback_data="payosalert|mute")],
    ])

def record_payos_failure(reason: str, user_id="", now_ts: float | None = None) -> dict:
    global PAYOS_FAILURE_EVENTS
    timestamp = float(now_ts if now_ts is not None else time.time())
    cutoff = timestamp - (10 * 60)
    PAYOS_FAILURE_EVENTS = [item for item in PAYOS_FAILURE_EVENTS if float(item.get("timestamp") or 0) >= cutoff]
    event = {
        "timestamp": timestamp,
        "reason": sanitize_log_text(str(reason or "PayOS unavailable"))[:240],
        "user_id": str(user_id or ""),
    }
    PAYOS_FAILURE_EVENTS.append(event)
    return {"count": len(PAYOS_FAILURE_EVENTS), "latest": event}

async def record_payos_failure_and_maybe_alert(context, reason: str, user_id="", now_ts: float | None = None) -> bool:
    global PAYOS_LAST_ALERT_AT
    payload = record_payos_failure(reason, user_id=user_id, now_ts=now_ts)
    timestamp = float(now_ts if now_ts is not None else time.time())
    cooldown_seconds = PAYOS_ALERT_COOLDOWN_MINUTES * 60
    if payload["count"] < 3 or timestamp < PAYOS_ALERT_MUTED_UNTIL or (PAYOS_LAST_ALERT_AT and timestamp - PAYOS_LAST_ALERT_AT < cooldown_seconds):
        return False
    latest = payload["latest"]
    text = (
        "🚨 <b>Cảnh báo PayOS</b>\n\n"
        "Tình trạng: PayOS QR tạo lỗi liên tiếp.\n"
        f"Số lần lỗi trong 10 phút: <b>{payload['count']}</b>\n"
        f"Lỗi gần nhất: <code>{html.escape(latest['reason'])}</code>\n"
        f"Thời gian: <code>{datetime.now().strftime('%d/%m/%Y %H:%M:%S')}</code>\n"
        f"User bị ảnh hưởng: <code>{html.escape(latest['user_id'] or '-')}</code>\n\n"
        "Gợi ý: kiểm tra bộ ENV PayOS, trạng thái đăng ký và dùng nạp thủ công trong thời gian gián đoạn."
    )
    sent = False
    for admin_id in owner_and_admin_ids():
        try:
            await context.bot.send_message(chat_id=admin_id, text=text, parse_mode="HTML", reply_markup=payos_alert_keyboard())
            sent = True
        except Exception as exc:
            logger.warning("PayOS alert send skipped: %s", type(exc).__name__)
    if sent:
        PAYOS_LAST_ALERT_AT = timestamp
    return sent

def payos_expiry_days_remaining(today=None) -> int | None:
    if not PAYOS_REGISTRATION_EXPIRES_AT:
        return None
    try:
        expiry = datetime.strptime(PAYOS_REGISTRATION_EXPIRES_AT, "%Y-%m-%d").date()
    except ValueError:
        return None
    current = today or datetime.now().date()
    return (expiry - current).days

def payos_expiry_keyboard() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("🧪 Test PayOS", callback_data="payosalert|test"), InlineKeyboardButton("💵 Mở nạp thủ công", callback_data="payosalert|manual")],
        [InlineKeyboardButton("✅ Đã gia hạn", callback_data="payosalert|renewed"), InlineKeyboardButton("🔕 Nhắc lại sau", callback_data="payosalert|remind_later")],
    ])

async def maybe_send_payos_expiry_reminder(bot_client, today=None) -> bool:
    if not PAYOS_EXPIRY_ALERT_ENABLED:
        return False
    days = payos_expiry_days_remaining(today=today)
    if days is None or days not in PAYOS_EXPIRY_REMINDER_DAYS:
        return False
    reminder_key = f"{PAYOS_REGISTRATION_EXPIRES_AT}:{days}"
    if get_system_setting("payos_expiry_last_reminder", "") == reminder_key:
        return False
    text = (
        "⏰ <b>Nhắc gia hạn PayOS</b>\n\n"
        f"PayOS của TOAN AAS dự kiến hết hạn vào: <code>{html.escape(PAYOS_REGISTRATION_EXPIRES_AT)}</code>\n"
        f"Còn khoảng: <b>{days} ngày</b>\n\n"
        "Bạn nên kiểm tra/gia hạn để tránh QR động bị gián đoạn."
    )
    sent = False
    for admin_id in owner_and_admin_ids():
        try:
            await bot_client.send_message(chat_id=admin_id, text=text, parse_mode="HTML", reply_markup=payos_expiry_keyboard())
            sent = True
        except Exception as exc:
            logger.warning("PayOS expiry reminder skipped: %s", type(exc).__name__)
    if sent:
        set_system_setting("payos_expiry_last_reminder", reminder_key, note="PayOS expiry reminder sent", updated_by="system")
    return sent

async def payos_expiry_monitor_loop(bot_client):
    while True:
        try:
            await maybe_send_payos_expiry_reminder(bot_client)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.warning("PayOS expiry monitor skipped: %s", type(exc).__name__)
        await asyncio.sleep(24 * 60 * 60)

def payos_package_callback_data(pkg_key: str, uid) -> str:
    return f"payos_pkg|{pkg_key}|{uid}"

def manual_package_callback_data(pkg_key: str, uid) -> str:
    return f"manual|start|{pkg_key}|{uid}"

PAYOS_CREATE_SIGNATURE_DEFAULT_VARIANT = "standard_sorted"
PAYOS_CREATE_SIGNATURE_FIELDS = ("amount", "cancelUrl", "description", "orderCode", "returnUrl")
PAYOS_CREATE_SIGNATURE_VARIANTS = {
    "standard_sorted": PAYOS_CREATE_SIGNATURE_FIELDS,
    "faq_order": ("amount", "orderCode", "description", "returnUrl", "cancelUrl"),
    "payload_order": ("orderCode", "amount", "description", "cancelUrl", "returnUrl"),
}
PAYOS_OFFICIAL_CREATE_SIGNATURE_NOTE = (
    "Official payOS create payment link signature data: "
    "amount,cancelUrl,description,orderCode,returnUrl"
)
PAYOS_CREATE_PAYMENT_ENDPOINT = "https://api-merchant.payos.vn/v2/payment-requests"
PAYOS_DEBUG_SIGNATURE_VARIANTS = ("standard_sorted",)

def normalize_payos_signature_variant(variant: str | None) -> str:
    variant = str(variant or "").strip().lower()
    if variant in PAYOS_CREATE_SIGNATURE_VARIANTS or variant == "sorted_all_payload_keys":
        return variant
    return PAYOS_CREATE_SIGNATURE_DEFAULT_VARIANT

def payos_signature_fields_for_variant(payload: dict, variant: str | None = None) -> tuple[str, ...]:
    variant = normalize_payos_signature_variant(variant)
    if variant == "sorted_all_payload_keys":
        return tuple(sorted(key for key in payload.keys() if key != "signature"))
    return PAYOS_CREATE_SIGNATURE_VARIANTS[variant]

def build_payos_signature_data(payload: dict, variant: str | None = None) -> str:
    fields = payos_signature_fields_for_variant(payload, variant)
    missing = [key for key in fields if key not in payload]
    if missing:
        raise KeyError(f"Missing PayOS signature field(s): {', '.join(missing)}")
    return "&".join(f"{key}={payload[key]}" for key in fields)

def payos_payload_type_summary(payload: dict) -> str:
    return (
        f"orderCode type={type(payload.get('orderCode')).__name__}; "
        f"amount type={type(payload.get('amount')).__name__}; "
        f"description length={len(str(payload.get('description') or ''))}; "
        f"cancelUrl={payload.get('cancelUrl')}; "
        f"returnUrl={payload.get('returnUrl')}"
    )

def mask_payos_signature(signature: str) -> str:
    signature = str(signature or "")
    if len(signature) <= 16:
        return "***" if signature else "missing"
    return signature[:8] + "***" + signature[-8:]

def mask_key_fingerprint(value: str) -> str:
    value = str(value or "")
    if not value:
        return "missing"
    if len(value) <= 8:
        return value[:2] + "***" + value[-2:]
    return value[:4] + "***" + value[-4:]

def env_strip_diagnostic(name: str, value: str) -> dict:
    raw = os.environ.get(name, "")
    stripped = str(raw or "").strip()
    return {
        "configured": bool(str(value or "")),
        "raw_len": len(str(raw or "")),
        "stripped_len": len(stripped),
        "stripped_differs": str(raw or "") != stripped,
    }

def payos_header_debug_summary() -> list[str]:
    return [
        f"• x-client-id: <code>{'yes' if PAYOS_CLIENT_ID else 'no'}</code>",
        f"• x-api-key: <code>{'yes' if PAYOS_API_KEY else 'no'}</code>",
        "• Content-Type: <code>application/json</code>",
    ]

def payos_sdk_availability() -> tuple[bool, str]:
    for module_name in ("payos", "payos_sdk"):
        try:
            __import__(module_name)
            return True, module_name
        except Exception:
            continue
    return False, ""

def get_payos_create_signature_variant() -> str:
    # Customer payment creation must always use the PayOS documented order.
    # Debug variants are admin-only and must not override live /naptien.
    return PAYOS_CREATE_SIGNATURE_DEFAULT_VARIANT

def sign_payos_payment_request(data: dict, variant: str | None = None) -> tuple[str, str]:
    raw_str = build_payos_signature_data(data, variant or PAYOS_CREATE_SIGNATURE_DEFAULT_VARIANT)
    signature = hmac.new(
        PAYOS_CHECKSUM_KEY.encode("utf-8"),
        raw_str.encode("utf-8"),
        hashlib.sha256
    ).hexdigest()
    return signature, raw_str

def parse_payos_response_safe(res) -> tuple[dict, str]:
    try:
        data = res.json()
        if isinstance(data, dict):
            return data, ""
        return {}, str(data)[:500]
    except Exception:
        return {}, (getattr(res, "text", "") or "")[:500]

def format_payos_create_debug(
    http_status,
    res_data: dict,
    raw_preview: str,
    order_code: int,
    amount: int,
    description: str,
    cancel_url: str,
    return_url: str,
    signature_data: str,
    signature_variant: str = "standard",
    html_mode: bool = False,
) -> str:
    data = res_data if isinstance(res_data, dict) else {}
    payos_code = data.get("code", "")
    payos_desc = data.get("desc", "") or data.get("description", "")
    payos_message = data.get("message", "")
    if isinstance(data.get("data"), dict):
        payos_message = payos_message or data["data"].get("message", "") or data["data"].get("desc", "")
    if html_mode:
        def val(value):
            return f"<code>{html.escape(str(value))}</code>"
        signature_line = f"<code>{html.escape(signature_data)}</code>"
        raw_line = f"\nRaw: {val(raw_preview[:500])}" if raw_preview else ""
    else:
        def val(value):
            return str(value)
        signature_line = str(signature_data)
        raw_line = f"\nRaw: {raw_preview[:500]}" if raw_preview else ""
    return (
        f"HTTP: {val(http_status or 'UNKNOWN')}\n"
        f"Code: {val(payos_code or '')}\n"
        f"Desc: {val(payos_desc or '')}\n"
        f"Message: {val(payos_message or '')}\n"
        f"Order: {val(order_code)}\n"
        f"Amount: {val(amount)}\n"
        f"Description: {val(description)}\n"
        f"Cancel URL: {val(cancel_url)}\n"
        f"Return URL: {val(return_url)}\n"
        f"Signature variant: {val(signature_variant)}\n"
        f"Signature data:\n{signature_line}"
        f"{raw_line}"
    )

async def create_payos_payment_request(payos_body: dict, signature_variant: str | None = None) -> tuple[object, dict, str, str]:
    # Live checkout creation follows payOS official/SDK create-payment signature order:
    # amount, cancelUrl, description, orderCode, returnUrl. Do not URL-encode before signing.
    active_variant = normalize_payos_signature_variant(signature_variant) if signature_variant else get_payos_create_signature_variant()
    signature, raw_str = sign_payos_payment_request(payos_body, active_variant)
    request_body = {**payos_body, "signature": signature}
    headers = {
        "x-client-id": PAYOS_CLIENT_ID,
        "x-api-key": PAYOS_API_KEY,
        "Content-Type": "application/json"
    }
    async with httpx.AsyncClient() as client:
        res = await client.post(
            PAYOS_CREATE_PAYMENT_ENDPOINT,
            headers=headers,
            json=request_body,
            timeout=30.0
        )
    res_data, raw_preview = parse_payos_response_safe(res)
    return res, res_data, raw_preview, raw_str

def web_billing_api_url(path: str = "/billing/create-payment-link") -> str:
    base = (WEB_BILLING_API_BASE_URL or "").strip().rstrip("/")
    return base + "/" + str(path or "").strip().lstrip("/") if base else ""

def web_billing_checkout_enabled(payment_type: str = "") -> bool:
    return bool(
        WEB_BILLING_ENABLED
        and WEB_BILLING_APPLY_CONFIRMED
        and WEB_BILLING_API_BASE_URL
        and WEB_BILLING_API_TOKEN
        and normalize_payment_type(payment_type) in {"topup_xu", "storage_addon", "combo_purchase", "monthly_package"}
    )

def web_billing_bridge_status_payload() -> dict:
    endpoint = web_billing_api_url("/billing/create-payment-link")
    safe_base = (WEB_BILLING_API_BASE_URL or "").strip().rstrip("/")
    return {
        "web_billing_enabled": bool(WEB_BILLING_ENABLED),
        "apply_confirmed": bool(WEB_BILLING_APPLY_CONFIRMED),
        "api_base": safe_base,
        "api_token_configured": bool(WEB_BILLING_API_TOKEN),
        "create_payment_endpoint": endpoint,
        "payos_webhook_target": PAYOS_WEBHOOK_URL,
        "return_url": PAYOS_RETURN_URL or "auto",
        "cancel_url": PAYOS_CANCEL_URL or "auto",
        "bot_fallback_enabled": bool(BOT_PAYOS_FALLBACK_ENABLED),
        "storage_addon_enabled": True,
        "risk_double_webhook": bool(WEB_BILLING_APPLY_CONFIRMED and BOT_PAYOS_FALLBACK_ENABLED),
        "safe_to_route_customer_payments": bool(web_billing_checkout_enabled("topup_xu") and not BOT_PAYOS_FALLBACK_ENABLED),
    }

def build_web_billing_payment_payload(
    user_id,
    payment_type: str,
    package_id: str,
    amount: int,
    metadata: dict | None = None,
) -> dict:
    payment_type = normalize_payment_type(payment_type)
    safe_metadata = dict(metadata or {})
    safe_metadata.update({
        "bot": "toanaas",
        "telegram_user_id": str(user_id),
        "return_url": PAYOS_RETURN_URL or "",
        "cancel_url": PAYOS_CANCEL_URL or "",
    })
    return {
        "source": "telegram",
        "user_id": str(user_id),
        "payment_type": payment_type,
        "package_id": str(package_id or payment_type),
        "amount": int(amount or 0),
        "metadata": safe_metadata,
    }

def normalize_billing_checkout_response(data: dict) -> dict:
    payload = data if isinstance(data, dict) else {}
    nested = payload.get("data") if isinstance(payload.get("data"), dict) else {}
    checkout_url = (
        payload.get("checkoutUrl")
        or payload.get("checkout_url")
        or nested.get("checkoutUrl")
        or nested.get("checkout_url")
        or ""
    )
    order_code = payload.get("orderCode") or payload.get("order_code") or nested.get("orderCode") or nested.get("order_code") or ""
    payment_link_id = payload.get("paymentLinkId") or payload.get("payment_link_id") or nested.get("paymentLinkId") or nested.get("payment_link_id") or ""
    ok = bool(checkout_url and (payload.get("success") is True or payload.get("code") == "00" or nested or payload.get("ok") is True))
    return {
        "ok": ok,
        "checkout_url": str(checkout_url or ""),
        "order_code": str(order_code or ""),
        "payment_link_id": str(payment_link_id or ""),
        "message": str(payload.get("message") or payload.get("desc") or nested.get("message") or nested.get("desc") or "")[:240],
    }

async def create_web_billing_payment_link(payload: dict) -> dict:
    if not WEB_BILLING_ENABLED:
        return {"ok": False, "reason": "web_billing_disabled"}
    if not WEB_BILLING_API_TOKEN:
        return {"ok": False, "reason": "missing_web_billing_token"}
    endpoint = web_billing_api_url("/billing/create-payment-link")
    if not endpoint:
        return {"ok": False, "reason": "missing_web_billing_base_url"}
    headers = {
        "Authorization": f"Bearer {WEB_BILLING_API_TOKEN}",
        "Content-Type": "application/json",
    }
    try:
        async with httpx.AsyncClient() as client:
            res = await client.post(endpoint, headers=headers, json=payload, timeout=20.0)
        try:
            data = res.json()
        except Exception:
            data = {}
        normalized = normalize_billing_checkout_response(data)
        normalized.update({"http_status": int(getattr(res, "status_code", 0) or 0), "endpoint": endpoint})
        if getattr(res, "status_code", 0) >= 400 and not normalized.get("ok"):
            normalized["reason"] = "web_billing_http_error"
        return normalized
    except Exception as exc:
        return {"ok": False, "reason": type(exc).__name__, "message": "web billing request failed"}

