def create_gift_code_record(conn, code: str, xu: int, usage_limit=1, per_user_limit=1, note="", created_by="", requires_assignment=None) -> tuple[bool, str]:
    norm_code = normalize_promo_code(code)
    xu = int(xu or 0)
    if not norm_code:
        return False, "missing_code"
    if xu <= 0:
        return False, "invalid_xu"
    c = conn.cursor()
    c.execute("SELECT promo_type FROM promotion_codes WHERE code=?", (norm_code,))
    existing = c.fetchone()
    assignment_required = 1 if (is_beta_gift_code(norm_code) if requires_assignment is None else bool(requires_assignment)) else 0
    if existing:
        if is_beta_gift_code(norm_code):
            c.execute(
                "UPDATE promotion_codes SET requires_assignment=1, updated_at=? WHERE code=? AND promo_type='gift_xu'",
                (now_text(), norm_code),
            )
        return False, "exists"
    now = now_text()
    c.execute(
        """INSERT INTO promotion_codes
        (code, bonus_xu, discount_percent, max_uses, used_count, min_amount, status, note, created_at, updated_at,
         name, promo_type, value, min_amount_vnd, max_bonus_xu, usage_limit, usage_count, per_user_limit, created_by, requires_assignment)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            norm_code,
            xu,
            0,
            int(usage_limit or 0),
            0,
            0,
            "active",
            str(note or ""),
            now,
            now,
            norm_code,
            "gift_xu",
            xu,
            0,
            xu,
            int(usage_limit or 0),
            0,
            max(1, int(per_user_limit or 1)),
            str(created_by or ADMIN_ID),
            assignment_required,
        ),
    )
    return True, "created"

def seed_beta_gift_codes(conn=None, created_by="") -> dict:
    own_conn = conn is None
    if own_conn:
        conn = db_connect()
    seeded = {}
    try:
        for code, xu, limit, per_user, note in DEFAULT_BETA_GIFT_CODES:
            ok, status = create_gift_code_record(
                conn,
                code,
                xu,
                usage_limit=limit,
                per_user_limit=per_user,
                note=note,
                created_by=created_by or ADMIN_ID,
                requires_assignment=True,
            )
            seeded[code] = {"ok": ok, "status": status, "xu": xu, "limit": limit, "per_user": per_user}
        if own_conn:
            conn.commit()
    finally:
        if own_conn:
            conn.close()
    return seeded

def user_paid_payos_count(conn, user_id) -> int:
    c = conn.cursor()
    c.execute(
        "SELECT COUNT(*) FROM payos_orders WHERE user_id=? AND status=? AND COALESCE(order_type,'topup')='topup'",
        (str(user_id), PAYOS_STATUS_PAID),
    )
    return int((c.fetchone() or [0])[0] or 0)

def user_successful_topup_count(conn, user_id, exclude_order_code="") -> int:
    uid = str(user_id)
    excluded = str(exclude_order_code or "").strip()
    payment_refs = set()
    fallback_events = set()
    c = conn.cursor()

    c.execute(
        "SELECT DISTINCT order_code FROM payos_orders WHERE user_id=? AND status=? AND COALESCE(order_type,'topup')='topup'",
        (uid, PAYOS_STATUS_PAID),
    )
    for row in c.fetchall():
        ref = str((row[0] if row else "") or "").strip()
        if ref and ref != excluded:
            payment_refs.add(ref)

    try:
        c.execute(
            "SELECT id, order_code FROM pending_deposits WHERE user_id=? AND status='approved'",
            (uid,),
        )
        for row in c.fetchall():
            deposit_id = str(row[0] or "").strip()
            ref = str(row[1] or "").strip()
            if ref:
                if ref != excluded:
                    payment_refs.add(ref)
            elif deposit_id:
                fallback_events.add(f"pending:{deposit_id}")
    except Exception:
        pass

    try:
        c.execute(
            """SELECT id, ref_id FROM credit_events
            WHERE user_id=? AND event_type IN ('manual_deposit','payos_paid','payos_deposit','admin_manual_deposit')""",
            (uid,),
        )
        for row in c.fetchall():
            ref = str(row[1] or "").strip()
            if ref:
                if ref != excluded and ref not in payment_refs:
                    payment_refs.add(ref)
    except Exception:
        pass

    return len(payment_refs) + len(fallback_events)

def count_user_promo_usage(conn, user_id, code: str) -> int:
    c = conn.cursor()
    c.execute(
        """SELECT COUNT(*) FROM promotion_redemptions
        WHERE user_id=? AND code=? AND status IN ('applied','redeemed','success')""",
        (str(user_id), normalize_promo_code(code)),
    )
    return int((c.fetchone() or [0])[0] or 0)

def count_user_gift_usage(conn, user_id, code: str) -> int:
    c = conn.cursor()
    c.execute(
        "SELECT COUNT(*) FROM gift_redemptions WHERE user_id=? AND code=? AND status='redeemed'",
        (str(user_id), normalize_promo_code(code)),
    )
    return int((c.fetchone() or [0])[0] or 0)

def count_gift_usage(conn, code: str) -> int:
    c = conn.cursor()
    c.execute(
        "SELECT COUNT(*) FROM gift_redemptions WHERE code=? AND status='redeemed'",
        (normalize_promo_code(code),),
    )
    return int((c.fetchone() or [0])[0] or 0)

def get_gift_assignment(conn, user_id, code: str) -> dict:
    c = conn.cursor()
    c.execute(
        """SELECT id, code, user_id, assigned_by, status, assigned_at, redeemed_at, note
        FROM gift_assignments WHERE code=? AND user_id=? LIMIT 1""",
        (normalize_promo_code(code), str(user_id)),
    )
    row = c.fetchone()
    if not row:
        return {}
    keys = ["id", "code", "user_id", "assigned_by", "status", "assigned_at", "redeemed_at", "note"]
    return dict(zip(keys, row))

def upsert_gift_assignment(conn, code: str, user_id, assigned_by, status="assigned", note="") -> dict:
    norm_code = normalize_promo_code(code)
    now = now_text()
    conn.execute(
        """INSERT INTO gift_assignments (code, user_id, assigned_by, status, assigned_at, note)
        VALUES (?,?,?,?,?,?)
        ON CONFLICT(code, user_id) DO UPDATE SET
            assigned_by=excluded.assigned_by,
            status=CASE WHEN gift_assignments.status='redeemed' THEN gift_assignments.status ELSE excluded.status END,
            assigned_at=COALESCE(gift_assignments.assigned_at, excluded.assigned_at),
            note=excluded.note""",
        (norm_code, str(user_id), str(assigned_by or ""), status, now, str(note or "")),
    )
    return get_gift_assignment(conn, user_id, norm_code)

def telegram_user_contact_text(user) -> tuple[str, str, str]:
    username = (getattr(user, "username", None) or "").strip()
    full_name = " ".join(
        p for p in [
            (getattr(user, "first_name", None) or "").strip(),
            (getattr(user, "last_name", None) or "").strip(),
        ]
        if p
    ).strip()
    contact_url = f"https://t.me/{username}" if username else ""
    return username, full_name, contact_url

def record_beta_gift_request(user, code: str) -> dict:
    norm_code = normalize_promo_code(code)
    if not user or not norm_code or not is_beta_gift_code(norm_code):
        return {"status": "ignored", "notify_admin": False}
    uid = str(getattr(user, "id", ""))
    username, full_name, contact_url = telegram_user_contact_text(user)
    now = now_text()
    conn = db_connect()
    try:
        c = conn.cursor()
        c.execute(
            """SELECT id, notify_count, first_requested_at
            FROM gift_beta_requests
            WHERE code=? AND user_id=? AND status='pending'
            LIMIT 1""",
            (norm_code, uid),
        )
        row = c.fetchone()
        if row:
            request_id, notify_count, first_requested_at = row
            c.execute(
                """UPDATE gift_beta_requests
                SET last_requested_at=?, notify_count=COALESCE(notify_count,0)+1,
                    username=?, full_name=?, contact_url=?
                WHERE id=?""",
                (now, username, full_name, contact_url, request_id),
            )
            conn.commit()
            return {
                "status": "pending",
                "notify_admin": False,
                "id": request_id,
                "notify_count": int(notify_count or 0) + 1,
                "first_requested_at": first_requested_at or "",
            }
        c.execute(
            """INSERT INTO gift_beta_requests
            (code, user_id, username, full_name, contact_url, status, first_requested_at, last_requested_at, notify_count, note)
            VALUES (?,?,?,?,?,?,?,?,?,?)""",
            (norm_code, uid, username, full_name, contact_url, "pending", now, now, 1, "User requested assigned beta gift code"),
        )
        request_id = c.lastrowid
        conn.commit()
        return {"status": "created", "notify_admin": True, "id": request_id, "notify_count": 1, "first_requested_at": now}
    finally:
        conn.close()

def mark_beta_gift_request_approved(conn, code: str, user_id) -> int:
    norm_code = normalize_promo_code(code)
    if not norm_code or not is_beta_gift_code(norm_code):
        return 0
    cur = conn.execute(
        """UPDATE gift_beta_requests
        SET status='approved', last_requested_at=?, note='Approved by admin gift grant'
        WHERE code=? AND user_id=? AND status='pending'""",
        (now_text(), norm_code, str(user_id)),
    )
    return int(cur.rowcount or 0)

