async def notify_admin_beta_gift_request(update: Update, context: ContextTypes.DEFAULT_TYPE, code: str) -> str:
    user = update.effective_user
    if not user or not ADMIN_ID:
        return "ignored"
    norm_code = normalize_promo_code(code)
    if not is_beta_gift_code(norm_code):
        return "ignored"
    request = record_beta_gift_request(user, norm_code)
    if not request.get("notify_admin"):
        return str(request.get("status") or "pending")
    username, full_name, contact_url = telegram_user_contact_text(user)
    username_line = f"@{html.escape(username)}" if username else "không có"
    full_name_line = html.escape(full_name or "không có")
    contact_line = html.escape(contact_url) if contact_url else "không có username, hãy dùng ID hoặc đợi user nhắn admin."
    text = (
        "🎁 <b>USER YÊU CẦU MÃ BETA</b>\n\n"
        "User vừa nhập mã nhưng chưa được cấp quyền.\n\n"
        f"• Request ID: <code>{html.escape(str(request.get('id') or '-'))}</code>\n"
        f"• Mã user nhập: <code>{html.escape(norm_code)}</code>\n"
        f"• User ID: <code>{html.escape(str(user.id))}</code>\n"
        f"• Username: {username_line}\n"
        f"• Tên hiển thị: {full_name_line}\n"
        f"• Liên hệ: {contact_line}\n\n"
        "Nếu muốn cấp, admin dùng:\n"
        f"<code>/gift {html.escape(norm_code)} {html.escape(str(user.id))}</code>\n\n"
        "Nếu không đủ điều kiện thì bỏ qua."
    )
    try:
        await context.bot.send_message(chat_id=int(ADMIN_ID), text=text, parse_mode="HTML")
        return "created"
    except Exception as e:
        logger.warning(f"Could not notify admin about beta gift request: {e}")
        return "created_notify_failed"

def validate_gift_code(user_id, code: str, conn=None) -> tuple[bool, dict, str]:
    norm_code = normalize_promo_code(code)
    if not norm_code:
        return False, {"code": ""}, "missing_code"
    own_conn = conn is None
    if own_conn:
        conn = db_connect()
    try:
        promo = get_promo_code_dict(conn, norm_code)
        if not promo:
            return False, {"code": norm_code}, "not_found"
        if not is_gift_promo(promo):
            return False, promo, "not_gift"
        status = str(promo.get("status") or "").lower()
        if status != "active":
            return False, promo, "inactive"
        now = now_text()
        if promo.get("starts_at") and str(promo["starts_at"]) > now:
            return False, promo, "not_started"
        if promo.get("ends_at") and str(promo["ends_at"]) < now:
            return False, promo, "expired"
        value = int(promo.get("value") or promo.get("bonus_xu") or 0)
        if value <= 0:
            return False, promo, "invalid_value"
        limit = promo_usage_limit(promo)
        total_used = max(promo_usage_count(promo), count_gift_usage(conn, norm_code))
        if limit > 0 and total_used >= limit:
            return False, promo, "sold_out"
        per_user_limit = max(1, int(promo.get("per_user_limit") or 1))
        if count_user_gift_usage(conn, user_id, norm_code) >= per_user_limit:
            return False, promo, "already_applied"
        if gift_requires_assignment(promo):
            assignment = get_gift_assignment(conn, user_id, norm_code)
            if not assignment:
                return False, promo, "assignment_required"
            assign_status = str(assignment.get("status") or "").lower()
            if assign_status == "redeemed":
                return False, promo, "already_applied"
            if assign_status not in {"assigned", "approved"}:
                return False, promo, "assignment_inactive"
            promo["assignment_id"] = assignment.get("id")
        return True, promo, "ok"
    finally:
        if own_conn:
            conn.close()

def redeem_gift_code(user_id, code: str, actor_id=None, actor_role: str = "user") -> tuple[bool, str, dict]:
    get_user(user_id)
    conn = db_connect()
    c = conn.cursor()
    try:
        c.execute("BEGIN IMMEDIATE")
        ok, promo, reason = validate_gift_code(user_id, code, conn=conn)
        if not ok:
            conn.rollback()
            return False, reason, promo
        norm_code = normalize_promo_code(code)
        xu = int(promo.get("value") or promo.get("bonus_xu") or 0)
        note = str(promo.get("note") or "Gift code")
        now = now_text()
        c.execute(
            """INSERT INTO gift_redemptions
            (code, user_id, xu, status, created_at, redeemed_at, note)
            VALUES (?,?,?,?,?,?,?)""",
            (norm_code, str(user_id), xu, "redeemed", now, now, note),
        )
        c.execute("UPDATE users SET credits = credits + ? WHERE user_id=?", (xu, str(user_id)))
        c.execute(
            """UPDATE promotion_codes
            SET usage_count=COALESCE(usage_count,0)+1,
                used_count=COALESCE(used_count,0)+1,
                updated_at=?
            WHERE code=?""",
            (now, norm_code),
        )
        c.execute(
            """UPDATE gift_assignments
            SET status='redeemed', redeemed_at=?
            WHERE code=? AND user_id=? AND status IN ('assigned','approved')""",
            (now, norm_code, str(user_id)),
        )
        mark_beta_gift_request_approved(conn, norm_code, user_id)
        record_credit_event(conn, user_id, xu, "gift_code", norm_code, note)
        record_audit(
            conn,
            actor_id or user_id,
            actor_role or "user",
            "gift.admin_grant" if str(actor_role or "").lower() == "admin" else "gift.redeemed",
            "promotion_code",
            norm_code,
            before=None,
            after={"user_id": str(user_id), "xu": xu, "actor_id": str(actor_id or user_id)},
            note=note,
        )
        emit_event(
            conn,
            "gift.redeemed",
            "promo",
            {"code": norm_code, "user_id": str(user_id), "xu": xu},
            status="processed",
        )
        conn.commit()
        credits, _, _ = get_user(user_id)
        return True, "redeemed", {"code": norm_code, "xu": xu, "balance": credits, "note": note}
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()

def grant_gift_code_to_user(admin_id, target_user_id, code: str) -> tuple[bool, str, dict]:
    norm_code = normalize_promo_code(code)
    if not norm_code:
        return False, "missing_code", {"code": ""}
    get_user(target_user_id)
    conn = db_connect()
    try:
        c = conn.cursor()
        c.execute("BEGIN IMMEDIATE")
        promo = get_promo_code_dict(conn, norm_code)
        if not promo:
            conn.rollback()
            return False, "not_found", {"code": norm_code}
        if not is_gift_promo(promo):
            conn.rollback()
            return False, "not_gift", promo
        status = str(promo.get("status") or "").lower()
        if status != "active":
            conn.rollback()
            return False, "inactive", promo
        value = int(promo.get("value") or promo.get("bonus_xu") or 0)
        if value <= 0:
            conn.rollback()
            return False, "invalid_value", promo
        limit = promo_usage_limit(promo)
        total_used = max(promo_usage_count(promo), count_gift_usage(conn, norm_code))
        if limit > 0 and total_used >= limit:
            conn.rollback()
            return False, "sold_out", promo
        per_user_limit = max(1, int(promo.get("per_user_limit") or 1))
        if count_user_gift_usage(conn, target_user_id, norm_code) >= per_user_limit:
            conn.rollback()
            return False, "already_applied", promo
        if is_beta_gift_code(norm_code):
            conn.execute(
                "UPDATE promotion_codes SET requires_assignment=1, updated_at=? WHERE code=? AND promo_type='gift_xu'",
                (now_text(), norm_code),
            )
        assignment = upsert_gift_assignment(
            conn,
            norm_code,
            target_user_id,
            admin_id,
            status="assigned",
            note=f"Admin {admin_id} assigned gift code",
        )
        record_audit(
            conn,
            admin_id,
            "admin",
            "gift.assigned",
            "promotion_code",
            norm_code,
            before=None,
            after={"user_id": str(target_user_id), "assignment_id": assignment.get("id")},
            note="Admin assigned gift before redemption",
        )
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return redeem_gift_code(target_user_id, norm_code, actor_id=admin_id, actor_role="admin")

def promo_topup_sequence_allowed(conn, user_id, code: str, after_paid=False, current_order_code="") -> tuple[bool, str]:
    paid_count = user_successful_topup_count(conn, user_id, exclude_order_code=current_order_code)
    code = normalize_promo_code(code)
    if code == PROMO_FIRST_TOPUP_CODE:
        expected = 1 if after_paid and not str(current_order_code or "").strip() else 0
        if paid_count == expected:
            return True, ""
        return False, "first_topup_only"
    if code == PROMO_SECOND_TOPUP_CODE:
        expected = 2 if after_paid and not str(current_order_code or "").strip() else 1
        if paid_count == expected:
            return True, ""
        return False, "second_topup_only"
    return True, ""

def validate_promo_code(user_id, code: str, amount_vnd=0, conn=None, after_paid=False, current_order_code="") -> tuple[bool, dict, str]:
    norm_code = normalize_promo_code(code)
    if not norm_code:
        return False, {}, "missing_code"
    own_conn = conn is None
    if own_conn:
        conn = db_connect()
    try:
        promo = get_promo_code_dict(conn, norm_code)
        if not promo:
            return False, {"code": norm_code}, "not_found"
        status = str(promo.get("status") or "").lower()
        if status != "active":
            return False, promo, "inactive"
        now = now_text()
        if promo.get("starts_at") and str(promo["starts_at"]) > now:
            return False, promo, "not_started"
        if promo.get("ends_at") and str(promo["ends_at"]) < now:
            return False, promo, "expired"
        limit = promo_usage_limit(promo)
        if limit > 0 and promo_usage_count(promo) >= limit:
            return False, promo, "sold_out"
        per_user_limit = max(1, int(promo.get("per_user_limit") or 1))
        amount_int = int(amount_vnd or 0)
        if amount_int > 0 and amount_int < 50000:
            return False, promo, "min_amount_not_met"
        if amount_int > 0 and amount_int < promo_min_amount(promo):
            return False, promo, "min_amount"
        if str(promo.get("promo_type") or "").lower() == "tier_up":
            owner = str(promo.get("owner_user_id") or "").strip()
            if owner and owner != str(user_id):
                return False, promo, "owner_only"

        period_type = promo_period_type(norm_code)
        period_key = promo_period_key(norm_code)
        used_in_period = promo_period_used(conn, user_id, norm_code, period_key)
        if norm_code in {PROMO_FIRST_TOPUP_CODE, PROMO_SECOND_TOPUP_CODE}:
            if used_in_period or count_user_promo_usage(conn, user_id, norm_code) >= per_user_limit:
                return False, promo, "already_used"
        elif period_type in {"daily", "weekly", "monthly"}:
            if used_in_period:
                return False, promo, "period_already_used"
        elif count_user_promo_usage(conn, user_id, norm_code) >= per_user_limit:
            return False, promo, "already_applied"

        ok_sequence, sequence_reason = promo_topup_sequence_allowed(
            conn,
            user_id,
            norm_code,
            after_paid=after_paid,
            current_order_code=current_order_code,
        )
        if not ok_sequence:
            return False, promo, sequence_reason
        return True, promo, "ok"
    finally:
        if own_conn:
            conn.close()

def calculate_promo_bonus(promo: dict, base_xu: int, amount_vnd: int = 0) -> int:
    promo_type = promo.get("promo_type") or "fixed_bonus_xu"
    value = int(promo.get("value") or promo.get("bonus_xu") or 0)
    if promo_type in {"percent_bonus", "tier_up"}:
        bonus = math.floor(int(base_xu or 0) * value / 100)
    elif promo_type == "fixed_bonus_xu":
        bonus = value
    else:
        bonus = 0
    max_bonus = int(promo.get("max_bonus_xu") or 0)
    if max_bonus > 0:
        bonus = min(bonus, max_bonus)
    return max(0, int(bonus or 0))

def get_user_pending_promo_raw(conn, user_id) -> dict:
    c = conn.cursor()
    c.execute("SELECT code, set_at, expires_at FROM user_promo_state WHERE user_id=?", (str(user_id),))
    row = c.fetchone()
    if not row:
        return {}
    return {"code": row[0], "set_at": row[1] or "", "expires_at": row[2] or ""}

def clear_user_pending_promo(user_id, conn=None):
    own_conn = conn is None
    if own_conn:
        conn = db_connect()
    conn.execute("DELETE FROM user_promo_state WHERE user_id=?", (str(user_id),))
    if own_conn:
        conn.commit()
        conn.close()

def get_user_pending_promo(user_id, conn=None) -> dict:
    own_conn = conn is None
    if own_conn:
        conn = db_connect()
    try:
        state = get_user_pending_promo_raw(conn, user_id)
        if not state:
            return {}
        if state.get("expires_at") and state["expires_at"] < vn_now_text():
            clear_user_pending_promo(user_id, conn)
            return {}
        ok, promo, reason = validate_promo_code(user_id, state["code"], conn=conn)
        if not ok:
            clear_user_pending_promo(user_id, conn)
            return {"code": normalize_promo_code(state["code"]), "status": reason}
        return {**state, "promo": promo, "status": "pending"}
    finally:
        if own_conn:
            conn.commit()
            conn.close()

def set_user_pending_promo(user_id, code: str, conn=None) -> dict:
    own_conn = conn is None
    if own_conn:
        conn = db_connect()
    c = conn.cursor()
    norm_code = normalize_promo_code(code)
    old_state = get_user_pending_promo_raw(conn, user_id)
    expires_at = promo_pending_expires_at(norm_code)
    c.execute(
        """INSERT INTO user_promo_state (user_id, code, set_at, expires_at)
        VALUES (?,?,?,?)
        ON CONFLICT(user_id) DO UPDATE SET code=excluded.code, set_at=excluded.set_at, expires_at=excluded.expires_at""",
        (str(user_id), norm_code, now_text(), expires_at),
    )
    if old_state.get("code") and old_state.get("code") != norm_code:
        c.execute(
            "UPDATE promotion_redemptions SET status='replaced', note=? WHERE user_id=? AND status='pending' AND code<>?",
            (f"Replaced by {norm_code}", str(user_id), norm_code),
        )
    if own_conn:
        conn.commit()
        conn.close()
    return {"old_code": old_state.get("code") or "", "new_code": norm_code, "expires_at": expires_at}

def ensure_pending_promo_redemption(conn, user_id, code: str, order_code="", amount_vnd=0, base_xu=0, bonus_xu=0) -> int:
    c = conn.cursor()
    norm_code = normalize_promo_code(code)
    period_type = promo_period_type(norm_code)
    period_key = promo_period_key(norm_code)
    note = f"period_type={period_type}; period_key={period_key}"
    c.execute("SELECT id, status FROM promotion_redemptions WHERE code=? AND user_id=?", (norm_code, str(user_id)))
    row = c.fetchone()
    if row:
        redemption_id, status = row
        if period_type == "lifetime" and str(status or "").lower() in {"applied", "redeemed", "success"}:
            return int(redemption_id)
        c.execute(
            """UPDATE promotion_redemptions
            SET status='pending', order_code=?, bonus_xu=?, amount_vnd=?, base_xu=?, created_at=?, applied_at='', redeemed_at='', note=?
            WHERE id=?""",
            (str(order_code or ""), int(bonus_xu or 0), int(amount_vnd or 0), int(base_xu or 0), now_text(), note, redemption_id),
        )
        return int(redemption_id)
    c.execute(
        """INSERT INTO promotion_redemptions
        (code, user_id, order_code, bonus_xu, status, created_at, applied_at, amount_vnd, base_xu, redeemed_at, note)
        VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
        (norm_code, str(user_id), str(order_code or ""), int(bonus_xu or 0), "pending", now_text(), "", int(amount_vnd or 0), int(base_xu or 0), "", note),
    )
    return int(c.lastrowid)

def activate_promo_for_user(user_id, code: str) -> tuple[bool, str, dict]:
    norm_code = normalize_promo_code(code)
    if not norm_code:
        return False, "missing_code", {}
    get_user(user_id)
    conn = db_connect()
    c = conn.cursor()
    try:
        c.execute("BEGIN IMMEDIATE")
        ok, promo, reason = validate_promo_code(user_id, norm_code, conn=conn)
        info = dict(promo or {"code": norm_code})
        info["bonus_xu"] = calculate_promo_bonus(info, 0, 0) if info else 0
        if not ok:
            conn.rollback()
            return False, reason, info
        current = get_user_pending_promo_raw(conn, user_id)
        state = set_user_pending_promo(user_id, norm_code, conn)
        info["expires_at"] = state.get("expires_at") or ""
        ensure_pending_promo_redemption(conn, user_id, norm_code)
        record_audit(
            conn,
            user_id,
            "user",
            "promo.activated",
            "promotion_code",
            norm_code,
            before={"pending_code": current.get("code") or ""},
            after={"user_id": str(user_id), "pending_code": norm_code, "expires_at": state["expires_at"]},
            note="User activated promo code; one pending promo only",
        )
        conn.commit()
        if current.get("code") == norm_code:
            return True, "already_pending", info
        if current.get("code"):
            info["replaced_code"] = current.get("code")
            return True, "replaced", info
        return True, "activated", info
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()

def get_user_promo_summary(user_id) -> dict:
    conn = db_connect()
    c = conn.cursor()
    try:
        pending = get_user_pending_promo(user_id, conn)
        c.execute(
            """SELECT r.code, r.status, r.order_code, r.bonus_xu, r.created_at, COALESCE(r.redeemed_at, r.applied_at),
                      COALESCE(p.min_amount_vnd, p.min_amount), COALESCE(p.usage_limit, p.max_uses),
                      COALESCE(p.usage_count, p.used_count), p.promo_type, p.value, p.max_bonus_xu, p.note
            FROM promotion_redemptions r
            LEFT JOIN promotion_codes p ON p.code=r.code
            WHERE r.user_id=?
            ORDER BY r.created_at DESC
            LIMIT 5""",
            (str(user_id),),
        )
        rows = c.fetchall()
        return {"rows": rows, "pending": pending}
    finally:
        conn.close()

def attach_pending_promo_to_order(user_id, order_code: str, amount_vnd: int, base_xu: int) -> dict:
    conn = db_connect()
    c = conn.cursor()
    try:
        c.execute("BEGIN IMMEDIATE")
        state = get_user_pending_promo(user_id, conn)
        if not state or not state.get("promo"):
            conn.commit()
            return {"attached": False, "reason": "no_pending"}
        promo = state["promo"]
        ok, promo, reason = validate_promo_code(user_id, promo["code"], amount_vnd=amount_vnd, conn=conn)
        if not ok:
            conn.commit()
            return {"attached": False, "code": normalize_promo_code(state.get("code")), "reason": reason}
        c.execute(
            "SELECT id FROM promotion_redemptions WHERE order_code=? AND status IN ('pending','applied','redeemed','success') LIMIT 1",
            (str(order_code),),
        )
        if c.fetchone():
            conn.commit()
            return {"attached": False, "code": promo["code"], "reason": "order_already_has_promo"}
        bonus = calculate_promo_bonus(promo, base_xu, amount_vnd)
        c.execute(
            "UPDATE promotion_redemptions SET status='replaced', note=? WHERE user_id=? AND status='pending' AND code<>?",
            (f"Order {order_code} selected {promo['code']}", str(user_id), promo["code"]),
        )
        redemption_id = ensure_pending_promo_redemption(
            conn, user_id, promo["code"], order_code=order_code, amount_vnd=amount_vnd, base_xu=base_xu, bonus_xu=bonus
        )
        conn.commit()
        return {"attached": True, "id": redemption_id, "code": promo["code"], "bonus_xu": bonus, "promo": promo}
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()

def redeem_promo_for_order(conn, user_id, order_code: str, amount_vnd: int, base_xu: int) -> dict:
    c = conn.cursor()
    c.execute(
        """SELECT id, code, bonus_xu FROM promotion_redemptions
        WHERE user_id=? AND order_code=? AND status IN ('applied','redeemed','success')
        ORDER BY applied_at DESC, redeemed_at DESC
        LIMIT 1""",
        (str(user_id), str(order_code)),
    )
    applied_row = c.fetchone()
    if applied_row:
        return {
            "bonus_xu": 0,
            "code": normalize_promo_code(applied_row[1]),
            "status": "already_applied",
            "redemption_id": int(applied_row[0]),
        }

    c.execute(
        """SELECT id, code, bonus_xu FROM promotion_redemptions
        WHERE user_id=? AND order_code=? AND status='pending'
        ORDER BY created_at ASC
        LIMIT 1""",
        (str(user_id), str(order_code)),
    )
    row = c.fetchone()
    if not row:
        c.execute(
            """SELECT id, code, bonus_xu FROM promotion_redemptions
            WHERE user_id=? AND (order_code='' OR order_code IS NULL) AND status='pending'
            ORDER BY created_at ASC
            LIMIT 1""",
            (str(user_id),),
        )
        row = c.fetchone()
    if not row:
        return {"bonus_xu": 0, "code": "", "status": "none"}

    redemption_id, code, stored_bonus = row
    ok, promo, reason = validate_promo_code(
        user_id,
        code,
        amount_vnd=amount_vnd,
        conn=conn,
        after_paid=True,
        current_order_code=order_code,
    )
    if not ok:
        c.execute(
            """UPDATE promotion_redemptions
            SET status=?, order_code=?, amount_vnd=?, base_xu=?, applied_at=?, redeemed_at=?, note=?
            WHERE id=? AND status='pending'""",
            (reason, str(order_code), int(amount_vnd or 0), int(base_xu or 0), now_text(), now_text(), reason, redemption_id),
        )
        if get_user_pending_promo_raw(conn, user_id).get("code") == normalize_promo_code(code):
            clear_user_pending_promo(user_id, conn)
        return {"bonus_xu": 0, "code": normalize_promo_code(code), "status": reason}

    bonus = calculate_promo_bonus(promo, base_xu, amount_vnd)
    if int(stored_bonus or 0) > 0:
        bonus = int(stored_bonus or 0)
    period_type = promo_period_type(promo["code"])
    period_key = promo_period_key(promo["code"])
    c.execute(
        """INSERT OR IGNORE INTO promo_usage_periods
        (code, user_id, order_code, amount_vnd, base_xu, bonus_xu, period_type, period_key, status, applied_at, note)
        VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
        (
            promo["code"],
            str(user_id),
            str(order_code),
            int(amount_vnd or 0),
            int(base_xu or 0),
            int(bonus or 0),
            period_type,
            period_key,
            "applied",
            now_text(),
            "Redeemed after paid order; period guard",
        ),
    )
    if int(c.rowcount or 0) <= 0:
        c.execute(
            """UPDATE promotion_redemptions
            SET status='period_already_used', order_code=?, amount_vnd=?, base_xu=?, applied_at=?, redeemed_at=?, note=?
            WHERE id=?""",
            (
                str(order_code),
                int(amount_vnd or 0),
                int(base_xu or 0),
                now_text(),
                now_text(),
                f"Duplicate promo period {period_key}",
                redemption_id,
            ),
        )
        if get_user_pending_promo_raw(conn, user_id).get("code") == normalize_promo_code(code):
            clear_user_pending_promo(user_id, conn)
        return {"bonus_xu": 0, "code": normalize_promo_code(code), "status": "period_already_used"}

    if bonus > 0:
        c.execute("UPDATE users SET credits = credits + ? WHERE user_id=?", (bonus, str(user_id)))
        credit_event_type = "tier_promo_bonus" if str(promo.get("promo_type") or "").lower() == "tier_up" else "promo_bonus"
        record_credit_event(conn, user_id, bonus, credit_event_type, f"{promo['code']}:{order_code}", f"Promo {promo['code']} thưởng {bonus} Xu")
    c.execute(
        """UPDATE promotion_redemptions
        SET status='applied', order_code=?, bonus_xu=?, amount_vnd=?, base_xu=?, applied_at=?, redeemed_at=?, note=?
        WHERE id=? AND status='pending'""",
        (str(order_code), bonus, int(amount_vnd or 0), int(base_xu or 0), now_text(), now_text(), "Redeemed after PayOS success", redemption_id),
    )
    c.execute(
        """UPDATE promotion_redemptions
        SET status='skipped', note=?
        WHERE order_code=? AND status='pending' AND id<>?""",
        ("One order only uses one promo", str(order_code), redemption_id),
    )
    c.execute(
        """UPDATE promotion_codes
        SET used_count = used_count + 1,
            usage_count = usage_count + 1,
            updated_at=?
        WHERE code=?""",
        (now_text(), promo["code"]),
    )
    if str(promo.get("promo_type") or "").lower() == "tier_up":
        c.execute(
            """UPDATE member_tier_rewards
            SET status='used', used_at=?, note=?
            WHERE user_id=? AND promo_code=? AND COALESCE(used_at,'')=''""",
            (now_text(), f"Used on order {order_code}; bonus_xu={bonus}", str(user_id), promo["code"]),
        )
        record_usage_event_conn(
            conn,
            user_id,
            event_type="tier_promo_used",
            tool_name="member",
            command="/promo",
            status="applied",
            xu_delta=int(bonus or 0),
            amount_vnd=int(amount_vnd or 0),
            provider="internal",
            detail=f"code={promo['code']}; base_xu={int(base_xu or 0)}; bonus_xu={int(bonus or 0)}",
        )
    if get_user_pending_promo_raw(conn, user_id).get("code") == promo["code"]:
        clear_user_pending_promo(user_id, conn)
    record_audit(
        conn,
        "payos",
        "system",
        "promo.bonus_applied",
        "promotion_redemption",
        str(redemption_id),
        before={"status": "pending", "code": promo["code"]},
        after={"status": "applied", "order_code": str(order_code), "bonus_xu": bonus},
        note="Promo bonus applied inside PayOS paid transaction",
    )
    return {"bonus_xu": bonus, "code": promo["code"], "status": "applied", "redemption_id": redemption_id}

def apply_promo_bonus_for_paid_order(conn, user_id, order_code: str, amount_vnd: int) -> int:
    c = conn.cursor()
    c.execute("SELECT xu FROM payos_orders WHERE order_code=?", (str(order_code),))
    row = c.fetchone()
    base_xu = int(row[0] or 0) if row else 0
    result = redeem_promo_for_order(conn, user_id, order_code, amount_vnd, base_xu)
    return int(result.get("bonus_xu") or 0)

