def _tool_env_ready(env_keys):
    if not env_keys:
        return True
    return all(bool(_env(key)) for key in env_keys)

def _tool_node(name, kind, env_keys=None, cost="unknown", mode="api", note=""):
    env_keys = env_keys or []
    return {
        "name": name,
        "kind": kind,
        "cost": cost,
        "mode": mode,
        "env_keys": env_keys,
        "configured": _tool_env_ready(env_keys),
        "note": note,
    }

