def add_reference_video(owner_id, title, path_or_url, platform="", pattern_hint="", tags="", note=""):
    if not path_or_url:
        return 0
    conn = db_connect()
    c = conn.cursor()
    try:
        c.execute(
            """INSERT INTO reference_videos
            (owner_id, title, path_or_url, platform, pattern_hint, tags, note, status, created_at)
            VALUES (?,?,?,?,?,?,?,?,?)""",
            (
                str(owner_id),
                title or os.path.basename(path_or_url) or "reference video",
                path_or_url,
                (platform or "").lower(),
                pattern_hint or "",
                tags or "",
                note or "",
                "active",
                now_text(),
            ),
        )
        ref_id = c.lastrowid
        c.execute(
            """UPDATE reference_videos SET user_id=?,source_type=?,source_url=?,safety_notes=?,updated_at=?
            WHERE id=?""",
            (
                str(owner_id), "url" if re.match(r"^https?://", path_or_url or "", re.IGNORECASE) else "manual",
                path_or_url if re.match(r"^https?://", path_or_url or "", re.IGNORECASE) else "",
                REFERENCE_SAFETY_NOTE, now_text(), ref_id,
            ),
        )
        conn.commit()
    except sqlite3.OperationalError:
        ref_id = 0
    finally:
        conn.close()
    return ref_id

def reference_video_exists(owner_id, path_or_url):
    if not path_or_url:
        return False
    conn = db_connect()
    c = conn.cursor()
    try:
        c.execute(
            "SELECT id FROM reference_videos WHERE owner_id=? AND path_or_url=? LIMIT 1",
            (str(owner_id), path_or_url),
        )
        exists = bool(c.fetchone())
    except sqlite3.OperationalError:
        exists = False
    conn.close()
    return exists

def scan_reference_video_folder(owner_id, folder="", platform="", pattern_hint="", tags="", note="", limit=200):
    folder = folder or REFERENCE_VIDEO_DIR or r"D:\mybot\video AI tham khảo"
    result = {
        "folder": folder,
        "exists": os.path.isdir(folder),
        "created": [],
        "skipped": [],
        "errors": [],
        "limit": max(1, min(int(limit or 200), 1000)),
        "rule": "Import vào catalog để học format/hook/nhịp dựng; không copy nguyên video.",
    }
    if not result["exists"]:
        result["errors"].append(f"Folder không tồn tại: {folder}")
        return result
    video_exts = {".mp4", ".mov", ".m4v", ".webm", ".mkv"}
    scanned = 0
    try:
        for root, _, names in os.walk(folder):
            for name in names:
                if scanned >= result["limit"]:
                    break
                ext = os.path.splitext(name)[1].lower()
                if ext not in video_exts:
                    continue
                path = os.path.abspath(os.path.join(root, name))
                scanned += 1
                if reference_video_exists(owner_id, path):
                    result["skipped"].append(path)
                    continue
                rel_title = os.path.splitext(os.path.relpath(path, folder))[0]
                ref_id = add_reference_video(
                    owner_id,
                    title=rel_title,
                    path_or_url=path,
                    platform=platform,
                    pattern_hint=pattern_hint,
                    tags=tags or "reference,local-video",
                    note=note or "imported_by_reference_scan",
                )
                if ref_id:
                    result["created"].append({"id": ref_id, "path": path, "title": rel_title})
                else:
                    result["errors"].append(f"Không lưu được: {path}")
            if scanned >= result["limit"]:
                break
    except OSError as exc:
        result["errors"].append(str(exc))
    result["scanned"] = scanned
    result["created_count"] = len(result["created"])
    result["skipped_count"] = len(result["skipped"])
    result["error_count"] = len(result["errors"])
    return result

def list_reference_videos(owner_id, limit=40, platform="", status="active"):
    conn = db_connect()
    c = conn.cursor()
    clauses = ["owner_id=?"]
    params = [str(owner_id)]
    if status:
        clauses.append("COALESCE(status,'active')=?")
        params.append(status)
    if platform:
        clauses.append("(platform=? OR platform='')")
        params.append((platform or "").lower())
    try:
        c.execute(
            f"""SELECT id, title, path_or_url, platform, pattern_hint, tags, note, status, created_at
            FROM reference_videos
            WHERE {' AND '.join(clauses)}
            ORDER BY id DESC LIMIT ?""",
            params + [max(1, int(limit or 40))],
        )
        rows = c.fetchall()
    except sqlite3.OperationalError:
        rows = []
    conn.close()
    return rows

def serialize_reference_video(row):
    if not row:
        return None
    ref_id, title, path_or_url, platform, pattern_hint, tags, note, status, created_at = row
    source_type = "url" if re.match(r"^https?://", path_or_url or "", re.IGNORECASE) else "local_path"
    return {
        "id": ref_id,
        "title": title,
        "path_or_url": path_or_url,
        "source_type": source_type,
        "platform": platform,
        "pattern_hint": pattern_hint,
        "tags": tags,
        "note": note,
        "status": status,
        "created_at": created_at,
        "learning_note": (
            "Reference được admin lưu để học format/hook/nhịp dựng. "
            "Không copy nguyên video/voice/face/text/claim."
        ),
    }

def get_reference_video(owner_id, ref_id):
    if not ref_id:
        return None
    conn = db_connect()
    c = conn.cursor()
    try:
        c.execute(
            """SELECT id, title, path_or_url, platform, pattern_hint, tags, note, status, created_at
            FROM reference_videos WHERE owner_id=? AND id=? LIMIT 1""",
            (str(owner_id), int(ref_id)),
        )
        row = c.fetchone()
    except sqlite3.OperationalError:
        row = None
    conn.close()
    return serialize_reference_video(row)

def reference_match_score(ref, topic="", platform="", pattern_id="", product_name=""):
    blob = " ".join(
        str(ref.get(key) or "")
        for key in ["title", "platform", "pattern_hint", "tags", "note", "path_or_url"]
    ).lower()
    query = f"{topic} {platform} {pattern_id} {product_name}".lower()
    tokens = {
        token
        for token in re.split(r"[^0-9a-zA-ZÀ-ỹ]+", query)
        if len(token) >= 3
    }
    score = 0
    hits = []
    for token in tokens:
        if token and token in blob:
            score += 6
            hits.append(token)
    if platform and (ref.get("platform") or "").lower() in {"", platform.lower()}:
        score += 8
    if pattern_id and pattern_id.lower() in (ref.get("pattern_hint") or "").lower():
        score += 14
    if ref.get("source_type") == "local_path":
        score += 2
    return score, hits

def select_reference_examples_for_job(owner_id, job, limit=3):
    if not job:
        return []
    (
        _jid, _calendar_id, _campaign_id, _channel_id, _affiliate_id, platform, topic, _stage, _status,
        note, brief, _asset_url, _publish_url, _channel_name, _account_label, network, product_name, _affiliate_url
    ) = job
    pattern = select_video_pattern(job, 45)
    refs = []
    inventory = reference_video_inventory_data(limit=80, owner_id=owner_id)
    for item in inventory.get("catalog") or []:
        score, hits = reference_match_score(
            item,
            topic=f"{topic or ''} {brief or ''} {note or ''}",
            platform=platform or "",
            pattern_id=pattern.get("id") or "",
            product_name=f"{product_name or ''} {network or ''}",
        )
        item = dict(item)
        item["match_score"] = score
        item["match_hits"] = hits[:8]
        refs.append(item)
    for item in inventory.get("files") or []:
        ref = {
            "id": 0,
            "title": item.get("name") or item.get("relative_path") or "reference file",
            "path_or_url": item.get("relative_path") or item.get("name") or "",
            "source_type": "filesystem",
            "platform": "",
            "pattern_hint": "",
            "tags": "",
            "note": item.get("learning_note") or "",
            "created_at": item.get("modified_at") or "",
        }
        score, hits = reference_match_score(
            ref,
            topic=f"{topic or ''} {brief or ''} {note or ''}",
            platform=platform or "",
            pattern_id=pattern.get("id") or "",
            product_name=f"{product_name or ''} {network or ''}",
        )
        ref["match_score"] = score
        ref["match_hits"] = hits[:8]
        refs.append(ref)
    refs.sort(key=lambda item: (int(item.get("match_score") or 0), item.get("created_at") or ""), reverse=True)
    selected = refs[:max(1, int(limit or 3))]
    for item in selected:
        item["apply_rule"] = (
            "Học cấu trúc hook, nhịp cảnh, proof placement và CTA; viết lại bằng nội dung/asset TOAN AAS, "
            "không copy nguyên video/voice/face/text/claim."
        )
    return selected

def reference_video_inventory_data(limit=80, owner_id=None):
    folder = REFERENCE_VIDEO_DIR or r"D:\mybot\video AI tham khảo"
    video_exts = {".mp4", ".mov", ".m4v", ".webm", ".mkv"}
    files = []
    exists = os.path.isdir(folder)
    if exists:
        try:
            for root, _, names in os.walk(folder):
                for name in names:
                    ext = os.path.splitext(name)[1].lower()
                    if ext not in video_exts:
                        continue
                    path = os.path.join(root, name)
                    try:
                        stat = os.stat(path)
                    except OSError:
                        continue
                    rel_path = os.path.relpath(path, folder)
                    files.append({
                        "name": name,
                        "relative_path": rel_path,
                        "size_mb": round(stat.st_size / 1024 / 1024, 2),
                        "modified_at": datetime.fromtimestamp(stat.st_mtime).strftime("%Y-%m-%d %H:%M:%S"),
                        "learning_note": (
                            "Dùng làm reference format: hook, nhịp dựng, flow CTA, proof placement. "
                            "Không copy nguyên video/voice/face/text/claim."
                        ),
                    })
        except OSError as exc:
            return {
                "folder": folder,
                "exists": False,
                "count": 0,
                "files": [],
                "error": str(exc),
                "setup_hint": f"Tạo thư mục {folder} và đặt video tham khảo vào đó, hoặc set REFERENCE_VIDEO_DIR.",
            }
    files.sort(key=lambda item: item.get("modified_at") or "", reverse=True)
    catalog_rows = list_reference_videos(owner_id or ADMIN_ID, limit=limit)
    catalog = [serialize_reference_video(row) for row in catalog_rows]
    try:
        conn = db_connect()
        c = conn.cursor()
        c.execute(
            "SELECT COUNT(*) FROM reference_videos WHERE owner_id=? AND COALESCE(status,'active')='active'",
            (str(owner_id or ADMIN_ID),),
        )
        total_catalog_count = int(c.fetchone()[0] or 0)
        conn.close()
    except sqlite3.OperationalError:
        total_catalog_count = len(catalog)
    return {
        "folder": folder,
        "exists": exists,
        "count": len(files) + total_catalog_count,
        "filesystem_count": len(files),
        "catalog_count": total_catalog_count,
        "files": files[:max(1, int(limit or 80))],
        "catalog": catalog,
        "extensions": sorted(video_exts),
        "setup_hint": "" if exists else f"Tạo thư mục {folder} và đặt video tham khảo vào đó, hoặc set REFERENCE_VIDEO_DIR.",
        "worker_rule": (
            "Trước khi viết prompt/dựng video, đọc catalog/files reference để chọn 1-3 format gần nhất. "
            "Chỉ học cấu trúc và nhịp dựng; output phải là nội dung/asset riêng của TOAN AAS."
        ),
    }

