def operator_video_brief_data(owner_id, job_id=0, task_id=0, tool="", include_full_context=False):
    job_id = safe_int(job_id, 0)
    task_id = safe_int(task_id, 0)
    tool = (tool or "").strip().lower()
    if task_id and not job_id:
        task = get_production_task(owner_id, task_id)
        if task:
            job_id = int(task[1] or 0)
    if not job_id:
        job_id, _source = select_operator_focus_job_id(owner_id, 0)
    job = get_production_job(job_id, owner_id) if job_id else None
    if not job:
        return None

    (
        jid, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, stage, status,
        note, brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
    ) = job
    context_data = operator_job_context_data(owner_id, jid)
    task = get_production_task(owner_id, task_id) if task_id else next_worker_task(owner_id, job_id=jid, tool=tool)
    task_payload = serialize_operator_task(task)
    task_contract = operator_task_contract(task[0], task[3], task[1]) if task else operator_task_contract("<TASK_ID>", "task", jid)
    prompt_pack = operator_task_prompt_pack_data(owner_id, task_id=int(task[0])) if task else None
    manifest = ((context_data or {}).get("selected_manifest") or {}).get("data")
    if not manifest:
        manifest = fallback_production_manifest(job, variant=None, duration=80 if "phim" in (topic or "").lower() else 45)
    scenes = manifest.get("scenes") or []
    scene_briefs = []
    for scene in scenes[:12]:
        scene_briefs.append({
            "scene": scene.get("scene") or scene.get("scene_id"),
            "start": scene.get("start"),
            "end": scene.get("end"),
            "goal": scene.get("goal") or scene.get("purpose"),
            "image_prompt": scene.get("image_prompt") or scene.get("visual_prompt"),
            "video_prompt": scene.get("video_prompt") or scene.get("visual_prompt"),
            "voice_line": scene.get("voice_line") or scene.get("voiceover") or scene.get("voice_over"),
            "on_screen_text": scene.get("on_screen_text") or scene.get("text_overlay"),
            "asset_needed": scene.get("asset_needed"),
        })
    publish_pack = build_static_publish_pack(job, owner_id)
    distribution_pack = build_distribution_pack(owner_id, jid)
    comment_pack = publish_pack.get("comment_pack") or build_affiliate_comment_pack(owner_id, jid)
    affiliate_bundle = publish_pack.get("affiliate_bundle") or {}
    toolchain = operator_toolchain_data()
    brief_obj = parse_job_brief_object(brief)
    is_film_series = brief_obj.get("type") == "ai_film_series_episode" or manifest.get("video_pattern", {}).get("id") == "ai_film_series_episode"
    template = "kingcontent_film_series" if is_film_series else "viral_affiliate_short"
    base_url = (PUBLIC_BASE_URL or "https://<RAILWAY_DOMAIN>").rstrip("/")
    prompt_lines = [
        "Bạn là AI worker sản xuất video cho TOAN AAS.",
        "Mục tiêu: tạo output thật cho task/job hiện tại, ưu tiên tool tốt/có phí trước; lỗi/quota thì fallback tool rẻ/miễn phí và báo admin bằng tool-events.",
        f"Job #{jid} | platform={platform or '-'} | channel={channel_name or channel_id or '-'} | topic={topic or '-'}",
        f"Affiliate chính: {network or '-'} - {product_name or '-'} - {((affiliate_bundle.get('primary') or {}).get('tracking') or {}).get('caption') or affiliate_url or '-'}",
        f"Template: {template}",
        "Không copy nguyên video tham khảo; chỉ học hook/nhịp/cấu trúc. Không mạo danh người thật. Publish phải qua review/approve gate.",
        "Output bắt buộc: file/URL video, note ngắn, tool đã dùng, fallback nếu có, rồi POST complete/upload đúng endpoint.",
    ]
    if task_payload:
        prompt_lines.extend([
            "",
            f"Task #{task_payload.get('id')}: {task_payload.get('task_type')} / {task_payload.get('tool')}",
            f"Task title: {task_payload.get('title') or '-'}",
            f"Task prompt: {task_payload.get('prompt') or '-'}",
        ])
    if scene_briefs:
        prompt_lines.append("")
        prompt_lines.append("Scene plan:")
        for scene in scene_briefs[:8]:
            prompt_lines.append(
                f"- Scene {scene.get('scene')}: {scene.get('goal') or '-'} | voice={scene.get('voice_line') or '-'}"
            )

    next_urls = {
        "worker_pack": f"{base_url}/api/operator/jobs/{jid}/worker-pack" + (f"?task_id={int(task[0])}" if task else ""),
        "task_prompt": f"{base_url}/api/operator/tasks/{int(task[0])}/prompt-pack" if task else f"{base_url}/api/operator/tasks/<TASK_ID>/prompt-pack",
        "complete": f"{base_url}{task_contract.get('complete_url')}",
        "upload": f"{base_url}{task_contract.get('upload_url')}",
        "acceptance": f"{base_url}{task_contract.get('acceptance_url')}",
        "compose_video": f"{base_url}/api/operator/jobs/{jid}/compose-video",
        "review_video": f"{base_url}/api/operator/jobs/{jid}/review-video",
        "distribution_pack": f"{base_url}/api/operator/jobs/{jid}/distribution-pack",
        "comment_pack": f"{base_url}/api/operator/jobs/{jid}/comment-pack",
        "post_publish": f"{base_url}/api/operator/jobs/{jid}/post-publish",
        "performance": f"{base_url}/api/operator/performance",
    }
    return {
        "ok": True,
        "generated_at": now_text(),
        "job_id": jid,
        "task_id": int(task[0]) if task else 0,
        "template": template,
        "job": serialize_production_job(job),
        "task": task_payload,
        "ai_worker_prompt": "\n".join(prompt_lines),
        "production_manifest": {
            "title": manifest.get("title"),
            "series_title": manifest.get("series_title"),
            "duration_sec": manifest.get("duration_sec"),
            "format": manifest.get("format") or "9:16",
            "video_pattern": manifest.get("video_pattern"),
            "character_bible": manifest.get("character_bible") or brief_obj.get("character_bible") or {},
            "voice": manifest.get("voice"),
            "edit_instructions": manifest.get("edit_instructions"),
            "publish": manifest.get("publish"),
            "scene_count": len(scenes),
            "scenes": scene_briefs,
        },
        "affiliate_distribution": {
            "primary": (affiliate_bundle.get("primary") or publish_pack.get("primary_affiliate") or {}),
            "related_links": publish_pack.get("related_links", [])[:10],
            "placement_plan": publish_pack.get("placement_plan") or {},
            "caption": publish_pack.get("caption"),
            "pinned_comment": publish_pack.get("pinned_comment"),
            "comment_pack": comment_pack,
            "tracking_plan": (distribution_pack or {}).get("tracking_plan") or {},
            "disclosure": publish_pack.get("disclosure"),
        },
        "tool_order": [
            "Claude/Gemini: chốt storyboard/script/prompts",
            "Image/video generator: tạo scene_image/raw_video theo scene plan",
            "Fish Audio HD: voice chính; Edge TTS fallback nếu quota/lỗi",
            "CapCut/FFmpeg: subtitle, CTA, logo, ghép final_video",
            "Review gate: /review_video rồi /approve_publish",
            "Publisher handoff/API chính thức, sau đó ghi performance",
        ],
        "submit_contract": {
            "complete_url": next_urls["complete"],
            "upload_url": next_urls["upload"],
            "acceptance_url": next_urls["acceptance"],
            "complete_payload": task_contract.get("complete_payload"),
            "upload_form": task_contract.get("upload_form"),
        },
        "next_urls": next_urls,
        "telegram": {
            "video_brief": f"/video_brief job={jid}" + (f" task={int(task[0])}" if task else ""),
            "worker_pack": f"/worker_pack job={jid}" + (f" task={int(task[0])}" if task else ""),
            "task_prompt": f"/task_prompt id={int(task[0])}" if task else "/tasks",
            "compose_video": f"/compose_video job={jid} voice=1",
            "review_video": f"/review_video job={jid} send=1",
            "approve_publish": f"/approve_publish job={jid} queue=1 mode=manual",
            "comment_pack": f"/comment_pack job={jid} max=10 delay=30",
            "post_publish": f"/post_publish job={jid}",
        },
        "quality_gates": [
            "Hook rõ trong 1-3 giây đầu, mobile 9:16.",
            "Scene có action/camera/voice rõ, không text lỗi trong ảnh AI.",
            "Có disclosure affiliate và tracking source.",
            "OnlyFans/AI influencer: nhân vật tự tạo hoặc consent 18+, không mạo danh.",
            "Final video phải được review trước khi đăng.",
        ],
        "toolchain_policy": {
            "policy": toolchain.get("policy"),
            "failure_protocol": toolchain.get("failure_protocol"),
        },
        "full_context": context_data if include_full_context else None,
        "rule": "Video brief là gói giao việc ngắn cho Claude/n8n/tool worker: tạo output thật, trả qua complete/upload, không tự publish khi chưa qua gate.",
    }

def operator_video_work_orders_data(owner_id, job_ids=None, limit=8, tool=""):
    limit = max(1, min(safe_int(limit, 8), 20))
    normalized_ids = []
    for value in (job_ids or []):
        job_id = safe_int(value, 0)
        if job_id > 0 and job_id not in normalized_ids:
            normalized_ids.append(job_id)
        if len(normalized_ids) >= limit:
            break
    if not normalized_ids:
        focus_job_id, _source = select_operator_focus_job_id(owner_id, 0)
        if focus_job_id:
            normalized_ids.append(focus_job_id)
    base_url = (PUBLIC_BASE_URL or "https://<RAILWAY_DOMAIN>").rstrip("/")
    orders = []
    for job_id in normalized_ids[:limit]:
        brief = operator_video_brief_data(owner_id, job_id=job_id, tool=tool, include_full_context=False)
        if not brief:
            continue
        manifest = brief.get("production_manifest") or {}
        affiliate = brief.get("affiliate_distribution") or {}
        primary = affiliate.get("primary") or {}
        primary_tracking = ((primary.get("tracking") or {}).get("caption") if isinstance(primary, dict) else "") or ""
        task = brief.get("task") or {}
        submit = brief.get("submit_contract") or {}
        next_urls = brief.get("next_urls") or {}
        job = brief.get("job") or {}
        orders.append({
            "job_id": job_id,
            "task_id": brief.get("task_id") or task.get("id") or 0,
            "platform": job.get("platform"),
            "topic": job.get("topic"),
            "template": brief.get("template"),
            "scene_count": manifest.get("scene_count") or 0,
            "duration_sec": manifest.get("duration_sec"),
            "worker_prompt": brief.get("ai_worker_prompt"),
            "video_brief_url": f"{base_url}/api/operator/jobs/{job_id}/video-brief",
            "worker_pack_url": next_urls.get("worker_pack") or f"{base_url}/api/operator/jobs/{job_id}/worker-pack",
            "task_prompt_url": next_urls.get("task_prompt"),
            "complete_url": submit.get("complete_url"),
            "upload_url": submit.get("upload_url"),
            "acceptance_url": submit.get("acceptance_url"),
            "review_url": next_urls.get("review_video"),
            "compose_video_url": next_urls.get("compose_video"),
            "affiliate": {
                "product": (primary.get("product") if isinstance(primary, dict) else "") or ((job.get("affiliate") or {}).get("product") if isinstance(job.get("affiliate"), dict) else ""),
                "tracking_url": primary_tracking,
                "caption": affiliate.get("caption"),
                "pinned_comment": affiliate.get("pinned_comment"),
                "related_count": len(affiliate.get("related_links") or []),
            },
            "telegram": {
                "video_brief": f"/video_brief job={job_id}" + (f" task={brief.get('task_id')}" if brief.get("task_id") else ""),
                "worker_pack": f"/worker_pack job={job_id}" + (f" task={brief.get('task_id')}" if brief.get("task_id") else ""),
                "task_prompt": f"/task_prompt id={brief.get('task_id')}" if brief.get("task_id") else f"/tasks job={job_id}",
                "compose_video": f"/compose_video job={job_id} voice=1",
                "review_video": f"/review_video job={job_id} send=1",
                "approve_publish": f"/approve_publish job={job_id} queue=1 mode=manual",
            },
            "quality_gates": brief.get("quality_gates") or [],
        })
    return {
        "ok": True,
        "generated_at": now_text(),
        "count": len(orders),
        "job_ids": normalized_ids[:limit],
        "orders": orders,
        "rule": "Video work orders gom brief thực thi cho Claude/n8n/tool worker. Worker tạo output thật qua complete/upload, sau đó dừng ở review/approve gate.",
    }

def operator_voice_script_from_prompt(prompt=""):
    text = prompt or ""
    match = re.search(r"Script:\s*(.+)", text, flags=re.IGNORECASE | re.DOTALL)
    if match:
        text = match.group(1)
    text = re.sub(r"\n{3,}", "\n\n", text).strip()
    return text[:4500]

def first_labeled_line(text="", labels=None, default=""):
    labels = labels or []
    for line in str(text or "").splitlines():
        clean = line.strip(" -•\t")
        for label in labels:
            if clean.lower().startswith(label.lower()):
                value = clean[len(label):].strip(" :-")
                if value:
                    return value
    return default

def operator_visual_scene_text_pack(owner_id, task, job):
    task_id, row_job_id, manifest_id, task_type, tool, scene_no, title, prompt, status, output_url, note, updated_at = task
    (
        jid, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, stage, job_status,
        operator_note, brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
    ) = job
    manifest_scene = {}
    try:
        _manifest_row, manifest = latest_manifest_payload(owner_id, row_job_id)
    except Exception:
        manifest = {}
    for item in manifest.get("scenes") or []:
        try:
            if int(item.get("scene") or 0) == int(scene_no or 0):
                manifest_scene = item
                break
        except Exception:
            continue
    headline = (
        manifest_scene.get("on_screen_text")
        or manifest_scene.get("caption")
        or first_labeled_line(prompt, ["On-screen text", "Text", "Hook", "Caption"])
        or title
        or topic
        or "TOAN AAS Affiliate"
    )
    subline = (
        manifest_scene.get("voice_line")
        or first_labeled_line(prompt, ["Voice line", "Script", "CTA", "Visual prompt"])
        or product_name
        or network
        or "Video AI + affiliate tracking"
    )
    footer = "Link gợi ý ở mô tả/bình luận"
    if product_name or network:
        footer = f"{network or 'Affiliate'} • {product_name or 'Sản phẩm liên quan'}"
    return {
        "topic": truncate_text(topic or product_name or "TOAN AAS", 80),
        "headline": truncate_text(headline, 130),
        "subline": truncate_text(subline, 180),
        "footer": truncate_text(footer, 100),
        "scene_no": int(scene_no or 0),
        "platform": platform or "social",
    }

def load_operator_font(size=48, bold=False):
    candidates = [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "C:\\Windows\\Fonts\\arialbd.ttf" if bold else "C:\\Windows\\Fonts\\arial.ttf",
        "C:\\Windows\\Fonts\\segoeuib.ttf" if bold else "C:\\Windows\\Fonts\\segoeui.ttf",
    ]
    for path in candidates:
        try:
            if path and os.path.exists(path):
                return ImageFont.truetype(path, size)
        except Exception:
            continue
    return ImageFont.load_default()

def draw_wrapped_text(draw, xy, text, font, fill, max_width, line_gap=10, max_lines=5, align="center"):
    x, y = xy
    words = str(text or "").split()
    lines = []
    current = ""
    for word in words:
        candidate = f"{current} {word}".strip()
        width = draw.textbbox((0, 0), candidate, font=font)[2]
        if current and width > max_width:
            lines.append(current)
            current = word
        else:
            current = candidate
    if current:
        lines.append(current)
    if not lines:
        lines = [""]
    if len(lines) > max_lines:
        lines = lines[:max_lines]
        lines[-1] = truncate_text(lines[-1], 42).rstrip(".") + "..."
    for line in lines:
        bbox = draw.textbbox((0, 0), line, font=font)
        line_w = bbox[2] - bbox[0]
        line_h = bbox[3] - bbox[1]
        draw_x = x
        if align == "center":
            draw_x = x + max(0, (max_width - line_w) // 2)
        draw.text((draw_x, y), line, font=font, fill=fill)
        y += line_h + line_gap
    return y

async def create_operator_visual_scene_fallback(owner_id, task, job, duration=6):
    task_id, row_job_id, manifest_id, task_type, tool, scene_no, title, prompt, status, output_url, note, updated_at = task
    ffmpeg = shutil.which("ffmpeg")
    if not ffmpeg:
        return False, {"reason": "ffmpeg_missing", "manual_next": f"/worker_pack job={int(row_job_id)} task={int(task_id)}"}
    if Image is None:
        return False, {"reason": "pillow_missing", "manual_next": f"/worker_pack job={int(row_job_id)} task={int(task_id)}"}
    upload_root = os.path.abspath(OPERATOR_UPLOAD_DIR or "operator_uploads")
    job_dir = os.path.abspath(os.path.join(upload_root, f"job_{int(row_job_id)}"))
    if os.path.commonpath([upload_root, job_dir]) != upload_root:
        return False, {"reason": "invalid_visual_path"}
    os.makedirs(job_dir, exist_ok=True)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    png_path = os.path.abspath(os.path.join(job_dir, f"visual_scene_{int(scene_no or 0)}_task_{int(task_id)}_{stamp}.png"))
    out_path = os.path.abspath(os.path.join(job_dir, f"visual_scene_{int(scene_no or 0)}_task_{int(task_id)}_{stamp}.mp4"))
    if os.path.commonpath([upload_root, png_path]) != upload_root or os.path.commonpath([upload_root, out_path]) != upload_root:
        return False, {"reason": "invalid_visual_output_path"}

    pack = operator_visual_scene_text_pack(owner_id, task, job)
    width, height = 1080, 1920
    img = Image.new("RGB", (width, height), "#071611")
    draw = ImageDraw.Draw(img)
    for y in range(height):
        ratio = y / max(1, height - 1)
        r = int(8 + ratio * 10)
        g = int(34 + ratio * 64)
        b = int(28 + ratio * 42)
        draw.line([(0, y), (width, y)], fill=(r, g, b))
    draw.rounded_rectangle((70, 120, width - 70, height - 120), radius=42, fill=(246, 250, 247), outline=(32, 184, 123), width=4)
    draw.rounded_rectangle((94, 144, width - 94, 306), radius=30, fill=(7, 64, 48))
    draw.ellipse((width - 245, 190, width - 125, 310), fill=(30, 210, 135))
    draw.text((126, 190), "TOAN AAS", font=load_operator_font(58, True), fill=(238, 255, 247))
    draw.text((126, 252), f"Scene {pack['scene_no'] or 1} • {pack['platform']}", font=load_operator_font(28, False), fill=(167, 245, 211))
    draw_wrapped_text(draw, (126, 420), pack["topic"], load_operator_font(38, True), (9, 85, 62), width - 252, 10, 2, "center")
    draw_wrapped_text(draw, (126, 650), pack["headline"], load_operator_font(68, True), (3, 47, 35), width - 252, 16, 4, "center")
    draw.rounded_rectangle((150, 1120, width - 150, 1398), radius=28, fill=(226, 248, 238), outline=(155, 225, 190), width=2)
    draw_wrapped_text(draw, (190, 1172), pack["subline"], load_operator_font(40, False), (19, 79, 61), width - 380, 12, 4, "center")
    draw.rounded_rectangle((170, 1552, width - 170, 1668), radius=58, fill=(9, 145, 92))
    draw_wrapped_text(draw, (210, 1587), "Xem link liên quan", load_operator_font(40, True), (246, 255, 250), width - 420, 8, 1, "center")
    draw_wrapped_text(draw, (126, 1744), pack["footer"], load_operator_font(34, False), (7, 70, 52), width - 252, 10, 2, "center")
    img.save(png_path, "PNG")

    vf = "scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,format=yuv420p"
    cmd = [
        ffmpeg, "-y", "-loop", "1", "-t", str(max(3, min(int(duration or 6), 15))),
        "-i", png_path, "-vf", vf, "-r", "30", "-c:v", "libx264",
        "-pix_fmt", "yuv420p", "-movflags", "+faststart", "-an", out_path,
    ]
    try:
        proc = await asyncio.create_subprocess_exec(
            *cmd,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=180)
    except asyncio.TimeoutError:
        return False, {"reason": "ffmpeg_visual_timeout", "local_image": png_path}
    except Exception as exc:
        return False, {"reason": "ffmpeg_visual_exception", "error": str(exc), "local_image": png_path}
    if proc.returncode != 0 or not os.path.exists(out_path) or os.path.getsize(out_path) <= 0:
        return False, {
            "reason": "ffmpeg_visual_failed",
            "returncode": proc.returncode,
            "stderr": truncate_text((stderr or b"").decode("utf-8", errors="ignore"), 1200),
            "local_image": png_path,
        }
    ok, asset_id = add_production_asset(
        owner_id,
        row_job_id,
        "raw_video",
        "",
        "",
        f"operator_visual_autorun scene={int(scene_no or 0)} task:{task_id} fallback=ffmpeg_card",
        out_path,
        "video/mp4",
        os.path.basename(out_path),
    )
    if not ok:
        return False, {"reason": "asset_save_failed", "local_path": out_path}
    asset_url = operator_asset_url(asset_id)
    update_production_asset_url(owner_id, asset_id, asset_url)
    note_text = f"operator_visual_autorun ffmpeg_card asset:{asset_id} scene={int(scene_no or 0)}"
    changed, row = update_production_task(
        owner_id,
        task_id,
        status="ready",
        output_url=asset_url,
        note=note_text,
        asset_type="raw_video",
        record_asset=False,
    )
    if not changed or not row:
        return False, {"reason": "task_update_failed", "asset_id": asset_id, "asset_url": asset_url}
    readiness = apply_worker_output_job_state(
        owner_id,
        row[0],
        task_id=task_id,
        task_type=row[1],
        task_status="ready",
        asset_type="raw_video",
        note=note_text,
    )
    return True, {
        "task_id": int(task_id),
        "job_id": int(row[0]),
        "task_type": "visual_scene",
        "status": "ready",
        "asset_id": asset_id,
        "asset_url": asset_url,
        "local_path": out_path,
        "scene_no": int(scene_no or 0),
        "tool": "FFmpeg visual card",
        "fallback_used": True,
        "readiness": (readiness or {}).get("level", "UNKNOWN"),
        "note": note_text,
    }

async def synthesize_operator_voice_task(owner_id, task, job):
    task_id, row_job_id, manifest_id, task_type, tool, scene_no, title, prompt, status, output_url, note, updated_at = task
    (
        jid, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, stage, job_status,
        operator_note, brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
    ) = job
    script = operator_voice_script_from_prompt(prompt)
    if not script:
        return False, {"reason": "empty_voice_script"}
    upload_root = os.path.abspath(OPERATOR_UPLOAD_DIR or "operator_uploads")
    job_dir = os.path.abspath(os.path.join(upload_root, f"job_{int(row_job_id)}"))
    if os.path.commonpath([upload_root, job_dir]) != upload_root:
        return False, {"reason": "invalid_voice_path"}
    os.makedirs(job_dir, exist_ok=True)
    out_path = os.path.abspath(os.path.join(job_dir, f"voice_task_{int(task_id)}.mp3"))
    used_tool = ""
    fallback_used = False
    fish_error = ""
    if FISH_AUDIO_KEY:
        try:
            async with httpx.AsyncClient() as client:
                res = await client.post(
                    "https://api.fish.audio/v1/tts",
                    headers={"Authorization": f"Bearer {FISH_AUDIO_KEY}", "Content-Type": "application/json"},
                    json={"text": script, "reference_id": "7f0955e88846433e9ecb241357608bf8", "format": "mp3"},
                    timeout=45.0,
                )
            if res.status_code == 200 and res.content:
                with open(out_path, "wb") as f:
                    f.write(res.content)
                used_tool = "Fish Audio HD"
            else:
                fish_error = f"HTTP {res.status_code}"
                record_tool_event(owner_id, "voice", "Fish Audio HD", "error", "warning", row_job_id, task_id, "Edge TTS", fish_error)
        except Exception as exc:
            fish_error = str(exc)
            record_tool_event(owner_id, "voice", "Fish Audio HD", "error", "warning", row_job_id, task_id, "Edge TTS", fish_error)
    if not used_tool:
        try:
            if not edge_tts:
                raise RuntimeError(f"edge-tts package missing: {EDGE_TTS_IMPORT_ERROR or 'import failed'}")
            communicate = edge_tts.Communicate(script, "vi-VN-NamMinhNeural")
            await communicate.save(out_path)
            used_tool = "Edge TTS"
            fallback_used = bool(fish_error or not FISH_AUDIO_KEY)
            if fallback_used:
                record_tool_event(
                    owner_id,
                    "voice",
                    "Edge TTS",
                    "fallback",
                    "info",
                    row_job_id,
                    task_id,
                    "",
                    f"Fallback voice. Fish status: {fish_error or 'missing FISH_AUDIO_KEY'}",
                )
        except Exception as exc:
            record_tool_event(owner_id, "voice", "Edge TTS", "error", "warning", row_job_id, task_id, "", str(exc))
            return False, {"reason": "edge_tts_failed", "error": str(exc), "fish_error": fish_error}
    if not os.path.exists(out_path) or os.path.getsize(out_path) <= 0:
        return False, {"reason": "voice_file_missing", "tool": used_tool}
    ok, asset_id = add_production_asset(
        owner_id,
        row_job_id,
        "voice",
        "",
        "",
        f"operator_voice_autorun task:{task_id} tool={used_tool} fallback={int(fallback_used)}",
        out_path,
        "audio/mpeg",
        os.path.basename(out_path),
    )
    if not ok:
        return False, {"reason": "asset_save_failed", "tool": used_tool}
    asset_url = operator_asset_url(asset_id)
    update_production_asset_url(owner_id, asset_id, asset_url)
    note_text = f"operator_voice_autorun tool={used_tool} fallback={int(fallback_used)} asset:{asset_id}"
    changed, row = update_production_task(
        owner_id,
        task_id,
        status="ready",
        output_url=asset_url,
        note=note_text,
        asset_type="voice",
        record_asset=False,
    )
    if not changed or not row:
        return False, {"reason": "task_update_failed", "asset_id": asset_id, "tool": used_tool}
    readiness = apply_worker_output_job_state(
        owner_id,
        row[0],
        task_id=task_id,
        task_type=row[1],
        task_status="ready",
        asset_type="voice",
        note=note_text,
    )
    return True, {
        "task_id": int(task_id),
        "job_id": int(row[0]),
        "task_type": "voice",
        "status": "ready",
        "asset_id": asset_id,
        "asset_url": asset_url,
        "local_path": out_path,
        "tool": used_tool,
        "fallback_used": fallback_used,
        "readiness": (readiness or {}).get("level", "UNKNOWN"),
        "note": note_text,
    }

async def operator_worker_autorun_data(owner_id, job_ids=None, limit=5, max_tasks=8, execute=False):
    limit = max(1, min(safe_int(limit, 5), 20))
    max_tasks = max(1, min(safe_int(max_tasks, 8), 40))
    normalized_ids = []
    for value in (job_ids or []):
        job_id = safe_int(value, 0)
        if job_id > 0 and job_id not in normalized_ids:
            normalized_ids.append(job_id)
        if len(normalized_ids) >= limit:
            break
    if not normalized_ids:
        focus_job_id, _source = select_operator_focus_job_id(owner_id, 0)
        if focus_job_id:
            normalized_ids.append(focus_job_id)
    completed = []
    blocked = []
    pending_external = []
    safe_types = {"proof_asset", "visual_scene", "voice", "edit"}
    processed = 0
    for job_id in normalized_ids[:limit]:
        rows = [
            get_production_task(owner_id, row[0])
            for row in list_production_tasks(owner_id, job_id=job_id, limit=240)
            if (row[7] or "queued").lower() in {"queued", "waiting", "working"}
        ]
        for task in rows:
            if not task:
                continue
            if processed >= max_tasks:
                break
            task_id, row_job_id, manifest_id, task_type, tool, scene_no, title, prompt, status, output_url, note, updated_at = task
            task_type_l = (task_type or "").lower()
            job = get_production_job(row_job_id, owner_id)
            if not job:
                blocked.append({"task_id": task_id, "job_id": row_job_id, "task_type": task_type, "reason": "job_not_found"})
                continue
            (
                jid, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, stage, job_status,
                operator_note, brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
            ) = job
            if task_type_l not in safe_types:
                if not any(item.get("task_id") == int(task_id) for item in pending_external):
                    pending_external.append({
                        "task_id": int(task_id),
                        "job_id": int(row_job_id),
                        "task_type": task_type,
                        "tool": tool,
                        "scene_no": int(scene_no or 0),
                        "title": title,
                        "reason": "Cần tool/file thật; autorun không giả lập media.",
                        "telegram": {
                            "task_prompt": f"/task_prompt id={int(task_id)}",
                            "worker_pack": f"/worker_pack job={int(row_job_id)} task={int(task_id)}",
                        },
                        "api": {
                            "prompt_pack": f"/api/operator/tasks/{int(task_id)}/prompt-pack",
                            "complete": f"/api/operator/tasks/{int(task_id)}/complete",
                            "upload": f"/api/operator/tasks/{int(task_id)}/upload",
                        },
                    })
                continue
            if not execute:
                completed.append({
                    "preview": True,
                    "task_id": int(task_id),
                    "job_id": int(row_job_id),
                    "task_type": task_type,
                    "would_status": "ready",
                    "output_url": (
                        affiliate_url if task_type_l == "proof_asset"
                        else "local_mp4_when_execute" if task_type_l == "visual_scene"
                        else "local_final_video_when_execute" if task_type_l == "edit"
                        else "local_mp3_when_execute"
                    ),
                    "note": "preview_safe_autorun",
                })
                processed += 1
                continue
            if task_type_l == "proof_asset":
                proof_url = affiliate_url or affiliate_tracking_url(affiliate_id, row_job_id, source=f"proof_task_{task_id}")
                proof_note = (
                    f"autorun_proof affiliate={network or '-'} product={product_name or '-'} "
                    f"requirement={truncate_text(title or prompt or '', 160)}"
                )
                changed, row = update_production_task(
                    owner_id,
                    task_id,
                    status="ready",
                    output_url=proof_url,
                    note=proof_note,
                    asset_type="proof_asset",
                    record_asset=True,
                )
            elif task_type_l == "voice":
                ok_voice, voice_result = await synthesize_operator_voice_task(owner_id, task, job)
                if ok_voice:
                    completed.append(voice_result)
                else:
                    blocked.append({
                        "task_id": int(task_id),
                        "job_id": int(row_job_id),
                        "task_type": task_type,
                        "reason": voice_result.get("reason") or "voice_failed",
                        "error": voice_result.get("error") or voice_result.get("fish_error") or "",
                    })
                processed += 1
                continue
            elif task_type_l == "visual_scene":
                ok_visual, visual_result = await create_operator_visual_scene_fallback(owner_id, task, job)
                if ok_visual:
                    completed.append(visual_result)
                else:
                    pending_external.append({
                        "task_id": int(task_id),
                        "job_id": int(row_job_id),
                        "task_type": task_type,
                        "tool": tool,
                        "scene_no": int(scene_no or 0),
                        "title": title,
                        "reason": visual_result.get("reason") or "visual_fallback_failed",
                        "manual_next": visual_result.get("manual_next") or f"/worker_pack job={int(row_job_id)} task={int(task_id)}",
                        "error": visual_result.get("error") or visual_result.get("stderr") or "",
                        "telegram": {
                            "task_prompt": f"/task_prompt id={int(task_id)}",
                            "worker_pack": f"/worker_pack job={int(row_job_id)} task={int(task_id)}",
                        },
                        "api": {
                            "prompt_pack": f"/api/operator/tasks/{int(task_id)}/prompt-pack",
                            "complete": f"/api/operator/tasks/{int(task_id)}/complete",
                            "upload": f"/api/operator/tasks/{int(task_id)}/upload",
                        },
                    })
                processed += 1
                continue
            elif task_type_l == "edit":
                ok_compose, compose_status, compose_result = await compose_job_video_with_ffmpeg(
                    owner_id,
                    row_job_id,
                    include_voice=True,
                    force=False,
                )
                if ok_compose:
                    completed.append({
                        "task_id": int(task_id),
                        "job_id": int(row_job_id),
                        "task_type": "edit",
                        "status": "ready",
                        "asset_id": compose_result.get("asset_id"),
                        "asset_url": compose_result.get("asset_url"),
                        "local_path": compose_result.get("local_path"),
                        "scene_count": compose_result.get("scene_count"),
                        "voice_included": compose_result.get("voice_included"),
                        "tool": "FFmpeg composer",
                        "note": compose_status,
                        "telegram_review": compose_result.get("telegram_review") or f"/review_video job={int(row_job_id)} send=1",
                    })
                else:
                    pending_external.append({
                        "task_id": int(task_id),
                        "job_id": int(row_job_id),
                        "task_type": task_type,
                        "tool": tool,
                        "scene_no": int(scene_no or 0),
                        "title": title,
                        "reason": compose_status,
                        "message": compose_result.get("message") or "",
                        "manual_next": compose_result.get("manual_next") or f"/worker_pack job={int(row_job_id)} task={int(task_id)}",
                        "error": compose_result.get("error") or compose_result.get("stderr") or "",
                        "telegram": {
                            "compose_video": f"/compose_video job={int(row_job_id)} voice=1",
                            "worker_pack": f"/worker_pack job={int(row_job_id)} task={int(task_id)}",
                        },
                        "api": {
                            "compose": f"/api/operator/jobs/{int(row_job_id)}/compose-video",
                            "complete": f"/api/operator/tasks/{int(task_id)}/complete",
                            "upload": f"/api/operator/tasks/{int(task_id)}/upload",
                        },
                    })
                processed += 1
                continue
            if changed and row:
                readiness = apply_worker_output_job_state(
                    owner_id,
                    row[0],
                    task_id=task_id,
                    task_type=row[1],
                    task_status="ready",
                    asset_type="proof_asset" if task_type_l == "proof_asset" else "review_note",
                    note=proof_note,
                )
                completed.append({
                    "task_id": int(task_id),
                    "job_id": int(row[0]),
                    "task_type": row[1],
                    "status": "ready",
                    "output_url": proof_url,
                    "readiness": (readiness or {}).get("level", "UNKNOWN"),
                    "note": proof_note,
                })
            else:
                blocked.append({"task_id": int(task_id), "job_id": int(row_job_id), "task_type": task_type, "reason": "task_not_updated"})
            processed += 1
    job_ids_for_orders = normalized_ids[:limit]
    return {
        "ok": True,
        "execute": bool(execute),
        "generated_at": now_text(),
        "job_ids": job_ids_for_orders,
        "completed": completed,
        "blocked": blocked,
        "pending_external": pending_external,
        "completed_count": len([item for item in completed if not item.get("preview")]),
        "preview_count": len([item for item in completed if item.get("preview")]),
        "next_video_work_orders": operator_video_work_orders_data(owner_id, job_ids_for_orders, limit=min(limit, 8), tool="claude") if job_ids_for_orders else {"ok": True, "count": 0, "orders": []},
        "rule": "Autorun hoàn thành proof, visual fallback, voice và edit/compose an toàn. Voice dùng Fish nếu có key, lỗi/quota thì fallback Edge TTS. Visual_scene tạo raw_video FFmpeg card khi có ffmpeg/Pillow; edit ghép final_video bằng FFmpeg khi đủ scene. Review/publish vẫn qua admin gate; không fake publish.",
    }

def select_operator_focus_job_id(owner_id, job_id=0):
    try:
        job_id = int(job_id or 0)
    except (TypeError, ValueError):
        job_id = 0
    if job_id and get_production_job(job_id, owner_id):
        return job_id, "explicit"
    task = next_worker_task(owner_id)
    if task:
        return int(task[1]), "next_worker_task"
    for row in list_publish_queue(owner_id, limit=20):
        qid, row_job_id, platform, channel_name, mode, status, scheduled_at, publish_url, topic, updated_at = row
        if (status or "").lower() in {"queued", "scheduled", "publishing", "blocked"} and row_job_id:
            return int(row_job_id), "open_publish_queue"
    for row in list_production_jobs(owner_id, limit=20):
        row_job_id, stage, status, platform, topic, channel_name, product_name, updated_at = row
        if (status or "").lower() not in {"published", "done", "cancelled"}:
            return int(row_job_id), "open_job"
    return 0, "none"

def operator_pipeline_pack_data(owner_id, job_id=0, days=30, platform="tiktok", limit=8):
    focus_job_id, source = select_operator_focus_job_id(owner_id, job_id)
    command_center = operator_command_center_data(owner_id, days=days, platform=platform, limit=limit)
    router = operator_channel_router_data(owner_id, platform=platform, niche="công nghệ AI affiliate", limit=limit)
    if not focus_job_id:
        return {
            "ok": True,
            "generated_at": now_text(),
            "focus_job_id": 0,
            "focus_source": source,
            "command_center": command_center,
            "channel_router": router,
            "pipeline_state": "NO_ACTIVE_JOB",
            "next_action": {
                "type": "LAUNCH",
                "telegram": router.get("commands", {}).get("operator_launch_best") or "/operator_launch topic=công nghệ AI platform=tiktok channel=all limit=3 build=1",
                "api": {"method": "POST", "url": "/api/operator/launch"},
            },
            "rule": "Chưa có job active: hãy launch pipeline mới rồi đọc lại pipeline-pack theo job_id.",
        }
    job = get_production_job(focus_job_id, owner_id)
    readiness = production_readiness_data(owner_id, focus_job_id)
    worker_next = operator_worker_next_summary(owner_id, [focus_job_id], limit=1)
    distribution = build_distribution_pack(owner_id, focus_job_id)
    review = build_video_review_summary(owner_id, focus_job_id)
    post_publish = build_post_publish_handoff(owner_id, focus_job_id, days=days)
    publisher = publisher_status_data(owner_id)
    serialized_job = serialize_production_job(job)
    readiness_level = (readiness or {}).get("level", "UNKNOWN")
    next_task = ((worker_next[0] if worker_next else {}).get("next_task") or {})
    if next_task.get("id"):
        pipeline_state = "WORKER_NEEDED"
        next_action = {
            "type": "WORK_TASK",
            "telegram": f"/task_handoff id={next_task.get('id')}",
            "api": {"method": "GET", "url": f"/api/operator/tasks/claim?job_id={focus_job_id}&include_context=1&include_prompt=1"},
            "worker_pack": f"/api/operator/jobs/{focus_job_id}/worker-pack",
        }
    elif readiness_level == "READY_TO_QUEUE" and (serialized_job or {}).get("status") != "approved":
        pipeline_state = "NEEDS_ADMIN_APPROVAL"
        next_action = {
            "type": "APPROVE",
            "telegram": f"/review_video job={focus_job_id} send=1 rồi /approve_publish job={focus_job_id} queue=1 mode=manual",
            "api": {"method": "GET", "url": f"/api/operator/jobs/{focus_job_id}/review-video"},
            "approve_api": {"method": "POST", "url": f"/api/operator/jobs/{focus_job_id}/approve"},
        }
    elif readiness_level == "READY_TO_QUEUE":
        pipeline_state = "QUEUE_PUBLISH"
        next_action = {
            "type": "QUEUE",
            "telegram": f"/approve_publish job={focus_job_id} queue=1 mode=manual",
            "api": {"method": "POST", "url": f"/api/operator/jobs/{focus_job_id}/approve"},
        }
    elif readiness_level == "READY_TO_PUBLISH" or (publisher.get("open_queue") or []):
        pipeline_state = "PUBLISHER_NEEDED"
        next_action = {
            "type": "PUBLISH",
            "telegram": "/publisher_run platform=tiktok mode=api hoặc /publisher_handoff queue=<QUEUE_ID>",
            "api": {"method": "POST", "url": "/api/operator/publisher/run"},
        }
    elif (serialized_job or {}).get("publish_url"):
        pipeline_state = "TRACK_AND_SCALE"
        next_action = {
            "type": "TRACK",
            "telegram": f"/post_publish job={focus_job_id}",
            "api": {"method": "GET", "url": f"/api/operator/jobs/{focus_job_id}/post-publish"},
        }
    else:
        pipeline_state = readiness_level
        next_action = {
            "type": "CHECK_READY",
            "telegram": f"/job_ready job={focus_job_id}",
            "api": {"method": "GET", "url": f"/api/operator/jobs/{focus_job_id}/ready"},
        }
    return {
        "ok": True,
        "generated_at": now_text(),
        "focus_job_id": focus_job_id,
        "focus_source": source,
        "pipeline_state": pipeline_state,
        "next_action": next_action,
        "job": serialized_job,
        "readiness": readiness,
        "worker_next": worker_next[0] if worker_next else {},
        "distribution_pack": distribution,
        "review_video": review,
        "post_publish": post_publish,
        "publisher": {
            "ready": publisher.get("ready"),
            "api_ready": publisher.get("api_ready"),
            "open_queue": publisher.get("open_queue"),
            "blockers": publisher.get("blockers"),
        },
        "command_center": command_center,
        "channel_router": router,
        "api_sequence": [
            f"GET /api/operator/jobs/{focus_job_id}/pipeline-pack",
            f"GET /api/operator/jobs/{focus_job_id}/worker-pack",
            f"GET /api/operator/jobs/{focus_job_id}/distribution-pack",
            f"GET /api/operator/jobs/{focus_job_id}/review-video",
            f"POST /api/operator/jobs/{focus_job_id}/approve",
            "POST /api/operator/publisher/run",
            f"GET /api/operator/jobs/{focus_job_id}/post-publish",
            "POST /api/operator/performance",
        ],
        "telegram_sequence": [
            f"/pipeline_pack job={focus_job_id}",
            f"/worker_pack job={focus_job_id}",
            f"/distribution_pack job={focus_job_id}",
            f"/review_video job={focus_job_id} send=1",
            f"/approve_publish job={focus_job_id} queue=1 mode=manual",
            "/publisher_run platform=tiktok mode=api",
            f"/post_publish job={focus_job_id}",
        ],
        "rule": "Pipeline pack là bảng điều khiển một job từ worker đến publish và tracking. AI commander chỉ thực hiện next_action hợp lệ; không bỏ qua review/approve gate.",
    }

def add_performance_event(owner_id, job_id, event_type, value=0, amount=0, note="", variant_id=0, affiliate_id_override=0):
    job = get_production_job(job_id, owner_id)
    if not job:
        return False, None
    if variant_id:
        variant = get_creative_variant(owner_id, variant_id)
        if not variant or int(variant[1]) != int(job_id):
            return False, None
    _, _, _, channel_id, affiliate_id, platform, *_ = job
    if affiliate_id_override:
        affiliate_id = int(affiliate_id_override)
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """INSERT INTO performance_events
        (owner_id, job_id, variant_id, channel_id, affiliate_id, platform, event_type, value, amount, note, created_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
        (str(owner_id), job_id, int(variant_id or 0), channel_id, affiliate_id, platform, event_type, int(value), int(amount), note, now_text())
    )
    conn.commit()
    conn.close()
    return True, job

def record_affiliate_click_event(owner_id, affiliate_id, job_id=0, source="redirect_affiliate", note=""):
    affiliate = get_affiliate_link(affiliate_id, owner_id)
    if not affiliate:
        return False, "affiliate_not_found", {}
    job_id = int(job_id or 0)
    job = get_production_job(job_id, owner_id) if job_id else None
    if job:
        ok, _job = add_performance_event(
            owner_id,
            job_id,
            "click",
            1,
            0,
            note,
            0,
            affiliate_id_override=affiliate_id,
        )
        return (True, "recorded", {"job_id": job_id, "affiliate_id": affiliate_id}) if ok else (False, "job_not_found", {})
    platform = "social"
    if source:
        platform = str(source).split("_", 1)[0][:40] or "social"
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """INSERT INTO performance_events
        (owner_id, job_id, variant_id, channel_id, affiliate_id, platform, event_type, value, amount, note, created_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
        (str(owner_id), 0, 0, 0, int(affiliate_id), platform, "click", 1, 0, note, now_text())
    )
    event_id = c.lastrowid
    conn.commit()
    conn.close()
    return True, "recorded_without_job", {"event_id": event_id, "job_id": 0, "affiliate_id": affiliate_id}

def record_affiliate_postback(owner_id, job_id=0, affiliate_id=0, event_type="order", value=1, amount=0, source="affiliate_postback", order_id="", note=""):
    event_type = (event_type or "order").lower()
    if event_type not in {"order", "revenue", "lead"}:
        event_type = "order"
    affiliate_id = int(affiliate_id or 0)
    job_id = int(job_id or 0)
    if not job_id:
        job_id = extract_job_id_from_tracking_source(source) or extract_job_id_from_tracking_source(note)
    if not job_id and affiliate_id:
        conn = db_connect()
        c = conn.cursor()
        c.execute(
            """SELECT id FROM production_jobs
               WHERE owner_id=? AND affiliate_id=?
               ORDER BY updated_at DESC, id DESC LIMIT 1""",
            (str(owner_id), affiliate_id)
        )
        row = c.fetchone()
        conn.close()
        job_id = int(row[0]) if row else 0
    if not job_id:
        return False, "missing_job_id", {}
    detail_parts = []
    if affiliate_id:
        detail_parts.append(f"affiliate:{affiliate_id}")
    if order_id:
        detail_parts.append(f"order:{order_id}")
    if note:
        detail_parts.append(note)
    ok, job = add_performance_event(
        owner_id,
        job_id,
        event_type,
        int(value or 1),
        int(amount or 0),
        format_tracking_note(source or "affiliate_postback", " | ".join(detail_parts)),
        0,
        affiliate_id_override=affiliate_id,
    )
    if not ok:
        return False, "job_not_found", {}
    if amount:
        update_production_job(job_id, owner_id, status="published", note=f"affiliate_postback:{event_type} amount={amount}")
    return True, "recorded", {"job_id": job_id, "affiliate_id": affiliate_id, "event_type": event_type, "amount": int(amount or 0)}

