def affiliate_campaign_cockpit_data(owner_id, days=30, platform="tiktok", limit=10, affiliate_id=0):
    days = max(1, min(int(days or 30), 180))
    limit = max(3, min(int(limit or 10), 50))
    platform = (platform or "tiktok").lower()
