LAST_MEDIA_BY_USER: dict = {}
LAST_AUDIO_FILE = LAST_MEDIA_BY_USER
MEDIA_FACTORY_STATE_TTL_SECONDS = 10 * 60
LAST_USER_AUDIO: dict[int, dict] = {}
LAST_USER_VIDEO: dict[int, dict] = {}
LAST_USER_IMAGE: dict[int, dict] = {}

def is_audio_timeout_error(error) -> bool:
    value = f"{type(error).__name__}: {error}".lower()
    return any(marker in value for marker in ("timedout", "timed out", "timeout", "readtimeout"))

VOICE_FREE_COST  = VOICE_BASE_COST
IMAGE_FREE_COST  = IMAGE_REMOVE_BG_BASE_COST

def message_media_candidate(message) -> tuple[object | None, str]:
    if not message:
        return None, ""
    for attr, file_type in (
        ("voice", "voice"),
        ("audio", "audio"),
        ("video", "video"),
    ):
        media = getattr(message, attr, None)
        if media:
            return media, file_type
    doc = getattr(message, "document", None)
    if doc:
        mime = str(getattr(doc, "mime_type", "") or "")
        file_name = str(getattr(doc, "file_name", "") or "")
        guessed = mimetypes.guess_type(file_name)[0] or ""
        if mime.startswith(("audio/", "video/")) or guessed.startswith(("audio/", "video/")):
            return doc, "document"
    return None, ""

def media_content_type(media, file_type: str = "") -> str:
    content_type = str(getattr(media, "mime_type", "") or "")
    file_name = str(getattr(media, "file_name", "") or "")
    if not content_type and file_name:
        content_type = mimetypes.guess_type(file_name)[0] or ""
    if not content_type:
        content_type = "audio/ogg" if file_type == "voice" else "application/octet-stream"
    return content_type

def cache_recent_media_state(update: Update) -> str:
    try:
        message = update.message
        user_id = int(update.effective_user.id) if update.effective_user else 0
        if not message or not user_id:
            return ""
        created = {"created_at": time.time(), "created_at_text": now_text()}
        if getattr(message, "photo", None):
            photo = message.photo[-1]
            LAST_USER_IMAGE[user_id] = {
                **created,
                "file_id": str(photo.file_id or ""),
                "file_size": int(photo.file_size or 0),
                "mime_type": "image/jpeg",
                "file_name": "telegram_photo.jpg",
            }
            return "image"
        media, file_type = message_media_candidate(message)
        if not media:
            return ""
        info = {
            **created,
            "file_id": str(getattr(media, "file_id", "") or ""),
            "file_unique_id": str(getattr(media, "file_unique_id", "") or ""),
            "file_type": file_type,
            "mime_type": media_content_type(media, file_type),
            "file_name": str(getattr(media, "file_name", "") or ""),
            "file_size": int(getattr(media, "file_size", 0) or 0),
            "duration": int(getattr(media, "duration", 0) or 0),
        }
        mime = info.get("mime_type") or ""
        if file_type == "video" or mime.startswith("video/"):
            LAST_USER_VIDEO[user_id] = info
            return "video"
        if file_type in {"voice", "audio"} or mime.startswith("audio/"):
            LAST_USER_AUDIO[user_id] = info
            return "audio"
    except Exception as e:
        logger.warning(f"media factory state cache failed: {e}")
    return ""

def get_recent_media_state(store: dict[int, dict], user_id) -> dict:
    item = store.get(int(user_id or 0)) or {}
    if not item:
        return {}
    if time.time() - float(item.get("created_at") or 0) > MEDIA_FACTORY_STATE_TTL_SECONDS:
        store.pop(int(user_id or 0), None)
        return {}
    return dict(item)

def get_selected_media_state(store: dict[int, dict], user_id) -> dict:
    item = store.get(int(user_id or 0)) or {}
    if not item:
        return {}
    if time.time() - float(item.get("created_at") or 0) > MEDIA_PREVIEW_TTL_SECONDS:
        store.pop(int(user_id or 0), None)
        return {}
    return dict(item)

def remember_last_media(update: Update):
    try:
        message = update.message
        if not message or not update.effective_user:
            return
        media, file_type = message_media_candidate(message)
        if not media:
            return
        LAST_MEDIA_BY_USER[str(update.effective_user.id)] = {
            "file_id": str(getattr(media, "file_id", "") or ""),
            "file_unique_id": str(getattr(media, "file_unique_id", "") or ""),
            "file_type": file_type,
            "mime_type": media_content_type(media, file_type),
            "file_name": str(getattr(media, "file_name", "") or ""),
            "file_size": int(getattr(media, "file_size", 0) or 0),
            "created_at_ts": time.time(),
            "created_at": now_text(),
        }
    except Exception as e:
        logger.warning(f"last media cache write failed: {e}")

async def resolve_stt_test_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> dict | None:
    reply = update.message.reply_to_message if update.message else None
    media, file_type = message_media_candidate(reply)
    source = "reply"
    meta = {}
    if media:
        meta = {
            "file_id": str(getattr(media, "file_id", "") or ""),
            "file_type": file_type,
            "mime_type": media_content_type(media, file_type),
            "file_name": str(getattr(media, "file_name", "") or ""),
            "file_size": int(getattr(media, "file_size", 0) or 0),
            "created_at": "",
        }
        try:
            file_obj = await media.get_file()
        except Exception as e:
            logger.warning(f"audio media get_file failed: {provider_error_summary(e)}")
            meta.update({
                "source": source,
                "content_type": meta.get("mime_type") or "application/octet-stream",
                "bytes": b"",
                "error": "telegram_timeout" if is_audio_timeout_error(e) else "telegram_download_error",
                "error_detail": provider_error_summary(e),
            })
            return meta
    else:
        cache = LAST_MEDIA_BY_USER.get(str(update.effective_user.id if update.effective_user else ""))
        if not cache:
            return None
        age = time.time() - float(cache.get("created_at_ts") or 0)
        if age > LAST_MEDIA_CACHE_TTL_SECONDS:
            return None
        source = "last_media"
        meta = dict(cache)
        try:
            file_obj = await context.bot.get_file(meta.get("file_id") or "")
        except Exception as e:
            logger.warning(f"cached audio get_file failed: {provider_error_summary(e)}")
            meta.update({
                "source": source,
                "content_type": meta.get("mime_type") or "application/octet-stream",
                "bytes": b"",
                "error": "telegram_timeout" if is_audio_timeout_error(e) else "telegram_download_error",
                "error_detail": provider_error_summary(e),
            })
            return meta
    meta.update({
        "source": source,
        "content_type": meta.get("mime_type") or "application/octet-stream",
    })
    if int(meta.get("file_size", 0) or 0) > 15 * 1024 * 1024:
        meta["bytes"] = b""
        return meta
    try:
        file_bytes = bytes(await file_obj.download_as_bytearray())
    except Exception as e:
        logger.warning(f"audio download failed: {provider_error_summary(e)}")
        meta["bytes"] = b""
        meta["error"] = "telegram_timeout" if is_audio_timeout_error(e) else "telegram_download_error"
        meta["error_detail"] = provider_error_summary(e)
        return meta
    meta["bytes"] = file_bytes
    return meta

def ensure_user_modes(user_id) -> dict:
    uid = str(user_id)
    conn = db_connect()
    try:
        conn.execute("""CREATE TABLE IF NOT EXISTS user_modes (
            user_id TEXT PRIMARY KEY,
            chat_mode TEXT DEFAULT 'normal',
            ai_level TEXT DEFAULT 'normal',
            voice_mode TEXT DEFAULT '',
            media_mode TEXT DEFAULT '',
            translate_mode_target TEXT DEFAULT '',
            updated_at TEXT,
            note TEXT
        )""")
        try:
            conn.execute("ALTER TABLE user_modes ADD COLUMN translate_mode_target TEXT DEFAULT ''")
        except Exception:
            pass
        row = conn.execute(
            "SELECT chat_mode, ai_level, voice_mode, media_mode, COALESCE(translate_mode_target,''), updated_at, note FROM user_modes WHERE user_id=?",
            (uid,),
        ).fetchone()
        if not row:
            conn.execute(
                "INSERT OR IGNORE INTO user_modes (user_id, chat_mode, ai_level, voice_mode, media_mode, translate_mode_target, updated_at, note) VALUES (?,?,?,?,?,?,?,?)",
                (uid, "normal", "normal", "", "", "", now_text(), "default"),
            )
            conn.commit()
            row = ("normal", "normal", "", "", "", now_text(), "default")
        return {
            "user_id": uid,
            "chat_mode": row[0] or "normal",
            "ai_level": row[1] or "normal",
            "voice_mode": row[2] or "",
            "media_mode": row[3] or "",
            "translate_mode_target": row[4] or "",
            "updated_at": row[5] or "",
            "note": row[6] or "",
        }
    finally:
        conn.close()

def set_user_chat_mode(user_id, mode: str, username="", note="") -> tuple[bool, dict]:
    mode = str(mode or "normal").lower().strip()
    if mode not in {"normal", "pro", "deep"}:
        mode = "normal"
    current = ensure_user_modes(user_id)
    changed = current.get("chat_mode") != mode or current.get("ai_level") != mode
    if not changed:
        return False, current
    conn = db_connect()
    try:
        conn.execute(
            """INSERT INTO user_modes (user_id, chat_mode, ai_level, voice_mode, media_mode, updated_at, note)
            VALUES (?,?,?,?,?,?,?)
            ON CONFLICT(user_id) DO UPDATE SET
                chat_mode=excluded.chat_mode,
                ai_level=excluded.ai_level,
                updated_at=excluded.updated_at,
                note=excluded.note""",
            (str(user_id), mode, mode, current.get("voice_mode", ""), current.get("media_mode", ""), now_text(), note),
        )
        record_usage_event_conn(
            conn,
            user_id,
            username=username,
            event_type="mode_enabled" if mode != "normal" else "mode_disabled",
            tool_name="user_mode",
            command=f"/chat_{mode}_on" if mode != "normal" else "/chat_mode_off",
            status=mode,
            detail=note,
        )
        conn.commit()
    finally:
        conn.close()
    return True, ensure_user_modes(user_id)

