async def handle_provider_choice(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    parts = query.data.split("|")
    if len(parts) != 4:
        return
    _, service, mode, uid_str = parts
    uid = int(uid_str)

    if query.from_user.id != uid:
        await query.answer("⚠️ Không phải yêu cầu của bạn!", show_alert=True)
        return

    pending = USER_PENDING.pop(uid, None)
    if not pending:
        await query.edit_message_text("⏰ Yêu cầu đã hết hạn hoặc đã xử lý.")
        return

    if mode == "cancel":
        refunded = refund_charged_credit(
            uid,
            pending.get("cost", 0),
            "refund",
            "",
            "Hoàn xu do khách hủy yêu cầu",
            pending.get("premium_charged", False),
        )
        await query.edit_message_text("❌ Đã huỷ." + (" Xu được hoàn lại." if refunded else ""))
        return

    chat_id  = pending["chat_id"]
    cost     = pending["cost"]
    svc_type = pending["type"]

    if svc_type == "voice":
        data = pending["data"]
        if mode == "free":
            refund_charged_credit(
                uid,
                cost,
                "refund",
                "",
                "Hoàn phí voice cao cấp trước khi chọn gói tiết kiệm",
                pending.get("premium_charged", False),
            )
            free_charge = spend_fixed_credit_info(uid, VOICE_FREE_COST, "spend_voice_free", "Gói voice tiết kiệm")
            voice_free_charged = int(free_charge.get("final_cost") or 0)
            if not free_charge.get("ok"):
                credits_now, _, _ = get_user(uid)
                await edit_insufficient_credits(query, credits_now, voice_free_charged or VOICE_FREE_COST, uid)
                return
            await query.edit_message_text("⏳ <i>Đang tổng hợp giọng nói (Gói Tiết Kiệm)...</i>", parse_mode="HTML")
            out = f"v_{uid}.mp3"
            try:
                if not edge_tts:
                    raise RuntimeError(f"edge-tts package missing: {EDGE_TTS_IMPORT_ERROR or 'import failed'}")
                communicate = edge_tts.Communicate(data, "vi-VN-NamMinhNeural")
                await communicate.save(out)
                with open(out, "rb") as f:
                    await context.bot.send_audio(
                        chat_id=chat_id, audio=f,
                        caption=f"🔊 Gói Tiết Kiệm — Tổng hợp giọng nói thành công! (-{voice_free_charged} Xu)"
                    )
                await query.delete_message()
            except Exception as e:
                logger.error(f"Edge TTS error: {e}")
                refund_charged_credit(uid, voice_free_charged, "refund", "", "Hoàn gói voice tiết kiệm do lỗi", voice_free_charged > 0)
                await query.edit_message_text("❌ Gói Tiết Kiệm gặp lỗi.")
            finally:
                if os.path.exists(out):
                    os.remove(out)
        else:
            await query.edit_message_text("⏳ <i>Đang tổng hợp giọng nói (Gói Cao Cấp)...</i>", parse_mode="HTML")
            out = f"v_{uid}.mp3"
            ok = False
            premium_charge = spend_fixed_credit_info(uid, cost, "spend_voice_paid", "Gói voice cao cấp Fish Audio", apply_member_discount_flag=False)
            premium_charged = bool(premium_charge.get("ok"))
            cost = int(premium_charge.get("final_cost") or cost)
            if not premium_charged:
                credits_now, _, _ = get_user(uid)
                await edit_insufficient_credits(query, credits_now, cost, uid)
                return
            premium_refunded = False
            fallback_charged = False
            try:
                if FISH_AUDIO_KEY:
                    try:
                        async with httpx.AsyncClient() as client:
                            res = await client.post(
                                "https://api.fish.audio/v1/tts",
                                headers={"Authorization": f"Bearer {FISH_AUDIO_KEY}", "Content-Type": "application/json"},
                                json={"text": data, "reference_id": "7f0955e88846433e9ecb241357608bf8", "format": "mp3"},
                                timeout=30.0
                            )
                        if res.status_code == 200:
                            with open(out, "wb") as f:
                                f.write(res.content)
                            ok = True
                            with open(out, "rb") as f:
                                await context.bot.send_audio(
                                    chat_id=chat_id, audio=f,
                                    caption=f"🎙️ Gói Cao Cấp — Tổng hợp thành công! (-{cost} Xu)"
                                )
                            await query.delete_message()
                        else:
                            logger.warning(f"Fish Audio {res.status_code} — fallback Edge TTS")
                            await alert_admin(
                                context,
                                "Fish Audio HD",
                                f"HTTP {res.status_code}. Đã fallback Edge TTS cho user={uid}. Kiểm tra quota/số dư/API key."
                            )
                    except Exception as e:
                        logger.error(f"Fish Audio exception: {e} — fallback Edge TTS")
                        await alert_admin(
                            context,
                            "Fish Audio HD",
                            f"Exception: {str(e)}. Đã fallback Edge TTS cho user={uid}. Kiểm tra quota/số dư/API key."
                        )
                else:
                    await alert_admin(
                        context,
                        "Fish Audio HD",
                        f"Chưa cấu hình FISH_AUDIO_KEY. Đã fallback Edge TTS cho user={uid}."
                    )
                if not ok:
                    premium_refunded = refund_charged_credit(
                        uid,
                        cost,
                        "refund",
                        "",
                        "Hoàn phí voice cao cấp do fallback",
                        premium_charged,
                    )
                    fallback_charge = spend_fixed_credit_info(uid, VOICE_FREE_COST, "spend_voice_free_fallback", "Fallback sang Edge TTS")
                    fallback_cost = int(fallback_charge.get("final_cost") or 0)
                    if not fallback_charge.get("ok"):
                        credits_now, _, _ = get_user(uid)
                        await edit_insufficient_credits(query, credits_now, fallback_cost or VOICE_FREE_COST, uid)
                        return
                    fallback_charged = True
                    try:
                        if not edge_tts:
                            raise RuntimeError(f"edge-tts package missing: {EDGE_TTS_IMPORT_ERROR or 'import failed'}")
                        communicate = edge_tts.Communicate(data, "vi-VN-NamMinhNeural")
                        await communicate.save(out)
                        with open(out, "rb") as f:
                            await context.bot.send_audio(
                                chat_id=chat_id, audio=f,
                                caption=f"🔊 Gói Tiết Kiệm — Hoàn thành! (-{fallback_cost} Xu)"
                            )
                        await query.delete_message()
                    except Exception as e:
                        logger.error(f"Edge TTS fallback error: {e}")
                        refund_charged_credit(uid, fallback_cost, "refund", "", "Hoàn gói voice fallback do lỗi", fallback_charged and fallback_cost > 0)
                        await query.edit_message_text(
                            "❌ Tạo voice đang tạm lỗi.\n"
                            "Xu đã hoàn lại nếu đã trừ. Vui lòng thử lại sau."
                        )
            except Exception as e:
                logger.error(f"Voice paid error: {e}")
                if not premium_refunded:
                    refund_charged_credit(uid, cost, "refund", "", "Hoàn phí voice cao cấp do lỗi", premium_charged)
                await query.edit_message_text("❌ Lỗi tổng hợp giọng.")
            finally:
                if os.path.exists(out):
                    os.remove(out)

    elif svc_type == "image":
        img_bytes = pending["file_bytes"]
        if mode == "free":
            refund_charged_credit(
                uid,
                cost,
                "refund",
                "",
                "Hoàn phí ảnh cao cấp trước khi chọn gói tiết kiệm",
                pending.get("premium_charged", False),
            )
            free_charge = spend_fixed_credit_info(uid, IMAGE_FREE_COST, "spend_image_free", "Gói tách nền tiết kiệm")
            image_free_charged = int(free_charge.get("final_cost") or 0)
            if not free_charge.get("ok"):
                credits_now, _, _ = get_user(uid)
                await edit_insufficient_credits(query, credits_now, image_free_charged or IMAGE_FREE_COST, uid)
                return
            await query.edit_message_text("⏳ <i>Đang tách nền (Gói Tiết Kiệm)...</i>", parse_mode="HTML")
            ok = False
            if CUTOUT_API_KEY:
                try:
                    async with httpx.AsyncClient() as client:
                        res = await client.post(
                            "https://www.cutout.pro/api/v1/matting2?mattingType=2&crop=true",
                            headers={"APIKEY": CUTOUT_API_KEY},
                            files={"file": img_bytes},
                            timeout=30.0
                        )
                    image_ok, png_bytes, image_detail = normalize_provider_image_response(res, "Cutout")
                    if image_ok:
                        await context.bot.send_document(
                            chat_id=chat_id, document=telegram_png_document(png_bytes),
                            filename="no_bg.png",
                            caption=f"✂️ Gói Tiết Kiệm — Tách nền thành công! (-{image_free_charged} Xu)"
                        )
                        save_tool_test_result("image_remove_bg", "PASS", "provider=cutout; cost_level=low; remove_bg command success", uid)
                        save_tool_test_result("image", "PASS", "provider=cutout; cost_level=low; remove_bg command success", uid)
                        await query.delete_message()
                        ok = True
                    else:
                        logger.warning(f"Cutout invalid output: {image_detail}")
                        save_tool_test_result("image_remove_bg", "FAIL", f"provider=cutout; {image_detail}", uid)
                        record_api_debug("cutout", "remove_bg_customer", "FAIL", getattr(res, "status_code", 0), image_detail)
                except Exception as e:
                    logger.error(f"Cutout error: {e}")
                    record_api_debug("cutout", "remove_bg_customer", "FAIL", 0, provider_error_summary(e))
            if not ok:
                refund_charged_credit(uid, image_free_charged, "refund", "", "Hoàn gói tách nền tiết kiệm do lỗi", image_free_charged > 0)
                await query.edit_message_text(
                    "❌ Tách nền đang admin test/chưa mở public hoặc công cụ đang lỗi.\n"
                    "Bot chưa trừ Xu. Vui lòng thử lại sau."
                )
        else:
            await query.edit_message_text("⏳ <i>Đang tách nền (Gói Cao Cấp)...</i>", parse_mode="HTML")
            ok = False
            premium_charge = spend_fixed_credit_info(uid, cost, "spend_image_paid", "Gói tách nền cao cấp RemoveBG", apply_member_discount_flag=False)
            premium_charged = bool(premium_charge.get("ok"))
            cost = int(premium_charge.get("final_cost") or cost)
            if not premium_charged:
                credits_now, _, _ = get_user(uid)
                await edit_insufficient_credits(query, credits_now, cost, uid)
                return
            premium_refunded = False
            if REMOVEBG_API_KEY:
                try:
                    async with httpx.AsyncClient() as client:
                        res = await client.post(
                            "https://api.remove.bg/v1.0/removebg",
                            headers={"X-Api-Key": REMOVEBG_API_KEY},
                            files={"image_file": img_bytes},
                            data={"size": "auto"},
                            timeout=30.0
                        )
                    image_ok, png_bytes, image_detail = normalize_provider_image_response(res, "RemoveBG")
                    if image_ok:
                        await context.bot.send_document(
                            chat_id=chat_id, document=telegram_png_document(png_bytes),
                            filename="no_bg.png",
                            caption=f"✂️ Gói Cao Cấp — Tách nền HD thành công! (-{cost} Xu)"
                        )
                        save_tool_test_result("image_remove_bg", "PASS", "provider=removebg; cost_level=medium; remove_bg command success", uid)
                        save_tool_test_result("image", "PASS", "provider=removebg; cost_level=medium; remove_bg command success", uid)
                        await query.delete_message()
                        ok = True
                    else:
                        logger.warning(f"RemoveBG invalid output: {image_detail} → fallback Cutout")
                        save_tool_test_result("image_remove_bg", "FAIL", f"provider=removebg; {image_detail}", uid)
                        record_api_debug("removebg", "remove_bg_customer", "FAIL", getattr(res, "status_code", 0), image_detail)
                        await alert_admin(
                            context,
                            "RemoveBG HD",
                            f"{image_detail}. Đã fallback Cutout.pro cho user={uid}. Kiểm tra quota/số dư/API key."
                        )
                except Exception as e:
                    logger.error(f"RemoveBG error: {e}")
                    record_api_debug("removebg", "remove_bg_customer", "FAIL", 0, provider_error_summary(e))
                    await alert_admin(
                        context,
                        "RemoveBG HD",
                        f"Exception: {str(e)}. Đã fallback Cutout.pro cho user={uid}. Kiểm tra quota/số dư/API key."
                    )
            else:
                await alert_admin(
                    context,
                    "RemoveBG HD",
                    f"Chưa cấu hình REMOVEBG_API_KEY. Đã fallback Cutout.pro cho user={uid}."
                )
            if not ok:
                premium_refunded = refund_charged_credit(
                    uid,
                    cost,
                    "refund",
                    "",
                    "Hoàn phí ảnh cao cấp do fallback",
                    premium_charged,
                )
                fallback_charge = spend_fixed_credit_info(uid, IMAGE_FREE_COST, "spend_image_free_fallback", "Fallback sang Cutout")
                fallback_cost = int(fallback_charge.get("final_cost") or 0)
                if not fallback_charge.get("ok"):
                    credits_now, _, _ = get_user(uid)
                    await edit_insufficient_credits(query, credits_now, fallback_cost or IMAGE_FREE_COST, uid)
                    return
                cutout_ok = False
                if CUTOUT_API_KEY:
                    try:
                        async with httpx.AsyncClient() as client:
                            res = await client.post(
                                "https://www.cutout.pro/api/v1/matting2?mattingType=2&crop=true",
                                headers={"APIKEY": CUTOUT_API_KEY},
                                files={"file": img_bytes},
                                timeout=30.0
                            )
                        image_ok, png_bytes, image_detail = normalize_provider_image_response(res, "Cutout")
                        if image_ok:
                            await context.bot.send_document(
                                chat_id=chat_id, document=telegram_png_document(png_bytes),
                                filename="no_bg.png",
                                caption=f"✂️ Gói Tiết Kiệm — Hoàn thành! (-{fallback_cost} Xu)"
                            )
                            save_tool_test_result("image_remove_bg", "PASS", "provider=cutout; cost_level=low; remove_bg fallback success", uid)
                            save_tool_test_result("image", "PASS", "provider=cutout; cost_level=low; remove_bg fallback success", uid)
                            await query.delete_message()
                            cutout_ok = True
                        else:
                            logger.warning(f"Cutout fallback invalid output: {image_detail}")
                            save_tool_test_result("image_remove_bg", "FAIL", f"provider=cutout; {image_detail}", uid)
                            record_api_debug("cutout", "remove_bg_customer_fallback", "FAIL", getattr(res, "status_code", 0), image_detail)
                    except Exception as e:
                        logger.error(f"Cutout fallback error: {e}")
                        record_api_debug("cutout", "remove_bg_customer_fallback", "FAIL", 0, provider_error_summary(e))
                if not cutout_ok:
                    refund_charged_credit(uid, fallback_cost, "refund", "", "Hoàn gói tách nền fallback do lỗi", fallback_cost > 0)
                    if not premium_refunded:
                        refund_charged_credit(uid, cost, "refund", "", "Hoàn phí ảnh cao cấp do lỗi", premium_charged)
                    await query.edit_message_text(
                        "❌ Tách nền đang admin test/chưa mở public hoặc công cụ đang lỗi.\n"
                        "Bot chưa trừ Xu. Vui lòng thử lại sau."
                    )


async def handle_package_choice(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Xử lý sinh hóa đơn và link QR Động từ PayOS khi khách click chọn gói"""
    expire_old_payos_orders()
    query = update.callback_query
    await query.answer()
    parts = query.data.split("|")
    if len(parts) != 3:
        return
    _, pkg_key, uid_str = parts
    uid = int(uid_str)

    if query.from_user.id != uid:
        await query.answer("⚠️ Không phải yêu cầu của bạn!", show_alert=True)
        return

    if pkg_key.startswith("manual_"):
        manual_key = pkg_key.replace("manual_", "", 1)
        if manual_key in PAYMENT_PACKAGES:
            pkg = PAYMENT_PACKAGES[manual_key]
            amount = int(pkg["amount"])
            get_user(uid, query.from_user.first_name or "Manual payment user")
            package_credit = calculate_package_credit_for_user(uid, amount)
            base_xu = int(package_credit.get("base_xu") or pkg["xu"])
            launch_preview = int(package_credit.get("launch_bonus_xu") or 0)
            xu = int(package_credit.get("total_xu") or base_xu)
            order_code = generate_order_code()
            create_order(
                order_code,
                uid,
                amount,
                xu,
                base_xu=base_xu,
                launch_bonus_xu=launch_preview,
                package_amount_vnd=amount,
            )
            set_manual_bill_state(uid, order_code=order_code, amount=amount, xu=xu, pkg_key=manual_key)
            await query.edit_message_text(
                manual_payment_text(uid, amount, xu, order_code, "Bạn đã chọn nạp thủ công."),
                parse_mode="HTML",
            )
            try:
                await context.bot.send_photo(
                    chat_id=query.message.chat_id,
                    photo=manual_qr_url(uid, amount, order_code),
                    caption="🏦 QR thủ công theo đúng số tiền và nội dung chuyển khoản.",
                    parse_mode="HTML",
                )
            except Exception as e:
                logger.error(f"Manual QR callback send error: {e}")
            return
        set_manual_bill_state(uid, order_code="MANUAL")
        return await query.edit_message_text(
            manual_custom_payment_text(uid, "Bạn đã chọn nạp thủ công."),
            parse_mode="HTML",
        )

    if pkg_key not in PAYMENT_PACKAGES:
        await query.edit_message_text("❌ Mệnh giá nạp không hợp lệ.")
        return

    pkg = PAYMENT_PACKAGES[pkg_key]
    amount = pkg["amount"]
    get_user(uid, query.from_user.first_name or "PayOS user")
    package_credit = calculate_package_credit_for_user(uid, amount)
    base_xu = int(package_credit.get("base_xu") or pkg["xu"])
    launch_preview = int(package_credit.get("launch_bonus_xu") or 0)
    xu = int(package_credit.get("total_xu") or base_xu)
    if web_billing_checkout_enabled("topup_xu"):
        web_payload = build_web_billing_payment_payload(
            uid,
            "topup_xu",
            pkg_key,
            amount,
            {
                "base_xu": int(base_xu),
                "launch_bonus_preview_xu": int(launch_preview),
                "expected_total_xu": int(xu),
            },
        )
        web_result = await create_web_billing_payment_link(web_payload)
        if web_result.get("ok") and web_result.get("checkout_url"):
            web_order = web_result.get("order_code") or "web_app"
            return await query.edit_message_text(
                "⚡ <b>ĐÃ KHỞI TẠO HÓA ĐƠN PAYOS QUA WEB APP</b>\n\n"
                f"📋 Mệnh giá: <b>{html.escape(pkg['text'])}</b>\n"
                f"💰 Số tiền: <b>{amount:,}đ</b>\n"
                f"🪙 Xu dự kiến: <b>+{xu} Xu</b>\n"
                f"🆔 Mã đơn Web App: <code>{html.escape(str(web_order))}</code>\n\n"
                "Xu chỉ được cộng khi webhook PayOS đã xác thực thành công. Không cộng Xu ở bước tạo link.",
                parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔗 Thanh toán PayOS", url=web_result["checkout_url"])]])
            )
        if not BOT_PAYOS_FALLBACK_ENABLED:
            return await query.edit_message_text(
                "❌ Web Billing chưa tạo được link thanh toán. Bot chưa tạo đơn và chưa cộng/trừ Xu."
            )
    order_code = generate_order_code()
    create_order(
        order_code,
        uid,
        amount,
        xu,
        base_xu=base_xu,
        launch_bonus_xu=launch_preview,
        package_amount_vnd=amount,
    )
    if flag_on("payment_freeze"):
        update_order_status(order_code, PAYOS_STATUS_CANCELLED)
        await query.edit_message_text(
            payos_checkout_unavailable_text(
                pkg_key,
                amount,
                order_code,
                "PayOS QR động đang khóa an toàn. Dùng /thucong nếu cần nạp thủ công.",
            ),
            parse_mode="HTML",
            reply_markup=payos_unavailable_keyboard(pkg_key, uid),
        )
        return

    if not PAYOS_CLIENT_ID or not PAYOS_API_KEY or not PAYOS_CHECKSUM_KEY:
        update_order_status(order_code, PAYOS_STATUS_CANCELLED)
        await record_payos_failure_and_maybe_alert(context, "PayOS config missing", user_id=uid)
        await query.edit_message_text(
            payos_checkout_unavailable_text(
                pkg_key,
                amount,
                order_code,
                "Thiếu PAYOS_CLIENT_ID/PAYOS_API_KEY/PAYOS_CHECKSUM_KEY.",
            ),
            parse_mode="HTML",
            reply_markup=payos_unavailable_keyboard(pkg_key, uid),
        )
        return

    return_url = make_payos_return_url(context)
    payos_body = {
        "orderCode": order_code,
        "amount": amount,
        "description": make_payos_description(pkg_key),
        "cancelUrl": make_payos_cancel_url(context),
        "returnUrl": return_url
    }

    try:
        res = None
        res_data = {}
        raw_preview = ""
        raw_str = ""
        res, res_data, raw_preview, raw_str = await create_payos_payment_request(payos_body)
        if res.status_code == 200 and res_data.get("code") == "00":
            checkout_data = res_data["data"]
            checkout_url = checkout_data["checkoutUrl"]
            update_order_checkout_info(order_code, checkout_url, checkout_data.get("paymentLinkId", ""))
            promo_attach = attach_pending_promo_to_order(uid, order_code, amount, base_xu)
            launch_preview_line = (
                f"🎁 Launch Bonus dự kiến: <b>+{launch_preview} Xu</b> nếu còn lần đầu mua mệnh giá này.\n"
                if launch_preview else ""
            )
            total_preview_line = (
                f"🧾 Tổng Xu mệnh giá này sau PayOS success: <b>+{xu} Xu</b>\n"
                if launch_preview else ""
            )
            promo_line = ""
            if promo_attach.get("attached"):
                promo_line = (
                    f"🎁 Mã <code>{html.escape(promo_attach.get('code') or '')}</code> sẽ tặng thêm "
                    f"<b>+{int(promo_attach.get('bonus_xu') or 0)} Xu</b> sau khi thanh toán thành công.\n"
                    "• Mỗi đơn chỉ áp dụng 1 mã, không cộng dồn.\n"
                )
            elif promo_attach.get("code") and promo_attach.get("reason") not in {"no_pending"}:
                reason_text = promo_code_status_message(str(promo_attach.get("reason") or ""))
                promo_line = (
                    f"⚠️ Mã <code>{html.escape(promo_attach.get('code') or '')}</code> chưa đủ điều kiện cho mệnh giá này "
                    f"({html.escape(reason_text)}), đơn vẫn tạo bình thường.\n"
                )
            qr_text = (
                f"⚡ <b>ĐÃ KHỞI TẠO HÓA ĐƠN QR ĐỘNG SUCCESS</b>\n\n"
                f"📋 Mệnh giá lựa chọn: <b>{pkg['text']}</b>\n"
                f"💰 Số tiền cần chuyển: <b>{amount:,}đ</b>\n"
                f"🪙 Xu gốc: <b>+{base_xu} Xu</b>\n"
                f"{launch_preview_line}"
                f"{total_preview_line}"
                f"{promo_line}"
                f"🆔 Mã đơn định danh: <code>{order_code}</code>\n\n"
                f"⏳ Hóa đơn hết hạn sau <b>{ORDER_TTL_MINUTES} phút</b>.\n\n"
                f"👉 Nhấn vào nút liên kết dưới đây để nhận diện mã QR thanh toán động. Hệ thống sẽ tự động điền sẵn số tiền và nội dung hóa đơn chính xác!"
            )
            logger.info(f"PayOS create success | order={order_code}")
            kb = InlineKeyboardMarkup([[InlineKeyboardButton("🔗 QUÉT MÃ QR THANH TOÁN", url=checkout_url)]])
            await query.edit_message_text(qr_text, parse_mode="HTML", reply_markup=kb)
        else:
            update_order_status(order_code, PAYOS_STATUS_CANCELLED)
            logger.error(
                "PayOS create failed | status=%s | order=%s | amount=%s | response=%s | signature_data=%s | raw=%s",
                getattr(res, "status_code", ""),
                order_code,
                amount,
                res_data,
                raw_str,
                raw_preview[:500],
            )
            desc = res_data.get("desc") or res_data.get("message") or raw_preview or "Lỗi không rõ"
            await record_payos_failure_and_maybe_alert(context, desc, user_id=uid)
            await query.edit_message_text(
                payos_checkout_unavailable_text(pkg_key, amount, order_code, desc),
                parse_mode="HTML",
                reply_markup=payos_unavailable_keyboard(pkg_key, uid),
            )
    except Exception as e:
        update_order_status(order_code, PAYOS_STATUS_CANCELLED)
        logger.error(f"PayOS Exception: {e}")
        await record_payos_failure_and_maybe_alert(context, f"{type(e).__name__}: {e}", user_id=uid)
        await query.edit_message_text(
            payos_checkout_unavailable_text(pkg_key, amount, order_code, str(e)),
            parse_mode="HTML",
            reply_markup=payos_unavailable_keyboard(pkg_key, uid),
        )

async def handle_manual_package_choice(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    parts = (query.data or "").split("|")
    if len(parts) < 2:
        return
    action = parts[1]
    if action in {"approve", "approve_expected", "approve_custom", "reject", "confirm"}:
        if not is_admin_user(query.from_user.id):
            return await query.answer("Bạn không có quyền duyệt bill.", show_alert=True)
        if action in {"approve", "approve_expected", "approve_custom"} and len(parts) == 3 and str(parts[2]).isdigit():
            deposit_id = int(parts[2])
            conn = db_connect()
            try:
                row = conn.execute(
                    "SELECT user_id,xu,expected_xu FROM pending_deposits WHERE id=? AND status IN ('pending','pending_admin_review') LIMIT 1",
                    (deposit_id,),
                ).fetchone()
            finally:
                conn.close()
            if not row:
                return await query.message.reply_text("⚠️ Bill này không còn ở trạng thái chờ duyệt.")
            expected_xu = int(row[2] or row[1] or 0)
            if action == "approve_expected":
                set_manual_approval_state(
                    query.from_user.id,
                    deposit_id,
                    row[0],
                    step="confirm",
                    amount=expected_xu,
                    expected_xu=expected_xu,
                    reason="Duyệt đúng Xu dự kiến",
                )
                return await query.message.reply_text(
                    f"✅ <b>Xác nhận duyệt đúng Xu dự kiến</b>\n\n"
                    f"• Bill: <code>#{deposit_id}</code>\n"
                    f"• User: <code>{html.escape(str(row[0]))}</code>\n"
                    f"• Cộng: <b>{expected_xu} Xu</b>\n\n"
                    "Chỉ xác nhận sau khi đã kiểm tra tiền/giao dịch thật.",
                    parse_mode="HTML",
                    reply_markup=InlineKeyboardMarkup([[
                        InlineKeyboardButton("✅ Xác nhận cộng Xu", callback_data=f"manual|confirm|{deposit_id}|{expected_xu}"),
                        InlineKeyboardButton("❌ Không duyệt", callback_data=f"manual|reject|{deposit_id}"),
                    ]]),
                )
            set_manual_approval_state(
                query.from_user.id,
                deposit_id,
                row[0],
                amount=expected_xu,
                expected_xu=expected_xu,
            )
            return await query.message.reply_text(
                f"✅ Bill #{deposit_id} đang chờ nhập Xu thực tế. Hãy nhập số Xu cần cộng trong tin nhắn tiếp theo.\n"
                "Bot chưa cộng Xu ở bước này."
            )
        if action == "reject" and len(parts) == 3 and str(parts[2]).isdigit():
            proxy_update = SimpleNamespace(effective_user=query.from_user, message=query.message)
            old_args = list(context.args or [])
            context.args = [parts[2]]
            try:
                return await cmd_tuchoi(proxy_update, context)
            finally:
                context.args = old_args
        if action == "confirm" and len(parts) == 4 and str(parts[2]).isdigit() and str(parts[3]).isdigit():
            state = get_manual_approval_state(query.from_user.id)
            if not state or int(state.get("deposit_id") or 0) != int(parts[2]) or int(state.get("amount") or 0) != int(parts[3]):
                return await query.answer("Xác nhận đã hết hạn hoặc không khớp.", show_alert=True)
            approval_state = dict(state)
            MANUAL_APPROVAL_STATE.pop(str(query.from_user.id), None)
            proxy_update = SimpleNamespace(effective_user=query.from_user, message=query.message)
            old_args = list(context.args or [])
            context.args = [parts[2], parts[3], approval_state.get("reason") or ""]
            try:
                return await cmd_duyet(proxy_update, context)
            finally:
                context.args = old_args
        return
    if action == "currency" and len(parts) == 4:
        currency = str(parts[2] or "").upper()
        uid = int(parts[3]) if str(parts[3]).isdigit() else int(query.from_user.id)
        if query.from_user.id != uid:
            return await query.answer("⚠️ Không phải yêu cầu của bạn!", show_alert=True)
        if currency == "VND":
            existing_state = get_active_manual_bill_state(uid) or {}
            selected_pkg_key = str(existing_state.get("pkg_key") or "")
            if selected_pkg_key in PAYMENT_PACKAGES:
                preview = manual_vnd_topup_preview(uid, selected_pkg_key, "bank_acb")
                set_manual_bill_state(
                    uid,
                    order_code=existing_state.get("order_code") or "MANUAL",
                    step="select_method",
                    **preview,
                )
                return await query.edit_message_text(
                    "🇻🇳 <b>Chọn phương thức nạp VND</b>\n\n"
                    f"Mệnh giá: <b>{int(preview['amount_vnd']):,}đ</b>\n"
                    f"Xu gốc dự kiến: <b>{int(preview['base_xu']):,} Xu</b>\n\n"
                    "ACB/VietQR có thể nhận ưu đãi cộng Xu nếu tài khoản đủ điều kiện. "
                    "ZaloPay không áp dụng ưu đãi cộng Xu.".replace(",", "."),
                    parse_mode="HTML",
                    reply_markup=manual_domestic_method_keyboard(uid),
                )
            set_manual_bill_state(uid, order_code="MANUAL", currency="VND", foreign_manual=False, step="select_amount")
            return await query.edit_message_text(
                manual_domestic_amount_text(),
                parse_mode="HTML",
                reply_markup=manual_domestic_amount_keyboard(uid),
            )
        if not MANUAL_FOREIGN_TOPUP_ENABLED or currency not in SUPPORTED_MANUAL_CURRENCIES or currency not in {"USD", "CNY"}:
            return await query.edit_message_text("⚠️ Loại tiền này chưa được mở cho nạp thủ công.", reply_markup=manual_payment_menu_keyboard(uid))
        set_manual_bill_state(uid, order_code="MANUAL", currency=currency, foreign_manual=True, step="select_amount")
        return await query.edit_message_text(
            manual_foreign_amount_text(currency),
            parse_mode="HTML",
            reply_markup=manual_foreign_amount_keyboard(currency, uid),
        )
    if action == "vndamount" and len(parts) == 4:
        pkg_key = str(parts[2] or "")
        uid = int(parts[3]) if str(parts[3]).isdigit() else int(query.from_user.id)
        if query.from_user.id != uid:
            return await query.answer("⚠️ Không phải yêu cầu của bạn!", show_alert=True)
        if pkg_key not in PAYMENT_PACKAGES:
            return await query.edit_message_text(manual_domestic_amount_text(), parse_mode="HTML", reply_markup=manual_domestic_amount_keyboard(uid))
        preview = manual_vnd_topup_preview(uid, pkg_key, "bank_acb")
        set_manual_bill_state(uid, order_code="MANUAL", step="select_method", **preview)
        return await query.edit_message_text(
            "🇻🇳 <b>Chọn phương thức nạp VND</b>\n\n"
            f"Mệnh giá: <b>{int(preview['amount_vnd']):,}đ</b>\n"
            f"Xu gốc dự kiến: <b>{int(preview['base_xu']):,} Xu</b>\n\n"
            "ACB/VietQR có thể nhận ưu đãi cộng Xu nếu tài khoản đủ điều kiện. "
            "ZaloPay không áp dụng ưu đãi cộng Xu.".replace(",", "."),
            parse_mode="HTML",
            reply_markup=manual_domestic_method_keyboard(uid),
        )
    if action == "fxamount" and len(parts) == 5:
        currency = str(parts[2] or "").upper()
        uid = int(parts[4]) if str(parts[4]).isdigit() else int(query.from_user.id)
        if query.from_user.id != uid:
            return await query.answer("⚠️ Không phải yêu cầu của bạn!", show_alert=True)
        try:
            preview = foreign_topup_preview(currency, parts[3])
        except ValueError:
            return await query.edit_message_text("⚠️ Mệnh giá quốc tế không hợp lệ.", reply_markup=manual_foreign_amount_keyboard(currency, uid))
        set_manual_bill_state(uid, order_code="MANUAL", amount=preview["amount_vnd"], xu=preview["expected_xu"], **preview)
        return await query.edit_message_text(
            manual_foreign_preview_text(preview),
            parse_mode="HTML",
            reply_markup=manual_foreign_preview_keyboard(preview, uid),
        )
    if action == "fxcustom" and len(parts) == 4:
        currency = str(parts[2] or "").upper()
        uid = int(parts[3]) if str(parts[3]).isdigit() else int(query.from_user.id)
        if query.from_user.id != uid:
            return await query.answer("⚠️ Không phải yêu cầu của bạn!", show_alert=True)
        set_manual_bill_state(uid, order_code="MANUAL", currency=currency, foreign_manual=True, step="await_foreign_amount")
        return await query.edit_message_text(
            f"✍️ Hãy nhập số {currency} muốn nạp trong tin nhắn tiếp theo.\n\nBot chỉ tạo bản quy đổi tạm tính, chưa cộng Xu và chưa tự duyệt giao dịch.",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton(f"⬅️ Mệnh giá {currency}", callback_data=f"manual|currency|{currency}|{uid}"),
                InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main"),
            ]]),
        )
    if action == "fxmethod" and len(parts) == 6:
        currency = str(parts[2] or "").upper()
        method = str(parts[4] or "")
        uid = int(parts[5]) if str(parts[5]).isdigit() else int(query.from_user.id)
        if query.from_user.id != uid:
            return await query.answer("⚠️ Không phải yêu cầu của bạn!", show_alert=True)
        if method not in {"zalopay_personal", "zalopay_merchant", "momo_tuithantai", "usdt_trc20"} or not manual_method_enabled(method, uid):
            return await query.edit_message_text("⚠️ Phương thức này chưa được bật hoặc đang chờ admin kiểm tra.", reply_markup=manual_foreign_amount_keyboard(currency, uid))
        try:
            preview = foreign_topup_preview(currency, parts[3], method=method)
        except ValueError:
            return await query.edit_message_text("⚠️ Mệnh giá quốc tế không hợp lệ.", reply_markup=manual_foreign_amount_keyboard(currency, uid))
        transfer_content = f"AAS {uid} {currency} MANUAL"
        set_manual_bill_state(
            uid,
            order_code="MANUAL",
            amount=preview["amount_vnd"],
            xu=preview["expected_xu"],
            transfer_content=transfer_content,
            step="await_payment",
            **preview,
        )
        sent = await send_manual_payment_qr(
            update,
            context,
            method,
            manual_payment_method_text(uid, method, get_active_manual_bill_state(uid)),
            manual_method_keyboard(uid),
        )
        update_manual_bill_state(uid, step="await_payment" if sent else "select_method")
        return
    uid_token = parts[-1] if len(parts) >= 3 else str(query.from_user.id)
    uid = int(uid_token) if str(uid_token).isdigit() else int(query.from_user.id)
    if query.from_user.id != uid and not (action == "history" and is_admin_user(query.from_user.id)):
        await query.answer("⚠️ Không phải yêu cầu của bạn!", show_alert=True)
        return
    if action == "menu":
        state = get_active_manual_bill_state(uid)
        if not state:
            set_manual_bill_state(uid, order_code="MANUAL")
        return await query.edit_message_text(manual_payment_menu_text(), parse_mode="HTML", reply_markup=manual_payment_menu_keyboard(uid))
    if action == "history":
        text, keyboard = manual_topup_history_payload(uid)
        return await query.edit_message_text(text, parse_mode="HTML", reply_markup=keyboard)
    if action == "method" and len(parts) == 4:
        method = parts[2]
        if not manual_method_enabled(method, uid):
            return await query.edit_message_text(
                "⚠️ Phương thức này đang được admin kiểm tra, hiện chưa mở công khai.\n\nBạn có thể dùng PayOS QR động hoặc nạp thủ công qua ngân hàng.",
                reply_markup=manual_payment_menu_keyboard(uid),
            )
        state = get_active_manual_bill_state(uid) or {}
        pkg_key = str(state.get("pkg_key") or "")
        if pkg_key not in PAYMENT_PACKAGES:
            return await query.edit_message_text(
                manual_domestic_amount_text(),
                parse_mode="HTML",
                reply_markup=manual_domestic_amount_keyboard(uid),
            )
        preview = manual_vnd_topup_preview(uid, pkg_key, method)
        update_manual_bill_state(uid, step="select_method", **preview)
        sent = await send_manual_payment_qr(
            update,
            context,
            method,
            manual_payment_method_text(uid, method, get_active_manual_bill_state(uid)),
            manual_method_keyboard(uid),
        )
        update_manual_bill_state(uid, step="await_payment" if sent else "select_method")
        return
    if action == "await_bill":
        state = get_active_manual_bill_state(uid)
        if not state:
            set_manual_bill_state(uid, order_code="MANUAL")
        update_manual_bill_state(uid, step="await_bill")
        return await query.edit_message_text(
            "📷 <b>Gửi bill/TXID nạp thủ công</b>\n\nHãy gửi một ảnh bill hoặc TXID trong tin nhắn tiếp theo. "
            "TOAN AAS chỉ chuyển thông tin sang chờ admin đối soát, chưa cộng Xu tự động.",
            parse_mode="HTML",
            reply_markup=manual_method_keyboard(uid),
        )
    if action != "start":
        return
    pkg_key = parts[2] if len(parts) >= 3 else "manual_custom"
    if pkg_key in PAYMENT_PACKAGES:
        pkg = PAYMENT_PACKAGES[pkg_key]
        amount = int(pkg["amount"])
        get_user(uid, query.from_user.first_name or "Manual payment user")
        package_credit = calculate_package_credit_for_user(uid, amount)
        base_xu = int(package_credit.get("base_xu") or pkg["xu"])
        launch_preview = int(package_credit.get("launch_bonus_xu") or 0)
        xu = int(package_credit.get("total_xu") or base_xu)
        order_code = generate_order_code()
        create_order(
            order_code,
            uid,
            amount,
            xu,
            base_xu=base_xu,
            launch_bonus_xu=launch_preview,
            package_amount_vnd=amount,
        )
        set_manual_bill_state(uid, order_code=order_code, amount=amount, xu=xu, pkg_key=pkg_key)
        return await query.edit_message_text(manual_payment_menu_text(), parse_mode="HTML", reply_markup=manual_payment_menu_keyboard(uid))
    set_manual_bill_state(uid, order_code="MANUAL")
    return await query.edit_message_text(
        manual_payment_menu_text(),
        parse_mode="HTML",
        reply_markup=manual_payment_menu_keyboard(uid),
    )

async def handle_payos_alert_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global PAYOS_ALERT_MUTED_UNTIL
    query = update.callback_query
    await query.answer()
    if not is_admin_user(query.from_user.id):
        return await query.answer("Lệnh này chỉ dành cho admin.", show_alert=True)
    action = (query.data or "").split("|", 1)[-1]
    if action == "manual":
        set_manual_bill_state(query.from_user.id, order_code="MANUAL")
        return await query.edit_message_text(manual_payment_menu_text(), parse_mode="HTML", reply_markup=manual_payment_menu_keyboard(query.from_user.id))
    if action == "test":
        return await query.edit_message_text(
            "🧪 Dùng <code>/payos_debug_create 10000</code> để kiểm tra tạo checkout hoặc "
            "<code>/payos_env_check</code> để kiểm tra cấu hình đã mask. Các lệnh test không tự cộng Xu.",
            parse_mode="HTML",
        )
    if action == "mute":
        PAYOS_ALERT_MUTED_UNTIL = time.time() + 60 * 60
        return await query.edit_message_text("🔕 Đã tắt cảnh báo lỗi PayOS trong 1 giờ. Luồng thanh toán không bị thay đổi.")
    if action == "renewed":
        return await query.edit_message_text(
            "✅ Hãy cập nhật ENV <code>PAYOS_REGISTRATION_EXPIRES_AT=YYYY-MM-DD</code> bằng ngày hết hạn mới rồi redeploy. "
            "Bot không tự sửa ENV hoặc trạng thái PayOS.",
            parse_mode="HTML",
        )
    if action == "remind_later":
        return await query.edit_message_text("🔕 Đã đóng nhắc lần này. Bot chỉ nhắc lại ở mốc ngày cấu hình tiếp theo.")

# ─── HANDLERS ────────────────────────────────────────────────────────────────
def is_admin_user(user_id) -> bool:
    uid = str(user_id)
    return uid in OWNER_IDS or uid in ADMIN_IDS

def is_owner_user(user_id) -> bool:
    return str(user_id) in OWNER_IDS

def is_admin_or_owner(user_id) -> bool:
    return is_owner_user(user_id) or is_admin_user(user_id)

def owner_and_admin_ids() -> list[str]:
    ids = set(str(x) for x in OWNER_IDS if str(x).strip())
    ids.update(str(x) for x in ADMIN_IDS if str(x).strip())
    return sorted(ids)

def get_system_role(user_id) -> str:
    if is_owner_user(user_id):
        return "owner"
    if str(user_id) in ADMIN_IDS:
        return "admin"
    return "user"

def effective_admin_role(user_id) -> str:
    return get_system_role(user_id)

def admin_display_badge(user_id) -> str:
    role = get_system_role(user_id)
    if role == "owner":
        return "👑 OWNER"
    if role == "admin":
        return "🛡 ADMIN"
    return ""

def get_role_badge(user_id) -> str:
    badge = admin_display_badge(user_id)
    if badge:
        return badge
    try:
        profile = get_member_profile(user_id)
        return profile.get("tier_badge") or get_member_badge(profile.get("tier"))
    except Exception:
        return get_member_badge("newbie")

def owner_required_text(user_id) -> str:
    return (
        "⛔ Lệnh này chỉ dành cho Owner.\n\n"
        f"ID Telegram hiện tại của bạn: <code>{html.escape(str(user_id))}</code>\n"
        "Hãy thêm ID này vào <code>OWNER_IDS</code> trên Railway nếu đây là tài khoản chủ.\n"
        "Gõ <code>/admin_whoami</code> để kiểm tra quyền hiện tại."
    )

UNKNOWN_COMMAND_SUGGESTIONS = {
    "birthady": "birthday",
    "birhday": "birthday",
    "bithday": "birthday",
    "birthday": "birthday",
    "vip": "vip_policy",
    "member": "member",
    "profile": "profile",
    "start": "start",
    "naptien": "naptien",
    "nap_tien": "naptien",
    "pricing": "pricing",
    "memory": "memory",
    "note": "note",
    "notes": "notes",
    "remind": "remind",
}

async def handle_unknown_or_unmatched_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    text = (update.message.text or update.message.caption or "").strip()
    command = text.split()[0].lstrip("/").split("@", 1)[0].lower() if text else ""
    suggestion = UNKNOWN_COMMAND_SUGGESTIONS.get(command)
    extra = f"\nCó phải bạn muốn <code>/{html.escape(suggestion)}</code> không?" if suggestion and suggestion != command else ""
    await update.message.reply_text(
        "⚠️ Lệnh chưa được hỗ trợ hoặc sai cú pháp. Gõ <code>/start</code> để xem menu."
        f"{extra}",
        parse_mode="HTML",
    )

async def cmd_admin_whoami(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    username = update.effective_user.username or ""
    role = get_system_role(uid)
    owner_ids_count = len([x for x in OWNER_IDS if str(x).strip()])
    admin_ids_count = len([x for x in ADMIN_IDS if str(x).strip()])
    warnings = []
    if owner_ids_count <= 0:
        warnings.append("⚠️ OWNER_IDS đang rỗng, hãy set OWNER_IDS trên Railway.")
    if not is_owner_user(uid):
        warnings.append("Nếu đây là tài khoản chủ, thêm ID này vào OWNER_IDS trên Railway.")
    warning_block = ("\n\n" + "\n".join(warnings)) if warnings else ""
    await update.message.reply_text(
        "🛡 <b>ADMIN DEBUG</b>\n\n"
        f"• Telegram ID: <code>{html.escape(str(uid))}</code>\n"
        f"• Username: <b>{html.escape('@' + username if username else '-')}</b>\n"
        f"• is_owner: <code>{'yes' if is_owner_user(uid) else 'no'}</code>\n"
        f"• is_admin: <code>{'yes' if is_admin_user(uid) else 'no'}</code>\n"
        f"• Effective role: <code>{html.escape(role)}</code>\n"
        f"• Can emergency_lock: <code>{'yes' if is_owner_user(uid) else 'no'}</code>\n"
        f"• Can set_vip: <code>{'yes' if is_admin_user(uid) else 'no'}</code>\n"
        f"• Can approve birthday: <code>{'yes' if is_admin_user(uid) else 'no'}</code>\n\n"
        "<b>ENV</b>\n"
        f"• OWNER_IDS loaded: <code>{owner_ids_count}</code>\n"
        f"• ADMIN_IDS loaded: <code>{admin_ids_count}</code>"
        f"{warning_block}",
        parse_mode="HTML",
    )

