def provider_status_text(value) -> str:
    if isinstance(value, bool):
        return "configured" if value else "missing"
    return bool_env_status(value)

def provider_runtime_status_text(configured: bool, *tool_names: str) -> str:
    if not configured:
        return "missing"
    result = preferred_tool_test_result(*tool_names) if tool_names else {"status": "NOT_TESTED", "detail": ""}
    status = str(result.get("status") or "NOT_TESTED").upper()
    detail = str(result.get("detail") or "").lower()
    if status == "PASS":
        return "configured/tested_pass"
    if status == "FAIL":
        quota_markers = ("quota", "429", "rate limit", "ratelimit", "resource_exhausted", "insufficient_quota")
        return "quota_fail" if any(marker in detail for marker in quota_markers) else "configured/fail"
    if status in {"MISSING", "DISABLED"}:
        return status.lower()
    return "configured/not_tested"

def video_provider_status_line(label: str, configured: bool, test_name: str, stage: str) -> str:
    return (
        f"• {html.escape(label)}: <code>{provider_status_text(configured)}</code>"
        f" | tested <code>{html.escape(tool_test_status_text(test_name))}</code>"
        f" | stage <code>{html.escape(stage or 'DISABLED')}</code>"
    )

async def reply_html_lines(update: Update, lines: list[str], limit: int = 3600):
    chunk = []
    current_len = 0
    for line in lines:
        line = str(line)
        add_len = len(line) + 1
        if chunk and current_len + add_len > limit:
            await update.message.reply_text("\n".join(chunk), parse_mode="HTML")
            chunk = []
            current_len = 0
        chunk.append(line)
        current_len += add_len
    if chunk:
        await update.message.reply_text("\n".join(chunk), parse_mode="HTML")

def tool_test_setting_key(tool_name: str, field: str) -> str:
    clean_tool = re.sub(r"[^a-z0-9_:-]", "_", str(tool_name or "").strip().lower())
    clean_field = re.sub(r"[^a-z0-9_:-]", "_", str(field or "").strip().lower())
    return f"tool_test:{clean_tool}:{clean_field}"

def save_tool_test_result(tool_name: str, status: str, detail: str = "", updated_by=""):
    status_clean = str(status or "UNKNOWN").upper()[:40]
    detail_clean = str(detail or "")[:1000]
    tested_at = now_text()
    set_system_setting(tool_test_setting_key(tool_name, "status"), status_clean, detail_clean, updated_by)
    set_system_setting(tool_test_setting_key(tool_name, "at"), tested_at, detail_clean, updated_by)
    set_system_setting(tool_test_setting_key(tool_name, "detail"), detail_clean, detail_clean, updated_by)
    return {"status": status_clean, "tested_at": tested_at, "detail": detail_clean}

def get_tool_test_result(tool_name: str) -> dict:
    return {
        "status": get_system_setting(tool_test_setting_key(tool_name, "status"), "NOT_TESTED") or "NOT_TESTED",
        "tested_at": get_system_setting(tool_test_setting_key(tool_name, "at"), "") or "",
        "detail": get_system_setting(tool_test_setting_key(tool_name, "detail"), "") or "",
    }

def tool_test_status_text(tool_name: str) -> str:
    result = get_tool_test_result(tool_name)
    status = str(result.get("status") or "NOT_TESTED").upper()
    tested_at = result.get("tested_at") or ""
    return f"{status}" + (f" at {tested_at}" if tested_at else "")

def preferred_tool_test_result(*tool_names: str) -> dict:
    fallback = None
    for tool_name in tool_names:
        result = get_tool_test_result(tool_name)
        if fallback is None:
            fallback = result
        if str(result.get("status") or "").upper() not in {"", "NOT_TESTED"}:
            return result
    return fallback or {"status": "NOT_TESTED", "tested_at": "", "detail": ""}

def preferred_tool_test_status_text(*tool_names: str) -> str:
    result = preferred_tool_test_result(*tool_names)
    status = str(result.get("status") or "NOT_TESTED").upper()
    tested_at = result.get("tested_at") or ""
    return f"{status}" + (f" at {tested_at}" if tested_at else "")

LOCAL_WORKER_JOB_TYPES = {
    "worker_ping",
    "ffmpeg_health",
    "ffmpeg_probe",
    "frame_video_render",
    "video_local_edit",
    "add_music_to_video_planned",
    "add_voice_to_video_planned",
    "image_to_music_video_planned",
    "comfy_health_planned",
    "comfy_image_test_planned",
}
LOCAL_WORKER_JOB_STATUSES = {"queued", "running", "succeeded", "failed", "cancelled"}

def parse_now_text(value: str):
    try:
        return datetime.strptime(str(value or ""), "%Y-%m-%d %H:%M:%S")
    except Exception:
        return None

def local_worker_last_heartbeat() -> dict:
    heartbeat_at = get_system_setting("local_worker:last_heartbeat", "")
    worker_id = get_system_setting("local_worker:worker_id", "")
    heartbeat_dt = parse_now_text(heartbeat_at)
    age_seconds = None
    connected = False
    if heartbeat_dt:
        age_seconds = max(0, int((datetime.now() - heartbeat_dt).total_seconds()))
        connected = age_seconds <= 90
    return {
        "worker_id": worker_id,
        "last_heartbeat": heartbeat_at,
        "age_seconds": age_seconds,
        "connected": connected,
    }

def local_worker_job_from_row(row) -> dict:
    if not row:
        return {}
    fields = [
        "id", "user_id", "command", "job_type", "status", "provider",
        "input_file_id", "output_file_id", "output_url", "error_short",
        "created_at", "started_at", "finished_at", "xu_cost", "admin_only",
        "worker_id", "updated_at",
    ]
    return {fields[i]: row[i] if i < len(row) else "" for i in range(len(fields))}

def create_local_worker_job(
    user_id="",
    command="",
    job_type="worker_ping",
    provider="local_worker",
    input_file_id="",
    xu_cost=0,
    admin_only=True,
) -> int:
    job_type = str(job_type or "").strip()
    if job_type not in LOCAL_WORKER_JOB_TYPES:
        raise ValueError("unsupported local worker job type")
    conn = db_connect()
    try:
        c = conn.cursor()
        now = now_text()
        c.execute(
            """INSERT INTO local_worker_jobs
            (user_id, command, job_type, status, provider, input_file_id, created_at, xu_cost, admin_only, updated_at)
            VALUES (?,?,?,?,?,?,?,?,?,?)""",
            (
                str(user_id or ""),
                str(command or ""),
                job_type,
                "queued",
                str(provider or "local_worker"),
                str(input_file_id or ""),
                now,
                int(xu_cost or 0),
                1 if admin_only else 0,
                now,
            ),
        )
        conn.commit()
        return int(c.lastrowid)
    finally:
        conn.close()

def get_local_worker_job(job_id) -> dict:
    conn = db_connect()
    try:
        c = conn.cursor()
        c.execute(
            """SELECT id,user_id,command,job_type,status,provider,input_file_id,output_file_id,output_url,
                      error_short,created_at,started_at,finished_at,xu_cost,admin_only,worker_id,updated_at
               FROM local_worker_jobs WHERE id=?""",
            (str(job_id),),
        )
        return local_worker_job_from_row(c.fetchone())
    finally:
        conn.close()

def list_local_worker_jobs(limit: int = 10) -> list[dict]:
    conn = db_connect()
    try:
        c = conn.cursor()
        c.execute(
            """SELECT id,user_id,command,job_type,status,provider,input_file_id,output_file_id,output_url,
                      error_short,created_at,started_at,finished_at,xu_cost,admin_only,worker_id,updated_at
               FROM local_worker_jobs
               ORDER BY id DESC
               LIMIT ?""",
            (max(1, min(int(limit or 10), 50)),),
        )
        return [local_worker_job_from_row(row) for row in c.fetchall()]
    finally:
        conn.close()

def count_local_worker_jobs() -> dict:
    conn = db_connect()
    try:
        c = conn.cursor()
        c.execute("SELECT status, COUNT(*) FROM local_worker_jobs GROUP BY status")
        counts = {str(status or "unknown"): int(count or 0) for status, count in c.fetchall()}
        return {
            "queued": counts.get("queued", 0),
            "running": counts.get("running", 0),
            "succeeded": counts.get("succeeded", 0),
            "failed": counts.get("failed", 0),
            "cancelled": counts.get("cancelled", 0),
            "total": sum(counts.values()),
        }
    except sqlite3.OperationalError:
        return {"queued": 0, "running": 0, "succeeded": 0, "failed": 0, "cancelled": 0, "total": 0}
    finally:
        conn.close()

def update_local_worker_job(job_id, status: str, worker_id: str = "", error_short: str = "", output_file_id: str = "", output_url: str = "") -> dict:
    status = str(status or "").strip().lower()
    if status not in LOCAL_WORKER_JOB_STATUSES:
        raise ValueError("invalid local worker job status")
    job = get_local_worker_job(job_id)
    if not job:
        raise ValueError("local worker job not found")
    now = now_text()
    started_at = job.get("started_at") or (now if status == "running" else "")
    finished_at = job.get("finished_at") or (now if status in {"succeeded", "failed", "cancelled"} else "")
    conn = db_connect()
    try:
        conn.execute(
            """UPDATE local_worker_jobs
               SET status=?, worker_id=?, error_short=?, output_file_id=?, output_url=?,
                   started_at=?, finished_at=?, updated_at=?
               WHERE id=?""",
            (
                status,
                str(worker_id or job.get("worker_id") or "")[:120],
                str(error_short or "")[:500],
                str(output_file_id or job.get("output_file_id") or "")[:500],
                str(output_url or job.get("output_url") or "")[:1000],
                started_at,
                finished_at,
                now,
                str(job_id),
            ),
        )
        conn.commit()
    finally:
        conn.close()
    updated = get_local_worker_job(job_id)
    if updated.get("job_type") == "ffmpeg_health":
        save_tool_test_result(
            "ffmpeg_local",
            "PASS" if status == "succeeded" else ("FAIL" if status == "failed" else "RUNNING"),
            updated.get("error_short") or "local ffmpeg health queued/running",
            updated.get("worker_id") or "local_worker",
        )
    if updated.get("job_type") == "worker_ping":
        save_tool_test_result(
            "local_worker",
            "PASS" if status == "succeeded" else ("FAIL" if status == "failed" else "RUNNING"),
            updated.get("error_short") or "local worker ping queued/running",
            updated.get("worker_id") or "local_worker",
        )
    return updated

def handle_frame_video_worker_job_update(previous_job: dict, updated_job: dict) -> None:
    if not updated_job or str(updated_job.get("job_type") or "") != "frame_video_render":
        return
    previous_status = str((previous_job or {}).get("status") or "").lower()
    status = str(updated_job.get("status") or "").lower()
    if previous_status in {"succeeded", "failed", "cancelled"}:
        return
    payload = {}
    try:
        raw = str(updated_job.get("input_file_id") or "")
        payload = json.loads(raw) if raw else {}
    except Exception:
        payload = {}
    frame_job_id = str(payload.get("frame_job_id") or "")
    user_id = str(payload.get("user_id") or updated_job.get("user_id") or "")
    charged_amount = int(payload.get("charged_amount") or updated_job.get("xu_cost") or 0)
    if status == "succeeded":
        if frame_job_id:
            update_frame_video_job(frame_job_id, status="success", detail=f"local_worker_job:{updated_job.get('id')} sent")
        save_tool_test_result("frame_video", "PASS", f"local worker render job {updated_job.get('id')} succeeded", user_id)
        return
    if status == "failed":
        reason = sanitize_log_text(str(updated_job.get("error_short") or "worker_failed"))[:240]
        if charged_amount > 0 and user_id:
            refund_charged_credit(user_id, charged_amount, "frame_video_refund", "", "Hoàn Xu ghép ảnh thành video do worker lỗi", True)
        if frame_job_id:
            update_frame_video_job(frame_job_id, status="failed", detail=f"worker_failed:{reason}")
        set_frame_video_last_error(f"worker_failed:{reason}")
        save_tool_test_result("frame_video", "FAIL", f"local worker render failed:{reason}", user_id)

