def provider_registry_by_capability(capability: str) -> list[dict]:
    capability = str(capability or "").strip()
    registry = provider_registry()
    return [
        {**payload, "name": name}
        for name, payload in registry.items()
        if capability in set(payload.get("capabilities") or [])
    ]

def shopaikey_is_configured() -> bool:
    return bool(SHOPAIKEY_API_KEY and SHOPAIKEY_ENABLED and SHOPAIKEY_ADMIN_ONLY)

def shopaikey_chat_fallback_models() -> list[str]:
    return [m.strip() for m in str(SHOPAIKEY_CHAT_FALLBACK_MODELS or "").split(",") if m.strip()]

def shopaikey_public_chat_fallback_enabled() -> bool:
    return bool(SHOPAIKEY_ENABLED and SHOPAIKEY_API_KEY and SHOPAIKEY_BASE_URL)

def shopaikey_chat_model_sequence(model_override: str = "") -> list[str]:
    raw_models = []
    override = str(model_override or "").strip()
    if override:
        raw_models.append(override)
    else:
        raw_models.append(SHOPAIKEY_CHAT_MODEL or SHOPAIKEY_DEFAULT_MODEL or "gpt-4o-mini")
        raw_models.extend(shopaikey_chat_fallback_models())
    models = []
    seen = set()
    blocked = {"gpt-5-mini"}
    for model in raw_models:
        value = str(model or "").strip()
        if not value:
            continue
        marker = value.lower()
        if marker in blocked or marker in seen:
            continue
        seen.add(marker)
        models.append(value)
    for required in ("gpt-4o-mini", "gpt-4.1-mini", "qwen-plus"):
        marker = required.lower()
        if marker not in seen:
            seen.add(marker)
            models.append(required)
    return models or ["gpt-4o-mini", "gpt-4.1-mini", "qwen-plus"]

def shopaikey_video_fallback_models() -> list[str]:
    return [m.strip() for m in str(SHOPAIKEY_VIDEO_FALLBACK_MODELS or "").split(",") if m.strip()]

def shopaikey_video_model_sequence(model_override: str = "") -> list[str]:
    raw_models = []
    override = str(model_override or "").strip()
    if override:
        raw_models.append(override)
    else:
        raw_models.append(SHOPAIKEY_VIDEO_MODEL or "veo3.1-fast")
        raw_models.extend(shopaikey_video_fallback_models())
    models = []
    seen = set()
    for model in raw_models:
        value = str(model or "").strip()
        if not value:
            continue
        marker = value.lower()
        if marker in seen:
            continue
        seen.add(marker)
        models.append(value)
    return models or ["veo3.1-fast"]

def shopaikey_confirmation_token() -> str:
    return hashlib.sha256(f"{time.time()}:{random.random()}".encode("utf-8")).hexdigest()[:18]

def set_shopaikey_pending_confirmation(user_id, payload: dict) -> str:
    token = shopaikey_confirmation_token()
    SHOPAIKEY_PENDING_CONFIRMATIONS[token] = {
        **(payload or {}),
        "user_id": str(user_id or ""),
        "created_at_ts": time.time(),
    }
    return token

def pop_shopaikey_pending_confirmation(token: str, user_id) -> dict | None:
    token = str(token or "").strip()
    item = SHOPAIKEY_PENDING_CONFIRMATIONS.get(token)
    if not item:
        return None
    if str(item.get("user_id") or "") != str(user_id or ""):
        return None
    if time.time() - float(item.get("created_at_ts") or 0) > SHOPAIKEY_CONFIRMATION_TTL_SECONDS:
        SHOPAIKEY_PENDING_CONFIRMATIONS.pop(token, None)
        return None
    return SHOPAIKEY_PENDING_CONFIRMATIONS.pop(token, None)

def shopaikey_paid_image_source_job(user_id) -> dict | None:
    uid = str(user_id or "")
    if not uid:
        return None
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute(
            """
            SELECT image.*
            FROM shopaikey_jobs image
            WHERE image.user_id=?
              AND image.job_type='image'
              AND UPPER(image.status)='SUCCESS'
              AND image.admin_only=0
              AND image.xu_deducted > 0
              AND (COALESCE(image.result_url, '') <> '' OR COALESCE(image.output_file_id, '') <> '')
            ORDER BY image.id DESC
            LIMIT 1
            """,
            (uid,),
        ).fetchone()
        return dict(row) if row else None
    finally:
        conn.close()

def shopaikey_paid_image_source_available(user_id, source_job_id: str) -> bool:
    uid = str(user_id or "")
    source = str(source_job_id or "").strip()
    if not uid or not source:
        return False
    conn = db_connect()
    try:
        row = conn.execute(
            """
            SELECT image.id
            FROM shopaikey_jobs image
            WHERE image.id=?
              AND image.user_id=?
              AND image.job_type='image'
              AND UPPER(image.status)='SUCCESS'
              AND image.admin_only=0
              AND (COALESCE(image.result_url, '') <> '' OR COALESCE(image.output_file_id, '') <> '')
            LIMIT 1
            """,
            (int(source), uid),
        ).fetchone()
        return bool(row)
    except Exception:
        return False
    finally:
        conn.close()

def media_price_multiplier() -> int:
    return max(1, int(MEDIA_PRICE_MULTIPLIER or 2))

def media_tier_price(cost_xu: int, provider_cost_xu: int, fallback_xu: int = 0) -> int:
    explicit = int(cost_xu or 0)
    if explicit > 0:
        return explicit
    provider_cost = int(provider_cost_xu or 0)
    if provider_cost > 0:
        return max(0, provider_cost * media_price_multiplier())
    return max(0, int(fallback_xu or 0))

