    "image_prompt_wait_image",
    "image_prompt_wait_purpose",
    "image_prompt_manual_description",
    "image_prompt_goal_custom",
    "image_prompt_subject",
    "image_prompt_style_custom",
    "image_prompt_ratio_custom",
