def image_tool_latest_key(user_id, tool: str = "") -> str:
    return f"{user_id}:{str(tool or '').strip().lower()}"

def save_image_tool_result(user_id, tool: str, payload: dict) -> dict:
    data = dict(payload or {})
    data["tool"] = str(tool or "").strip().lower()
    data["created_at_ts"] = time.time()
    LAST_IMAGE_TOOL_RESULTS[image_tool_latest_key(user_id, tool)] = data
    return data

def get_image_tool_result(user_id, tool: str) -> dict | None:
    key = image_tool_latest_key(user_id, tool)
    result = LAST_IMAGE_TOOL_RESULTS.get(key) or {}
    if not result:
        return None
    if time.time() - float(result.get("created_at_ts") or 0) > TREND_WORKFLOW_TTL_SECONDS:
        LAST_IMAGE_TOOL_RESULTS.pop(key, None)
        return None
    return result

def recent_image_file_state(user_id) -> dict:
    recent = get_recent_media_state(LAST_USER_IMAGE, safe_int(user_id, 0))
    if recent.get("file_id"):
        return {
            "file_id": str(recent.get("file_id") or "")[:240],
            "file_unique_id": str(recent.get("file_unique_id") or "")[:240],
            "source_name": str(recent.get("file_name") or "telegram_photo.jpg")[:180],
        }
    last_file = get_last_user_file(user_id)
    if str(last_file.get("kind") or "").lower() in {"photo", "document"} and str(last_file.get("mime_type") or "").lower().startswith("image/"):
        return {
            "file_id": str(last_file.get("file_id") or "")[:240],
            "file_unique_id": str(last_file.get("file_unique_id") or "")[:240],
            "source_name": str(last_file.get("file_name") or last_file.get("filename") or "uploaded_image")[:180],
        }
    return {}

def image_action_lock_key(user_id, action: str, source_id: str = "") -> str:
    return f"{user_id}:{str(action or '').strip().lower()}:{str(source_id or '').strip()[:240]}"

def acquire_image_action_lock(user_id, action: str, source_id: str = "", ttl_seconds: int = 180) -> bool:
    key = image_action_lock_key(user_id, action, source_id)
    now_ts = time.time()
    expires_at = float(IMAGE_ACTION_LOCKS.get(key) or 0)
    if expires_at > now_ts:
        return False
    IMAGE_ACTION_LOCKS[key] = now_ts + max(10, int(ttl_seconds or 180))
    return True

def release_image_action_lock(user_id, action: str, source_id: str = "", cooldown_seconds: int = 0) -> None:
    key = image_action_lock_key(user_id, action, source_id)
    if int(cooldown_seconds or 0) > 0:
        IMAGE_ACTION_LOCKS[key] = time.time() + int(cooldown_seconds)
    else:
        IMAGE_ACTION_LOCKS.pop(key, None)

