def feedback_context_for_user(user_id) -> str:
    uid = str(user_id or "")
    active = []
    for key, value in list(USER_PENDING.items()):
        if key.endswith(f":{uid}") and isinstance(value, dict):
            action = value.get("pending_action")
            if action and action != "feedback":
                active.append(str(action))
    return ",".join(active[:5])

def store_customer_feedback(user, category: str, content: str, context: str = "") -> int:
    uid = str(getattr(user, "id", "") or "")
    username = getattr(user, "username", "") or getattr(user, "first_name", "") or ""
    slug = str(category or "").strip() or "other_error"
    text = re.sub(r"\s+", " ", str(content or "").strip())[:2000]
    ctx = re.sub(r"\s+", " ", str(context or "").strip())[:500]
    conn = db_connect()
    try:
        cur = conn.execute(
            """INSERT INTO feedback (user_id, username, category, content, context, status, timestamp)
            VALUES (?,?,?,?,?,?,?)""",
            (uid, username, slug, text, ctx, "new", now_text()),
        )
        conn.commit()
        return int(cur.lastrowid or 0)
    finally:
        conn.close()

def clear_media_creator_pending_states(user_id) -> bool:
    free_hub_cleared = clear_free_hub_pending(user_id)
    support_cleared = clear_support_ticket_pending(user_id)
    quick_cleared = clear_quick_media_pending(user_id)
    quick_image_flow_cleared = clear_quick_image_flow(user_id)
    public_image_cleared = clear_public_image_prompt_pending(user_id)
    public_video_cleared = clear_public_video_prompt_pending(user_id)
    media_aspect_cleared = clear_media_aspect_pending(user_id)
    public_video_context_cleared = clear_public_video_package_context(user_id)
    creative_motion_cleared = clear_creative_motion_pending(user_id)
    cinematic_ad_cleared = clear_cinematic_ad_pending(user_id)
    trend_cleared = clear_trend_video_flow_pending(user_id)
    trend_confirm_cleared = clear_trend_workflow_confirm_pending(user_id)
    feedback_cleared = clear_feedback_pending(user_id)
    image_menu_cleared = clear_image_menu_pending(user_id)
    frame_video_cleared = clear_frame_video_state(user_id)
    storyboard_cleared = clear_storyboard_state(user_id)
    developing_video_cleared = clear_developing_video_pending(user_id)
    video_dubbing_cleared = clear_video_dubbing_pending(user_id)
    video_addon_cleared = clear_video_addon_state(user_id)
    marketing_cleared = clear_marketing_pending(user_id)
    return bool(free_hub_cleared or support_cleared or quick_cleared or quick_image_flow_cleared or public_image_cleared or public_video_cleared or media_aspect_cleared or public_video_context_cleared or creative_motion_cleared or cinematic_ad_cleared or trend_cleared or trend_confirm_cleared or feedback_cleared or image_menu_cleared or frame_video_cleared or storyboard_cleared or developing_video_cleared or video_dubbing_cleared or video_addon_cleared or marketing_cleared)

