def shopaikey_video_payload_data(payload: dict) -> dict:
    if not isinstance(payload, dict):
        return {}
    data = payload.get("data")
    if isinstance(data, dict):
        return data
    return payload

def shopaikey_video_result_url(payload: dict) -> str:
    data = shopaikey_video_payload_data(payload)
    candidates = [
        data.get("result_url"),
        data.get("video_url"),
        data.get("url"),
        data.get("output_url"),
        data.get("download_url"),
    ]
    result = data.get("result") or data.get("output") or data.get("outputs")
    if isinstance(result, dict):
        candidates.extend([result.get("url"), result.get("video_url"), result.get("result_url")])
    elif isinstance(result, list) and result:
        first = result[0]
        if isinstance(first, dict):
            candidates.extend([first.get("url"), first.get("video_url"), first.get("result_url")])
        else:
            candidates.append(first)
    nested = data.get("data")
    if isinstance(nested, dict):
        candidates.extend([nested.get("result_url"), nested.get("video_url"), nested.get("url")])
        nested_items = nested.get("data")
        if isinstance(nested_items, list) and nested_items:
            first_nested = nested_items[0]
            if isinstance(first_nested, dict):
                candidates.extend([first_nested.get("video_url"), first_nested.get("result_url"), first_nested.get("url")])
    elif isinstance(nested, list) and nested:
        first_nested = nested[0]
        if isinstance(first_nested, dict):
            candidates.extend([first_nested.get("video_url"), first_nested.get("result_url"), first_nested.get("url")])
    for item in candidates:
        value = str(item or "").strip()
        if value.startswith("http://") or value.startswith("https://"):
            return value
    return ""

def shopaikey_video_smoke_prompt() -> str:
    return "A short clean futuristic turquoise AI automation logo animation, white background, minimal, no extra text except TOAN AAS"

def shopaikey_video_request_payload(model: str, prompt: str = "") -> dict:
    model = str(model or SHOPAIKEY_VIDEO_MODEL or "veo3.1-fast").strip()
    safe_prompt = str(prompt or "").strip()[:1200] or shopaikey_video_smoke_prompt()
    payload = {
        "model": model,
        "prompt": safe_prompt,
    }
    if model == "grok-video-3":
        return payload
    if model == "grok-video-3-10s":
        payload["metadata"] = {"quality": "720p"}
        return payload
    payload["metadata"] = {
        "aspect_ratio": "16:9",
        "enhance_prompt": False,
        "enable_upsample": False,
    }
    return payload

def shopaikey_workflow_image_to_video_prompt(asset: dict | None = None) -> str:
    preview = shopaikey_safe_prompt_preview((asset or {}).get("prompt_preview") or "")
    base = (
        "Create a short vertical 9:16 video from this workflow image. "
        "Clean futuristic turquoise AI automation style, smooth slow push-in, subtle motion, white/bright background, "
        "minimal, no extra text except TOAN AAS if already present."
    )
    return (base + (f" Source image context: {preview}" if preview else ""))[:1200]

def shopaikey_workflow_image_to_video_payload(model: str, image_url: str, prompt: str = "") -> dict:
    model = str(model or SHOPAIKEY_VIDEO_MODEL or "veo3.1-fast").strip()
