def shopaikey_admin_freeze_warning_text() -> str:
    frozen, row, _message = is_provider_frozen("shopaikey")
    if not frozen:
        return "OFF"
    reason = row.get("reason_code") or "provider_freeze"
    return f"ON ({reason}) — admin smoke test only, không mở public."

def shopaikey_billing_flow_status_text() -> str:
    if not SHOPAIKEY_REQUIRE_CONFIRM_BEFORE_DEDUCT:
        return "not_ready_confirm_disabled"
    if not SHOPAIKEY_REFUND_ON_PROVIDER_FAIL:
        return "not_ready_refund_disabled"
    if image_base_cost_xu() <= 0 or video_base_cost_xu() <= 0:
        return "not_ready_cost_missing"
    return "ready_guarded_public_off" if not (SHOPAIKEY_PUBLIC_IMAGE_ENABLED or SHOPAIKEY_PUBLIC_VIDEO_ENABLED) else "ready_public_env_on"

def provider_freeze_display(provider: str = "shopaikey") -> dict:
    frozen, row, _message = is_provider_frozen(provider)
    if not frozen:
        return {
            "frozen": False,
            "reason": "-",
            "message": "-",
            "unfreeze_after": "-",
            "error_count": int(row.get("error_count") or 0) if row else 0,
            "last_error_at": str(row.get("last_error_at") or "-") if row else "-",
        }
    return {
        "frozen": True,
        "reason": str(row.get("reason_code") or "-"),
        "message": str(row.get("reason_message") or "-"),
        "unfreeze_after": str(row.get("unfreeze_after") or "-"),
        "error_count": int(row.get("error_count") or 0),
        "last_error_at": str(row.get("last_error_at") or "-"),
    }

def provider_freeze_runtime_on(provider: str = "shopaikey") -> bool:
    state = current_system_mode()
    display = provider_freeze_display(provider)
    return bool(state.get("provider_freeze") or PROVIDER_FREEZE_ENABLED or display.get("frozen"))

def public_video_runtime_status_text() -> str:
    video_freeze = provider_freeze_display("shopaikey_video")
    if video_freeze.get("frozen"):
        return "FROZEN"
    return "ON" if (SHOPAIKEY_PUBLIC_VIDEO_ENABLED and VIDEO_AI_PUBLIC_ENABLED) else "OFF"

def public_voice_runtime_status_text() -> str:
    return "admin-only"

def shopaikey_generation_unavailable_message(status: str = "", detail: str = "") -> str:
    error_class = classify_provider_error(0, status, detail)
    return user_friendly_error(error_class, "shopaikey")

def shopaikey_public_generation_guard(job_type: str) -> tuple[bool, str]:
    job = str(job_type or "").lower()
    freeze = is_tool_frozen(job, "shopaikey")
    if freeze.get("frozen"):
        if job == "video":
            return False, USER_VIDEO_PROVIDER_FROZEN_MESSAGE
        return False, freeze.get("message") or USER_PROVIDER_BUSY_MESSAGE
    if job == "image" and not SHOPAIKEY_PUBLIC_IMAGE_ENABLED:
        return False, "🧪 Tính năng này đang thử nghiệm nội bộ, chưa mở công khai. TOAN AAS sẽ mở sau khi kiểm tra ổn định."
    if job == "video" and not (SHOPAIKEY_PUBLIC_VIDEO_ENABLED and VIDEO_AI_PUBLIC_ENABLED):
        return False, "🧪 Tính năng này đang thử nghiệm nội bộ, chưa mở công khai. TOAN AAS sẽ mở sau khi kiểm tra ổn định."
    if not SHOPAIKEY_ENABLED or not SHOPAIKEY_API_KEY:
        return False, "Hệ thống tạo ảnh/video đang bảo trì ngắn hoặc chưa sẵn sàng."
    return True, ""

def shopaikey_active_job_for_user(user_id, job_type: str = "") -> dict | None:
    if not (SHOPAIKEY_VIDEO_JOB_LOCK_ENABLED and SHOPAIKEY_PUBLIC_JOB_LOCK_ENABLED):
        return None
    uid = str(user_id or "")
    kind = str(job_type or "").lower()
    if not uid:
        return None
    if kind == "video":
        try:
            mark_stale_public_video_jobs(uid)
            mark_stale_admin_video_jobs(uid)
        except Exception:
            pass
    statuses = tuple(sorted(SHOPAIKEY_ACTIVE_JOB_STATUSES))
    placeholders = ",".join("?" for _ in statuses)
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    try:
        rows = conn.execute(
            f"""
            SELECT * FROM shopaikey_jobs
            WHERE user_id=?
              AND (?='' OR job_type=?)
              AND UPPER(status) IN ({placeholders})
            ORDER BY id DESC
            LIMIT 1
            """,
            (uid, kind, kind, *statuses),
        ).fetchall()
        return dict(rows[0]) if rows else None
    finally:
        conn.close()

