def customer_tool_readiness_payload() -> dict:
    providers = provider_status_payload()
    tests = {name: get_tool_test_result(name) for name in ["ai", "image", "tts", "stt", "downloader"]}
    ai_test = preferred_tool_test_result("ai_chat", "ai")
    image_test = preferred_tool_test_result("image_remove_bg", "image")
    public_cobalt = bool(providers["downloader"].get("cobalt_public"))
    cobalt_self_host = bool(providers["downloader"].get("cobalt_self_host"))
    return {
        "ai": {
            "configured": bool(providers["ai"]["ready"]),
            "tested": ai_test["status"] == "PASS",
            "label": "ready" if ai_test["status"] == "PASS" else ("configured/not tested" if providers["ai"]["ready"] else "missing"),
        },
        "image_remove_bg": {
            "configured": bool(providers["image"]["ready"]),
            "tested": image_test["status"] == "PASS",
            "label": "ready" if image_test["status"] == "PASS" else ("thử nghiệm" if providers["image"]["ready"] else "missing"),
        },
        "tts": {
            "configured": bool(providers["audio"].get("elevenlabs") or providers["audio"].get("fish_audio") or providers["audio"].get("edge_tts")),
            "tested": tests["tts"]["status"] == "PASS",
            "label": "ready" if tests["tts"]["status"] == "PASS" else ("admin-only/not tested" if (providers["audio"].get("elevenlabs") or providers["audio"].get("fish_audio") or providers["audio"].get("edge_tts")) else "missing"),
        },
        "stt": {
            "configured": bool(providers["audio"]["deepgram"]),
            "tested": tests["stt"]["status"] == "PASS",
            "label": "ready" if tests["stt"]["status"] == "PASS" else ("thử nghiệm" if providers["audio"]["deepgram"] else "missing"),
        },
        "downloader": {
            "configured": cobalt_self_host,
            "tested": tests["downloader"]["status"] == "PASS",
            "label": "ready" if tests["downloader"]["status"] == "PASS" else ("disabled/public cobalt" if public_cobalt else "Cobalt self-host missing"),
        },
        "publish": {
            "customer_publish": bool(providers["media_factory"]["customer_publish"]),
            "auto_publish": bool(providers["media_factory"]["auto_publish"]),
            "ads_assistant": bool(providers["media_factory"].get("ads_assistant", False)),
        },
    }

def promo_readiness_payload() -> dict:
    conn = None
    try:
        conn = db_connect()
        promo = get_promo_code_dict(conn, PROMO_BETA50_CODE)
        if not promo:
            return {"beta50_seeded": False, "status": "missing", "bonus_xu": 0, "used_count": 0, "max_uses": 0, "label": ""}
        return {
            "beta50_seeded": str(promo.get("status") or "").lower() == "active",
            "status": promo.get("status") or "missing",
            "bonus_xu": int(promo.get("bonus_xu") or 0),
            "used_count": promo_usage_count(promo),
            "max_uses": promo_usage_limit(promo),
            "label": promo_public_label(promo),
        }
    except Exception as e:
        return {"beta50_seeded": False, "status": "error", "error": str(e)[:120], "bonus_xu": 0, "used_count": 0, "max_uses": 0, "label": ""}
    finally:
        if conn:
            conn.close()

def sales_readiness_payload() -> dict:
    providers = provider_status_payload()
    db_status = db_status_payload()
    state = current_system_mode()
    ops_mode = current_system_mode()
    commands = {
        "naptien": callable(globals().get("cmd_naptien")),
        "backup_db": callable(globals().get("cmd_backup_db")),
        "film": callable(globals().get("cmd_film")),
        "growth_ai": callable(globals().get("cmd_growth_ai")),
        "campaign_report": callable(globals().get("cmd_campaign_report")),
        "performance_report": callable(globals().get("cmd_performance_report")),
        "doc_tools": callable(globals().get("cmd_doc_tools")),
        "memory": callable(globals().get("cmd_memory")),
        "note": callable(globals().get("cmd_note")),
        "reminders": callable(globals().get("cmd_reminders")),
        "promo": callable(globals().get("cmd_promo")),
        "promo_guide": callable(globals().get("cmd_promo_guide")),
        "promo_seed_policy": callable(globals().get("cmd_promo_seed_policy")),
        "promo_seed_beta": callable(globals().get("cmd_promo_seed_beta")),
        "package_catalog": callable(globals().get("cmd_package_catalog")),
        "grant_combo": callable(globals().get("cmd_grant_combo")),
        "grant_monthly": callable(globals().get("cmd_grant_monthly")),
        "user_packages": callable(globals().get("cmd_user_packages")),
        "adjust_package": callable(globals().get("cmd_adjust_package")),
        "revoke_package": callable(globals().get("cmd_revoke_package")),
        "emergency_status": callable(globals().get("cmd_emergency_status")),
        "ops_plan": callable(globals().get("cmd_ops_plan")),
        "guide_menu": callable(globals().get("main_guide_keyboard")) and callable(globals().get("guide_section_text")),
        "ux_polish": callable(globals().get("public_image_success_keyboard")) and callable(globals().get("public_video_success_keyboard")),
        "feedback_loop": callable(globals().get("handle_feedback_callback")) and callable(globals().get("handle_feedback_pending_text")),
    }
    blockers = []
    if not db_status["ok"]:
        blockers.append("DB chưa OK")
    if not providers["payos"]["ready"]:
        blockers.append("PayOS thiếu Client ID/API Key/Checksum")
    if not providers["ai"]["ready"]:
        blockers.append("Thiếu Gemini hoặc OpenAI")
    if not commands["naptien"]:
        blockers.append("Thiếu /naptien")
    if not commands["film"]:
        blockers.append("Thiếu /film")
    if not commands["backup_db"]:
        blockers.append("Thiếu /backup_db")
    payos_test = {
        "status": (get_system_setting("payos_real_payment_test_status", "NOT_TESTED") or "NOT_TESTED").upper(),
        "at": get_system_setting("payos_real_payment_test_at", ""),
        "order": get_system_setting("payos_real_payment_test_order", ""),
        "note": get_system_setting("payos_real_payment_test_note", ""),
    }
    payos_debug = {
        "status": (get_system_setting("payos_debug_create_status", "NOT_TESTED") or "NOT_TESTED").upper(),
        "at": get_system_setting("payos_debug_create_at", ""),
        "order": get_system_setting("payos_debug_create_order", ""),
        "checkout_url": get_system_setting("payos_debug_create_checkout_url", ""),
        "payment_link_id": get_system_setting("payos_debug_create_payment_link_id", ""),
        "http_status": get_system_setting("payos_debug_create_http_status", ""),
        "code": get_system_setting("payos_debug_create_code", ""),
        "desc": get_system_setting("payos_debug_create_desc", ""),
        "note": get_system_setting("payos_debug_create_note", ""),
    }
    base_ready = not blockers
    checkout_ready = payos_debug["status"] == "PASS" and bool(payos_debug.get("checkout_url"))
    sales_ready = base_ready and checkout_ready and payos_test["status"] == "PASS"
    if ops_mode.get("emergency_lock"):
        status = "LOCKED / EMERGENCY SAFE MODE"
    elif ops_mode.get("maintenance_mode"):
        status = "MAINTENANCE MODE"
    elif sales_ready:
        status = "SALES READY"
    elif base_ready and checkout_ready:
        status = "BETA READY"
    elif base_ready:
        status = "BETA READY / NEED PAYOS DEBUG"
    else:
        status = "NOT READY"
    try:
        data_persistence = data_persistence_status_payload(include_counts=False)
    except Exception as e:
        data_persistence = {
            "data_loss_risk": True,
            "data_loss_risk_level": "ERROR",
            "db_path": display_db_path(DB_FILE),
            "startup_prep_reason": str(e)[:160],
        }
    try:
        video_queue = shopaikey_video_queue_counts()
    except Exception:
        video_queue = {"queued": 0, "running": 0, "success": 0, "failed": 0, "total": 0}
    try:
        media_pricing = media_workflow_pricing_payload()
    except Exception:
        media_pricing = {}
    return {
        "status": status,
        "db_ok": db_status["ok"],
        "providers": providers,
        "commands": commands,
        "packages": len(PAYMENT_PACKAGES),
        "trial_credits": TRIAL_CREDITS,
        "free_chat_daily": FREE_CHAT_DAILY,
        "payos_debug_create": payos_debug,
        "payos_real_test": payos_test,
        "promo": promo_readiness_payload(),
        "ops": ops_mode,
        "data_persistence": data_persistence,
        "shopaikey_usage": shopaikey_last_usage_snapshot(),
        "video_freeze": provider_freeze_display("shopaikey_video"),
        "video_queue": video_queue,
        "public_image_enabled": bool(SHOPAIKEY_PUBLIC_IMAGE_ENABLED),
        "public_video_enabled": bool(SHOPAIKEY_PUBLIC_VIDEO_ENABLED),
        "media_pricing": media_pricing,
        "video_tier_names": list((media_pricing.get("video_tiers") or {}).keys()),
        "image_aspect_ratios": list(media_aspect_ratio_options("image")),
        "video_aspect_ratios": list(media_aspect_ratio_options("video")),
        "video_combos": media_pricing.get("video_combos") or [],
        "combo_rank_points_excluded": True,
        "package_wallet": package_wallet_status_payload(),
        "refund_guard": bool(SHOPAIKEY_REFUND_ON_PROVIDER_FAIL),
        "job_lock": bool(SHOPAIKEY_PUBLIC_JOB_LOCK_ENABLED),
        "blockers": blockers,
        "note": "SALES READY chỉ bật khi /payos_debug_create PASS và admin đã mark PayOS real payment test PASS.",
    }

