def find_asset_path(filename: str) -> str:
    safe_name = os.path.basename(str(filename or "").strip())
    if not safe_name:
        return ""
    base_dir = os.path.dirname(os.path.abspath(__file__))
    candidates = [
        safe_name,
        os.path.join(os.getcwd(), safe_name),
        os.path.join(base_dir, safe_name),
        os.path.join(base_dir, "docs", safe_name),
        os.path.join(base_dir, "static", safe_name),
        os.path.join(base_dir, "assets", safe_name),
    ]
    for path in candidates:
        if path and os.path.exists(path):
            return path
    search_dirs = [
        os.getcwd(),
        base_dir,
        os.path.join(base_dir, "docs"),
        os.path.join(base_dir, "static"),
        os.path.join(base_dir, "assets"),
    ]
    target = safe_name.lower()
    for directory in search_dirs:
        try:
            for item in os.listdir(directory):
                if item.lower() == target:
                    return os.path.join(directory, item)
        except Exception:
            pass
    return ""

def guide_docx_candidates() -> list[str]:
    base_dir = os.path.dirname(__file__)
    return [
        GUIDE_DOCX_FILE,
        os.path.join(os.getcwd(), GUIDE_DOCX_FILE),
        os.path.join(base_dir, GUIDE_DOCX_FILE),
        os.path.join(base_dir, "docs", GUIDE_DOCX_FILE),
        os.path.join(base_dir, "static", GUIDE_DOCX_FILE),
        os.path.join(base_dir, "assets", GUIDE_DOCX_FILE),
    ]

def find_guide_docx_path() -> str:
    exact = find_asset_path(GUIDE_DOCX_FILE)
    if exact:
        return exact
    base_dir = os.path.dirname(os.path.abspath(__file__))
    search_dirs = [
        os.getcwd(),
        base_dir,
        os.path.join(base_dir, "docs"),
        os.path.join(base_dir, "static"),
        os.path.join(base_dir, "assets"),
    ]
    markers = ("huong_dan", "huong-dan", "toan_aas_huong_dan")
    for directory in search_dirs:
        try:
            for item in os.listdir(directory):
                lower = item.lower()
                if lower.endswith(".docx") and any(marker in lower for marker in markers):
                    return os.path.join(directory, item)
        except Exception:
            pass
    return ""

