async def handle_video_reference_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    uid = query.from_user.id
    lang = get_user_language(uid) or "vi"
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else "start"
    value = parts[2] if len(parts) > 2 else ""

    if action == "hub":
        clear_developing_video_pending(uid)
        return await safe_edit_or_send(query, video_reference_hub_text(lang), parse_mode="HTML", reply_markup=video_reference_hub_keyboard(lang))
    if action == "profile":
        clear_developing_video_pending(uid)
        profile = get_latest_channel_profile(uid)
        return await safe_edit_or_send(query, channel_profile_text(profile, lang), parse_mode="HTML", reply_markup=channel_profile_keyboard(lang))
    if action == "profile_create":
        clear_developing_video_pending(uid)
        set_developing_video_pending(uid, "videoref", "profile_platform", language=lang)
        text = "📺 Kênh của bạn đăng ở đâu?" if normalize_user_language(lang) == "vi" else "📺 Which platform is your channel on?"
        return await safe_edit_or_send(query, text, reply_markup=channel_profile_platform_keyboard(lang))
    if action == "profile_platform":
        set_developing_video_pending(uid, "videoref", "profile_niche", platform=value or "other", language=lang)
        text = "1/6. Hãy nhập ngành/chủ đề chính của kênh." if normalize_user_language(lang) == "vi" else "1/6. Enter the channel niche."
        return await safe_edit_or_send(query, text, reply_markup=video_v6_keyboard([], lang, back=("⬅️ Hồ sơ kênh", "videoref|profile")))
    if action == "profile_affiliate":
        state = get_developing_video_pending(uid) or {}
        restore_developing_video_pending(uid, "videoref", state, "profile_goal")
        set_developing_video_pending(uid, "videoref", "profile_goal", affiliate_allowed=(value == "yes"))
        text = "6/6. Mục tiêu chính của kênh là gì?" if normalize_user_language(lang) == "vi" else "6/6. What is the main channel goal?"
        return await safe_edit_or_send(query, text, reply_markup=channel_profile_goal_keyboard(lang))
    if action == "profile_goal":
        state = get_developing_video_pending(uid) or {}
        state["primary_goal"] = value or "content"
        profile_id = create_channel_profile(uid, state)
        clear_developing_video_pending(uid)
        profile = get_latest_channel_profile(uid)
        prefix = "✅ Đã lưu hồ sơ kênh.\n\n" if profile_id and normalize_user_language(lang) == "vi" else ("✅ Channel profile saved.\n\n" if profile_id else "⚠️ Không lưu được hồ sơ kênh.\n\n")
        return await safe_edit_or_send(query, prefix + channel_profile_text(profile, lang), parse_mode="HTML", reply_markup=channel_profile_keyboard(lang))
    if action == "catalog":
        clear_developing_video_pending(uid)
        return await safe_edit_or_send(
            query,
            reference_catalog_text(uid, lang),
            parse_mode="HTML",
            reply_markup=video_v6_keyboard(
                [("📤 Thêm video mẫu" if normalize_user_language(lang) == "vi" else "📤 Add reference", "videoref|start")],
                lang,
                back=("⬅️ Video mẫu / Kênh mẫu", "videoref|hub"),
            ),
        )
    if action == "link":
        clear_developing_video_pending(uid)
        set_developing_video_pending(uid, "videoref", "link_input")
        text = (
            "🔗 Hãy gửi link video tham khảo.\n\nGiai đoạn này TOAN AAS không tải video từ nền tảng. Bot sẽ lưu link/metadata an toàn và yêu cầu upload file hoặc mô tả thủ công để phân tích. Không trừ Xu."
            if normalize_user_language(lang) == "vi" else
            "🔗 Send the reference link. TOAN AAS does not download platform videos in this phase; upload the file or provide a manual description. No Xu charged."
        )
        return await safe_edit_or_send(query, text, reply_markup=video_v6_keyboard([], lang, back=("⬅️ Video mẫu / Kênh mẫu", "videoref|hub")))
    if action == "manual":
        clear_developing_video_pending(uid)
        set_developing_video_pending(uid, "videoref", "manual_description")
        text = "✍️ Hãy mô tả hook, số cảnh, nhịp dựng, visual, caption và CTA của video mẫu." if normalize_user_language(lang) == "vi" else "✍️ Describe the hook, scenes, pacing, visual style, caption and CTA."
        return await safe_edit_or_send(query, text, reply_markup=video_v6_keyboard([], lang, back=("⬅️ Video mẫu / Kênh mẫu", "videoref|hub")))
    if action == "format":
        plan = get_latest_developing_video_plan(uid, "videoref")
        if plan:
            return await safe_edit_or_send_long_html(query, video_reference_plan_text(plan, lang), reply_markup=video_reference_result_keyboard(lang))
        return await safe_edit_or_send(
            query,
            "🎬 Hãy upload video mẫu, nhập link/mô tả hoặc chọn format trong kho trước. Bước lập kế hoạch không trừ Xu."
            if normalize_user_language(lang) == "vi" else "🎬 Add a reference or choose a saved format first. Planning does not charge Xu.",
            reply_markup=video_reference_hub_keyboard(lang),
        )
    if action == "publish_package":
        plan = get_latest_developing_video_plan(uid, "videoref") or {"selected_topic": "nội dung theo format kênh"}
        package = create_publish_package(uid, plan, get_latest_channel_profile(uid))
        return await safe_edit_or_send(query, publish_package_text(package, lang), parse_mode="HTML", reply_markup=publish_package_keyboard(lang))
    if action == "save_catalog":
        plan = get_latest_developing_video_plan(uid, "videoref") or {}
        ref_id = _safe_int(plan.get("reference_id"), 0)
        if ref_id:
            update_reference_video_metadata(
                ref_id,
                uid,
                niche=_short_pending_text(plan.get("selected_topic"), 180),
                format_type=_short_pending_text(plan.get("analysis_kind"), 60),
                hook_pattern="hook_0_3s_then_proof_then_cta",
                scene_count=3,
                caption_style="short_channel_aware",
                cta_style="soft_action_cta",
                visual_style="original_adaptation",
                safety_notes=REFERENCE_SAFETY_NOTE,
                status="active",
            )
        text = "📌 Đã lưu metadata/format vào kho mẫu. Không lưu bản video lớn lâu dài và không trừ Xu." if normalize_user_language(lang) == "vi" else "📌 Format metadata saved. No long-term large video storage and no Xu charge."
        return await safe_edit_or_send(query, text, reply_markup=video_reference_result_keyboard(lang))
    if action == "performance":
        clear_developing_video_pending(uid)
        set_developing_video_pending(uid, "videoref", "performance_input")
        text = (
            "📊 Nhập hiệu quả bài đăng theo mẫu:\nurl=https://... views=1000 likes=50 comments=5 clicks=10 orders=2 revenue=500000 note=..."
            if normalize_user_language(lang) == "vi" else
            "📊 Enter performance: url=https://... views=1000 likes=50 comments=5 clicks=10 orders=2 revenue=500000 note=..."
        )
        return await safe_edit_or_send(query, text, reply_markup=video_v6_keyboard([], lang, back=("⬅️ Gói đăng bài", "videoref|publish_package")))
    if action == "auto_publish":
        text = (
            "🚫 TOAN AAS hiện chỉ xuất gói đăng bài để bạn tự đăng. Tự động đăng sẽ mở sau khi kết nối kênh hợp lệ và bạn xác nhận rõ. Bot chưa lưu token và chưa đăng nội dung."
            if normalize_user_language(lang) == "vi" else
            "🚫 Manual publish package only. Auto-publish stays disabled until a valid channel is connected and explicitly confirmed."
        )
        return await safe_edit_or_send(query, text, reply_markup=publish_package_keyboard(lang))

    if not VIDEO_ANALYZE_ENABLED:
        clear_developing_video_pending(uid)
        return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))

    if action in {"start", "await_video", "back_upload"}:
        clear_developing_video_pending(uid)
        set_developing_video_pending(uid, "videoref", "await_video")
        return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))

    pending = get_developing_video_pending(uid)
    plan = get_latest_developing_video_plan(uid, "videoref")
    state = pending or plan or {}
    if state.get("processing") == "1" and VIDEO_WAITING_LOCK_ENABLED:
        return await safe_edit_or_send(
            query,
            "⏳ Yêu cầu trước vẫn đang được xử lý. TOAN AAS chưa tạo thêm job mới."
            if normalize_user_language(lang) == "vi"
            else "⏳ The previous request is still processing. TOAN AAS did not create another job.",
        )
    if action == "back_direction":
        if not state.get("source_file_id"):
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        restore_developing_video_pending(uid, "videoref", state, "direction")
        return await safe_edit_or_send(query, video_reference_direction_text(state, lang), parse_mode="HTML", reply_markup=video_reference_direction_keyboard(lang))
    if action == "direction_custom":
        if not state.get("source_file_id"):
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        restore_developing_video_pending(uid, "videoref", state, "direction_custom")
        return await safe_edit_or_send(
            query,
            "✍️ Hãy nhập hướng phân tích video mẫu." if normalize_user_language(lang) == "vi" else "✍️ Enter the reference-video analysis direction.",
            reply_markup=video_v6_keyboard([], lang, back=("⬅️ Quay lại hướng phân tích" if normalize_user_language(lang) == "vi" else "⬅️ Back", "videoref|back_direction")),
        )
    if action == "direction":
        if not state.get("source_file_id"):
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        set_developing_video_pending(uid, "videoref", "topic_suggestions", analysis_kind=value or "ad", suggest_offset=0)
        current = get_developing_video_pending(uid) or {}
        return await safe_edit_or_send(query, video_reference_topic_text(current, lang), parse_mode="HTML", reply_markup=video_reference_topic_keyboard(lang))
    if action == "topic_refresh":
        if not state.get("analysis_kind"):
            return await safe_edit_or_send(query, video_reference_direction_text(state, lang), parse_mode="HTML", reply_markup=video_reference_direction_keyboard(lang))
        offset = _safe_int(state.get("suggest_offset"), 0) + 3
        restore_developing_video_pending(uid, "videoref", state, "topic_suggestions")
        set_developing_video_pending(uid, "videoref", "topic_suggestions", suggest_offset=offset)
        current = get_developing_video_pending(uid) or {}
        return await safe_edit_or_send(query, video_reference_topic_text(current, lang), parse_mode="HTML", reply_markup=video_reference_topic_keyboard(lang))
    if action == "topic_custom":
        if not state.get("analysis_kind"):
            return await safe_edit_or_send(query, video_reference_direction_text(state, lang), parse_mode="HTML", reply_markup=video_reference_direction_keyboard(lang))
        restore_developing_video_pending(uid, "videoref", state, "topic_custom")
        return await safe_edit_or_send(
            query,
            "✍️ Hãy nhập sản phẩm/chủ đề mới." if normalize_user_language(lang) == "vi" else "✍️ Enter the new product/topic.",
            reply_markup=video_v6_keyboard([], lang, back=("⬅️ Quay lại 3 gợi ý" if normalize_user_language(lang) == "vi" else "⬅️ Back to suggestions", "videoref|back_topics")),
        )
    if action == "back_topics":
        if not state.get("analysis_kind"):
            return await safe_edit_or_send(query, video_reference_direction_text(state, lang), parse_mode="HTML", reply_markup=video_reference_direction_keyboard(lang))
        restore_developing_video_pending(uid, "videoref", state, "topic_suggestions")
        return await safe_edit_or_send(query, video_reference_topic_text(state, lang), parse_mode="HTML", reply_markup=video_reference_topic_keyboard(lang))
    if action == "topic_choice":
        try:
            idx = max(1, min(3, int(value or "1")))
        except Exception:
            idx = 1
        topics = video_reference_topic_suggestions(state, lang)
        selected = topics[idx - 1] if idx <= len(topics) else (topics[0] if topics else "")
        working = dict(state)
        working["selected_topic"] = selected
        working["selected_suggestion_index"] = str(idx)
        working["processing"] = "1"
        restore_developing_video_pending(uid, "videoref", working, "processing")
        await safe_edit_or_send(query, video_reference_waiting_text(lang))
        working["processing"] = "0"
        clear_developing_video_pending(uid)
        plan = save_developing_video_plan(uid, "videoref", working)
        return await safe_edit_or_send_long_html(query, video_reference_plan_text(plan, lang), reply_markup=video_reference_result_keyboard(lang))
    if action == "version_refresh":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        refreshed = dict(plan)
        refreshed["prompt_variant_offset"] = str(_safe_int(refreshed.get("prompt_variant_offset"), 0) + 1)
        refreshed["motion_offset"] = str(_safe_int(refreshed.get("motion_offset"), 0) + 3)
        refreshed["music_offset"] = str(_safe_int(refreshed.get("music_offset"), 0) + 3)
        refreshed = save_developing_video_plan(uid, "videoref", refreshed)
        return await safe_edit_or_send_long_html(query, video_reference_plan_text(refreshed, lang), reply_markup=video_reference_result_keyboard(lang))
    if action == "finalization":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        render_plan = structured_video_plan(plan, "videoref")
        package = {
            "source": "reference_video_plan",
            "concept_text": plan.get("selected_topic") or "",
            "video_prompt": render_plan.get("prompt") or "",
            "music_choice": {"label": "reference-plan music/voice"},
        }
        source_state = dict(plan)
        source_state["video_prompt"] = package["video_prompt"]
        return await open_video_finalization(query, uid, "videoref", source_state, lang, "videoref|plan", package)
    if action == "image_prompts":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        return await safe_edit_or_send(
            query,
            video_reference_image_prompts_text(plan, lang),
            parse_mode="HTML",
            reply_markup=video_reference_result_keyboard(lang),
        )
    if action == "sample_segments":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        return await safe_edit_or_send(
            query,
            video_reference_segment_plan_text(plan, lang),
            parse_mode="HTML",
            reply_markup=video_reference_result_keyboard(lang),
        )
    if action == "video_prompts":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        duration = max(1, _safe_int(plan.get("source_duration"), 0))
        scene_count = max(3, min(12, math.ceil(duration / max(1, VIDEO_PROVIDER_RENDER_MAX_SECONDS))))
        return await safe_edit_or_send_long_html(
            query,
            detailed_video_scene_prompts_text(plan, "videoref", lang, scene_count=scene_count),
            reply_markup=video_reference_result_keyboard(lang),
        )
    if action == "frame_plan":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        text = (
            "🎞 <b>Planning ghép ảnh thành video</b>\n\n"
            "1. Tạo/lưu ảnh từng cảnh.\n"
            "2. Gửi ảnh đúng thứ tự.\n"
            "3. Chọn tỉ lệ, thời lượng, hiệu ứng và nhạc.\n"
            "4. Xem giá và xác nhận trước khi render.\n\n"
            "Planning miễn phí. Khi render thật, TOAN AAS giữ nguyên billing Ghép ảnh thành video hiện tại."
            if normalize_user_language(lang) == "vi"
            else
            "🎞 <b>Image slideshow planning</b>\n\nCreate/save scene images, upload them in order, choose ratio/duration/effect/music, then review price before rendering.\n\nPlanning is free. Real rendering keeps the existing frame-video billing."
        )
        return await safe_edit_or_send(
            query,
            text,
            parse_mode="HTML",
            reply_markup=video_v6_keyboard(
                [("📷 Bắt đầu gửi ảnh" if normalize_user_language(lang) == "vi" else "📷 Start uploading images", "framevideo|start")],
                lang,
                back=("⬅️ Quay lại kế hoạch" if normalize_user_language(lang) == "vi" else "⬅️ Back to plan", "videoref|plan"),
            ),
        )
    if action == "generate":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        active = shopaikey_active_job_for_user(uid, "video")
        if active:
            return await safe_edit_or_send(query, public_video_active_job_text(lang), reply_markup=public_video_active_job_keyboard(active, lang))
        render_plan = structured_video_plan(plan, "videoref")
        package = {
            "source": "reference_video_plan",
            "concept_text": plan.get("selected_topic") or "",
            "video_prompt": render_plan.get("prompt") or "",
            "music_choice": {"label": "reference-plan music/voice"},
        }
        source_state = dict(plan)
        source_state["video_prompt"] = package["video_prompt"]
        return await open_video_finalization(query, uid, "videoref", source_state, lang, "videoref|plan", package)
    if action == "save":
        return await safe_edit_or_send(
            query,
            "💾 Đã lưu kế hoạch video mẫu trong phiên hiện tại. Bot chưa gọi provider và chưa trừ Xu."
            if normalize_user_language(lang) == "vi"
            else "💾 Reference-video plan saved in this session. No provider call and no Xu charged.",
            reply_markup=video_reference_result_keyboard(lang),
        )
    if action == "plan":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        return await safe_edit_or_send_long_html(query, video_reference_plan_text(plan, lang), reply_markup=video_reference_result_keyboard(lang))
    return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))

async def handle_self_scene_ai_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    uid = query.from_user.id
    lang = get_user_language(uid) or "vi"
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else "start"
    if action == "start":
        clear_developing_video_pending(uid)
        return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
    if action == "direction_refresh":
        current = get_developing_video_pending(uid) or {}
        offset = _safe_int(current.get("style_offset"), 0) + 3
        set_developing_video_pending(uid, "selfscene", "direction", style_offset=offset)
        state = get_developing_video_pending(uid) or {}
        return await safe_edit_query_message(query, self_scene_start_text(lang, state), reply_markup=self_scene_input_keyboard(lang, state))
    if action == "direction_choice":
        state = get_developing_video_pending(uid) or {}
        try:
            idx = max(1, min(3, int(parts[2] if len(parts) > 2 else "1")))
        except Exception:
            idx = 1
        options = self_scene_direction_suggestions(_safe_int(state.get("style_offset"), 0), lang)
        selected = options[idx - 1] if idx <= len(options) else (options[0] if options else {})
        direction_text = selected.get("label") or self_scene_direction_label(selected.get("code"), lang)
        set_developing_video_pending(uid, "selfscene", "object", direction=direction_text, direction_code=selected.get("code") or "")
        state = get_developing_video_pending(uid) or {}
        return await safe_edit_query_message(query, self_scene_object_text(state, lang), reply_markup=self_scene_object_keyboard(lang))
    if action == "direction":
        direction = parts[2] if len(parts) > 2 else "context"
        set_developing_video_pending(uid, "selfscene", "object", direction=direction)
        state = get_developing_video_pending(uid) or {}
        return await safe_edit_query_message(query, self_scene_object_text(state, lang), reply_markup=self_scene_object_keyboard(lang))
    if action == "direction_custom":
        set_developing_video_pending(uid, "selfscene", "direction_custom")
        return await safe_edit_query_message(
            query,
            self_scene_direction_custom_text(lang),
            reply_markup=video_v6_keyboard(
                [],
                lang,
                back=("⬅️ Quay lại hướng" if normalize_user_language(lang) == "vi" else "⬅️ Back to directions", "selfscene|start"),
            ),
        )
    if action in {"object", "input"}:
        input_type = parts[2] if len(parts) > 2 else "custom"
        if input_type == "video":
            recent = get_recent_media_state(LAST_USER_VIDEO, uid) or {}
            if not recent.get("file_id"):
                set_developing_video_pending(uid, "selfscene", "await_video", input_type="video")
                return await safe_edit_query_message(
                    query,
                    "📎 Hãy gửi video tự quay cần đổi cảnh. TOAN AAS chỉ lưu Telegram file ID trong phiên, chưa gọi provider và chưa trừ Xu."
                    if normalize_user_language(lang) == "vi"
                    else "📎 Send the self-shot video to transform. TOAN AAS only keeps its Telegram file ID in this session; no provider call and no Xu charged.",
                    reply_markup=video_v6_keyboard([], lang, back=("⬅️ Quay lại đối tượng" if normalize_user_language(lang) == "vi" else "⬅️ Back to subject", "selfscene|back_object")),
                )
            set_developing_video_pending(
                uid,
                "selfscene",
                "context",
                input_type="video",
                selected_topic=self_scene_input_label("video", lang),
                source_file_id=recent.get("file_id"),
                source_file_name=recent.get("file_name") or "self_scene_video.mp4",
                source_mime_type=recent.get("mime_type") or "video/mp4",
                source_duration=recent.get("duration") or 0,
                source_file_size=recent.get("file_size") or 0,
            )
            state = get_developing_video_pending(uid) or {}
            return await safe_edit_query_message(query, self_scene_context_text(state, lang), reply_markup=self_scene_context_keyboard(lang))
        if input_type != "custom":
            subject = self_scene_input_label(input_type, lang)
            set_developing_video_pending(uid, "selfscene", "context", input_type=input_type, selected_topic=subject)
            state = get_developing_video_pending(uid) or {}
            return await safe_edit_query_message(query, self_scene_context_text(state, lang), reply_markup=self_scene_context_keyboard(lang))
        set_developing_video_pending(uid, "selfscene", "describe", input_type=input_type)
        return await safe_edit_query_message(
            query,
            self_scene_describe_text(input_type, lang),
            reply_markup=video_v6_keyboard(
                [],
                lang,
                back=("⬅️ Quay lại đối tượng" if normalize_user_language(lang) == "vi" else "⬅️ Back to subject", "selfscene|back_object"),
            ),
        )
    pending = get_developing_video_pending(uid)
    if action == "back_object":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        return await safe_edit_query_message(query, self_scene_object_text(pending, lang), reply_markup=self_scene_object_keyboard(lang))
    if action == "back_context":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        return await safe_edit_query_message(query, self_scene_context_text(pending, lang), reply_markup=self_scene_context_keyboard(lang))
    if action == "back_style":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        return await safe_edit_query_message(query, self_scene_style_text(pending, lang), reply_markup=self_scene_style_keyboard(lang))
    if action == "back_music":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        return await safe_edit_query_message(query, self_scene_music_text(pending, lang), reply_markup=self_scene_music_keyboard(lang))
    if action == "context_custom":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        set_developing_video_pending(uid, "selfscene", "context_custom")
