def localized_menu_content(action: str, is_admin: bool, lang: str, user_id=None) -> tuple[str, InlineKeyboardMarkup]:
    lang = normalize_user_language(lang) or "vi"
    if action in {"main", "back"}:
        return localized_start_menu_text(user_id or "__customer__", lang), localized_main_menu_keyboard(is_admin, lang)
    if action == "main_video":
        return menu_text_main_video_i18n(lang), main_video_keyboard(lang)
    if action == "main_ai":
        return menu_text_main_ai_i18n(lang), main_ai_keyboard(lang)
    if action == "main_memory":
        return menu_text_main_memory_i18n(lang), main_memory_keyboard(lang, user_id)
    if action == "memory_storage_status":
        return memory_status_text(user_id or "__customer__"), memory_storage_nav_keyboard(lang)
    if action == "memory_storage_addon":
        return memory_storage_addon_text(), memory_storage_addon_keyboard(lang)
    if action == "memory_storage_cleanup":
        return memory_storage_cleanup_text(), memory_storage_nav_keyboard(lang)
    if action == "main_docs":
        return menu_text_main_docs_i18n(lang), main_docs_keyboard(lang)
    if action == "main_image":
        return menu_text_main_image_i18n(lang), main_image_keyboard(lang)
    if action == "main_music":
        return menu_text_main_music_i18n(lang), music_tools_keyboard(lang)
    if action == "main_audio":
        return menu_text_main_audio_i18n(lang), main_audio_keyboard(lang)
    if action == "translate":
        return translation_menu_text(lang), translation_menu_keyboard(lang)
    if action == "translation_language_hub":
        return translation_language_hub_text(lang), translation_language_hub_keyboard(lang)
    if action == "translation_auto_target":
        return menu_text_translate_i18n(False, lang), translate_language_keyboard(False, lang)
    if action == "translate_more":
        return menu_text_translate_i18n(True, lang), translate_language_keyboard(True, lang)
    if action == "main_quick":
        return menu_text_main_quick_i18n(lang), main_quick_keyboard(lang)
    if action == "main_topup":
        return menu_text_main_topup_i18n(lang), main_topup_keyboard(lang, user_id)
    if action == "main_profile":
        return menu_text_main_profile_i18n(user_id or "__customer__", lang), main_profile_keyboard(lang)
    if action == "profile_packages":
        return user_package_summary_text(user_id or "__customer__"), profile_child_keyboard(lang)
    if action == "profile_ref_link":
        return referral_account_link_text(user_id or "__customer__", BOT_USERNAME, lang), profile_child_keyboard(lang)
    if action == "profile_ref_policy":
        return referral_account_policy_text(user_id or "__customer__"), profile_child_keyboard(lang)
    if action == "profile_ref_stats":
        return referral_account_stats_text(user_id or "__customer__"), profile_child_keyboard(lang)
    if action == "main_guide":
        return menu_text_main_guide_i18n(lang), main_guide_keyboard(lang)
    if action == "guide":
        return guide_index_text_i18n(lang), guide_keyboard("", lang)
    if action.startswith("guide_"):
        section = action.replace("guide_", "", 1)
        return guide_section_text_i18n(section, lang), guide_keyboard(section, lang)
    if action in ADMIN_MENU_PAGE_HANDLERS:
        return ADMIN_MENU_PAGE_HANDLERS[action]()
    if action == "doc_tools":
        return doc_tools_menu_text_i18n(lang), doc_tools_keyboard(lang)
    if action.startswith("hint_"):
        section, hint = menu_hint_text_i18n(action, lang)
        return hint, menu_nav_keyboard_i18n(section, is_admin, lang)
    return menu_content(action, is_admin)

