async def cmd_huongdan(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id if update.effective_user else 0
    lang = get_user_language(uid) or "vi"
    section = context.args[0] if context.args else ""
    await update.message.reply_text(
        guide_section_text_i18n(section, lang),
        parse_mode="HTML",
        reply_markup=guide_keyboard(section, lang),
    )
    if section or PUBLIC_BASE_URL:
        return
    sent_any = False
    filename = GUIDE_DOCX_FILE
    path = find_guide_docx_path()
    if os.path.exists(path):
        try:
            with open(path, "rb") as f:
                await context.bot.send_document(
                    chat_id=update.effective_chat.id,
                    document=f,
                    filename=filename,
                    caption=f"📘 {filename}",
                )
            sent_any = True
        except Exception as e:
            logger.warning(f"Cannot send guide document {filename}: {e}")
    if not sent_any:
        await update.message.reply_text(
            "⚠️ Chưa có file Word hướng dẫn. Admin cần set PUBLIC_BASE_URL hoặc kiểm tra file hướng dẫn trong repo."
        )

async def cmd_guide_debug(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    found = find_guide_docx_path()
    candidates = guide_docx_candidates()
    lines = [
        "📘 <b>Guide Debug</b>",
        f"• Found: <code>{'YES' if found else 'NO'}</code>",
        f"• File: <code>{html.escape(GUIDE_DOCX_FILE)}</code>",
        f"• CWD: <code>{html.escape(os.getcwd())}</code>",
        "",
        "<b>Candidates</b>",
    ]
    for idx, path in enumerate(candidates, 1):
        lines.append(f"{idx}. <code>{html.escape(os.path.basename(path))}</code> — <code>{'exists' if os.path.exists(path) else 'missing'}</code>")
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

def terms_keyboard() -> InlineKeyboardMarkup:
    rows = []
    url = terms_pdf_download_url()
    if url:
        rows.append([InlineKeyboardButton("📄 Tải điều khoản PDF", url=url)])
    rows.append([InlineKeyboardButton("💬 Nhắn admin/hỗ trợ", url=SUPPORT_TELEGRAM_URL or "https://t.me/toanaas")])
    return InlineKeyboardMarkup(rows)

