async def cmd_tool_test_ai(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    gemini_status = "MISSING"
    gemini_detail = ""
    openai_status = "MISSING"
    openai_detail = ""
    result_preview = ""

    if gemini_client:
        try:
            def run_gemini():
                return gemini_client.models.generate_content(
                    model="gemini-2.0-flash",
                    contents="Reply exactly: OK TOAN AAS",
                )
            res = await asyncio.to_thread(run_gemini)
            result_preview = (getattr(res, "text", "") or "")[:160]
            gemini_status = "PASS" if result_preview else "FAIL"
            gemini_detail = result_preview or "empty_response"
            record_api_debug("gemini", "tool_test_ai", gemini_status, 0, gemini_detail)
        except Exception as e:
            gemini_status = "FAIL"
            gemini_detail = provider_error_summary(e)[:240]
            record_api_debug("gemini", "tool_test_ai", "FAIL", 0, gemini_detail)

    if openai_client:
        try:
            def run_openai():
                return openai_client.chat.completions.create(
                    model="gpt-4o-mini",
                    messages=[
                        {"role": "system", "content": "You are a short smoke-test responder."},
                        {"role": "user", "content": "Reply exactly: OK TOAN AAS"},
                    ],
                    max_tokens=20,
                )
            res = await asyncio.to_thread(run_openai)
            openai_text = (res.choices[0].message.content or "")[:160]
            if not result_preview:
                result_preview = openai_text
            openai_status = "PASS" if openai_text else "FAIL"
            openai_detail = openai_text or "empty_response"
            record_api_debug("openai", "tool_test_ai", openai_status, 0, openai_detail)
        except Exception as e:
            openai_status = "FAIL"
            openai_detail = provider_error_summary(e)[:240]
            record_api_debug("openai", "tool_test_ai", "FAIL", 0, openai_detail)

    overall = "PASS" if "PASS" in {gemini_status, openai_status} else ("MISSING" if {gemini_status, openai_status} == {"MISSING"} else "FAIL")
    save_tool_test_result("ai", overall, f"Gemini={gemini_status}; OpenAI={openai_status}", update.effective_user.id)
    save_tool_test_result("ai_gemini", gemini_status, gemini_detail, update.effective_user.id)
    save_tool_test_result("ai_openai", openai_status, openai_detail, update.effective_user.id)
    await update.message.reply_text(
        "🤖 <b>AI Smoke Test</b>\n\n"
        f"• Gemini: <code>{html.escape(gemini_status)}</code>"
        + (f" — <code>{html.escape(gemini_detail[:180])}</code>" if gemini_detail else "")
        + "\n"
        f"• OpenAI fallback: <code>{html.escape(openai_status)}</code>"
        + (f" — <code>{html.escape(openai_detail[:180])}</code>" if openai_detail else "")
        + "\n"
        f"• Overall: <code>{html.escape(overall)}</code>\n"
        f"• Provider used: <code>{'Gemini' if gemini_status == 'PASS' else ('OpenAI' if openai_status == 'PASS' else '-')}</code>\n"
        f"• Result: <code>{html.escape(result_preview or '-')}</code>\n\n"
        "Không hiển thị API key.",
        parse_mode="HTML",
    )

async def cmd_orchestrator_status(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    registry = provider_registry()
    lines = [
        "🧭 <b>TOAN AAS Provider Orchestrator V1</b>",
        "",
        "Trạng thái: <code>ADMIN_FIRST</code>",
        "Public paid render: <code>OFF</code>",
        "Xu deduction in smoke tests: <code>OFF</code>",
        "Secret logging: <code>OFF</code>",
        "",
        "<b>Capabilities</b>",
    ]
    for capability in sorted(PROVIDER_ORCHESTRATOR_CAPABILITIES):
        candidates = provider_registry_by_capability(capability)
        summary = ", ".join(
            f"{item.get('label')}:{item.get('stage')}"
            for item in candidates
        ) or "-"
        lines.append(f"• {html.escape(capability)}: <code>{html.escape(summary)}</code>")
    lines.extend([
        "",
        "<b>Provider health</b>",
    ])
    for name, payload in registry.items():
        health = payload.get("health") or {}
        status = str(health.get("status") or "NOT_TESTED").upper()
        lines.append(
            f"• {html.escape(payload.get('label') or name)}: "
            f"configured=<code>{'yes' if payload.get('configured') else 'no'}</code> | "
            f"stage=<code>{html.escape(str(payload.get('stage') or 'planned'))}</code> | "
            f"tested=<code>{html.escape(status)}</code>"
        )
    lines.extend([
        "",
        "<b>Smoke commands</b>",
        "• <code>/provider_matrix</code>",
        "• <code>/tool_test_openrouter</code>",
        "• <code>/tool_test_kling_status</code>",
        "• <code>/tool_test_replicate_status</code>",
        "• <code>/tool_test_elevenlabs_status</code>",
        "• <code>/tool_test_deepgram_status</code>",
        "• <code>/shopaikey_status</code> | <code>/tool_test_shopaikey</code> | <code>/tool_test_shopaikey_chat</code>",
    ])
    await reply_html_lines(update, lines)

