async def cmd_transcribe(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    if not DEEPGRAM_API_KEY:
        return await reply_translation_surface(update, TRANSLATE_AUDIO_MISSING_STT_TEXT)
    media_info = await resolve_stt_test_media(update, context)
    if not media_info:
        return await reply_translation_surface(
            update,
            "⚠️ Gửi voice/audio/video ngắn rồi reply hoặc gõ /transcribe trong vòng 2 phút."
        )
    if media_info.get("error"):
        return await reply_translation_surface(
            update,
            TRANSLATE_AUDIO_TIMEOUT_TEXT
            if media_info.get("error") == "telegram_timeout" else TRANSLATE_AUDIO_ERROR_TEXT
        )
    file_size = int(media_info.get("file_size", 0) or 0)
    if file_size > 15 * 1024 * 1024 or not media_info.get("bytes"):
        return await reply_translation_surface(update, TRANSLATE_AUDIO_ERROR_TEXT)
    raw_cost = calculate_dynamic_cost("whisper", file_size)
    ok_credit, _charge_preview = await preview_media_factory_credit_or_reply(update, uid, raw_cost, "spend_transcribe")
    if not ok_credit:
        return
    try:
        transcript = (await AgentDeepgram.transcribe(
            media_info["bytes"],
            context,
            content_type=media_info.get("content_type") or "application/octet-stream",
        ) or "").strip()
        if not transcript or transcript.startswith("❌"):
            save_tool_test_result("stt", "FAIL", transcript[:400] or "empty_transcript", uid)
            return await reply_translation_surface(update, TRANSLATE_AUDIO_ERROR_TEXT)
        charge_result = await spend_media_factory_after_success_or_reply(
            update,
            uid,
            raw_cost,
            "spend_transcribe",
            f"Transcribe audio: {file_size} bytes",
        )
        if not charge_result.get("ok"):
            return
        save_tool_test_result("stt", "PASS", f"provider=deepgram; source={media_info.get('source')}", uid)
        balance = get_user(uid)[0] if not is_admin_user(uid) else "∞"
        await reply_translation_surface(
            update,
            "🎙 BÓC BĂNG AUDIO TOAN AAS\n\n"
            "• Bóc băng: đã bật\n\n"
            "<b>Nội dung:</b>\n"
            f"{html.escape(transcript[:3500])}\n\n"
            f"💼 Còn lại: {balance} Xu | /naptien để nạp thêm",
            parse_mode="HTML",
        )
    except Exception:
        save_tool_test_result("stt", "FAIL", "transcribe_provider_failed", uid)
        await reply_translation_surface(update, TRANSLATE_AUDIO_ERROR_TEXT)

async def handle_auto_translate_message(update: Update, context: ContextTypes.DEFAULT_TYPE, text: str, target: str):
    uid = update.effective_user.id
    username = update.effective_user.username or update.effective_user.first_name or ""
    await context.bot.send_chat_action(chat_id=update.effective_chat.id, action="typing")
    try:
        result = await translate_to_language(text[:1800], target)
        provider = result.get("provider") or "translation"
        translated = result.get("text") or ""
        record_usage_event(
            uid,
            username=username,
            event_type="tool_success",
            tool_name="auto_translate",
            command="translate_mode",
            status=target,
            provider=provider,
            detail=f"target={target}",
        )
        await update.message.reply_text(
            "🌐 <b>BẢN DỊCH TOAN AAS</b>\n\n"
            "• Nguồn: <code>auto</code>\n"
            f"• Đích: <b>{html.escape(translate_target_label(target))}</b>\n"
            + "\n"
            f"{html.escape(translated)}\n\n"
            "<i>/translate_mode_off để tắt</i>",
            parse_mode="HTML",
        )
    except Exception as e:
        statuses = getattr(e, "statuses", {}) if isinstance(e, TranslationProviderError) else {}
        errors = getattr(e, "errors", {}) if isinstance(e, TranslationProviderError) else {"error": provider_error_summary(e)}
        detail = ai_failure_detail(statuses, errors) if statuses else provider_error_summary(e)
        record_usage_event(
            uid,
            username=username,
            event_type="tool_fail",
            tool_name="auto_translate",
            command="translate_mode",
            status="provider_fail",
            provider="translation_router",
            detail=detail,
        )
        if is_admin_user(uid):
            await update.message.reply_text(
                "❌ Dịch tự động đang tạm lỗi hoặc hết quota provider.\n"
                f"• Chi tiết: {html.escape(detail[:240])}\n"
                "Không có Xu nào bị trừ.\n"
                "Không chuyển sang AI chat để tránh trả lời sai ngữ cảnh.\n"
                "Tắt dịch: /translate_mode_off",
            )
        else:
            await update.message.reply_text(
                "❌ Dịch tự động đang tạm lỗi hoặc quá tải.\n"
                "Bot chưa trừ Xu. Vui lòng thử lại sau.\n"
                "Không chuyển sang AI chat để tránh trả lời sai ngữ cảnh.\n"
                "Tắt dịch: /translate_mode_off"
            )

async def cmd_tool_test_image(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    reply = update.message.reply_to_message if update.message else None
    if not (reply and getattr(reply, "photo", None)):
        return await update.message.reply_text(
            "⚠️ Vui lòng gửi ảnh nhỏ trước, sau đó reply ảnh bằng <code>/tool_test_image</code>.\n"
            "Nếu muốn xử lý thật cho khách, dùng luồng tách nền ảnh hiện tại của bot.",
            parse_mode="HTML",
        )
    photo_size = reply.photo[-1]
    img_bytes = bytes(await (await photo_size.get_file()).download_as_bytearray())
    test_result = await run_image_provider_tests(img_bytes)
    output_bytes = test_result["output_bytes"]
    output_provider = test_result["output_provider"]
    remove_info = test_result["removebg"]
    cutout_info = test_result["cutout"]
    overall = "PASS" if output_bytes else ("MISSING" if remove_info["status"] == "MISSING" and cutout_info["status"] == "MISSING" else "FAIL")
    remove_line = format_image_provider_status("RemoveBG", remove_info["status"], remove_info["detail"])
    cutout_line = format_image_provider_status("Cutout", cutout_info["status"], cutout_info["detail"])
    detail = f"RemoveBG={remove_line}; Cutout={cutout_line}"
    save_tool_test_result("image", overall, detail, update.effective_user.id)
    if output_bytes:
        save_tool_test_result("image_remove_bg", "PASS", f"provider={output_provider.lower()}; cost_level=low; tool_test_image success", update.effective_user.id)
    elif overall == "FAIL":
        save_tool_test_result("image_remove_bg", "FAIL", detail, update.effective_user.id)
    if output_bytes:
        out = telegram_png_document(output_bytes, "toan_aas_tool_test_no_bg.png")
        await update.message.reply_document(
            document=out,
            filename=out.name,
            caption=f"🖼 Image Provider Smoke Test: {output_provider} PASS",
        )
    await update.message.reply_text(
        ("✅ <b>Image provider PASS</b>\n\n" if output_bytes else "❌ <b>Image provider FAIL</b>\n\n")
        + "\n".join(image_provider_block("RemoveBG", remove_info)) + "\n"
        + "\n".join(image_provider_block("Cutout", cutout_info)) + "\n"
        f"• Output sent: <code>{'yes' if output_bytes else 'no'}</code>\n"
        + (f"• Provider: <code>{html.escape(output_provider)}</code>\n" if output_bytes else "")
        + (f"• Error: <code>{html.escape(detail[:500])}</code>\n" if detail and not output_bytes else "")
        + ("• Xu đã hoàn nếu có trừ.\n" if not output_bytes else "")
        + "\nKhông hiển thị API key.",
        parse_mode="HTML",
    )

