def normalize_music_inline_command_text(text: str) -> str:
    raw = (text or "").strip()
    if not raw:
        return ""
    bot_name = str(BOT_USERNAME or "toanaasbot").lstrip("@").lower()
    lowered = raw.lower()
    mention_prefix = f"@{bot_name} "
    if lowered.startswith(mention_prefix):
        raw = raw.split(None, 1)[1].strip() if len(raw.split(None, 1)) > 1 else ""
    if not raw.startswith("/"):
        return ""
    first, *rest = raw.split(maxsplit=1)
    if "@" in first:
        command_name, mention = first.split("@", 1)
        if mention.lower() != bot_name:
            return ""
        first = command_name
    return first + (f" {rest[0]}" if rest else "")

async def dispatch_music_inline_command(update: Update, context: ContextTypes.DEFAULT_TYPE, command_text: str) -> bool:
    raw = (command_text or "").strip()
    if not raw.startswith("/"):
        return False
    first, *rest = raw.split(maxsplit=1)
    command = first.lstrip("/").split("@", 1)[0].lower()
    handler_map = {
        "music_prompt": cmd_music_prompt,
        "music_library": cmd_music_library,
        "sfx_library": cmd_sfx_library,
        "media_library": cmd_media_library,
    }
    handler = handler_map.get(command)
    if not handler:
        return False
    old_args = getattr(context, "args", None)
    try:
        context.args = (rest[0].split() if rest else [])
        await handler(update, context)
    finally:
        context.args = old_args
    return True

async def handle_music_guided_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.message.text or not update.effective_user:
        return False
    uid = update.effective_user.id
    state = get_music_guided_pending(uid)
    if not state:
        return False
    text = _short_pending_text(update.message.text, 900)
    if not text or text.startswith("/"):
        return False
    lang = music_ui_lang(uid)
    action = str(state.get("pending_action") or "")
    clear_music_guided_pending(uid)
    if action == "music_prompt_input":
        blocked = music_copyright_block_reason(text)
        if blocked:
            await update.message.reply_text(
                "⛔ Prompt nhạc này có rủi ro bản quyền/clone.\n\n"
                f"• Dấu hiệu: <code>{html.escape(blocked)}</code>\n"
                "Hãy mô tả mood, tempo, nhạc cụ, bối cảnh video và cảm xúc thay vì nhắc nghệ sĩ/bài hát cụ thể.\n"
                "Bot chưa trừ Xu.",
                parse_mode="HTML",
                reply_markup=music_guided_back_keyboard(lang),
            )
            return True
        suggestions = music_prompt_suggestions(text, 0, lang)
        save_music_guided_result(uid, {"description": text, "offset": 0, "suggestions": suggestions, "selected_prompt": ""})
        await update.message.reply_text(
            music_prompt_suggestions_text(text, 0, lang),
            parse_mode="HTML",
            reply_markup=music_prompt_result_keyboard(lang),
            disable_web_page_preview=True,
        )
        return True
    if action == "music_library_keyword":
        await send_music_library_results(update.message, uid, text)
        return True
    if action == "sfx_library_keyword":
        await send_sfx_library_results(update.message, uid, text)
        return True
    if action == "media_library_keyword":
        await send_media_library_results(update.message, uid, text)
        return True
    if action == "voice_text":
        save_music_guided_result(uid, {"voice_text": text})
        await update.message.reply_text(
            voice_style_suggestions_text(text, lang),
            parse_mode="HTML",
            reply_markup=voice_style_keyboard(lang),
        )
        return True
    return False

def music_ai_provider_summary() -> str:
    providers = []
    if MUSICFUL_API_KEY:
        providers.append("Musicful")
    if MINIMAX_API_KEY and MINIMAX_GROUP_ID:
        providers.append("MiniMax")
    elif MINIMAX_API_KEY:
        providers.append("MiniMax thiếu group_id")
    if STABILITY_API_KEY:
        providers.append("Stability/Stable Audio")
    if MUBERT_API_KEY:
        providers.append("Mubert")
    if BEATOVEN_API_KEY:
        providers.append("Beatoven")
    if SOUNDRAW_API_KEY:
        providers.append("Soundraw")
    return ", ".join(providers) or "missing"

