def xu_number(value: int = 0) -> str:
    return f"{int(value or 0):,}".replace(",", ".")

def round_video_xu(value, step: int = 0) -> int:
    unit = max(1, int(step or VIDEO_PRICE_ROUND_TO_XU or 1))
    amount = max(0.0, float(value or 0))
    return int(math.ceil(amount / unit) * unit) if amount else 0

def video_quality_from_tier(tier: str = "") -> str:
    normalized = normalize_video_tier(tier)
    if normalized in {"high", "premium"}:
        return "high"
    if normalized in {"standard", "common"}:
        return "standard"
    return "fast"

def normalize_video_processing_type(value: str = "") -> str:
    normalized = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "frame": "local_frame_video",
        "local": "local_frame_video",
        "text_to_video": "ai_text_to_video",
        "image_to_video": "ai_image_to_video",
        "video_to_video": "ai_video_to_video",
        "long": "long_ai_video",
        "long_video": "long_ai_video",
    }
    normalized = aliases.get(normalized, normalized)
    allowed = {
        "local_frame_video", "ai_text_to_video", "ai_image_to_video", "ai_video_to_video",
        "long_ai_video", "video_sample_to_prompt", "subtitle_only", "translate_subtitle",
        "dub_only", "subtitle_plus_dub",
    }
    return normalized if normalized in allowed else "ai_text_to_video"

def calculate_video_base_price(
    duration_seconds,
    processing_type,
    quality_tier,
    segment_seconds=None,
    include_retry_buffer=True,
) -> dict:
    duration = max(1, int(math.ceil(float(duration_seconds or 0))))
    processing = normalize_video_processing_type(processing_type)
    quality = str(quality_tier or "standard").strip().lower()
    if quality not in {"fast", "standard", "high"}:
        quality = video_quality_from_tier(quality)
    notes = []
    if processing in {"subtitle_only", "translate_subtitle", "dub_only", "subtitle_plus_dub", "video_sample_to_prompt"}:
        return {
            "duration_seconds": duration,
            "processing_type": processing,
            "quality_tier": quality,
            "segments": 0,
            "segment_seconds": 0,
            "base_video_xu": 0,
            "notes": ["No video rendering charge for this processing type."],
        }
    if processing == "local_frame_video":
        raw = max(float(LOCAL_FRAME_VIDEO_MIN_XU), duration * float(LOCAL_FRAME_VIDEO_XU_PER_SECOND))
        return {
            "duration_seconds": duration,
            "processing_type": processing,
            "quality_tier": quality,
            "segments": 1,
            "segment_seconds": duration,
            "base_video_xu": round_video_xu(raw),
            "notes": notes,
        }
    rate = {
        "fast": VIDEO_AI_FAST_XU_PER_SECOND,
        "standard": VIDEO_AI_STANDARD_XU_PER_SECOND,
        "high": VIDEO_AI_HIGH_XU_PER_SECOND,
    }[quality]
    is_long = processing == "long_ai_video" or duration > int(VIDEO_AI_MAX_PROVIDER_SEGMENT_SECONDS or 60)
    default_segment = VIDEO_AI_LONG_SEGMENT_SECONDS if is_long else VIDEO_AI_DEFAULT_SEGMENT_SECONDS
    segment = max(1, min(int(segment_seconds or default_segment), int(VIDEO_AI_MAX_PROVIDER_SEGMENT_SECONDS or 60)))
    segments = max(1, int(math.ceil(duration / segment)))
    factor = 1.0
    if is_long:
        factor = float(VIDEO_LONG_EXTRA_FACTOR or 1.0)
        if include_retry_buffer:
            # The long-video risk price uses the larger configured safety factor,
            # not two compounded markups. This keeps the published examples stable.
            factor = max(factor, float(VIDEO_RETRY_BUFFER_FACTOR or 1.0))
        notes.append(f"Long video split into {segments} segments; risk factor {factor:.2f}x.")
    raw = duration * float(rate or 0) * factor
    return {
        "duration_seconds": duration,
        "processing_type": processing,
        "quality_tier": quality,
        "segments": segments,
        "segment_seconds": segment,
        "base_video_xu": round_video_xu(raw),
        "notes": notes,
    }

def calculate_video_addon_price(
    duration_seconds,
    subtitle_option="none",
    dubbing_option="none",
    translation_enabled=False,
) -> dict:
    duration = max(1, int(math.ceil(float(duration_seconds or 0))))
    subtitle = str(subtitle_option or "none").strip().lower()
    dubbing = str(dubbing_option or "none").strip().lower()
    translated = bool(translation_enabled or "translated" in subtitle or "translated" in dubbing)
    has_subtitle = subtitle not in {"", "none", "off"}
    has_dubbing = dubbing not in {"", "none", "off"}
    minutes = duration / 60.0
    subtitle_xu = 0
    dubbing_xu = 0
    if has_subtitle and has_dubbing:
        combined_rate = VIDEO_TRANSLATED_SUBTITLE_PLUS_DUB_XU_PER_MINUTE if translated else VIDEO_SUBTITLE_PLUS_DUB_XU_PER_MINUTE
        combined_min = (VIDEO_SUBTITLE_MIN_XU + VIDEO_DUB_MIN_XU) if not translated else max(
            VIDEO_SUBTITLE_MIN_XU + VIDEO_DUB_MIN_XU,
            VIDEO_TRANSLATED_SUBTITLE_PLUS_DUB_XU_PER_MINUTE,
        )
        combined = round_video_xu(max(float(combined_min), minutes * float(combined_rate)), VIDEO_SUBTITLE_DUB_PRICE_ROUND_TO_XU)
        dubbing_xu = round_video_xu(max(float(VIDEO_DUB_MIN_XU), minutes * float(VIDEO_DUB_XU_PER_MINUTE)), VIDEO_SUBTITLE_DUB_PRICE_ROUND_TO_XU)
        subtitle_xu = max(0, combined - dubbing_xu)
    elif has_subtitle:
        rate = VIDEO_SUBTITLE_TRANSLATE_XU_PER_MINUTE if translated else VIDEO_SUBTITLE_CREATE_XU_PER_MINUTE
        minimum = max(VIDEO_SUBTITLE_MIN_XU, rate)
        subtitle_xu = round_video_xu(max(float(minimum), minutes * float(rate)), VIDEO_SUBTITLE_DUB_PRICE_ROUND_TO_XU)
    elif has_dubbing:
        dubbing_xu = round_video_xu(max(float(VIDEO_DUB_MIN_XU), minutes * float(VIDEO_DUB_XU_PER_MINUTE)), VIDEO_SUBTITLE_DUB_PRICE_ROUND_TO_XU)
    return {
        "duration_seconds": duration,
        "subtitle_option": subtitle,
        "dubbing_option": dubbing,
        "translation_enabled": translated,
        "subtitle_xu": int(subtitle_xu),
        "dubbing_xu": int(dubbing_xu),
        "addon_xu": int(subtitle_xu + dubbing_xu),
    }

def calculate_music_price(project: dict | None = None, duration_seconds=None, music_option: str = "none", item_count: int = 0) -> dict:
    project = project if isinstance(project, dict) else {}
    duration = max(1, int(math.ceil(float(
        project.get("duration_seconds") or duration_seconds or VIDEO_AI_DEFAULT_SEGMENT_SECONDS
    ))))
    option = str(
        project.get("music_option")
        or project.get("current_video_music_option")
        or music_option
        or "none"
    ).strip().lower()
    count = max(0, int(project.get("music_item_count") or project.get("sfx_count") or item_count or 0))
    notes = []
    music_xu = 0
    if option in {"", "none", "off", "no", "không"}:
        option = "none"
    elif option in {"uploaded", "upload", "user_upload", "own"}:
        option = "user_upload"
        music_xu = int(USER_UPLOAD_MUSIC_XU or 0)
    elif option in {"library", "background", "suggested", "music_library"}:
        option = "library"
        music_xu = int(MUSIC_LIBRARY_XU or 0)
    elif option in {"sfx", "sfx_library", "sound_effect"}:
        option = "sfx_library"
        count = max(1, count)
        music_xu = round_video_xu(
            max(float(SFX_LIBRARY_MIN_XU), count * float(SFX_LIBRARY_XU_PER_ITEM)),
            MUSIC_AI_PRICE_ROUND_TO_XU,
        )
    elif option in {"ai", "ai_music", "music_ai", "suno"}:
        option = "ai_music"
        if not (MUSIC_AI_ENABLED and SHOPAIKEY_MUSIC_ENABLED and SHOPAIKEY_MUSIC_ENDPOINT):
            notes.append("AI music provider is disabled or its verified endpoint is missing; no music charge added.")
        else:
            blocks = max(1, int(math.ceil(duration / 30.0)))
            music_xu = round_video_xu(
                max(float(MUSIC_AI_MIN_XU), blocks * float(MUSIC_AI_XU_PER_30_SECONDS)),
                MUSIC_AI_PRICE_ROUND_TO_XU,
            )
    else:
        notes.append(f"Unknown music option '{option}' treated as no-charge planning metadata.")
    return {
        "music_option": option,
        "music_item_count": count,
        "music_xu": int(music_xu),
        "music_notes": notes,
    }

def calculate_video_total_price(
    duration_seconds,
    processing_type,
    quality_tier,
    subtitle_option="none",
    dubbing_option="none",
    translation_enabled=False,
    segment_seconds=None,
    include_retry_buffer=True,
    music_option="none",
    music_item_count=0,
) -> dict:
    base = calculate_video_base_price(
        duration_seconds,
        processing_type,
        quality_tier,
        segment_seconds=segment_seconds,
        include_retry_buffer=include_retry_buffer,
    )
    addon = calculate_video_addon_price(
        duration_seconds,
        subtitle_option,
        dubbing_option,
        translation_enabled,
    )
    music = calculate_music_price(
        duration_seconds=duration_seconds,
        music_option=music_option,
        item_count=music_item_count,
    )
    total = round_video_xu(
        int(base.get("base_video_xu") or 0)
        + int(addon.get("addon_xu") or 0)
        + int(music.get("music_xu") or 0)
    )
    return {
        **base,
        **addon,
        **music,
        "total_xu": total,
        "estimated_vnd": total * int(XU_TO_VND or 100),
        "notes": list(base.get("notes") or []) + list(music.get("music_notes") or []),
    }

def video_duration_seconds_from_payload(payload: dict | None = None, default: int = 0) -> int:
    payload = payload or {}
    for key in ("current_video_duration_seconds", "duration_seconds", "total_duration_seconds", "seconds", "duration"):
        value = payload.get(key)
        if isinstance(value, (int, float)) and float(value) > 0:
            return max(1, int(math.ceil(float(value))))
        match = re.search(r"(\d+(?:\.\d+)?)\s*(giây|second|seconds|sec|s|phút|minute|minutes|min)\b", str(value or ""), re.I)
        if match:
            number = float(match.group(1))
            unit = match.group(2).lower()
            return max(1, int(math.ceil(number * 60 if unit in {"phút", "minute", "minutes", "min"} else number)))
    prompt = " ".join(str(payload.get(key) or "") for key in ("prompt", "original_prompt", "video_prompt", "concept_text"))
    match = re.search(r"(\d+(?:\.\d+)?)\s*(giây|second|seconds|sec|s|phút|minute|minutes|min)\b", prompt, re.I)
    if match:
        number = float(match.group(1))
        unit = match.group(2).lower()
        return max(1, int(math.ceil(number * 60 if unit in {"phút", "minute", "minutes", "min"} else number)))
    return max(1, int(default or VIDEO_AI_DEFAULT_SEGMENT_SECONDS or 8))

def build_video_project(
    user_id,
    source_flow: str,
    payload: dict | None = None,
    finalization: dict | None = None,
) -> dict:
    payload = dict(payload or {})
    finalization_data = video_finalization_defaults() if "video_finalization_defaults" in globals() else {}
    finalization_data.update(dict(finalization or payload.get("video_finalization") or {}))
    created_at = str(payload.get("created_at") or now_text())
    duration = video_duration_seconds_from_payload(payload, VIDEO_AI_DEFAULT_SEGMENT_SECONDS)
    processing = normalize_video_processing_type(
        payload.get("processing_type") or video_processing_type_for_payload(payload)
        if "video_processing_type_for_payload" in globals()
        else payload.get("processing_type") or "ai_text_to_video"
    )
    quality = str(payload.get("quality_tier") or video_quality_from_tier(payload.get("video_tier") or "standard"))
    segment_seconds = max(1, int(payload.get("segment_seconds") or (
        VIDEO_AI_LONG_SEGMENT_SECONDS if processing == "long_ai_video" else VIDEO_AI_DEFAULT_SEGMENT_SECONDS
    )))
    project_seed = f"{user_id}:{source_flow}:{created_at}:{payload.get('package_id') or payload.get('source_job_id') or ''}"
    project_id = str(payload.get("project_id") or ("vproj_" + hashlib.sha256(project_seed.encode("utf-8")).hexdigest()[:16]))
    music_option = str(payload.get("music_option") or finalization_data.get("music_mode") or "none")
    subtitle_option = str(payload.get("subtitle_option") or (
        "subtitle_translated" if finalization_data.get("translation_enabled") and finalization_data.get("subtitle_enabled")
        else "subtitle_original" if finalization_data.get("subtitle_enabled")
        else "none"
    ))
    dubbing_option = str(payload.get("dubbing_option") or (
        "dub_translated" if finalization_data.get("translation_enabled") and finalization_data.get("dub_enabled")
        else "dub_original" if finalization_data.get("dub_enabled") or finalization_data.get("voice_enabled")
        else "none"
    ))
    price_preview = calculate_video_total_price(
        duration,
        processing,
        quality,
        subtitle_option,
        dubbing_option,
        bool(payload.get("translation_enabled") or finalization_data.get("translation_enabled")),
        segment_seconds,
        True,
        music_option,
        int(payload.get("music_item_count") or 0),
    )
    return {
        "project_id": project_id,
        "user_id": str(user_id),
        "source_flow": str(source_flow or payload.get("source_flow") or payload.get("source") or "video_plan")[:80],
        "flow_intent": str(payload.get("flow_intent") or payload.get("intent") or "")[:200],
        "aspect_ratio": str(payload.get("aspect_ratio") or "9:16")[:16],
        "duration_seconds": duration,
        "segment_seconds": segment_seconds,
        "segments": max(1, int(math.ceil(duration / segment_seconds))),
        "processing_type": processing,
        "quality_tier": quality,
        "scenes": list(payload.get("scenes") or [])[:50],
        "script_text": str(payload.get("script_text") or payload.get("original_prompt") or payload.get("prompt") or "")[:4000],
        "caption_text": str(payload.get("caption_text") or payload.get("caption") or "")[:2000],
        "image_prompts": list(payload.get("image_prompts") or [])[:50],
        "video_prompts": list(payload.get("video_prompts") or [])[:50],
        "image_assets": list(payload.get("image_assets") or [])[:50],
        "source_video_assets": list(payload.get("source_video_assets") or [])[:20],
        "music_option": music_option,
        "music_source": str(payload.get("music_source") or finalization_data.get("music_mode") or "")[:80],
        "music_file_id": str(payload.get("music_file_id") or finalization_data.get("music_file_id") or "")[:220],
        "music_prompt": str(payload.get("music_prompt") or finalization_data.get("music_prompt") or "")[:1000],
        "subtitle_option": subtitle_option,
        "dubbing_option": dubbing_option,
        "translation_enabled": bool(payload.get("translation_enabled") or finalization_data.get("translation_enabled")),
        "target_language": str(payload.get("target_language") or finalization_data.get("subtitle_language") or finalization_data.get("voice_language") or "")[:80],
        "voice_style": str(payload.get("voice_style") or finalization_data.get("voice_style") or "natural")[:80],
        "price_preview": price_preview,
        "provider_flags": {
            "video_ai_public": bool(VIDEO_AI_PUBLIC_ENABLED and SHOPAIKEY_PUBLIC_VIDEO_ENABLED),
            "image_to_video": bool(VIDEO_IMAGE_TO_VIDEO_ENABLED),
            "video_to_video": bool(VIDEO_VIDEO_TO_VIDEO_ENABLED),
            "long_render": bool(VIDEO_LONG_RENDER_ENABLED),
            "trend_render": bool(VIDEO_TREND_RENDER_ENABLED),
            "tts": bool(SHOPAIKEY_TTS_ENABLED),
            "music_ai": bool(MUSIC_AI_ENABLED and SHOPAIKEY_MUSIC_ENABLED and SHOPAIKEY_MUSIC_ENDPOINT),
        },
        "status": str(payload.get("status") or "planning")[:40],
        "created_at": created_at,
        "updated_at": now_text(),
    }

def frame_video_effect_is_motion(effect: str = "") -> bool:
    return frame_video_effect_payload(effect).get("token") in {"zoom", "pan", "slide", "random"}

def frame_video_base_price_for_count(count: int = 0) -> int:
    count = max(2, int(count or 0))
    if count <= 5:
        return int(FRAME_VIDEO_BASE_2_5_XU or 0)
    if count <= 10:
        return int(FRAME_VIDEO_BASE_6_10_XU or 0)
    if count <= 20:
        return int(FRAME_VIDEO_BASE_11_20_XU or 0)
    return int(FRAME_VIDEO_BASE_11_20_XU or 0) + ((count - 20) * int(FRAME_VIDEO_EXTRA_IMAGE_XU or 0))

def frame_video_duration_extra_for_state(state: dict) -> int:
    token = str((state or {}).get("duration") or "standard").strip().lower()
    count = len((state or {}).get("photos") or [])
    if token == "fast":
        return max(0, int(count or 0) - 5) * int(FRAME_VIDEO_FAST_EXTRA_PER_IMAGE_AFTER_5_XU or 0)
    if token == "slow":
        return int(FRAME_VIDEO_DURATION_SLOW_EXTRA_XU or 0)
    if token == "standard":
        return int(FRAME_VIDEO_DURATION_STANDARD_EXTRA_XU or 0)
    return 0

def frame_video_effect_extra_for_state(state: dict) -> int:
    effect = frame_video_effect_payload((state or {}).get("effect") or "fade").get("token") or "fade"
    if effect == "random":
        return int(FRAME_VIDEO_RANDOM_EFFECT_EXTRA_XU or 0)
    if effect in {"zoom", "pan", "slide"}:
        return int(FRAME_VIDEO_MOTION_EFFECT_EXTRA_XU or 0)
    return 0

def frame_video_audio_extra_for_state(state: dict) -> int:
    music_choice = str((state or {}).get("music_choice") or "").strip().lower()
    voice_choice = str((state or {}).get("voice_choice") or "").strip().lower()
    if (music_choice and music_choice not in {"skip", "none"} and bool((state or {}).get("music_merge_enabled"))) or (
        voice_choice and voice_choice not in {"skip", "none"} and bool((state or {}).get("voice_merge_enabled"))
    ):
        return int(FRAME_VIDEO_MUSIC_PRICE_XU or 0)
    return 0

def frame_video_price_breakdown(state: dict) -> dict:
    count = len((state or {}).get("photos") or [])
    duration_seconds = frame_video_estimated_output_seconds(state)
    pricing = calculate_video_total_price(
        duration_seconds,
        "local_frame_video",
        "fast",
        (state or {}).get("current_video_subtitle_option") or "none",
        (state or {}).get("current_video_dubbing_option") or "none",
        bool((state or {}).get("translation_enabled")),
        segment_seconds=duration_seconds,
    )
    return {
        "image_count": max(2, int(count or 0)),
        "duration_seconds": int(math.ceil(duration_seconds or 0)),
        "base": int(pricing.get("base_video_xu") or 0),
        "duration_extra": 0,
        "effect_extra": 0,
        "audio_extra": 0,
        "subtitle_xu": int(pricing.get("subtitle_xu") or 0),
        "dubbing_xu": int(pricing.get("dubbing_xu") or 0),
        "addon_xu": int(pricing.get("addon_xu") or 0),
        "estimated_vnd": int(pricing.get("estimated_vnd") or 0),
        "total": int(pricing.get("total_xu") or 0),
    }

def frame_video_status_payload() -> dict:
    worker = local_worker_status_payload()
    ffmpeg_path = frame_video_ffmpeg_path()
    return {
        "enabled": bool(FRAME_VIDEO_ENABLED),
        "public_enabled": bool(FRAME_VIDEO_PUBLIC_ENABLED),
        "direct_render_enabled": bool(FRAME_VIDEO_DIRECT_RENDER_ENABLED),
        "require_local_worker": bool(FRAME_VIDEO_REQUIRE_LOCAL_WORKER),
        "price_xu": int(LOCAL_FRAME_VIDEO_MIN_XU or 0),
        "price_per_second_xu": int(LOCAL_FRAME_VIDEO_XU_PER_SECOND or 0),
        "basic_price_xu": int(FRAME_VIDEO_BASIC_PRICE_XU or 0),
        "effect_price_xu": int(FRAME_VIDEO_EFFECT_PRICE_XU or 0),
        "music_price_xu": int(FRAME_VIDEO_MUSIC_PRICE_XU or 0),
        "base_2_5_xu": int(FRAME_VIDEO_BASE_2_5_XU or 0),
        "base_6_10_xu": int(FRAME_VIDEO_BASE_6_10_XU or 0),
        "base_11_20_xu": int(FRAME_VIDEO_BASE_11_20_XU or 0),
        "extra_image_xu": int(FRAME_VIDEO_EXTRA_IMAGE_XU or 0),
        "fast_extra_per_image_after_5_xu": int(FRAME_VIDEO_FAST_EXTRA_PER_IMAGE_AFTER_5_XU or 0),
        "duration_standard_extra_xu": int(FRAME_VIDEO_DURATION_STANDARD_EXTRA_XU or 0),
        "duration_slow_extra_xu": int(FRAME_VIDEO_DURATION_SLOW_EXTRA_XU or 0),
        "motion_effect_extra_xu": int(FRAME_VIDEO_MOTION_EFFECT_EXTRA_XU or 0),
        "random_effect_extra_xu": int(FRAME_VIDEO_RANDOM_EFFECT_EXTRA_XU or 0),
        "max_images": int(FRAME_VIDEO_MAX_IMAGES or 20),
        "max_output_seconds": int(FRAME_VIDEO_MAX_OUTPUT_SECONDS or 90),
        "max_input_mb": int(FRAME_VIDEO_MAX_INPUT_MB or 50),
        "max_render_seconds": int(FRAME_VIDEO_MAX_RENDER_SECONDS or 180),
        "max_concurrent_jobs": int(FRAME_VIDEO_MAX_CONCURRENT_JOBS or 1),
        "active_jobs": int(frame_video_active_jobs_count()),
        "ttl_seconds": int(FRAME_VIDEO_STATE_TTL_SECONDS or 600),
        "ffmpeg_configured": bool(ffmpeg_path),
        "ffmpeg_path_source": "PATH" if shutil.which("ffmpeg") else ("LOCAL_FFMPEG_PATH" if ffmpeg_path else "missing"),
        "railway_runtime": bool(is_railway_runtime()),
        "local_worker_enabled": bool(worker.get("enabled")),
        "local_worker_poll_enabled": bool(worker.get("poll_enabled")),
        "local_worker_connected": bool(worker.get("connected")),
        "local_worker_ffmpeg_path": str(worker.get("ffmpeg_path") or ""),
        "last_error": get_frame_video_last_error(),
    }

def frame_video_render_type(state: dict) -> str:
    effect = frame_video_effect_payload((state or {}).get("effect") or "fade").get("token") or "fade"
    music_choice = str((state or {}).get("music_choice") or "").strip().lower()
    voice_choice = str((state or {}).get("voice_choice") or "").strip().lower()
    if (
        (music_choice and music_choice not in {"skip", "none"} and bool((state or {}).get("music_merge_enabled")))
        or (voice_choice and voice_choice not in {"skip", "none"} and bool((state or {}).get("voice_merge_enabled")))
    ):
        return "music"
    if effect in {"zoom", "pan", "slide", "random"}:
        return "effect"
    return "basic"

def frame_video_price_for_state(state: dict) -> int:
    return int(frame_video_price_breakdown(state).get("total") or 0)

def set_frame_video_last_error(detail: str = "") -> None:
    global FRAME_VIDEO_LAST_ERROR
    FRAME_VIDEO_LAST_ERROR = sanitize_log_text(str(detail or ""))[:300]
    if FRAME_VIDEO_LAST_ERROR:
        try:
            set_system_setting("frame_video_last_error", FRAME_VIDEO_LAST_ERROR, note="Frame video guard/runtime error")
        except Exception:
            pass

def get_frame_video_last_error() -> str:
    try:
        stored = get_system_setting("frame_video_last_error", "")
        if stored:
            return str(stored or "")[:300]
    except Exception:
        pass
    return str(FRAME_VIDEO_LAST_ERROR or "")[:300]

def clear_frame_video_last_error(updated_by="") -> None:
    global FRAME_VIDEO_LAST_ERROR
    FRAME_VIDEO_LAST_ERROR = ""
    set_system_setting("frame_video_last_error", "", note="Frame video last error cleared", updated_by=updated_by)

def frame_video_active_jobs_count() -> int:
    active_statuses = {"queued", "waiting_worker", "rendering"}
    return sum(1 for job in FRAME_VIDEO_JOBS.values() if str(job.get("status") or "").lower() in active_statuses)

def frame_video_total_input_mb(state: dict) -> float:
    total_bytes = 0
    for photo in (state or {}).get("photos") or []:
        try:
            total_bytes += int(photo.get("file_size") or 0)
        except Exception:
            continue
    return round(total_bytes / (1024 * 1024), 2)

def frame_video_estimated_output_seconds(state: dict) -> float:
    duration = frame_video_duration_payload((state or {}).get("duration") or "standard")
    count = len((state or {}).get("photos") or [])
    return round(float(duration.get("seconds") or 0) * max(0, int(count or 0)), 2)

def frame_video_worker_connected() -> bool:
    try:
        worker = local_worker_status_payload()
        return bool(worker.get("enabled") and worker.get("poll_enabled") and worker.get("token_configured") and worker.get("connected"))
    except Exception:
        return False

def frame_video_maintenance_text() -> str:
    return "🎞 Công cụ ghép ảnh thành video đang bảo trì hoặc cần worker xử lý. TOAN AAS chưa trừ Xu. Vui lòng thử lại sau."

def frame_video_runtime_guard(state: dict, user_id=0) -> dict:
    photos = list((state or {}).get("photos") or [])
    image_count = len(photos)
    total_input_mb = frame_video_total_input_mb(state)
    output_seconds = frame_video_estimated_output_seconds(state)
    worker_connected = frame_video_worker_connected()
    active_jobs = frame_video_active_jobs_count()

    if not FRAME_VIDEO_ENABLED:
        return {"ok": False, "action": "blocked", "reason": "disabled", "message": frame_video_maintenance_text(), "worker_connected": worker_connected}
    if not FRAME_VIDEO_PUBLIC_ENABLED and not is_admin_user(user_id):
        return {"ok": False, "action": "blocked", "reason": "public_off", "message": frame_video_maintenance_text(), "worker_connected": worker_connected}
    if image_count < 2:
        return {"ok": False, "action": "blocked", "reason": "not_enough_images", "message": "⚠️ Cần ít nhất 2 ảnh để ghép thành video. Bot chưa trừ Xu.", "worker_connected": worker_connected}
    if image_count > int(FRAME_VIDEO_MAX_IMAGES or 20):
        return {
            "ok": False,
            "action": "blocked",
            "reason": "too_many_images",
            "message": f"⚠️ Số ảnh vượt giới hạn {int(FRAME_VIDEO_MAX_IMAGES or 20)} ảnh. Bot chưa trừ Xu.",
            "worker_connected": worker_connected,
        }
    if total_input_mb and total_input_mb > float(FRAME_VIDEO_MAX_INPUT_MB or 50):
        return {
            "ok": False,
            "action": "blocked",
            "reason": "input_too_large",
            "message": f"⚠️ Bộ ảnh quá lớn ({total_input_mb} MB). Giới hạn hiện tại là {int(FRAME_VIDEO_MAX_INPUT_MB or 50)} MB. Bot chưa trừ Xu.",
            "worker_connected": worker_connected,
        }
    if output_seconds > float(FRAME_VIDEO_MAX_OUTPUT_SECONDS or 90):
        return {
            "ok": False,
            "action": "blocked",
            "reason": "output_too_long",
            "message": f"⚠️ Video dự kiến dài {output_seconds}s, vượt giới hạn {int(FRAME_VIDEO_MAX_OUTPUT_SECONDS or 90)}s. Bot chưa trừ Xu.",
            "worker_connected": worker_connected,
        }
    if active_jobs >= int(FRAME_VIDEO_MAX_CONCURRENT_JOBS or 1):
        return {
            "ok": False,
            "action": "blocked",
            "reason": "concurrency_limit",
            "message": "Bạn đang có tác vụ ghép video đang xử lý. Vui lòng chờ kết quả, không cần gửi lại lệnh.",
            "worker_connected": worker_connected,
        }
    if FRAME_VIDEO_REQUIRE_LOCAL_WORKER and not worker_connected:
        return {"ok": False, "action": "blocked", "reason": "worker_unavailable", "message": frame_video_maintenance_text(), "worker_connected": worker_connected}
    if not FRAME_VIDEO_DIRECT_RENDER_ENABLED:
        if worker_connected:
            return {"ok": False, "action": "worker_queue", "reason": "direct_render_disabled", "message": "", "worker_connected": worker_connected}
        return {"ok": False, "action": "blocked", "reason": "direct_render_disabled", "message": frame_video_maintenance_text(), "worker_connected": worker_connected}
    if is_railway_runtime() and not FRAME_VIDEO_DIRECT_RENDER_ENABLED:
        return {"ok": False, "action": "blocked", "reason": "railway_direct_render_disabled", "message": frame_video_maintenance_text(), "worker_connected": worker_connected}
    return {"ok": True, "action": "direct_render", "reason": "ok", "message": "", "worker_connected": worker_connected}

def frame_video_worker_payload(frame_job_id: str, user_id, chat_id, state: dict, charged_amount: int = 0) -> str:
    ratio = frame_video_ratio_payload((state or {}).get("ratio") or "9x16")
    duration = frame_video_duration_payload((state or {}).get("duration") or "standard")
    effect = frame_video_effect_payload((state or {}).get("effect") or "fade")
    photos = []
    for item in list((state or {}).get("photos") or [])[:FRAME_VIDEO_MAX_IMAGES]:
        photos.append({
            "file_id": str(item.get("file_id") or ""),
            "file_size": int(item.get("file_size") or 0),
        })
    payload = {
        "frame_job_id": str(frame_job_id or ""),
        "user_id": str(user_id or ""),
        "chat_id": str(chat_id or ""),
        "charged_amount": int(charged_amount or 0),
        "photos": photos,
        "ratio": str((state or {}).get("ratio") or "9x16"),
        "width": int(ratio.get("width") or 720),
        "height": int(ratio.get("height") or 1280),
        "duration": str((state or {}).get("duration") or "standard"),
        "seconds_per_image": float(duration.get("seconds") or 1.5),
        "effect": str(effect.get("token") or "fade"),
        "max_render_seconds": int(FRAME_VIDEO_MAX_RENDER_SECONDS or 180),
        "caption": (
            "✅ Đã ghép ảnh thành video.\n"
            f"Job: {str(frame_job_id or '')}\n"
            f"Đã trừ: {int(charged_amount or 0)} Xu.\n"
            "Video được render bằng Local Worker."
        ),
    }
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":"))

def create_frame_video_job(user_id, chat_id, state: dict, charged_amount: int = 0, status: str = "queued") -> str:
    global FRAME_VIDEO_JOB_SEQ
    FRAME_VIDEO_JOB_SEQ += 1
    job_id = f"fv{int(time.time())}{FRAME_VIDEO_JOB_SEQ:04d}"
    breakdown = frame_video_price_breakdown(state)
    FRAME_VIDEO_JOBS[job_id] = {
        "job_id": job_id,
        "user_id": str(user_id or ""),
        "chat_id": str(chat_id or ""),
        "status": str(status or "queued"),
        "created_at": now_text(),
        "updated_at": now_text(),
        "image_count": int(breakdown.get("image_count") or 0),
        "ratio": str((state or {}).get("ratio") or "9x16"),
        "duration": str((state or {}).get("duration") or "standard"),
        "effect": str((state or {}).get("effect") or "fade"),
        "charged_amount": int(charged_amount or 0),
        "price_breakdown": breakdown,
        "detail": "",
    }
    return job_id

def update_frame_video_job(job_id: str, **kwargs) -> dict:
    job = FRAME_VIDEO_JOBS.get(str(job_id or "")) or {}
    if not job:
        return {}
    job.update(kwargs)
    job["updated_at"] = now_text()
    FRAME_VIDEO_JOBS[str(job_id)] = job
    return job

def frame_video_job_for_user(job_id: str, user_id=0) -> dict:
    job = FRAME_VIDEO_JOBS.get(str(job_id or "")) or {}
    if not job:
        return {}
    if is_admin_user(user_id) or str(job.get("user_id") or "") == str(user_id or ""):
        return job
    return {}

def frame_video_job_status_text(job: dict) -> str:
    if not job:
        return "⚠️ Không tìm thấy job ghép video này."
    ratio = frame_video_ratio_payload(job.get("ratio") or "9x16")
    duration = frame_video_duration_payload(job.get("duration") or "standard")
    effect = frame_video_effect_payload(job.get("effect") or "fade")
    detail = str(job.get("detail") or "").strip()
    lines = [
        "🎞 <b>Trạng thái ghép ảnh thành video</b>",
        "",
        f"• Job: <code>{html.escape(str(job.get('job_id') or '-'))}</code>",
        f"• Trạng thái: <code>{html.escape(str(job.get('status') or '-'))}</code>",
        f"• Số ảnh: <code>{int(job.get('image_count') or 0)}</code>",
        f"• Tỷ lệ: <code>{html.escape(str(ratio.get('label') or '-'))}</code>",
        f"• Thời lượng: <code>{html.escape(str(duration.get('label') or '-'))}</code>",
        f"• Hiệu ứng: <code>{html.escape(str(effect.get('label') or '-'))}</code>",
        f"• Xu: <code>{str(int(job.get('charged_amount') or 0)) + ' Xu đã trừ' if int(job.get('charged_amount') or 0) > 0 else 'chưa trừ'}</code>",
        f"• Cập nhật: <code>{html.escape(str(job.get('updated_at') or '-'))}</code>",
    ]
    if detail:
        lines.append(f"• Ghi chú: <code>{html.escape(detail[:240])}</code>")
    return "\n".join(lines)

def frame_video_job_status_keyboard(job_id: str) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("🔄 Kiểm tra trạng thái ghép video", callback_data=f"framevideo|status|{str(job_id or '')}")],
        [InlineKeyboardButton("🏠 Menu chính", callback_data="framevideo|main")],
    ])

def set_frame_video_state(user_id, state: dict) -> dict:
    now_ts = time.time()
    state = dict(state or {})
    state["type"] = "frame_video"
    state.setdefault("created_at_ts", now_ts)
    state["updated_at_ts"] = now_ts
    state["expires_at_ts"] = now_ts + FRAME_VIDEO_STATE_TTL_SECONDS
    USER_PENDING[frame_video_pending_key(user_id)] = state
    return state

def get_frame_video_state(user_id) -> dict:
    key = frame_video_pending_key(user_id)
    state = USER_PENDING.get(key) or {}
    if not isinstance(state, dict) or state.get("type") != "frame_video":
        if state:
            USER_PENDING.pop(key, None)
        return {}
    if float(state.get("expires_at_ts") or 0) < time.time():
        USER_PENDING.pop(key, None)
        return {}
    return state

def clear_frame_video_state(user_id) -> bool:
    frame_cleared = USER_PENDING.pop(frame_video_pending_key(user_id), None) is not None
    addon_cleared = USER_PENDING.pop(f"video_addon:{user_id}", None) is not None
    return bool(frame_cleared or addon_cleared)

