def frame_video_ffmpeg_filter(width: int, height: int, seconds_per_image: float, effect: str) -> str:
    base = f"scale={width}:{height}:force_original_aspect_ratio=increase,crop={width}:{height},setsar=1"
    effect = frame_video_effect_payload(effect).get("token") or "none"
    if effect == "fade":
        fade_out_start = max(0.0, float(seconds_per_image or 0) - 0.25)
        return f"{base},fade=t=in:st=0:d=0.25,fade=t=out:st={fade_out_start:.2f}:d=0.25,format=yuv420p"
    if effect == "zoom":
        frames = max(1, int(float(seconds_per_image or 0) * 30))
        zoom_w = width * 2
        zoom_h = height * 2
        return (
            f"scale={zoom_w}:{zoom_h}:force_original_aspect_ratio=increase,crop={zoom_w}:{zoom_h},"
            f"zoompan=z='min(zoom+0.0015,1.08)':d={frames}:"
            f"x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':s={width}x{height}:fps=30,"
            "setsar=1,format=yuv420p"
        )
    if effect == "pan":
        frames = max(1, int(float(seconds_per_image or 0) * 30))
        pan_w = max(width + 2, int(width * 1.12))
        return (
            f"scale={pan_w}:{height}:force_original_aspect_ratio=increase,crop={pan_w}:{height},"
            f"zoompan=z=1:d={frames}:x='(iw-ow)*on/{max(frames - 1, 1)}':y='(ih-oh)/2':s={width}x{height}:fps=30,"
            "setsar=1,format=yuv420p"
        )
    if effect == "slide":
        frames = max(1, int(float(seconds_per_image or 0) * 30))
        slide_w = max(width + 2, int(width * 1.18))
        return (
            f"scale={slide_w}:{height}:force_original_aspect_ratio=increase,crop={slide_w}:{height},"
            f"zoompan=z=1:d={frames}:x='(iw-ow)*(1-on/{max(frames - 1, 1)})':y='(ih-oh)/2':s={width}x{height}:fps=30,"
            "setsar=1,format=yuv420p"
        )
    return f"{base},format=yuv420p"

def frame_video_concat_path(path: str) -> str:
    return str(path or "").replace("\\", "/").replace("'", "'\\''")

async def render_frame_video_paths(
    image_paths: list[str],
    output_path: str,
    width: int,
    height: int,
    seconds_per_image: float,
    effect: str,
    ffmpeg_path: str = "",
) -> tuple[bool, str]:
    ffmpeg = ffmpeg_path or frame_video_ffmpeg_path()
    if not ffmpeg:
        return False, "ffmpeg_missing"
    if len(image_paths or []) < 2:
        return False, "not_enough_images"
    clips: list[str] = []
    directory = os.path.dirname(output_path) or tempfile.gettempdir()
    effect_token = frame_video_effect_payload(effect).get("token") or "fade"
    random_cycle = ["fade", "zoom", "pan", "slide"]
    for idx, image_path in enumerate(image_paths[:FRAME_VIDEO_MAX_IMAGES], start=1):
        clip_path = os.path.join(directory, f"frame_video_clip_{idx}.mp4")
        clip_effect = random_cycle[(idx - 1) % len(random_cycle)] if effect_token == "random" else effect_token
        vf = frame_video_ffmpeg_filter(width, height, seconds_per_image, clip_effect)
        cmd = [
            ffmpeg, "-y",
            "-loop", "1",
            "-t", f"{float(seconds_per_image):.2f}",
            "-i", image_path,
            "-vf", vf,
            "-r", "30",
            "-an",
            "-c:v", "libx264",
            "-preset", "veryfast",
            "-pix_fmt", "yuv420p",
            "-movflags", "+faststart",
            clip_path,
        ]
        ok, detail = await run_ffmpeg_command(cmd, timeout=FRAME_VIDEO_RENDER_TIMEOUT_SECONDS)
        if not ok or not os.path.exists(clip_path):
            return False, f"clip_{idx}:{detail}"
        clips.append(clip_path)
    concat_path = os.path.join(directory, "frame_video_concat.txt")
    with open(concat_path, "w", encoding="utf-8") as f:
        for clip in clips:
            f.write(f"file '{frame_video_concat_path(clip)}'\n")
    concat_cmd = [
        ffmpeg, "-y",
        "-f", "concat",
        "-safe", "0",
        "-i", concat_path,
        "-c", "copy",
        "-movflags", "+faststart",
        output_path,
    ]
    ok, detail = await run_ffmpeg_command(concat_cmd, timeout=FRAME_VIDEO_RENDER_TIMEOUT_SECONDS)
    if not ok or not os.path.exists(output_path):
        return False, f"concat:{detail}"
    return True, "ok"

async def render_frame_video_from_state(context: ContextTypes.DEFAULT_TYPE, state: dict, output_path: str, tmpdir: str) -> tuple[bool, str]:
    ratio = frame_video_ratio_payload(state.get("ratio") or "9x16")
    duration = frame_video_duration_payload(state.get("duration") or "standard")
    effect = frame_video_effect_payload(state.get("effect") or "fade")
    image_paths: list[str] = []
    for idx, photo in enumerate((state.get("photos") or [])[:FRAME_VIDEO_MAX_IMAGES], start=1):
        file_id = str(photo.get("file_id") or "")
        path = os.path.join(tmpdir, f"frame_input_{idx}.jpg")
        if file_id:
            await telegram_file_to_path(context, file_id, path)
            image_paths.append(path)
            continue
        image_url = str(photo.get("image_url") or photo.get("url") or "").strip()
        if image_url:
            await url_to_path(image_url, path, max_bytes=10 * 1024 * 1024)
            image_paths.append(path)
    return await render_frame_video_paths(
        image_paths,
        output_path,
        int(ratio["width"]),
        int(ratio["height"]),
        float(duration["seconds"]),
        str(effect["token"]),
    )

async def handle_frame_video_photo(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.effective_user or not update.message or not getattr(update.message, "photo", None):
        return False
    uid = update.effective_user.id
    state = get_frame_video_state(uid)
    if not state or state.get("step") != "collect":
        return False
    photos = list(state.get("photos") or [])
    if len(photos) >= FRAME_VIDEO_MAX_IMAGES:
        await update.message.reply_text(
            f"Đã đủ {FRAME_VIDEO_MAX_IMAGES}/{FRAME_VIDEO_MAX_IMAGES} ảnh. Vui lòng bấm ✅ Xong để tiếp tục.",
            reply_markup=frame_video_collect_keyboard(),
        )
        return True
    photo = update.message.photo[-1]
    file_id = str(photo.file_id or "")
    if file_id and file_id not in {str(item.get("file_id") or "") for item in photos}:
        photos.append({"file_id": file_id, "file_size": int(getattr(photo, "file_size", 0) or 0)})
    state["photos"] = photos[:FRAME_VIDEO_MAX_IMAGES]
    set_frame_video_state(uid, state)
    await update.message.reply_text(frame_video_collect_text(len(state["photos"])), reply_markup=frame_video_collect_keyboard())
    return True

async def render_video_with_audio(update: Update, context: ContextTypes.DEFAULT_TYPE, video_info: dict, audio_info: dict, mode: str):
    ffmpeg = shutil.which("ffmpeg")
    if not ffmpeg:
        return await update.message.reply_text("⚠️ Server chưa có ffmpeg. Admin cần cài ffmpeg để ghép nhạc/voice vào video. Bot chưa trừ Xu.")
    if not video_info:
        return await update.message.reply_text("⚠️ Chưa có video. Hãy gửi video hoặc reply video rồi dùng lệnh này. Bot chưa trừ Xu.")
    if not audio_info:
        return await update.message.reply_text("⚠️ Chưa có audio/nhạc. Hãy chọn nhạc bằng /select_music hoặc gửi audio rồi dùng lại lệnh. Bot chưa trừ Xu.")
    with tempfile.TemporaryDirectory() as tmpdir:
        video_path = await materialize_media_source(context, video_info, tmpdir, ".mp4")
        audio_path = await materialize_media_source(context, audio_info, tmpdir, ".mp3")
        out_path = os.path.join(tmpdir, f"toan_aas_{mode}.mp4")
        cmd = [
            ffmpeg, "-y",
            "-i", video_path,
            "-i", audio_path,
            "-map", "0:v:0",
            "-map", "1:a:0",
            "-c:v", "copy",
            "-c:a", "aac",
            "-shortest",
            out_path,
        ]
        ok, detail = await run_ffmpeg_command(cmd)
        if not ok or not os.path.exists(out_path):
            safe_detail = html.escape(str(detail or "ffmpeg_failed")[:300])
            return await update.message.reply_text(
                "❌ Render video chưa thành công trong admin test.\n"
                f"Admin detail: <code>{safe_detail}</code>\n\n"
                "Bot chưa trừ Xu.",
                parse_mode="HTML",
            )
        caption = "✅ Đã ghép nhạc vào video." if mode == "add_music" else "✅ Đã ghép voice/audio vào video."
        with open(out_path, "rb") as f:
            await context.bot.send_video(chat_id=update.effective_chat.id, video=f, caption=f"{caption}\nBot chưa trừ Xu trong admin test.")

async def render_image_music_video(update: Update, context: ContextTypes.DEFAULT_TYPE, image_info: dict, audio_info: dict):
    ffmpeg = shutil.which("ffmpeg")
    if not ffmpeg:
        return await update.message.reply_text("⚠️ Server chưa có ffmpeg. Admin cần cài ffmpeg để tạo video từ ảnh + nhạc. Bot chưa trừ Xu.")
    if not image_info:
        return await update.message.reply_text("⚠️ Chưa có ảnh. Hãy gửi ảnh hoặc reply ảnh rồi dùng /image_to_music_video. Bot chưa trừ Xu.")
    with tempfile.TemporaryDirectory() as tmpdir:
        image_path = await materialize_media_source(context, image_info, tmpdir, ".jpg")
        out_path = os.path.join(tmpdir, "toan_aas_image_music.mp4")
