def promo_code_status_message(status: str) -> str:
    messages = {
        "not_found": "Mã không hợp lệ, hết lượt, hết hạn hoặc chưa đủ điều kiện.",
        "inactive": "Mã đang tạm khóa.",
        "disabled": "Mã đang tạm khóa.",
        "sold_out": "Mã đã hết lượt dùng.",
        "expired": "Mã đã hết hạn.",
        "not_started": "Mã chưa đến thời gian áp dụng.",
        "already_applied": "Mã này đã được dùng cho tài khoản của bạn.",
        "already_used": "Mã này đã được dùng đủ lượt cho tài khoản của bạn.",
        "period_already_used": "Mã này đã được dùng trong kỳ hiện tại. Hãy chờ kỳ reset tiếp theo.",
        "min_amount_not_met": "Gói 10k/20k không áp dụng mã ưu đãi. Vui lòng chọn gói từ 50k trở lên.",
        "min_amount": "Mệnh giá nạp chưa đạt số tiền tối thiểu của mã.",
        "first_topup_only": "Mã FIRST30 chỉ dành cho lần nạp đầu tiên.",
        "second_topup_only": "Mã SECOND15 chỉ dành cho lần nạp thứ 2.",
        "owner_only": "Mã ưu đãi cá nhân này chỉ dùng cho đúng tài khoản được cấp.",
    }
    return messages.get(status, "Mã không hợp lệ, hết lượt, hết hạn hoặc chưa đủ điều kiện.")

async def _cmd_promo_impl(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    record_usage_event(
        uid,
        username=update.effective_user.username or update.effective_user.first_name or "",
        event_type="command",
        tool_name="promo",
        command="/promo",
        status="requested" if context.args else "guide",
        detail=normalize_promo_code(context.args[0]) if context.args else "",
    )
    if not context.args:
        summary = get_user_promo_summary(uid)
        rows = summary.get("rows") or []
        pending = summary.get("pending") or {}
        lines = [
            "🎁 <b>Mã ưu đãi TOAN AAS</b>",
            "",
            "Nhập mã được admin công bố:",
            "<code>/promo FIRST30</code>",
            "<code>/promo WEEKLY10</code>",
            "",
            "Xem ưu đãi đang có: <code>/khuyenmai</code>",
            "Xem mã cá nhân của bạn: <code>/my_promos</code>",
            "",
            "<b>Chính sách:</b>",
            "• Ưu đãi áp dụng cho đơn nạp từ 50k",
            "• Gói 10k/20k chỉ để thử nghiệm",
            "• Mỗi đơn chỉ áp dụng 1 mã",
            "• Không cộng dồn mã",
            "• Bonus Xu dịch vụ chỉ cộng sau khi thanh toán/duyệt bill thành công",
        ]
        if pending.get("promo"):
            lines.extend([
                "",
                f"🎫 Mã đang chờ áp dụng: <code>{html.escape(pending['promo']['code'])}</code>",
                "Nếu nhập mã khác, mã mới sẽ thay mã này.",
            ])
        if rows:
            lines.append("")
            lines.append("<b>Mã gần đây</b>")
            for row in rows:
                code, status, order_code, bonus_xu, created_at, applied_at, min_amount, max_uses, used_count, promo_type, value, max_bonus_xu, note = row
                order_part = f" | order {html.escape(str(order_code))}" if order_code else ""
                label = promo_public_label({"promo_type": promo_type, "value": value, "bonus_xu": bonus_xu})
                lines.append(
                    f"• <code>{html.escape(str(code))}</code>: <code>{html.escape(str(status))}</code>"
                    f" | {html.escape(label)}{order_part}"
                )
        return await update.message.reply_text("\n".join(lines), parse_mode="HTML")

    code = context.args[0]
    conn = db_connect()
    try:
        promo = get_promo_code_dict(conn, code)
    finally:
        conn.close()
    if promo and is_gift_promo(promo):
        ok, status, gift_info = redeem_gift_code(uid, code)
        if ok:
            return await update.message.reply_text(
                "✅ <b>Bạn đã nhận quà TOAN AAS</b>\n\n"
                f"• Mã: <code>{html.escape(gift_info.get('code') or normalize_promo_code(code))}</code>\n"
                f"• Xu dịch vụ nhận: <b>+{int(gift_info.get('xu') or 0)} Xu</b>\n"
                f"• Số dư mới: <b>{int(gift_info.get('balance') or 0)} Xu dịch vụ</b>",
                parse_mode="HTML",
            )
        if status == "assignment_required":
            request_status = await notify_admin_beta_gift_request(update, context, code)
            message = (
                gift_beta_request_pending_message(update.effective_user, code)
                if request_status == "pending"
                else gift_needs_assignment_message(update.effective_user, code)
            )
            return await update.message.reply_text(
                message,
                parse_mode="HTML",
                reply_markup=beta_gift_support_keyboard(),
            )
        if status == "already_applied":
            return await update.message.reply_text(
                "ℹ️ Mã quà tặng này đã được nhận trên tài khoản của bạn, hệ thống không cộng trùng.",
                parse_mode="HTML",
            )
        return await update.message.reply_text(
            "❌ Mã quà tặng không hợp lệ, đã hết lượt hoặc chưa được kích hoạt.\n\n"
            f"Lý do: <code>{html.escape(status)}</code>",
            parse_mode="HTML",
        )

    ok, status, info = activate_promo_for_user(uid, code)
    norm_code = html.escape(info.get("code") or normalize_promo_code(code))
    if ok and status in {"activated", "already_pending", "replaced"}:
        replaced = info.get("replaced_code") or ""
        replaced_line = (
            f"Đã thay mã <code>{html.escape(replaced)}</code> bằng <code>{norm_code}</code>. "
            "Mỗi đơn chỉ áp dụng 1 mã, không cộng dồn.\n\n"
            if status == "replaced" and replaced else ""
        )
        return await update.message.reply_text(
            "✅ <b>Đã lưu mã ưu đãi</b>\n\n"
            f"{replaced_line}"
            f"• Mã: <code>{norm_code}</code>\n"
            f"• Ưu đãi: <b>{html.escape(promo_public_label(info))}</b> khi nạp thành công\n"
            f"• Áp dụng cho đơn nạp từ <b>{promo_min_amount(info):,}đ</b> trở lên\n"
            f"• Mã đang chờ dùng đến: <code>{html.escape(info.get('expires_at') or '-')}</code>\n"
            "• Mỗi đơn chỉ áp dụng 1 mã\n"
            "• Không cộng dồn mã khác\n"
            "• Có thể cộng với Launch Bonus nếu mệnh giá đó còn lần đầu mua\n"
            "• Áp dụng cho lần nạp tiếp theo nếu đủ điều kiện\n\n"
            "Dùng <code>/naptien</code> để mua/nạp Xu dịch vụ.",
            parse_mode="HTML",
        )
    return await update.message.reply_text(
        "❌ " + html.escape(promo_code_status_message(status)) + "\n\n"
        "Xem các ưu đãi gợi ý: <code>/khuyenmai</code>",
        parse_mode="HTML",
    )

async def cmd_promo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    log_command_received("promo", update)
    try:
        return await _cmd_promo_impl(update, context)
    except Exception as e:
        logger.error(
            "cmd_promo failed\n%s",
            sanitize_log_text("".join(traceback.format_exception(type(e), e, e.__traceback__)))[:4000],
        )
        user_text = (
            "❌ Mã ưu đãi đang lỗi xử lý tạm thời. Admin đã được ghi log để kiểm tra.\n\n"
            "Bạn có thể thử lại sau hoặc xem ưu đãi gợi ý: <code>/khuyenmai</code>"
        )
        if update.effective_user and is_admin_user(update.effective_user.id):
            user_text += f"\n\n<code>{html.escape(type(e).__name__)}: {html.escape(sanitize_log_text(str(e))[:800])}</code>"
        await update.message.reply_text(user_text, parse_mode="HTML")
        if ADMIN_ID:
            try:
                await context.bot.send_message(
                    chat_id=int(ADMIN_ID),
                    text=(
                        "🚨 <b>PROMO COMMAND ERROR</b>\n\n"
                        f"• User: <code>{html.escape(str(update.effective_user.id if update.effective_user else '-'))}</code>\n"
                        f"• Error: <code>{html.escape(type(e).__name__)}: {html.escape(sanitize_log_text(str(e))[:1200])}</code>"
                    ),
                    parse_mode="HTML",
                )
            except Exception:
                pass

