async def cmd_trial_bonus_status(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    conn = db_connect()
    try:
        total_granted = sql_scalar(conn, "SELECT COUNT(*) FROM trial_bonus_claims WHERE status='granted'", default=0) or 0
        total_blocked_user = sql_scalar(conn, "SELECT COUNT(*) FROM trial_bonus_claims WHERE status='blocked_duplicate_user'", default=0) or 0
        rows = conn.execute(
            """SELECT telegram_user_id, claim_source, bonus_amount, status, created_at, reason
               FROM trial_bonus_claims
               ORDER BY id DESC
               LIMIT 5"""
        ).fetchall()
    finally:
        conn.close()
    lines = [
        "🎁 <b>Trial Bonus Anti-Spam Status</b>",
        "",
        "Scope: <code>chỉ áp dụng 200 Xu miễn phí, không áp dụng mệnh giá nạp trả phí/promo trả phí</code>",
        f"• Enabled: <code>{'yes' if TRIAL_BONUS_ENABLED else 'no'}</code>",
        f"• Amount: <code>{int(TRIAL_BONUS_AMOUNT or 0)} Xu</code>",
        f"• Require IP: <code>{'yes' if TRIAL_BONUS_REQUIRE_IP else 'no'}</code>",
        f"• IP check enabled: <code>{'yes' if TRIAL_BONUS_IP_CHECK_ENABLED else 'no'}</code>",
        f"• Telegram-only fallback: <code>{'yes' if TRIAL_BONUS_ALLOW_TELEGRAM_ONLY_FALLBACK else 'no'}</code>",
        f"• Web claim enabled: <code>{'yes' if TRIAL_BONUS_WEB_CLAIM_ENABLED else 'no'}</code>",
        f"• Granted rows: <code>{int(total_granted)}</code>",
        f"• Duplicate user blocked rows: <code>{int(total_blocked_user)}</code>",
        "",
        "<b>Last claims</b>",
    ]
    if rows:
        for user_id, source, amount, status, created_at, reason in rows:
            lines.append(
                f"• <code>{html.escape(str(user_id or '-'))}</code> | <code>{html.escape(str(source or '-'))}</code> | "
                f"<code>{html.escape(str(status or '-'))}</code> | <code>{int(amount or 0)} Xu</code> | "
                f"<code>{html.escape(str(created_at or '-'))}</code> | {html.escape(str(reason or '-')[:90])}"
            )
    else:
        lines.append("• <code>chưa có dữ liệu</code>")
    lines.extend([
        "",
        "Telegram /start không có IP người dùng; IP hash chỉ enforce khi có web/HTTP/WebApp claim an toàn.",
        "Không lưu raw IP và không đụng PayOS/top-up/member tier.",
    ])
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_gift(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    record_usage_event(
        uid,
        username=update.effective_user.username or update.effective_user.first_name or "",
        event_type="command",
        tool_name="gift",
        command="/gift",
        status="requested" if context.args else "guide",
        detail=normalize_promo_code(context.args[0]) if context.args else "",
    )
    if not context.args:
        text = (
            "🎁 <b>Nhận quà TOAN AAS</b>\n\n"
            "Nếu admin gửi mã quà tặng cho bạn, dùng:\n"
            "<code>/gift MÃ_ADMIN_GỬI</code>\n"
            "<code>/nhanqua MÃ_ADMIN_GỬI</code>\n\n"
            "Mã quà tặng sự kiện/hỗ trợ riêng chỉ dùng khi admin gửi mã cho bạn. "
            "Không cần tự thử nhiều mã vì hệ thống sẽ không cộng Xu dịch vụ nếu mã chưa được cấp cho ID Telegram của bạn."
        )
        if is_admin_user(update.effective_user.id):
            text += "\n\nAdmin cấp BETA cho user bằng: <code>/gift BETA100 USER_ID</code>\nXem request: <code>/gift_request_list</code>"
        return await update.message.reply_text(text, parse_mode="HTML")
    code = context.args[0]
    if is_admin_user(update.effective_user.id) and len(context.args) >= 2:
        target_user_id = context.args[1].strip()
        ok, status, info = grant_gift_code_to_user(update.effective_user.id, target_user_id, code)
        if ok:
            try:
                await context.bot.send_message(
                    chat_id=int(target_user_id),
                    text=(
                        "🎁 <b>Admin đã cấp quà TOAN AAS cho bạn</b>\n\n"
                        f"• Mã: <code>{html.escape(info.get('code') or normalize_promo_code(code))}</code>\n"
                        f"• Xu dịch vụ nhận: <b>+{int(info.get('xu') or 0)} Xu</b>\n"
                        f"• Số dư mới: <b>{int(info.get('balance') or 0)} Xu dịch vụ</b>"
                    ),
                    parse_mode="HTML",
                )
            except Exception:
                pass
            return await update.message.reply_text(
                "✅ <b>Đã cấp gift code cho user</b>\n\n"
                f"• User ID: <code>{html.escape(str(target_user_id))}</code>\n"
                f"• Mã: <code>{html.escape(info.get('code') or normalize_promo_code(code))}</code>\n"
            f"• Xu dịch vụ: <b>+{int(info.get('xu') or 0)} Xu</b>\n"
            f"• Số dư user: <b>{int(info.get('balance') or 0)} Xu dịch vụ</b>",
                parse_mode="HTML",
            )
        message = "Không cấp được mã quà tặng."
        if status == "already_applied":
            message = "User này đã nhận mã này rồi, hệ thống không cộng trùng."
        elif status == "not_found":
            message = "Mã gift chưa tồn tại. Hãy seed/tạo mã trước."
        return await update.message.reply_text(
            f"⚠️ {message}\nLý do: <code>{html.escape(status)}</code>",
            parse_mode="HTML",
        )
    ok, status, info = redeem_gift_code(update.effective_user.id, code)
    if ok:
        return await update.message.reply_text(
            "✅ <b>Bạn đã nhận quà TOAN AAS</b>\n\n"
            f"• Mã: <code>{html.escape(info.get('code') or normalize_promo_code(code))}</code>\n"
            f"• Xu dịch vụ nhận: <b>+{int(info.get('xu') or 0)} Xu</b>\n"
            f"• Số dư mới: <b>{int(info.get('balance') or 0)} Xu dịch vụ</b>",
            parse_mode="HTML",
        )
    if status == "assignment_required":
        request_status = await notify_admin_beta_gift_request(update, context, code)
        message = (
            gift_beta_request_pending_message(update.effective_user, code)
            if request_status == "pending"
            else gift_needs_assignment_message(update.effective_user, code)
        )
        return await update.message.reply_text(
            message,
            parse_mode="HTML",
            reply_markup=beta_gift_support_keyboard(),
        )
    if status == "already_applied":
        return await update.message.reply_text(
            "ℹ️ Mã quà tặng này đã được nhận trên tài khoản của bạn, hệ thống không cộng trùng.",
            parse_mode="HTML",
        )
    return await update.message.reply_text(
        "❌ Mã quà tặng không hợp lệ, đã hết lượt hoặc chưa được kích hoạt.\n\n"
        f"Lý do: <code>{html.escape(status)}</code>",
        parse_mode="HTML",
    )

async def cmd_gift_create(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    data = parse_key_value_args(" ".join(context.args))
    code = normalize_promo_code(data.get("code") or (context.args[0] if context.args else ""))
    xu = safe_int(data.get("xu") or data.get("value"), 0)
    usage_limit = safe_int(data.get("limit") or data.get("usage_limit"), 1)
    per_user = max(1, safe_int(data.get("per_user") or data.get("per_user_limit"), 1))
    note = (data.get("note") or "").strip()[:300]
    mode = normalize_promo_code(data.get("mode") or data.get("scope") or data.get("type") or "")
    requires_assignment = is_beta_gift_code(code) or mode in {"ASSIGNED", "PRIVATE", "INTERNAL"}
    if not code or xu <= 0:
        return await update.message.reply_text(
            "⚠️ Cú pháp: <code>/gift_create code=THANK100 xu=100 limit=100 per_user=1 mode=public note=\"Tặng trải nghiệm\"</code>",
            parse_mode="HTML",
        )
    conn = db_connect()
    try:
        ok, status = create_gift_code_record(
            conn,
            code,
            xu,
            usage_limit=usage_limit,
            per_user_limit=per_user,
            note=note,
            created_by=update.effective_user.id,
            requires_assignment=requires_assignment,
        )
        if ok:
            record_audit(
                conn,
                update.effective_user.id,
                "admin",
                "gift.created",
                "promotion_code",
                code,
                after={"xu": xu, "limit": usage_limit, "per_user": per_user, "requires_assignment": int(requires_assignment)},
                note=note,
            )
            conn.commit()
        else:
            conn.rollback()
    finally:
        conn.close()
    if not ok:
        return await update.message.reply_text(f"⚠️ Không tạo được mã <code>{html.escape(code)}</code>: <code>{html.escape(status)}</code>", parse_mode="HTML")
    await update.message.reply_text(
        "✅ <b>Đã tạo mã quà tặng</b>\n\n"
        f"Code: <code>{html.escape(code)}</code>\n"
        f"Xu: <b>+{xu}</b>\n"
        f"Limit: <b>{usage_limit}</b> lượt\n"
        f"Per user: <b>{per_user}</b> lần\n"
        f"Scope: <b>{'assigned/private' if requires_assignment else 'public'}</b>\n"
        f"Note: {html.escape(note or '-')}\n\n"
        f"User dùng: <code>/gift {html.escape(code)}</code> hoặc <code>/promo {html.escape(code)}</code>\n"
        f"Admin cấp riêng: <code>/gift {html.escape(code)} USER_ID</code>",
        parse_mode="HTML",
    )

