def build_realistic_image_prompt_rules() -> str:
    return (
        "Quy tắc prompt ảnh chân thật TOAN AAS:\n"
        "1. Cảm xúc tự nhiên: khuôn mặt/cử chỉ đời thường, không quá cứng.\n"
        "2. Ánh sáng thật: có vùng sáng/tối rõ, tránh ánh sáng đều giả.\n"
        "3. Chi tiết đời thường: tóc hơi rối, nếp vải, vật thể xung quanh.\n"
        "4. Phong cách chụp đời thực: như điện thoại/máy ảnh thật, góc chụp tự nhiên.\n"
        "5. Hậu cảnh tự nhiên: có chiều sâu, có vật thể phía sau, blur nhẹ nếu hợp lý.\n"
        "6. Khoảnh khắc tự nhiên: nhân vật/sản phẩm đang trong tình huống thật.\n"
        "7. Negative: không da nhựa, không mặt quá mịn, không ánh sáng studio giả, không tay méo, "
        "không chữ méo, không logo lạ, không watermark, không text sai."
    )

def media_factory_topic_from_args(context: ContextTypes.DEFAULT_TYPE, fallback: str = "") -> str:
    return (" ".join(context.args or []).strip() or fallback.strip())

def media_factory_username(update: Update) -> str:
    user = update.effective_user
    return ((user.username or user.first_name or "") if user else "").strip()

async def charge_media_factory_or_reply(update: Update, uid, cost: int, event_type: str, note: str) -> bool:
    if is_admin_user(uid) or int(cost or 0) <= 0:
        return True
    charge = apply_member_service_discount(uid, int(cost), event_type)
    final_cost = int(charge.get("final_cost") or 0)
    if spend_fixed_credit_info(uid, int(cost), event_type, note).get("ok"):
        return True
    credits, _, _ = get_user(uid)
    await update.message.reply_text(
        "⚠️ Không đủ Xu để dùng tính năng này.\n\n"
        f"• Cần: {final_cost} Xu\n"
        f"• Số dư hiện tại: {int(credits)} Xu\n\n"
        "Dùng /naptien để nạp thêm. Gói phổ biến: 50k / 100k / 200k."
    )
    return False

async def preview_media_factory_credit_or_reply(update: Update, uid, cost: int, event_type: str) -> tuple[bool, dict]:
    base_cost = int(cost or 0)
    if is_admin_user(uid) or base_cost <= 0:
        tier = "admin" if is_admin_user(uid) else (member_profile(uid).get("tier") or "newbie")
        return True, {"ok": True, "base_cost": base_cost, "final_cost": 0, "discount_xu": 0, "tier": tier}
    charge = apply_member_service_discount(uid, base_cost, event_type)
    final_cost = int(charge.get("final_cost") or 0)
    credits, _, _ = get_user(uid)
    if int(credits or 0) >= final_cost:
        return True, charge
    await update.effective_message.reply_text(
        "⚠️ Không đủ Xu để dùng tính năng này.\n\n"
        f"• Cần: {final_cost} Xu\n"
        f"• Số dư hiện tại: {int(credits or 0)} Xu\n\n"
        "Dùng /naptien để nạp thêm. Gói phổ biến: 50k / 100k / 200k."
    )
    return False, charge

async def spend_media_factory_after_success_or_reply(update: Update, uid, cost: int, event_type: str, note: str) -> dict:
    base_cost = int(cost or 0)
    if is_admin_user(uid) or base_cost <= 0:
        tier = "admin" if is_admin_user(uid) else (member_profile(uid).get("tier") or "newbie")
        return {"ok": True, "base_cost": base_cost, "final_cost": 0, "discount_xu": 0, "tier": tier}
    charge_result = spend_fixed_credit_info(uid, base_cost, event_type, note)
    if charge_result.get("ok"):
        return charge_result
    credits_now, _, _ = get_user(uid)
    final_cost = int(charge_result.get("final_cost") or charge_result.get("cost") or base_cost)
    await update.effective_message.reply_text(
        "⚠️ Không đủ Xu để dùng tính năng này.\n\n"
        f"• Cần: {final_cost} Xu\n"
        f"• Số dư hiện tại: {int(credits_now or 0)} Xu\n\n"
        "Dùng /naptien để nạp thêm."
    )
    return charge_result

async def reply_long_text(update: Update, text: str):
    text = str(text or "").strip()
    if not text:
        return await update.message.reply_text("⚠️ Không có nội dung để gửi.")
    chunk_size = 3600
    while len(text) > chunk_size:
        cut = text.rfind("\n\n", 0, chunk_size)
        if cut < 1200:
            cut = text.rfind("\n", 0, chunk_size)
        if cut < 1200:
            cut = chunk_size
        await update.message.reply_text(text[:cut].strip())
        text = text[cut:].strip()
    if text:
        await update.message.reply_text(text)

def doc_cost(action: str, pages: int = 1) -> int:
    if action == "ocr_pdf":
        return max(1, int(pages or 1)) * int(DOC_COSTS["ocr_pdf_per_page"])
    return int(DOC_COSTS.get(action, 10))

