        if pages > DOC_OCR_MAX_PAGES:
            return await update.message.reply_text(f"⚠️ OCR PDF tối đa {DOC_OCR_MAX_PAGES} trang/lần. File này có {pages} trang.")
        cost = 0 if is_admin_user(uid) else doc_cost("ocr_pdf", pages)
