async def process_due_memory_reminders(bot):
    now = memory_dt_text(memory_now())
    conn = db_connect()
    try:
        rows = conn.execute(
            """SELECT id, user_id, note_id, title, remind_text, repeat_rule, next_run_at
            FROM memory_reminders
            WHERE status='active' AND next_run_at IS NOT NULL AND next_run_at!='' AND next_run_at<=?
            ORDER BY next_run_at ASC LIMIT 25""",
            (now,),
        ).fetchall()
    finally:
        conn.close()
    for reminder_id, user_id, note_id, title, remind_text, repeat_rule, next_run_at in rows:
        try:
            note_line = ""
            if int(note_id or 0):
                note_line = f"\nGhi chú #{int(note_id)}: {html.escape(str(title or '')[:160])}"
            await bot.send_message(
                chat_id=str(user_id),
                text=(
                    "⏰ <b>NHẮC NHỞ TOAN AAS</b>\n\n"
                    f"{html.escape(str(remind_text or title or 'Nhắc việc'))}"
                    f"{note_line}\n\n"
                    "<b>Lệnh nhanh:</b>\n"
                    f"• <code>/reminder_done {int(reminder_id)}</code>\n"
                    f"• <code>/reminder_cancel {int(reminder_id)}</code>\n"
                    + (f"• <code>/note_view {int(note_id)}</code>" if int(note_id or 0) else "")
                ),
                parse_mode="HTML",
            )
            base_dt = memory_parse_stored_dt(next_run_at) or memory_now()
            next_dt = memory_next_repeat_after(repeat_rule, base_dt)
            conn = db_connect()
            try:
                if next_dt:
                    conn.execute(
                        "UPDATE memory_reminders SET last_sent_at=?, next_run_at=?, updated_at=? WHERE id=?",
                        (now_text(), memory_dt_text(next_dt), now_text(), int(reminder_id)),
                    )
                    status = "reminder_sent_repeat"
                else:
                    conn.execute(
                        "UPDATE memory_reminders SET status='done', last_sent_at=?, updated_at=? WHERE id=?",
                        (now_text(), now_text(), int(reminder_id)),
                    )
                    status = "reminder_sent_done"
                conn.commit()
            finally:
                conn.close()
            memory_record_event(user_id, status, note_id=note_id, reminder_id=reminder_id)
            save_tool_test_result("memory_reminders", "PASS", "due reminder sent", user_id)
        except Exception as e:
            logger.warning(f"Memory reminder send failed id={reminder_id}: {e}")
            memory_record_event(user_id, "reminder_send_failed", note_id=note_id, reminder_id=reminder_id, detail=str(e)[:220])

async def memory_reminder_loop(bot):
    await asyncio.sleep(20)
    while True:
        try:
            await process_due_memory_reminders(bot)
        except asyncio.CancelledError:
            raise
        except Exception as e:
            logger.warning(f"Memory reminder loop error: {e}")
        await asyncio.sleep(60)

def media_factory_ai(prompt: str, user_text: str, uid, fallback_text: str) -> str:
    try:
        output = AgentGemini.chat(prompt, user_text, uid)
        cleaned = (output or "").strip()
        if cleaned and not cleaned.startswith("❌") and len(cleaned) > 120:
            return cleaned
    except Exception as e:
        logger.warning(f"Media Factory AI fallback: {e}")
    return fallback_text

async def reply_ai_provider_failure(update: Update, uid, result: dict, tool_name: str = "ai") -> None:
    statuses = (result or {}).get("statuses") or {}
    errors = (result or {}).get("errors") or {}
    detail = ai_failure_detail(statuses, errors)
    save_tool_test_result(tool_name, "FAIL", detail, uid)
    message = (result or {}).get("message") or ai_failure_user_text(statuses, errors)
    await update.message.reply_text(message)

def create_media_factory_job(user_id, username, mode, topic, trend_title="", trend_summary="", image_prompt_pack="", video_prompt_pack="", caption_pack="", status="draft", cost_xu=0, note="") -> int:
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """INSERT INTO media_factory_jobs
        (user_id, username, mode, topic, trend_title, trend_summary, image_prompt_pack,
         video_prompt_pack, caption_pack, status, cost_xu, created_at, updated_at, approved_by, approved_at, note)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            str(user_id), str(username or ""), str(mode or ""), str(topic or ""),
            str(trend_title or ""), str(trend_summary or ""), str(image_prompt_pack or ""),
            str(video_prompt_pack or ""), str(caption_pack or ""), str(status or "draft"),
            int(cost_xu or 0), now_text(), now_text(), "", "", str(note or ""),
        ),
    )
    job_id = c.lastrowid
    conn.commit()
    conn.close()
    return int(job_id)

def get_media_factory_job(job_id: int) -> dict:
    conn = db_connect()
    try:
        c = conn.cursor()
        c.execute(
            """SELECT id, user_id, username, mode, topic, trend_title, trend_summary, image_prompt_pack,
                      video_prompt_pack, caption_pack, status, cost_xu, created_at, updated_at, approved_by, approved_at, note
            FROM media_factory_jobs WHERE id=?""",
            (int(job_id),),
        )
        row = c.fetchone()
        if not row:
            return {}
        keys = ["id", "user_id", "username", "mode", "topic", "trend_title", "trend_summary", "image_prompt_pack", "video_prompt_pack", "caption_pack", "status", "cost_xu", "created_at", "updated_at", "approved_by", "approved_at", "note"]
        return dict(zip(keys, row))
    finally:
        conn.close()

def update_media_factory_job_status(job_id: int, status: str, approved_by="", note="") -> bool:
    conn = db_connect()
    try:
        approved_at = now_text() if status == "approved" else ""
        cur = conn.execute(
            """UPDATE media_factory_jobs
            SET status=?, approved_by=COALESCE(NULLIF(?,''), approved_by),
                approved_at=COALESCE(NULLIF(?,''), approved_at),
                note=COALESCE(NULLIF(?,''), note), updated_at=?
            WHERE id=?""",
            (status, str(approved_by or ""), approved_at, str(note or ""), now_text(), int(job_id)),
        )
        conn.commit()
        return cur.rowcount > 0
    finally:
        conn.close()

