async def handle_creative_motion_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query:
        return
    await query.answer()
    uid = query.from_user.id
    data = query.data or ""
    parts = data.split("|")
    action = parts[1] if len(parts) >= 2 else "start"
    value = parts[2] if len(parts) >= 3 else ""
    lang = get_user_language(uid) or "vi"
    if action == "cancel":
        clear_creative_motion_pending(uid)
        return await safe_edit_query_message(
            query,
            ui_text(lang, "motion.cancelled"),
            reply_markup=main_video_keyboard(lang),
        )
    if action == "start":
        clear_media_creator_pending_states(uid)
        set_creative_motion_pending(uid, "topic")
        return await safe_edit_query_message(query, creative_motion_topic_text(lang), reply_markup=creative_motion_topic_keyboard(lang))
    if action == "topic":
        if value == "custom":
            set_creative_motion_pending(uid, "topic_custom")
            return await safe_edit_query_message(
                query,
                ui_text(lang, "motion.ask_topic", cost_line=html.escape(ui_text(lang, "common.no_api_no_charge"))),
                reply_markup=video_v6_keyboard(
                    [],
                    lang,
                    back=("🔙 Quay lại nhóm" if normalize_user_language(lang) == "vi" else "🔙 Back to categories", "motion|start"),
                ),
            )
        set_creative_motion_pending(uid, "suggestions", kind=value, suggest_offset=0)
        state = get_creative_motion_pending(uid) or {"kind": value, "suggest_offset": 0}
        return await safe_edit_query_message(
            query,
            creative_motion_suggestions_text(state, lang),
            reply_markup=creative_motion_suggestions_keyboard(lang),
        )
    pending = get_creative_motion_pending(uid) or {}
    if action == "refresh":
        kind = str(pending.get("kind") or "product")
        offset = _safe_int(pending.get("suggest_offset"), 0) + 3
        set_creative_motion_pending(uid, "suggestions", kind=kind, suggest_offset=offset)
        state = get_creative_motion_pending(uid) or {}
        return await safe_edit_query_message(
            query,
            creative_motion_suggestions_text(state, lang),
            reply_markup=creative_motion_suggestions_keyboard(lang),
        )
    if action == "choice":
        kind = str(pending.get("kind") or "product")
        suggestions = creative_motion_suggestions(kind, _safe_int(pending.get("suggest_offset"), 0), lang)
        try:
            idx = max(1, min(3, int(value or "1")))
        except Exception:
            idx = 1
        selected = suggestions[idx - 1] if idx <= len(suggestions) else (suggestions[0] if suggestions else {})
        topic = str(selected.get("title") or creative_motion_topic_label(kind, lang))
        set_creative_motion_pending(uid, "style", topic, kind=kind, selected_suggestion_index=idx)
        return await safe_edit_query_message(query, creative_motion_style_text(topic, lang), reply_markup=creative_motion_style_keyboard(lang))
    if action == "back_suggestions":
        kind = str(pending.get("kind") or "product")
        set_creative_motion_pending(uid, "suggestions", kind=kind)
        state = get_creative_motion_pending(uid) or {}
        return await safe_edit_query_message(
            query,
            creative_motion_suggestions_text(state, lang),
            reply_markup=creative_motion_suggestions_keyboard(lang),
        )
    if action == "back_style":
        topic = pending.get("topic") or creative_motion_topic_label(pending.get("kind") or "product", lang)
        set_creative_motion_pending(uid, "style", topic)
        return await safe_edit_query_message(query, creative_motion_style_text(topic, lang), reply_markup=creative_motion_style_keyboard(lang))
    if action == "style":
        topic = pending.get("topic") or "video quảng cáo sản phẩm"
        set_creative_motion_pending(uid, "result", topic)
        return await safe_edit_query_message(
            query,
            creative_motion_guide_text(topic, value, lang),
            reply_markup=creative_motion_result_keyboard(lang),
        )
    return await safe_edit_query_message(query, creative_motion_topic_text(lang), reply_markup=creative_motion_topic_keyboard(lang))

async def handle_creative_motion_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.message.text or not update.effective_user:
        return False
    uid = update.effective_user.id
    pending = get_creative_motion_pending(uid)
    if not pending:
        return False
    lang = get_user_language(uid) or "vi"
    text = re.sub(r"\s+", " ", update.message.text.strip())[:500]
    if not text:
        return False
    step = pending.get("step") or "topic"
    if step in {"topic", "topic_custom"}:
        set_creative_motion_pending(uid, "style", text)
        await update.message.reply_text(creative_motion_style_text(text, lang), parse_mode="HTML", reply_markup=creative_motion_style_keyboard(lang))
        return True
    clear_creative_motion_pending(uid)
    await update.message.reply_text(
        creative_motion_guide_text(pending.get("topic") or text, text, lang),
        parse_mode="HTML",
        reply_markup=creative_motion_result_keyboard(lang),
    )
    return True

CREATIVE_CINEMATIC_AD_PENDING_TTL_SECONDS = 10 * 60
LAST_CINEMATIC_AD_CONCEPTS: dict[str, dict] = {}

def cinematic_ad_pending_key(user_id) -> str:
    return f"cinematic_ad_concept:{user_id}"

def set_cinematic_ad_pending(user_id, step: str = "product", product: str = "", message: str = "", style: str = "cinematic") -> None:
    USER_PENDING[cinematic_ad_pending_key(user_id)] = {
        "pending_action": "cinematic_ad_concept",
        "step": str(step or "product"),
        "product": str(product or "")[:500],
        "message": str(message or "")[:500],
        "style": str(style or "cinematic")[:80],
        "created_at_ts": time.time(),
    }

def get_cinematic_ad_pending(user_id) -> dict | None:
    key = cinematic_ad_pending_key(user_id)
    pending = USER_PENDING.get(key) or {}
    if pending.get("pending_action") != "cinematic_ad_concept":
        return None
    age = time.time() - float(pending.get("created_at_ts") or 0)
    if age > CREATIVE_CINEMATIC_AD_PENDING_TTL_SECONDS:
        USER_PENDING.pop(key, None)
        return None
    return pending

def clear_cinematic_ad_pending(user_id) -> bool:
    return USER_PENDING.pop(cinematic_ad_pending_key(user_id), None) is not None

def cinematic_ad_latest_key(user_id) -> str:
    return str(user_id)

def cinematic_ad_concept_topic(product: str, message: str, style: str = "cinematic", lang: str = "vi") -> str:
    safe_product = re.sub(r"\s+", " ", str(product or "").strip())[:300] or ("产品/服务" if normalize_user_language(lang) == "zh" else ("product/service" if normalize_user_language(lang) != "vi" else "sản phẩm/dịch vụ"))
    safe_message = re.sub(r"\s+", " ", str(message or "").strip())[:300] or ("品牌信息" if normalize_user_language(lang) == "zh" else ("brand message" if normalize_user_language(lang) != "vi" else "thông điệp thương hiệu"))
    style_label = cinematic_ad_style_label(style, lang)
    if normalize_user_language(lang) == "zh":
        return f"电影感广告 concept：{safe_product}，信息：{safe_message}，风格：{style_label}"
    if normalize_user_language(lang) != "vi":
        return f"{style_label} advertising concept for {safe_product}, message: {safe_message}"
    return f"concept quảng cáo {style_label} cho {safe_product}, thông điệp {safe_message}"

def save_cinematic_ad_concept(user_id, product: str, message: str, style: str = "cinematic", lang: str = "vi") -> dict:
    style = normalize_cinematic_ad_style_code(style)
    concept = {
        "product": str(product or "")[:500],
        "message": str(message or "")[:500],
        "style": str(style or "cinematic")[:80],
        "topic": cinematic_ad_concept_topic(product, message, style, lang),
        "lang": normalize_user_language(lang) or "vi",
        "locked": False,
        "created_at_ts": time.time(),
    }
    LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(user_id)] = concept
    return concept

def get_latest_cinematic_ad_concept(user_id) -> dict | None:
    concept = LAST_CINEMATIC_AD_CONCEPTS.get(cinematic_ad_latest_key(user_id)) or {}
    if not concept:
        return None
    age = time.time() - float(concept.get("created_at_ts") or 0)
    if age > CREATIVE_CINEMATIC_AD_PENDING_TTL_SECONDS:
        LAST_CINEMATIC_AD_CONCEPTS.pop(cinematic_ad_latest_key(user_id), None)
        return None
    return concept

def lock_latest_cinematic_ad_concept(user_id) -> dict | None:
    concept = get_latest_cinematic_ad_concept(user_id)
    if not concept:
        return None
    concept["locked"] = True
    concept["locked_at_ts"] = time.time()
    LAST_CINEMATIC_AD_CONCEPTS[cinematic_ad_latest_key(user_id)] = concept
    return concept

def cinematic_ad_concept_input(concept: dict, lang: str = "vi") -> tuple[str, str, str, str]:
    product = str(concept.get("product") or "").strip() or ("产品/服务" if normalize_user_language(lang) == "zh" else ("product/service" if normalize_user_language(lang) != "vi" else "sản phẩm/dịch vụ"))
    message = str(concept.get("message") or "").strip() or ("品牌信息" if normalize_user_language(lang) == "zh" else ("brand message" if normalize_user_language(lang) != "vi" else "thông điệp thương hiệu"))
    style = normalize_cinematic_ad_style_code(concept.get("style") or "cinematic")
    topic = str(concept.get("topic") or "").strip() or cinematic_ad_concept_topic(product, message, style, lang)
    return product, message, style, topic

