def public_image_prompt_request_text(tier: str, lang: str = "vi") -> str:
    return ui_text(lang, "image.prompt.ask", label=html.escape(localized_image_tier_label(tier, lang)))

def media_aspect_pending_key(user_id) -> str:
    return f"media_aspect:{user_id}"

def set_media_aspect_pending(user_id, job_type: str, tier: str, prompt: str, package: dict | None = None) -> None:
    normalized_job_type = "image" if str(job_type or "").lower() == "image" else "video"
    USER_PENDING[media_aspect_pending_key(user_id)] = {
        "pending_action": "media_aspect",
        "job_type": normalized_job_type,
        "tier": normalize_image_tier(tier) if normalized_job_type == "image" else normalize_video_tier(tier),
        "prompt": re.sub(r"\s+", " ", str(prompt or "").strip())[:1400],
        "package": package or {},
        "created_at_ts": time.time(),
    }

def get_media_aspect_pending(user_id, job_type: str = "") -> dict | None:
    key = media_aspect_pending_key(user_id)
    pending = USER_PENDING.get(key) or {}
    if pending.get("pending_action") != "media_aspect":
        return None
    wanted = str(job_type or "").strip().lower()
    if wanted and pending.get("job_type") != wanted:
        return None
    age = time.time() - float(pending.get("created_at_ts") or 0)
    if age > QUICK_MEDIA_PENDING_TTL_SECONDS:
        USER_PENDING.pop(key, None)
        return None
    return pending

def clear_media_aspect_pending(user_id) -> bool:
    return USER_PENDING.pop(media_aspect_pending_key(user_id), None) is not None

def public_media_aspect_ratio_text(kind: str, tier: str, prompt: str = "", lang: str = "vi") -> str:
    kind_norm = "image" if str(kind or "").lower() == "image" else "video"
    label = localized_image_tier_label(tier, lang) if kind_norm == "image" else localized_video_tier_label(tier, lang)
    if normalize_user_language(lang) == "zh":
        return f"📐 <b>选择画面比例</b>\n\n套餐：<b>{html.escape(label)}</b>\nPrompt: <code>{html.escape(shopaikey_safe_prompt_preview(prompt))}</code>\n\n请选择比例。Bot 尚未调用 API，也未扣除 Xu。"
    if normalize_user_language(lang) != "vi":
        return f"📐 <b>Choose aspect ratio</b>\n\nTier: <b>{html.escape(label)}</b>\nPrompt: <code>{html.escape(shopaikey_safe_prompt_preview(prompt))}</code>\n\nChoose an aspect ratio. The bot has not called any API and has not charged Xu."
    return f"📐 <b>Chọn tỉ lệ khung hình</b>\n\nGói: <b>{html.escape(label)}</b>\nPrompt: <code>{html.escape(shopaikey_safe_prompt_preview(prompt))}</code>\n\nBạn muốn tạo theo tỉ lệ nào? Bot chưa gọi API và chưa trừ Xu."

def public_media_aspect_ratio_keyboard(kind: str, lang: str = "vi") -> InlineKeyboardMarkup:
    kind_norm = "image" if str(kind or "").lower() == "image" else "video"
    rows = []
    options = media_aspect_ratio_options(kind_norm)
    for idx in range(0, len(options), 2):
        row = []
        for aspect in options[idx:idx + 2]:
            label = media_aspect_ratio_label(aspect, kind_norm, lang)
            row.append(InlineKeyboardButton(label, callback_data=f"create_media|{kind_norm}_aspect_{media_aspect_ratio_token(aspect)}"))
        rows.append(row)
    rows.append([InlineKeyboardButton(ui_text(lang, "common.back"), callback_data="create_media|quick_image" if kind_norm == "image" else "create_media|quick_video")])
    rows.append([InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")])
    return InlineKeyboardMarkup(rows)

def with_aspect_line(text: str, aspect_ratio: str = "", lang: str = "vi", kind: str = "image") -> str:
    kind_norm = "image" if str(kind or "").lower() == "image" else "video"
    aspect = normalize_media_aspect_ratio(aspect_ratio, "9:16", kind_norm)
    if not aspect:
        return text
    label = media_aspect_ratio_label(aspect, kind_norm, lang) if kind_norm == "image" else aspect
    if normalize_user_language(lang) == "zh":
        line = f"• 画面比例: <b>{html.escape(label)}</b>"
    elif normalize_user_language(lang) != "vi":
        line = f"• Aspect ratio: <b>{html.escape(label)}</b>"
    else:
        line = f"• Tỉ lệ khung hình: <b>{html.escape(label)}</b>"
    return text.replace("• Prompt:", f"{line}\n• Prompt:", 1)

def shopaikey_confirm_keyboard(job_type: str, token: str, tier: str, lang: str = "vi") -> InlineKeyboardMarkup:
    kind = "image" if str(job_type or "").lower() == "image" else "video"
    tier_norm = normalize_image_tier(tier) if kind == "image" else normalize_video_tier(tier)
    rows = [
        [InlineKeyboardButton(ui_text(lang, "common.confirm"), callback_data=f"shopai|confirm|{token}")],
        [InlineKeyboardButton(ui_text(lang, "common.cancel"), callback_data=f"shopai|cancel|{token}")],
        [InlineKeyboardButton("📐 Đổi tỉ lệ" if normalize_user_language(lang) == "vi" else "📐 Change ratio", callback_data=f"create_media|{'ia' if kind == 'image' else 'va'}_{token}")],
        [InlineKeyboardButton("🔁 Chọn gói khác" if normalize_user_language(lang) == "vi" else "🔁 Choose another tier", callback_data="create_media|quick_image" if kind == "image" else "create_media|quick_video")],
        [InlineKeyboardButton(ui_text(lang, "common.back"), callback_data="create_media|quick_image" if kind == "image" else "create_media|quick_video")],
        [InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")],
    ]
    return InlineKeyboardMarkup(rows)

def public_image_confirm_text(tier: str, prompt: str, current_credits: int = 0, lang: str = "vi", aspect_ratio: str = "") -> str:
    payload = image_tier_payload(tier)
    cost = int(payload.get("cost") or 0)
    text = with_aspect_line(ui_text(
        lang,
        "image.confirm.cost",
        label=html.escape(localized_image_tier_label(tier, lang)),
        cost=cost,
        credits=int(current_credits or 0),
        warranty_note=html.escape(image_tier_warranty_note(tier, lang)),
        prompt=html.escape(shopaikey_safe_prompt_preview(prompt)),
    ), aspect_ratio, lang, "image")
    quality_label = "Quality control" if normalize_user_language(lang) != "vi" else "Kiểm soát chất lượng"
    return f"{text}\n\n<b>{quality_label}:</b> {html.escape(image_tier_quality_note(tier, lang))}"

def public_image_success_billing_note(deducted: int = 0, lang: str = "vi", admin_internal_free: bool = False) -> str:
    amount = int(deducted or 0)
    if admin_internal_free and amount <= 0:
        if normalize_user_language(lang) == "zh":
            return "已扣除：0 Xu（admin 内部测试）。Provider 仍可能消耗真实 credit。"
        if normalize_user_language(lang) != "vi":
            return "Charged: 0 Xu internally because this is an admin account. The provider may still consume real credit."
        return "Đã trừ: 0 Xu nội bộ do tài khoản admin. Provider có thể vẫn tốn credit thật."
    if normalize_user_language(lang) == "zh":
        return f"已扣除：{amount} Xu。"
    if normalize_user_language(lang) != "vi":
        return f"Charged: {amount} Xu."
    return f"Đã trừ: {amount} Xu."

def shopaikey_image_job_for_user(job_id: int = 0, user_id=0) -> dict | None:
    jid = int(job_id or 0)
    if jid <= 0:
        return None
    job = shopaikey_job_by_id(jid) or {}
    if not job or str(job.get("job_type") or "").lower() != "image":
        return None
    owner = str(job.get("user_id") or "")
    if owner and owner == str(user_id or ""):
        return job
    if is_admin_user(user_id):
        return job
    return None

def shopaikey_image_source_payload(job_id: int = 0, user_id=0) -> dict:
    job = shopaikey_image_job_for_user(job_id, user_id) or {}
    if not job:
        return {}
    return {
        "image_job_id": str(job.get("id") or ""),
        "image_url": str(job.get("result_url") or "").strip(),
        "telegram_file_id": str(job.get("output_file_id") or "").strip(),
        "image_prompt": str(job.get("prompt_preview") or "").strip()[:500],
        "tier": str(job.get("billing_status") or "").strip()[:80],
        "warranty_retry_count": max(0, int(job.get("retry_warranty_count") or 0)),
        "warranty_retry_used": max(0, int(job.get("retry_warranty_used") or 0)),
        "created_at": str(job.get("created_at") or ""),
    }

def image_to_video_subject_for_job(job_id: int = 0, user_id=0, lang: str = "vi") -> str:
    job = shopaikey_image_job_for_user(job_id, user_id) or {}
    prompt_preview = str(job.get("prompt_preview") or "").strip()
    if not prompt_preview:
        recent = get_recent_media_state(LAST_USER_IMAGE, safe_int(user_id, 0))
        prompt_preview = str((recent or {}).get("caption") or (recent or {}).get("file_name") or "").strip()
    if prompt_preview:
        return prompt_preview[:500]
    if normalize_user_language(lang) == "zh":
        return "已选择的图片 / 产品场景"
    if normalize_user_language(lang) != "vi":
        return "selected image / product scene"
    return "ảnh/sản phẩm đã chọn"

def image_to_video_prompt_from_image(job_id: int = 0, user_id=0, index: int = 1, lang: str = "vi") -> str:
    idx = max(1, min(3, int(index or 1)))
    subject = image_to_video_subject_for_job(job_id, user_id, lang)
    guard = video_text_render_guard(lang)
    if normalize_user_language(lang) == "zh":
        if idx == 1:
            return f"基于已选择图片制作 5 秒短视频。主体: {subject}. Camera slow push-in, subtle parallax, stable subject, clean light, keep product sharp, no watermark, no extra text. {guard}"
        if idx == 2:
            return f"基于已选择图片制作 10 秒短广告。主体: {subject}. Start with a clear hook, reveal the product/service, show one benefit, end with a clean final frame with space for CTA overlay, smooth camera motion, no distortion. {guard}"
        return f"基于已选择图片制作 15 秒 cinematic/lifestyle 视频。主体: {subject}. Add context, smooth cinematic camera movement, emotional reveal, final hero frame with empty space for message/CTA overlay, no watermark, no broken text. {guard}"
    if normalize_user_language(lang) != "vi":
        if idx == 1:
            return f"Create a 5-second video from the selected image. Subject/context: {subject}. Camera slowly pushes in, subtle parallax, stable subject, clean lighting, keep the product sharp, no watermark, no extra text. {guard}"
        if idx == 2:
            return f"Create a 10-second short ad from the selected image. Subject/context: {subject}. Start with a clear hook, reveal the product/service, show one benefit, end with a clean final frame with space for CTA overlay, smooth camera motion, no distortion. {guard}"
        return f"Create a 15-second cinematic/lifestyle video from the selected image. Subject/context: {subject}. Add context, smooth cinematic camera movement, emotional reveal, final hero frame with empty space for message/CTA overlay, no watermark, no broken text. {guard}"
    if idx == 1:
        return f"Tạo video 5 giây từ ảnh đã chọn. Chủ thể/bối cảnh: {subject}. Camera tiến nhẹ vào sản phẩm, parallax rất nhẹ, giữ sản phẩm rõ nét, ánh sáng sạch, phù hợp test nhanh/chi phí thấp, không watermark, không chữ thừa. {guard}"
    if idx == 2:
        return f"Tạo video quảng cáo ngắn 10 giây từ ảnh đã chọn. Chủ thể/bối cảnh: {subject}. Mở đầu bằng hook rõ, reveal sản phẩm/dịch vụ, nêu một lợi ích chính, kết thúc bằng khung sạch có khoảng trống để thêm CTA sau, chuyển động camera mượt, không méo hình. {guard}"
    return f"Tạo video cinematic/lifestyle 15 giây từ ảnh đã chọn. Chủ thể/bối cảnh: {subject}. Có bối cảnh sử dụng, chuyển động camera mượt, reveal cảm xúc, cảnh cuối là hero frame sạch để chèn thông điệp/CTA sau, không watermark, không chữ lỗi. {guard}"

