def image_to_video_public_off_prompt(job_id: int = 0, user_id=0, lang: str = "vi") -> str:
    job = shopaikey_job_by_id(int(job_id or 0)) if int(job_id or 0) else None
    prompt_preview = str((job or {}).get("prompt_preview") or "").strip()
    if not prompt_preview:
        recent = get_recent_media_state(LAST_USER_IMAGE, safe_int(user_id, 0))
        prompt_preview = str((recent or {}).get("caption") or (recent or {}).get("file_name") or "").strip()
    subject = prompt_preview or (
        "selected image / product scene"
        if normalize_user_language(lang) != "zh" else
        "已选择的图片 / 产品场景"
    )
    prompt = (
        f"Animate the selected image into a short clean product video. Subject/context: {subject}. "
        "Use slow push-in, subtle parallax, stable subject, clean lighting, premium commercial style, "
        "soft reveal, no watermark, no extra text, no distorted hands or faces. Duration 5 seconds, 16:9 or 9:16 depending on the source image."
    )
    text = ui_text(lang, "video.from_image_public_off", prompt=html.escape(prompt[:900]))
    if is_admin_user(user_id):
        text += "\n\n" + ui_text(lang, "video.admin_smoke_warning")
    return text

VIDEO_FINALIZATION_STATE_TTL_SECONDS = 30 * 60
VIDEO_FINALIZATION_LOCK_SECONDS = 12

def video_finalization_pending_key(user_id) -> str:
    return f"video_finalization:{user_id}"

def video_finalization_defaults() -> dict:
    return {
        "music_enabled": False,
        "music_mode": "none",
        "music_prompt": "",
        "music_file_id": "",
        "voice_enabled": False,
        "voice_mode": "none",
        "voice_text": "",
        "voice_file_id": "",
        "voice_language": "",
        "voice_style": "natural",
        "subtitle_enabled": False,
        "subtitle_mode": "none",
        "subtitle_text": "",
        "subtitle_language": "",
        "subtitle_burn_in": False,
        "dub_enabled": False,
        "dub_language": "",
        "translation_enabled": False,
        "music_item_count": 0,
        "subtitle_dub_enabled": False,
        "finalization_confirmed": False,
    }

def video_finalization_payload(state: dict | None = None) -> dict:
    state = dict(state or {})
    finalization = video_finalization_defaults()
    finalization.update(dict(state.get("video_finalization") or {}))
    payload = dict(state.get("source_payload") or {})
    music_mode = str(finalization.get("music_mode") or "none").strip().lower()
    payload.update({
        "video_finalization": finalization,
        "video_finalization_confirmed": bool(finalization.get("finalization_confirmed")),
        "music_option": music_mode if finalization.get("music_enabled") else "none",
        "music_choice": {
            "type": music_mode if finalization.get("music_enabled") else "none",
            "label": (
                "Nhạc tải lên" if music_mode == "uploaded"
                else "SFX có sẵn" if music_mode == "sfx_library"
                else "Nhạc AI" if music_mode == "ai_music"
                else "Nhạc nền gợi ý" if finalization.get("music_enabled")
                else "Không dùng nhạc"
            ),
        },
        "music_file_id": str(finalization.get("music_file_id") or "")[:220],
        "music_prompt": str(finalization.get("music_prompt") or "")[:1000],
        "music_item_count": int(finalization.get("music_item_count") or 0),
        "subtitle_option": (
            "subtitle_translated" if finalization.get("translation_enabled") and finalization.get("subtitle_enabled")
            else "subtitle_original" if finalization.get("subtitle_enabled")
            else "none"
        ),
        "dubbing_option": (
            "dub_translated" if finalization.get("translation_enabled") and (finalization.get("dub_enabled") or finalization.get("voice_enabled"))
            else "dub_original" if finalization.get("dub_enabled") or finalization.get("voice_enabled")
            else "none"
        ),
        "translation_enabled": bool(finalization.get("translation_enabled")),
        "target_language": str(finalization.get("subtitle_language") or finalization.get("voice_language") or finalization.get("dub_language") or "")[:80],
        "voice_style": str(finalization.get("voice_style") or "natural")[:80],
        "voice_text": str(finalization.get("voice_text") or "")[:3000],
        "voice_file_id": str(finalization.get("voice_file_id") or "")[:220],
        "subtitle_text": str(finalization.get("subtitle_text") or "")[:3000],
    })
    payload["video_project"] = build_video_project(
        state.get("user_id") or state.get("owner_user_id") or "",
        state.get("source") or payload.get("source_flow") or payload.get("source") or "video_plan",
        payload,
        finalization,
    )
    return payload

def set_video_finalization_state(user_id, state: dict) -> dict:
    now_ts = time.time()
    clean = dict(state or {})
    finalization = video_finalization_defaults()
    finalization.update(dict(clean.get("video_finalization") or {}))
    clean["video_finalization"] = finalization
    clean["pending_action"] = "video_finalization"
    clean.setdefault("step", "menu")
    clean.setdefault("session_id", hashlib.sha256(f"{user_id}:{now_ts}".encode("utf-8")).hexdigest()[:12])
    clean.setdefault("created_at_ts", now_ts)
    clean["updated_at_ts"] = now_ts
    clean["expires_at_ts"] = now_ts + VIDEO_FINALIZATION_STATE_TTL_SECONDS
    clean.setdefault("source", "video_plan")
    clean.setdefault("source_label", "")
    clean.setdefault("back_callback", "menu|main_video")
    clean.setdefault("photos", [])
    clean.setdefault("source_payload", {})
    USER_PENDING[video_finalization_pending_key(user_id)] = clean
    return clean

def get_video_finalization_state(user_id) -> dict:
    key = video_finalization_pending_key(user_id)
    state = USER_PENDING.get(key) or {}
    if state.get("pending_action") != "video_finalization":
        if state:
            USER_PENDING.pop(key, None)
        return {}
    if float(state.get("expires_at_ts") or 0) < time.time():
        USER_PENDING.pop(key, None)
        return {}
    return state

def clear_video_finalization_state(user_id) -> bool:
    return USER_PENDING.pop(video_finalization_pending_key(user_id), None) is not None

def update_video_finalization(user_id, **fields) -> dict:
    state = get_video_finalization_state(user_id)
    if not state:
        return {}
    finalization = video_finalization_defaults()
    finalization.update(dict(state.get("video_finalization") or {}))
    finalization.update(fields)
    state["video_finalization"] = finalization
    return set_video_finalization_state(user_id, state)

