async def cmd_feature_status(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    providers = provider_status_payload()
    features = [
        ("ai_image", "AI Image", providers["media_factory"].get("image_openai_generation_env")),
        ("ai_image_edit", "AI Image Edit", providers["media_factory"].get("image_openai_edit_env")),
        ("real_video", "Real Video", providers["media_factory"].get("real_video_env")),
        ("trend_live", "Trend Live", providers["media_factory"].get("trend_live_env")),
        ("stability_image", "Stability Image", providers["image"].get("stability")),
        ("image_upscale", "Image Upscale", providers["image"].get("upscale")),
        ("elevenlabs_tts", "ElevenLabs TTS", providers["audio"].get("elevenlabs")),
        ("auphonic_audio_enhance", "Auphonic Audio Enhance", providers["audio"].get("auphonic")),
        ("kling_video", "Kling Video", providers["video"].get("kling")),
        ("runway_video", "Runway Video", providers["video"].get("runway")),
        ("heygen_avatar", "HeyGen Avatar", providers["video"].get("heygen")),
        ("downloader", "Downloader", ENABLE_DOWNLOADER_PUBLIC),
        ("remove_bg", "RemoveBG/Cutout", providers["image"].get("ready")),
        ("auto_publish", "Auto Publish", ENABLE_AUTO_PUBLISH),
        ("customer_publish", "Customer Publish", ENABLE_CUSTOMER_PUBLISH),
        ("ads_assistant", "Ads Assistant", ENABLE_ADS_ASSISTANT),
    ]
    lines = [
        "🧭 <b>TOAN AAS Feature Release Status</b>",
        "",
        "<code>configured</code> = có env/provider/flag liên quan. <code>public</code> = đã mở cho khách.",
        "",
    ]
    for key, label, configured in features:
        result = get_tool_test_result(key)
        stage = configured_release_stage(key)
        lines.append(
            f"• {html.escape(label)}: stage <code>{html.escape(stage)}</code> | "
            f"configured <code>{'yes' if configured else 'no'}</code> | "
            f"tested <code>{html.escape(result.get('status') or 'NOT_TESTED')}</code> | "
            f"public <code>{'ON' if stage == 'PUBLIC_READY' else 'OFF'}</code>"
        )
    lines.extend([
        "",
        "Owner set stage: <code>/feature_set ai_image ADMIN_ONLY</code>",
        "Allowed: <code>PLANNED</code>, <code>ADMIN_ONLY</code>, <code>BETA_PRIVATE</code>, <code>PUBLIC_READY</code>, <code>DISABLED</code>",
        "Lưu ý: đổi stage không tự tạo API key, không tự bật env và không bỏ qua smoke test.",
    ])
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_feature_set(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    if not is_owner_user(uid):
        return await update.message.reply_text(owner_required_text(uid), parse_mode="HTML")
    if len(context.args or []) < 2:
        return await update.message.reply_text(
            "⚠️ Cú pháp: /feature_set FEATURE STATUS\n"
            "Ví dụ: /feature_set ai_image ADMIN_ONLY\n"
            "STATUS: PLANNED, ADMIN_ONLY, BETA_PRIVATE, PUBLIC_READY, DISABLED"
        )
    feature = normalize_feature_key(context.args[0])
    stage = normalize_release_stage(context.args[1])
    if not stage:
        return await update.message.reply_text("❌ STATUS không hợp lệ. Dùng PLANNED, ADMIN_ONLY, BETA_PRIVATE, PUBLIC_READY hoặc DISABLED.")
    set_system_flag(f"feature_stage:{feature}", stage, updated_by=uid, note="Owner updated feature release stage")
    await update.message.reply_text(
        "✅ Đã cập nhật feature stage.\n\n"
        f"• Feature: <code>{html.escape(feature)}</code>\n"
        f"• Stage: <code>{html.escape(stage)}</code>\n\n"
        "Lưu ý: stage chỉ là release gate. Provider/env/smoke test vẫn phải cấu hình và kiểm tra riêng.",
        parse_mode="HTML",
    )

async def cmd_admin_trend_video(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Chức năng này chỉ dành cho admin.")
    topic = media_factory_topic_from_args(context)
    if not topic:
        return await update.message.reply_text("⚠️ Cú pháp: /admin_trend_video <chủ đề>")
    fallback = fallback_media_factory_pack(topic)
    prompt = "Bạn là TOAN AAS Admin Trend-to-Video Pipeline. Tạo draft review nội bộ từ trend sang video pack. Không publish. Trả đầy đủ pack để admin review."
    output = media_factory_ai(prompt, topic, f"admin_trend_video_{update.effective_user.id}", fallback)
    job_id = create_media_factory_job(update.effective_user.id, media_factory_username(update), "admin_trend_video", topic, trend_title=topic, trend_summary=output[:1200], image_prompt_pack=output, video_prompt_pack=output, caption_pack=output, status="pending_review", cost_xu=0, note="admin_first_publish_off")
    await update.message.reply_text(
        "✅ Đã tạo Admin Trend-to-Video Draft\n\n"
        f"Job ID: {job_id}\n"
        f"Chủ đề: {topic}\n"
        "Trạng thái: pending_review\n\n"
        f"Lệnh tiếp:\n/review_job {job_id}\n/approve_job {job_id}\n/reject_job {job_id} <lý do>\n/publish_queue chỉ khi admin_publish bật"
    )

async def cmd_review_job(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Chức năng này chỉ dành cho admin.")
    try:
        job_id = int(context.args[0])
    except (IndexError, ValueError):
        return await update.message.reply_text("⚠️ Cú pháp: /review_job <job_id>")
    job = get_media_factory_job(job_id)
    if not job:
        return await update.message.reply_text("❌ Không tìm thấy Media Factory job.")
    content = job.get("caption_pack") or job.get("video_prompt_pack") or job.get("image_prompt_pack") or job.get("trend_summary") or ""
    await reply_long_text(update, f"🔎 REVIEW JOB #{job_id}\nStatus: {job.get('status')}\nMode: {job.get('mode')}\nTopic: {job.get('topic')}\n\n{content}")

async def cmd_approve_job(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Chức năng này chỉ dành cho admin.")
    try:
        job_id = int(context.args[0])
    except (IndexError, ValueError):
        return await update.message.reply_text("⚠️ Cú pháp: /approve_job <job_id>")
    if not update_media_factory_job_status(job_id, "approved", approved_by=update.effective_user.id, note="Admin approved content; publish remains gated."):
        return await update.message.reply_text("❌ Không tìm thấy job.")
    publish_on = is_feature_enabled("admin_publish", update.effective_user.id, default=False)
    note = "Publish vẫn đang tắt." if not publish_on else "Admin publish flag đang bật, vẫn cần dùng publish queue riêng."
    await update.message.reply_text(f"✅ Đã duyệt nội dung job #{job_id}. {note}")

async def cmd_reject_job(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Chức năng này chỉ dành cho admin.")
    try:
        job_id = int(context.args[0])
    except (IndexError, ValueError):
        return await update.message.reply_text("⚠️ Cú pháp: /reject_job <job_id> <lý do>")
    reason = " ".join(context.args[1:]).strip() or "Admin rejected"
    if not update_media_factory_job_status(job_id, "rejected", approved_by=update.effective_user.id, note=reason):
        return await update.message.reply_text("❌ Không tìm thấy job.")
    await update.message.reply_text(f"✅ Đã reject job #{job_id}. Lý do: {reason}")

