def package_purchase_detail_lines(package_type: str, code: str) -> list[str]:
    package_type = "monthly" if str(package_type or "").strip().lower() in {"monthly", "month", "plan"} else "combo"
    code = str(code or "").strip().lower()
    entry = package_catalog_entry(code, package_type)
    if not entry:
        return ["⚠️ <b>Gói không hợp lệ</b>", "", "Bot chưa tạo đơn và chưa trừ Xu."]
    kind = package_purchase_kind_label(package_type)
    label = str(entry.get("label") or code)
    price = package_purchase_price_vnd(package_type, code)
    price_text = f"{price:,}đ".replace(",", ".") if price > 0 else "liên hệ admin"
    duration_days = int(entry.get("default_days") or 0) if package_type == "monthly" else 0
    rows = [
        f"🎁 <b>{html.escape(kind)}: {html.escape(label)}</b>", "",
        f"• Giá: <b>{html.escape(price_text)}</b>" + ("/tháng" if package_type == "monthly" and price > 0 else ""),
    ]
    if duration_days:
        rows.append(f"• Thời hạn: <b>{duration_days} ngày</b>")
    rows.extend([
        f"• Quyền lợi: {html.escape(package_items_summary(entry.get('items') or {}))}",
        f"• Phù hợp: {html.escape(str(entry.get('note') or 'Dùng dịch vụ theo lượt/quyền trong gói.'))}", "",
        "Sau khi PayOS xác nhận thanh toán, gói/combo sẽ nằm trong <b>📦 Gói của tôi</b>.",
        "Khi dùng công cụ thuộc gói, hệ thống ưu tiên trừ lượt/quyền trong gói nếu còn.", "",
        "Gói/Combo không phải nạp Xu thường, không cộng bonus nạp Xu và không tự nâng hạng thành viên.", "",
        "Bạn có muốn thanh toán sản phẩm này không?",
    ])
    return rows

def package_purchase_confirm_keyboard(package_type: str, code: str) -> InlineKeyboardMarkup:
    package_type = "monthly" if str(package_type or "").strip().lower() in {"monthly", "month", "plan"} else "combo"
    code = str(code or "").strip().lower()
    back_action = "pricing|plans" if package_type == "monthly" else "pricing|combo"
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("✅ Xác nhận thanh toán", callback_data=f"pkgbuy|confirm|{package_type}|{code}"), InlineKeyboardButton("⬅️ Hủy", callback_data=back_action)],
        [InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")],
    ])

async def start_package_purchase(update: Update, context: ContextTypes.DEFAULT_TYPE, package_type: str, code: str, message=None):
    message = message or update.message
    uid = update.effective_user.id
    package_type = "monthly" if str(package_type or "").strip().lower() in {"monthly", "month", "plan"} else "combo"
    code = str(code or "").strip().lower()
    entry = package_catalog_entry(code, package_type)
    if not entry or entry.get("manual"):
        return await message.reply_text(
            "⚠️ Gói này cần admin hỗ trợ. Bot chưa tạo đơn và chưa trừ Xu.",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("📞 Liên hệ admin", callback_data="menu|support")],
                [InlineKeyboardButton("🔙 Quay lại bảng giá", callback_data="pricing|plans" if package_type == "monthly" else "pricing|combo")],
            ]),
        )
    get_user(uid, update.effective_user.first_name or update.effective_user.username or "")
    if package_type == "monthly":
        existing = resolve_package_for_user(uid, code)
        if existing and str(existing.get("status") or "") == "active" and not package_expired(existing.get("expires_at") or ""):
            return await message.reply_text(
                "⚠️ Bạn đang có gói tháng này còn hiệu lực.\n\n"
                "Vui lòng dùng hết hoặc chờ hết kỳ trước khi mua lại cùng gói. Bot chưa tạo đơn mới.",
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("📦 Gói của tôi", callback_data="pricing|my_packages")],
                    [InlineKeyboardButton("🔙 Quay lại bảng giá", callback_data="pricing|plans")],
                ]),
            )
    amount = package_purchase_price_vnd(package_type, code)
    if amount <= 0:
        return await message.reply_text(
            "⚠️ Giá gói này chưa cấu hình tự động.\n\n"
            "Vui lòng bấm Liên hệ admin để được hỗ trợ. Bot chưa tạo đơn, chưa cộng/trừ Xu.",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("📞 Liên hệ admin", callback_data="menu|support")],
                [InlineKeyboardButton("📦 Gói của tôi", callback_data="pricing|my_packages")],
                [InlineKeyboardButton("🔙 Quay lại bảng giá", callback_data="pricing|plans" if package_type == "monthly" else "pricing|combo")],
            ]),
        )
    if flag_on("emergency_lock") or flag_on("payment_freeze"):
        return await message.reply_text("⚠️ Thanh toán đang tạm khóa an toàn. Bot chưa tạo đơn gói dịch vụ.")
    if not PAYOS_CLIENT_ID or not PAYOS_API_KEY or not PAYOS_CHECKSUM_KEY:
        return await message.reply_text("❌ Chưa cấu hình đủ PayOS để mua gói dịch vụ. Bot chưa tạo đơn.")

    order_code = generate_order_code()
    duration_days = int(entry.get("default_days") or 0) if package_type == "monthly" else 0
    label = str(entry.get("label") or code)
    item_summary = package_items_summary(entry.get("items") or {})
    created_at = now_text()
    expires_at = datetime_text(datetime.now() + timedelta(minutes=ORDER_TTL_MINUTES))
    payment_type = "monthly_package_purchase" if package_type == "monthly" else "combo_purchase"
    metadata = {
        "type": "package_purchase",
        "payment_type": payment_type,
        "item_id": code,
        "user_id": str(uid),
        "amount_vnd": int(amount),
        "status": "pending",
        "created_at": created_at,
        "expires_at": expires_at,
        "note": f"{payment_type}:{code}",
        "package_type": package_type,
        "package_code": code,
        "package_label": label,
        "telegram_user_id": str(uid),
        "duration_days": duration_days,
    }
    create_order(
        order_code,
        uid,
        amount,
        0,
        base_xu=0,
        launch_bonus_xu=0,
        package_amount_vnd=0,
        order_type="package_purchase",
        plan_id=code,
        plan_name=label,
        duration_days=duration_days,
        plan_xu=0,
        metadata_json=json.dumps(metadata, ensure_ascii=False),
    )
    return_url = make_payos_return_url(context)
    payos_body = {
        "orderCode": int(order_code),
        "amount": int(amount),
        "description": package_purchase_description(package_type, code),
        "cancelUrl": make_payos_cancel_url(context),
        "returnUrl": return_url,
    }
    try:
        res, res_data, raw_preview, _raw_str = await create_payos_payment_request(payos_body)
        data = res_data if isinstance(res_data, dict) else {}
        checkout_data = data.get("data") if isinstance(data.get("data"), dict) else {}
        checkout_url = checkout_data.get("checkoutUrl", "")
        payment_link_id = checkout_data.get("paymentLinkId", "")
        if getattr(res, "status_code", "") == 200 and data.get("code") == "00" and checkout_url:
            update_order_checkout_info(order_code, checkout_url, payment_link_id)
            record_usage_event(
                uid,
                username=update.effective_user.username or update.effective_user.first_name or "",
                event_type="package_purchase_created",
                tool_name="package_wallet",
                command="/pricing_button",
                status="pending",
                amount_vnd=amount,
                provider="payos",
                detail=f"order={order_code}; package_type={package_type}; code={code}; counts_for_member_tier=false",
            )
            kind = package_purchase_kind_label(package_type)
            expires_line = f"• Thời hạn: <b>{duration_days} ngày</b>\n" if duration_days else ""
            return await message.reply_text(
                f"📦 <b>Thanh toán {html.escape(kind)}</b>\n\n"
                f"• Tên: <b>{html.escape(label)}</b>\n"
                f"• Giá: <b>{amount:,}đ</b>\n"
                f"{expires_line}"
                f"• Lượt sau khi thanh toán: {html.escape(item_summary)}\n"
                "• Sau khi PayOS xác nhận, bot tự lưu vào <b>📦 Gói của tôi</b>.\n"
                "• Khi dùng dịch vụ, bot tự gợi ý dùng lượt trong gói và trừ lượt nếu bạn chọn.\n"
                "• Không cộng Xu, không tính điểm nâng hạng, không chạy bonus nạp.\n\n"
                f"• Mã đơn: <code>{order_code}</code>",
                parse_mode="HTML",
                reply_markup=package_purchase_checkout_keyboard(checkout_url, package_type),
            )
        update_order_status(order_code, PAYOS_STATUS_CANCELLED)
        return await message.reply_text(
            "❌ PayOS chưa tạo được link thanh toán gói dịch vụ.\n"
            "Bot chưa kích hoạt gói, chưa cộng/trừ Xu.\n\n"
            f"Chi tiết ngắn: <code>{html.escape(str(data.get('desc') or data.get('message') or raw_preview or '-')[:220])}</code>",
            parse_mode="HTML",
        )
    except Exception as e:
        update_order_status(order_code, PAYOS_STATUS_CANCELLED)
        logger.warning("Package PayOS create failed: %s", sanitize_log_text(str(e))[:220])
        return await message.reply_text(
            "❌ PayOS chưa tạo được link thanh toán gói dịch vụ.\n"
            "Bot chưa kích hoạt gói, chưa cộng/trừ Xu.",
        )

async def start_plan_purchase(update: Update, context: ContextTypes.DEFAULT_TYPE, plan_id: str, message=None):
    message = message or update.message
    uid = update.effective_user.id
    plan_id = normalize_plan_id(plan_id)
    if not plan_id:
        return await message.reply_text(
            "⚠️ Gói tháng không hợp lệ.\n\n"
            "Vui lòng mở <b>💳 Bảng giá</b> → <b>📆 Gói tháng</b> rồi bấm gói muốn mua. Bot chưa tạo đơn.",
            parse_mode="HTML",
        )
    plan = PLAN_CATALOG[plan_id]
    get_user(uid, update.effective_user.first_name or update.effective_user.username or "")
    allowed, reason = user_can_buy_plan(uid, plan_id)
    if not allowed:
        return await message.reply_text(
            "⚠️ <b>Bạn chưa đủ điều kiện mua gói này.</b>\n\n"
            f"• Gói: <b>{html.escape(plan['name'])}</b>\n"
            f"• Điều kiện: <b>{html.escape(plan_required_tier_label(plan_id))}</b>\n"
            f"• Chi tiết: {html.escape(reason)}\n\n"
            "Bạn có thể nạp Xu để đạt hạng thành viên phù hợp: <code>/naptien</code>\n"
            "Lưu ý: tiền mua gói tháng không tính nâng hạng thành viên.\n"
            "Bot chưa trừ Xu.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("💳 Nạp Xu", callback_data="menu|main_topup")],
                [InlineKeyboardButton("📦 Xem gói tháng", callback_data="pricing|plans")],
            ]),
        )
    monthly_allowed, monthly_reason = can_purchase_monthly_plan(uid, plan_id)
    if not monthly_allowed:
        return await message.reply_text(
            "⚠️ <b>Gói tháng đã được mua trong tháng này.</b>\n\n"
            f"{html.escape(monthly_reason)}\n\n"
            "Bot chưa tạo checkout mới và chưa kích hoạt gói mới.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("📦 Xem gói tháng", callback_data="pricing|plans")],
                [InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")],
            ]),
        )
    if flag_on("emergency_lock") or flag_on("payment_freeze"):
        return await message.reply_text("⚠️ Thanh toán đang tạm khóa an toàn. Bot chưa tạo đơn gói tháng.")
    if not PAYOS_CLIENT_ID or not PAYOS_API_KEY or not PAYOS_CHECKSUM_KEY:
        return await message.reply_text("❌ Chưa cấu hình đủ PayOS để mua gói tháng. Bot chưa tạo đơn.")

    order_code = generate_order_code()
    amount = int(plan["price_vnd"])
    duration_days = int(plan["duration_days"])
    plan_xu = int(plan["plan_xu"])
    order_note = f"TOAN AAS PLAN {plan['name'].upper()} {duration_days}D USER {uid}"
    metadata = {
        "note": order_note,
        "type": "plan_purchase",
        "plan_id": plan_id,
        "plan_name": plan["name"],
        "telegram_user_id": str(uid),
        "duration_days": duration_days,
        "plan_xu": plan_xu,
    }
    create_order(
        order_code,
        uid,
        amount,
        0,
        base_xu=0,
        launch_bonus_xu=0,
        package_amount_vnd=0,
        order_type="plan_purchase",
        plan_id=plan_id,
        plan_name=plan["name"],
        duration_days=duration_days,
        plan_xu=plan_xu,
        metadata_json=json.dumps(metadata, ensure_ascii=False),
    )
    return_url = make_payos_return_url(context)
    payos_body = {
        "orderCode": int(order_code),
        "amount": int(amount),
        "description": make_payos_plan_description(plan_id),
        "cancelUrl": make_payos_cancel_url(context),
        "returnUrl": return_url,
    }
    try:
        res, res_data, raw_preview, _raw_str = await create_payos_payment_request(payos_body)
        data = res_data if isinstance(res_data, dict) else {}
        checkout_data = data.get("data") if isinstance(data.get("data"), dict) else {}
        checkout_url = checkout_data.get("checkoutUrl", "")
        payment_link_id = checkout_data.get("paymentLinkId", "")
        if getattr(res, "status_code", "") == 200 and data.get("code") == "00" and checkout_url:
            update_order_checkout_info(order_code, checkout_url, payment_link_id)
            record_usage_event(
                uid,
                username=update.effective_user.username or update.effective_user.first_name or "",
                event_type="plan_purchase_created",
                tool_name="subscription",
                command="/buy_plan",
                status="pending",
                amount_vnd=amount,
                provider="payos",
                detail=f"order={order_code}; plan={plan_id}; type=plan_purchase",
            )
            return await message.reply_text(
                f"📦 <b>Thanh toán gói {html.escape(plan['name'])}</b>\n\n"
                f"• Giá: <b>{amount:,}đ</b>\n"
                f"• Thời hạn: <b>{duration_days} ngày</b>\n"
                f"• Hạn mức: <b>{plan_xu:,} Xu xử lý/tháng</b>\n"
                f"• Điều kiện: <b>{html.escape(plan_required_tier_label(plan_id))}</b>\n"
                "• Ghi chú: tiền mua gói không tính vào tổng nạp nâng hạng.\n\n"
                f"• Mã đơn: <code>{order_code}</code>\n"
                f"• Nội dung nội bộ: <code>{html.escape(order_note)}</code>\n\n"
                "Bấm thanh toán bên dưới. Sau khi PayOS xác nhận thành công, bot sẽ tự kích hoạt gói.",
                parse_mode="HTML",
                reply_markup=plan_purchase_keyboard(checkout_url),
            )
        update_order_status(order_code, PAYOS_STATUS_CANCELLED)
        return await message.reply_text(
            "❌ PayOS chưa tạo được link thanh toán gói tháng.\n"
            "Bot chưa kích hoạt gói và chưa cộng/trừ Xu.\n\n"
            f"Chi tiết ngắn: <code>{html.escape(str(data.get('desc') or data.get('message') or raw_preview or '-')[:220])}</code>",
            parse_mode="HTML",
        )
    except Exception as e:
        update_order_status(order_code, PAYOS_STATUS_CANCELLED)
        logger.warning(f"Plan PayOS create failed: {e}")
        return await message.reply_text(
            "❌ PayOS chưa tạo được link thanh toán gói tháng.\n"
            "Bot chưa kích hoạt gói và chưa cộng/trừ Xu.",
        )

async def cmd_buy_plan(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text(
            "📆 Gói tháng hiện mua bằng nút trong Bảng giá.\n\n"
            "Vui lòng mở <b>💳 Bảng giá</b> → <b>📆 Gói tháng</b> rồi bấm gói muốn mua. Bot chưa tạo đơn.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("📆 Gói tháng", callback_data="pricing|plans")],
                [InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")],
            ]),
        )
