def build_chat_pro_prompt(user_prompt, tier=CHAT_TIER_PRO, model_level="standard"):
    tier_norm = normalize_chat_tier(tier)
    model_norm = normalize_chat_model(model_level)
    depth_line = (
        "Phân tích như cố vấn chiến lược/senior expert. Đưa kế hoạch, rủi ro, checklist hành động và ưu tiên rõ ràng."
        if tier_norm == CHAT_TIER_DEEP or model_norm in CHAT_ADVANCED_MODEL_LEVELS
        else "Trả lời sâu, có cấu trúc, thực chiến, không lan man."
    )
    return (
        "Bạn là Chat Pro của TOAN AAS.\n"
        f"{depth_line}\n"
        "Luôn trả lời tiếng Việt, trung thực, không bịa chắc chắn, không hứa kết quả doanh thu.\n"
        "Nếu thiếu dữ liệu, nói rõ giả định và đề xuất bước kiểm chứng.\n"
        "Khi phù hợp, xuất theo cấu trúc: Tóm tắt, Phân tích, Kế hoạch, Rủi ro, Việc làm ngay.\n\n"
        f"Yêu cầu của user:\n{user_prompt}"
    )

def call_chat_pro_ai(user_prompt: str, provider_payload: dict, user_id=None) -> str:
    if not provider_payload.get("ready"):
        raise RuntimeError(provider_payload.get("reason") or "Provider chưa sẵn sàng")
    provider = provider_payload.get("provider")
    system_prompt = build_chat_pro_prompt(
        user_prompt,
        provider_payload.get("tier", CHAT_TIER_PRO),
        provider_payload.get("model", "standard"),
    )
    try:
        if provider == "gemini" and gemini_client:
            res = gemini_client.models.generate_content(
                model="gemini-2.0-flash",
                config=types.GenerateContentConfig(system_instruction=system_prompt),
                contents=user_prompt,
            )
            output = res.text
        elif provider == "openai" and openai_client:
            res = openai_client.chat.completions.create(
                model="gpt-4o-mini",
                messages=[
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": user_prompt},
                ],
                max_tokens=1800,
            )
            output = res.choices[0].message.content
        else:
            raise RuntimeError(provider_payload.get("reason") or "Provider chưa sẵn sàng")
    except Exception as e:
        raise RuntimeError(f"{provider or 'AI'} error: {type(e).__name__}") from e
    output = (output or "").strip()
    if not output or output.startswith("❌"):
        raise RuntimeError(output or "AI không trả kết quả")
    return output

def chat_mode_cost(mode: str) -> int:
    mode_norm = normalize_chat_tier(mode or CHAT_TIER_NORMAL)
    if mode_norm == CHAT_TIER_DEEP:
        return CHAT_COST_DEEP_BASE
    if mode_norm == CHAT_TIER_PRO:
        return CHAT_COST_PRO
    return CHAT_COST_NORMAL

def chat_mode_instruction(mode: str) -> str:
    mode_norm = normalize_chat_tier(mode or CHAT_TIER_NORMAL)
    if mode_norm == CHAT_TIER_PRO:
        return (
            "Bạn là Trợ Lý Ảo TOAN AAS ở Chat Pro. "
            "Trả lời chi tiết hơn, có phân tích, checklist thực tế và bước hành động rõ ràng."
        )
    if mode_norm == CHAT_TIER_DEEP:
        return (
            "Bạn là Trợ Lý Ảo TOAN AAS ở Chat Deep. "
            "Phân tích sâu, có cấu trúc, chỉ ra rủi ro, giả định, kế hoạch triển khai và hành động ưu tiên."
        )
    return "Bạn là Trợ Lý Ảo TOAN AAS. Trả lời ngắn gọn, thực dụng, thân thiện."

def ai_failure_user_text(statuses: dict, errors: dict) -> str:
    return (
        "⚠️ AI chat đang bận hoặc hết quota tạm thời.\n"
        "Bot chưa trừ Xu. Vui lòng thử lại sau."
    )

def ai_failure_detail(statuses: dict, errors: dict) -> str:
    gemini = f"Gemini={str((statuses or {}).get('gemini') or 'MISSING').upper()}"
    openai = f"OpenAI={str((statuses or {}).get('openai') or 'MISSING').upper()}"
    shopaikey = f"ShopAIKey={str((statuses or {}).get('shopaikey') or 'MISSING').upper()}"
    details = []
    for key in ("gemini", "openai", "shopaikey"):
        err = str((errors or {}).get(key) or "").strip()
        if err:
            details.append(f"{key}:{err[:180]}")
    return "; ".join([gemini, openai, shopaikey, *details])[:900]

def is_ai_failure_text(value: str) -> bool:
    text = str(value or "").strip().lower()
    if not text:
        return True
    return any(marker in text for marker in (
        "lỗi cả gemini lẫn openai",
        "không có ai provider",
        "chưa cấu hình ai provider",
        "ai đang tạm hết quota",
        "ai chat đang bận",
    ))

async def call_ai_chat_with_fallback(system_prompt: str, user_text: str, user_id, max_tokens: int = 1200) -> dict:
    statuses = {"gemini": "MISSING", "openai": "MISSING", "shopaikey": "MISSING"}
    errors = {}
    uid_key = user_id

    if gemini_client:
        statuses["gemini"] = "TRYING"
        try:
            if uid_key not in user_memory:
                user_memory[uid_key] = []
            user_memory[uid_key].append(types.Content(role="user", parts=[types.Part(text=user_text)]))
            if len(user_memory[uid_key]) > 10:
                user_memory[uid_key] = user_memory[uid_key][-10:]

            def run_gemini():
                return gemini_client.models.generate_content(
                    model="gemini-2.0-flash",
                    config=types.GenerateContentConfig(system_instruction=system_prompt),
                    contents=user_memory[uid_key],
                )

            res = await asyncio.to_thread(run_gemini)
            output = (getattr(res, "text", "") or "").strip()
            if is_ai_failure_text(output):
                raise RuntimeError(output or "Gemini empty_response")
            user_memory[uid_key].append(types.Content(role="model", parts=[types.Part(text=output)]))
            statuses["gemini"] = "PASS"
            record_api_debug("gemini", "ai_chat", "PASS", 0, f"mode_chat_success chars={len(output)}")
            return {"ok": True, "provider": "gemini", "text": output, "statuses": statuses, "errors": errors}
        except Exception as e:
            statuses["gemini"] = "FAIL"
            errors["gemini"] = provider_error_summary(e)
            record_api_debug("gemini", "ai_chat", "FAIL", 0, errors["gemini"])
            logger.warning(f"AI chat Gemini fallback: {errors['gemini']}")

    if openai_client:
        statuses["openai"] = "TRYING"
        try:
            messages = [{"role": "system", "content": system_prompt}]
            if uid_key in user_memory:
                for item in user_memory[uid_key][-6:]:
                    try:
                        role = "user" if getattr(item, "role", "") == "user" else "assistant"
                        content = item.parts[0].text
                    except Exception:
                        continue
                    if content:
                        messages.append({"role": role, "content": content})
            messages.append({"role": "user", "content": user_text})

            def run_openai():
                return openai_client.chat.completions.create(
                    model=OPENAI_TEXT_MODEL,
                    messages=messages,
                    max_tokens=max_tokens,
                )

            res = await asyncio.to_thread(run_openai)
            output = ((res.choices[0].message.content if res and res.choices else "") or "").strip()
            if is_ai_failure_text(output):
                raise RuntimeError(output or "OpenAI empty_response")
            statuses["openai"] = "PASS"
            record_api_debug("openai", "ai_chat", "PASS", 0, f"mode_chat_success chars={len(output)}")
            return {"ok": True, "provider": "openai", "text": output, "statuses": statuses, "errors": errors}
        except Exception as e:
            statuses["openai"] = "FAIL"
            errors["openai"] = provider_error_summary(e)
            record_api_debug("openai", "ai_chat", "FAIL", 0, errors["openai"])
            logger.warning(f"AI chat OpenAI error: {errors['openai']}")

    if shopaikey_public_chat_fallback_enabled():
        statuses["shopaikey"] = "TRYING"
        try:
            result = await shopaikey_chat_completion(system_prompt, user_text, user_id, max_tokens=max_tokens)
            attempts = result.get("attempts") or []
            if result.get("ok") and str(result.get("text") or "").strip():
                output = str(result.get("text") or "").strip()
                statuses["shopaikey"] = "PASS"
                model = str(result.get("model") or "")
                record_api_debug("shopaikey", "ai_chat", "PASS", 0, f"model={model}; chars={len(output)}; attempts=" + ",".join(f"{a.get('model')}={a.get('status')}" for a in attempts))
                return {"ok": True, "provider": "shopaikey", "model": model, "text": output, "statuses": statuses, "errors": errors}
            statuses["shopaikey"] = str(result.get("status") or "FAIL").upper()
            errors["shopaikey"] = "; ".join(f"{a.get('model')}={a.get('status') or 'FAIL'}:{a.get('error_class') or '-'}" for a in attempts)[:300] or str(result.get("error_class") or result.get("status") or "FAIL")
            record_api_debug("shopaikey", "ai_chat", "FAIL", 0, errors["shopaikey"])
        except Exception as e:
            statuses["shopaikey"] = "FAIL"
            errors["shopaikey"] = provider_error_summary(e)
            record_api_debug("shopaikey", "ai_chat", "FAIL", 0, errors["shopaikey"])
            logger.warning(f"AI chat ShopAIKey error: {errors['shopaikey']}")

    return {
        "ok": False,
        "provider": "",
        "text": "",
        "statuses": statuses,
        "errors": errors,
        "message": ai_failure_user_text(statuses, errors),
    }

def chat_charge_line(cost: int, mode: str, is_free: bool = False, reason: str = "") -> str:
    if is_free:
        return f"(-0 Xu | {reason})" if reason else "(-0 Xu)"
    mode_norm = normalize_chat_tier(mode)
    if mode_norm == CHAT_TIER_DEEP:
        return f"(-{cost} Xu Chat Deep)"
    if mode_norm == CHAT_TIER_PRO:
        return f"(-{cost} Xu Chat Pro)"
    return f"(-{cost} Xu)"

def chat_insufficient_credits_text(mode: str, cost: int, credits: int) -> str:
    mode_norm = normalize_chat_tier(mode or CHAT_TIER_NORMAL)
    mode_label = user_mode_label({"chat_mode": mode_norm})
    off_hint = "\n• Có thể gõ /chat_pro_off hoặc /chat_deep_off để về chat thường." if mode_norm != CHAT_TIER_NORMAL else ""
    return (
        "❌ Bạn không đủ Xu để chat.\n"
        f"• Chế độ hiện tại: {mode_label}\n"
        f"• Chi phí: {int(cost)} Xu/lượt\n"
        f"• Số dư: {int(credits or 0)} Xu\n"
        "Gõ /naptien để nạp thêm."
        f"{off_hint}"
    )

def create_temp_chat_pro_file(user_id, content: str):
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = f"toan_aas_chat_pro_{user_id}_{timestamp}.md"
    with tempfile.NamedTemporaryFile("w", delete=False, suffix=".md", encoding="utf-8") as f:
        f.write(content or "")
        return f.name, filename

async def send_chat_pro_output(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user_id, output_text: str, caption: str):
    if len(output_text or "") <= 3200:
        await context.bot.send_message(chat_id=chat_id, text=f"{output_text}\n\n{caption}")
        return
    preview = truncate_text(output_text, 1800)
    await context.bot.send_message(chat_id=chat_id, text=f"{preview}\n\n{caption}\n\nĐã gửi bản đầy đủ bằng file.")
    tmp_path, filename = create_temp_chat_pro_file(user_id, output_text)
    try:
        with open(tmp_path, "rb") as f:
            await context.bot.send_document(chat_id=chat_id, document=f, filename=filename, caption="TOAN AAS Chat Pro - bản đầy đủ")
    finally:
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except Exception:
                pass

