def build_video_script_prompt(topic, niche, episodes, scenes, platforms, affiliate="", tone="", language="vi"):
    link_note = affiliate or "Không có link sản phẩm. Nếu phù hợp, hãy đề xuất CTA mềm nhưng không bịa link."
