tg_app: Application = None
tg_polling_task: asyncio.Task | None = None
tg_webhook_watchdog_task: asyncio.Task | None = None
tg_auto_backup_task: asyncio.Task | None = None
tg_memory_reminder_task: asyncio.Task | None = None
