@fastapi_app.post("/api/operator/jobs/{job_id}/approve")
async def api_operator_approve_publish(job_id: int, payload: OperatorApprovePublishRequest, request: Request):
    verify_operator_api_token(request)
    mode = (payload.mode or "manual").lower()
    if mode not in {"manual", "api"}:
        raise HTTPException(status_code=400, detail="mode must be manual or api")
    ok, reason, info = approve_publish_job(
        ADMIN_ID,
        job_id,
        note=payload.note or "api_approved_publish",
        queue=payload.queue,
        mode=mode,
        scheduled_at=payload.scheduled_at,
    )
    if not ok:
        status_code = 404 if reason == "job_not_found" else 400
        raise HTTPException(status_code=status_code, detail={"reason": reason, **info})
    if tg_app and ADMIN_ID and payload.notify_admin:
        try:
            await tg_app.bot.send_message(
                chat_id=ADMIN_ID,
                text=(
                    f"✅ <b>OPERATOR APPROVED PUBLISH</b>\n\n"
                    f"• Job: <code>#{job_id}</code>\n"
                    f"• Queue: <b>{'có' if info.get('queued') else 'không'}</b> | ID: <code>{info.get('queue_id') or '-'}</code>\n"
                    f"• Mode: <code>{html.escape(mode)}</code>\n"
                    f"• Note: {html.escape(payload.note or '-')}\n"
                    f"• Handoff: <code>/publisher_handoff queue={info.get('queue_id') or '<QUEUE_ID>'}</code>"
                ),
                parse_mode="HTML"
            )
            if info.get("queue_id"):
                item = get_publish_queue_item(ADMIN_ID, int(info.get("queue_id")))
                if item:
                    await tg_app.bot.send_message(
                        chat_id=ADMIN_ID,
                        text=format_publisher_handoff_summary(
                            int(info.get("queue_id")),
                            build_publisher_handoff(serialize_publish_queue_item(item)),
                        ),
                        parse_mode="HTML",
                    )
        except Exception as e:
            logger.error(f"Approve publish notify error: {e}")
    response = {"ok": True, "job_id": job_id, **info}
    if info.get("queue_id"):
        item = get_publish_queue_item(ADMIN_ID, int(info.get("queue_id")))
        if item:
            queue_payload = serialize_publish_queue_item(item)
            response["publisher_handoff"] = build_publisher_handoff(queue_payload)
            response["handoff_url"] = f"/api/operator/publish/{int(info.get('queue_id'))}/handoff"
    return response

@fastapi_app.post("/api/operator/approve-ready")
async def api_operator_approve_ready(payload: OperatorApproveReadyRequest, request: Request):
    verify_operator_api_token(request)
    ok, reason, result = approve_ready_jobs(
        ADMIN_ID,
        limit=payload.limit,
        mode=payload.mode,
        scheduled_at=payload.scheduled_at,
        note=payload.note or "api_batch_approve_ready",
    )
    if not ok:
        raise HTTPException(status_code=400, detail={"reason": reason, **(result or {})})
    approved = result.get("approved") or []
    if payload.notify_admin and tg_app and ADMIN_ID:
        try:
            lines = [
                "✅ <b>API BATCH APPROVE READY</b>",
                f"• Approved: <b>{len(approved)}</b> | Skipped: <b>{len(result.get('skipped') or [])}</b>",
            ]
            for item in approved[:8]:
                lines.append(
                    f"• job <code>#{item.get('job_id')}</code> → queue <code>#{item.get('queue_id') or '-'}</code> | "
                    f"<code>/publisher_handoff queue={item.get('queue_id') or '<QUEUE_ID>'}</code>"
                )
            await tg_app.bot.send_message(chat_id=ADMIN_ID, text="\n".join(lines), parse_mode="HTML")
            if payload.send_handoff:
                for item in approved[:3]:
                    queue_id = safe_int(item.get("queue_id"), 0)
                    if not queue_id:
                        continue
                    item_row = get_publish_queue_item(ADMIN_ID, queue_id)
                    if item_row:
                        await tg_app.bot.send_message(
                            chat_id=ADMIN_ID,
                            text=format_publisher_handoff_summary(
                                queue_id,
                                build_publisher_handoff(serialize_publish_queue_item(item_row)),
                            ),
                            parse_mode="HTML",
                        )
        except Exception as e:
            logger.error(f"Approve-ready notify error: {e}")
    return {"ok": True, **result}

